INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Jn', 4, 'pt', '[{"numero": 1, "texto": "Mas Jonas se desgostou muito, e se encheu de ira."}, {"numero": 2, "texto": "E orou ao SENHOR, e disse: Ah, SENHOR, não foi isto o que eu dizia enquanto ainda estava em minha terra? Por isso me preveni fugindo a Társis; porque sabia eu que tu és Deus gracioso e misericordioso, que demoras a te irar, tens grande misericórdia, e te arrependes do mal."}, {"numero": 3, "texto": "Agora pois, ó SENHOR, peço-te que me mates, porque é melhor para mim morrer do que viver."}, {"numero": 4, "texto": "E o SENHOR lhe disse: É correta essa tua ira?"}, {"numero": 5, "texto": "E Jonas saiu da cidade, e se sentou ao oriente da cidade, e fez para si ali uma barraca, e se sentou debaixo dela à sombra, até ver o que seria da cidade."}, {"numero": 6, "texto": "E o SENHOR Deus preparou uma planta, e a fez crescer sobre Jonas para que fizesse sombra sobre sua cabeça, e lhe aliviasse de seu mal-estar; e Jonas se alegrou grandemente por causa da planta."}, {"numero": 7, "texto": "Mas Deus preparou uma lagarta no dia seguinte ao amanhecer, a qual feriu a planta, e ela se secou."}, {"numero": 8, "texto": "E aconteceu que, ao levantar do sol, Deus preparou um quente vento oriental; e o sol feriu a Jonas na cabeça, de modo que ele se desmaiava, e desejava a morte, dizendo: Melhor é para mim morrer do que viver."}, {"numero": 9, "texto": "Então Deus disse a Jonas: É correta a tua ira pela planta?E ele respondeu: É correto eu me irar até a morte."}, {"numero": 10, "texto": "E o SENHOR disse: Tu tiveste pena da planta, na qual não trabalhaste, nem tu a fizeste crescer, que em uma noite nasceu, e em outra noite pereceu;"}, {"numero": 11, "texto": "E não teria eu pena de Nínive, aquela grande cidade onde há mais de cem e vinte mil pessoas que não sabem a diferença entre sua mão direita e a esquerda, e muitos animais?"}]'::jsonb, 'Almeida Livre'),
  ('Jn', 4, 'en', '[{"numero": 1, "texto": "But it displeased Jonah exceedingly, and he was very angry."}, {"numero": 2, "texto": "And he prayed unto the Lord, and said, I pray thee, O Lord, was not this my saying, when I was yet in my country? Therefore I fled before unto Tarshish: for I knew that thou art a gracious God, and merciful, slow to anger, and of great kindness, and repentest thee of the evil."}, {"numero": 3, "texto": "Therefore now, O Lord, take, I beseech thee, my life from me; for it is better for me to die than to live."}, {"numero": 4, "texto": "Then said the Lord, Doest thou well to be angry?"}, {"numero": 5, "texto": "So Jonah went out of the city, and sat on the east side of the city, and there made him a booth, and sat under it in the shadow, till he might see what would become of the city."}, {"numero": 6, "texto": "And the Lord God prepared a gourd, and made it to come up over Jonah, that it might be a shadow over his head, to deliver him from his grief. So Jonah was exceeding glad of the gourd."}, {"numero": 7, "texto": "But God prepared a worm when the morning rose the next day, and it smote the gourd that it withered."}, {"numero": 8, "texto": "And it came to pass, when the sun did arise, that God prepared a vehement east wind; and the sun beat upon the head of Jonah, that he fainted, and wished in himself to die, and said, It is better for me to die than to live."}, {"numero": 9, "texto": "And God said to Jonah, Doest thou well to be angry for the gourd? And he said, I do well to be angry, even unto death."}, {"numero": 10, "texto": "Then said the Lord, Thou hast had pity on the gourd, for the which thou hast not laboured, neither madest it grow; which came up in a night, and perished in a night:"}, {"numero": 11, "texto": "And should not I spare Nineveh, that great city, wherein are more than sixscore thousand persons that cannot discern between their right hand and their left hand; and also much cattle?"}]'::jsonb, 'King James Version'),
  ('Jn', 4, 'fr', '[{"numero": 1, "texto": "Cela déplut fort à Jonas, et il fut irrité."}, {"numero": 2, "texto": "Il implora l''''Eternel, et il dit: Ah! Eternel, n''''est-ce pas ce que je disais quand j''''étais encore dans mon pays? C''''est ce que je voulais prévenir en fuyant à Tarsis. Car je savais que tu es un Dieu compatissant et miséricordieux, lent à la colère et riche en bonté, et qui te repens du mal."}, {"numero": 3, "texto": "Maintenant, Eternel, prends-moi donc la vie, car la mort m''''est préférable à la vie."}, {"numero": 4, "texto": "L''''Eternel répondit: Fais-tu bien de t''''irriter?"}, {"numero": 5, "texto": "Et Jonas sortit de la ville, et s''''assit à l''''orient de la ville, Là il se fit une cabane, et s''''y tint à l''''ombre, jusqu''''à ce qu''''il vît ce qui arriverait dans la ville."}, {"numero": 6, "texto": "L''''Eternel Dieu fit croître un ricin, qui s''''éleva au-dessus de Jonas, pour donner de l''''ombre sur sa tête et pour lui ôter son irritation. Jonas éprouva une grande joie à cause de ce ricin."}, {"numero": 7, "texto": "Mais le lendemain, à l''''aurore, Dieu fit venir un ver qui piqua le ricin, et le ricin sécha."}, {"numero": 8, "texto": "Au lever du soleil, Dieu fit souffler un vent chaud d''''orient, et le soleil frappa la tête de Jonas, au point qu''''il tomba en défaillance. Il demanda la mort, et dit: La mort m''''est préférable à la vie."}, {"numero": 9, "texto": "Dieu dit à Jonas: Fais-tu bien de t''''irriter à cause du ricin? Il répondit: Je fais bien de m''''irriter jusqu''''à la mort."}, {"numero": 10, "texto": "Et l''''Eternel dit: Tu as pitié du ricin qui ne t''''a coûté aucune peine et que tu n''''as pas fait croître, qui est né dans une nuit et qui a péri dans une nuit."}, {"numero": 11, "texto": "Et moi, je n''''aurais pas pitié de Ninive, la grande ville, dans laquelle se trouvent plus de cent vingt mille hommes qui ne savent pas distinguer leur droite de leur gauche, et des animaux en grand nombre!"}]'::jsonb, 'Louis Segond 1910'),
  ('Jn', 4, 'es', '[{"numero": 1, "texto": "PERO Jonás se apesadumbró en extremo, y enojóse."}, {"numero": 2, "texto": "Y oró á Jehová, y dijo: Ahora, oh Jehová, ¿no es esto lo que yo decía estando aún en mi tierra? Por eso me precaví huyendo á Tarsis: porque sabía yo que tú eres Dios clemente y piadoso, tardo á enojarte, y de grande misericordia, y que te arrepientes del mal."}, {"numero": 3, "texto": "Ahora pues, oh Jehová, ruégote que me mates; porque mejor me es la muerte que la vida."}, {"numero": 4, "texto": "Y Jehová le dijo: ¿Haces tú bien en enojarte tanto?"}, {"numero": 5, "texto": "Y salióse Jonás de la ciudad, y asentó hacia el oriente de la ciudad, é hízose allí una choza, y se sentó debajo de ella á la sombra, hasta ver qué sería de la ciudad."}, {"numero": 6, "texto": "Y preparó Jehová Dios una calabacera, la cual creció sobre Jonás para que hiciese sombra sobre su cabeza, y le defendiese de su mal: y Jonás se alegró grandemente por la calabacera."}, {"numero": 7, "texto": "Mas Dios preparó un gusano al venir la mañana del día siguiente, el cual hirió á la calabacera, y secóse."}, {"numero": 8, "texto": "Y acaeció que al salir el sol, preparó Dios un recio viento solano; y el sol hirió á Jonás en la cabeza, y desmayábase, y se deseaba la muerte, diciendo: Mejor sería para mí la muerte que mi vida."}, {"numero": 9, "texto": "Entonces dijo Dios á Jonás: ¿Tanto te enojas por la calabacera? Y él respondió: Mucho me enojo, hasta la muerte."}, {"numero": 10, "texto": "Y dijo Jehová: Tuviste tú lástima de la calabacera, en la cual no trabajaste, ni tú la hiciste crecer; que en espacio de una noche nació, y en espacio de otra noche pereció:"}, {"numero": 11, "texto": "¿Y no tendré yo piedad de Nínive, aquella grande ciudad donde hay más de ciento y veinte mil personas que no conocen su mano derecha ni su mano izquierda, y muchos animales?"}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 1, 'pt', '[{"numero": 1, "texto": "No princípio era a Palavra, e a Palavra estava junto de Deus, e a Palavra era Deus."}, {"numero": 2, "texto": "Esta estava no princípio junto de Deus."}, {"numero": 3, "texto": "Por esta foram feitas todas as coisas, e sem ela não se fez coisa nenhuma do que foi feito."}, {"numero": 4, "texto": "Nela estava a vida, e a vida era a luz dos seres humanos."}, {"numero": 5, "texto": "E a luz brilha nas trevas; e as trevas não a compreenderam."}, {"numero": 6, "texto": "Houve um homem enviado por Deus, cujo nome era João."}, {"numero": 7, "texto": "Este veio por testemunho, para que testemunhasse da Luz, para que todos por ele cressem."}, {"numero": 8, "texto": "Ele não era a Luz; mas [foi enviado] para que testemunhasse da Luz."}, {"numero": 9, "texto": "[Esta] era a luz verdadeira, que ilumina a todo ser humano que vem ao mundo."}, {"numero": 10, "texto": "No mundo estava, e por ele foi feito o mundo; e o mundo não o conheceu."}, {"numero": 11, "texto": "Ao [seu] próprio veio, e os seus não o receberam."}, {"numero": 12, "texto": "Mas a todos quantos o receberam, deu-lhes poder de serem feitos filhos de Deus: aos que creem em seu nome."}, {"numero": 13, "texto": "Os quais não são gerados de sangue, nem de vontade da carne, nem de vontade de homem, mas sim de Deus."}, {"numero": 14, "texto": "E aquela Palavra se fez carne, e habitou entre nós; (e vimos sua glória, como glória do unigênito do Pai) cheio de graça e de verdade."}, {"numero": 15, "texto": "E João dele testemunhou, e clamou, dizendo: Este era aquele, de quem eu dizia: O que vem após mim é antes de mim; porque era primeiro que eu."}, {"numero": 16, "texto": "E de sua plenitude recebemos todos também graça por graça."}, {"numero": 17, "texto": "Porque a Lei foi dada por Moisés; a graça e a verdade foi feita por Jesus Cristo."}, {"numero": 18, "texto": "A Deus nunca ninguém o viu; o unigênito Filho, que está no seio do Pai, ele [o] declarou."}, {"numero": 19, "texto": "E este é o testemunho de João, quando os judeus mandaram alguns sacerdotes e levitas de Jerusalém, que lhe perguntassem: Tu quem és?"}, {"numero": 20, "texto": "E confessou, e não negou; e confessou: Eu não sou o Cristo."}, {"numero": 21, "texto": "E lhe perguntaram: Que, então? És tu Elias? E ele disse: Não sou. [Eles disseram] : Tu és o Profeta? E ele respondeu: Não."}, {"numero": 22, "texto": "Disseram-lhe pois: Quem és? Para darmos resposta aos que nos enviaram. Que dizes de ti mesmo?"}, {"numero": 23, "texto": "Disse: Eu sou a voz do que clama no deserto: Endireitai o caminho do Senhor, como disse o profeta Isaías."}, {"numero": 24, "texto": "E os enviados eram dos fariseus."}, {"numero": 25, "texto": "E perguntaram-lhe, e disseram-lhe: Por que pois batizas, se tu não és o Cristo, nem Elias, nem o profeta?"}, {"numero": 26, "texto": "João lhes respondeu, dizendo: Eu batizo com água; mas em meio de vós, está a quem vós não conheceis,"}, {"numero": 27, "texto": "Este é aquele que vem após mim, o qual já foi antes de mim, do qual eu não sou digno de desatar a tira de sua sandália."}, {"numero": 28, "texto": "Estas coisas aconteceram em Betábara, do outro lado do Jordão, onde João estava batizando."}, {"numero": 29, "texto": "O dia seguinte viu João a Jesus vir a ele, e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo."}, {"numero": 30, "texto": "Este é aquele do qual eu disse: Após mim vem um homem que já foi antes de mim; porque já era primeiro que eu."}, {"numero": 31, "texto": "E eu não o conhecia; mas para que fosse manifesto a Israel, por isso vim eu batizando com água."}, {"numero": 32, "texto": "E João testemunhou, dizendo: Eu vi o Espírito como pomba descer do céu, e repousou sobre ele."}, {"numero": 33, "texto": "E eu não o conhecia, mas aquele que me mandou a batizar com água, esse me disse: Sobre aquele que vires descer ao Espírito, e repousar sobre ele, esse é o que batiza com Espírito Santo."}, {"numero": 34, "texto": "E eu [o] vi, e testemunhado tenho, que este é o Filho de Deus."}, {"numero": 35, "texto": "O seguinte dia estava outra vez [ali] João, e dois de seus discípulos."}, {"numero": 36, "texto": "E vendo [por ali] andar a Jesus, disse: Eis o Cordeiro de Deus."}, {"numero": 37, "texto": "E os dois discípulos ouviram[-lhe] dizer [aquilo] , e seguiram a Jesus."}, {"numero": 38, "texto": "E Jesus, virando-se, e vendo-os seguir, disse-lhes: Que buscais? E eles lhe disseram: Rabi, (que traduzido, quer dizer, Mestre) onde moras?"}, {"numero": 39, "texto": "Disse-lhes ele: Vinde, e vede-o; Vieram, e viram onde morava, e na companhia dele naquele dia; e já era quase a hora décima."}, {"numero": 40, "texto": "Era André, o irmão de Simão Pedro, um dos dois que ouvira aquilo de João, e o haviam seguido."}, {"numero": 41, "texto": "Este achou primeiro a seu irmão Simão, e disse-lhe: Já achamos ao Messias(que traduzido, é o Cristo)."}, {"numero": 42, "texto": "E levou-o a Jesus. E Jesus, olhando para ele, disse: Tu és Simão, filho de Jonas; tu serás chamado Cefas. (que se traduz Pedro)."}, {"numero": 43, "texto": "O dia seguinte Jesus quis ir à Galileia, achou Filipe, e disse-lhe: Segue-me."}, {"numero": 44, "texto": "E Filipe era de Betsaida, da cidade de André e de Pedro."}, {"numero": 45, "texto": "Filipe achou Natanael, e disse-lhe: Achamos [aquele] de quem Moisés escreveu na Lei, e os Profetas: a Jesus, o filho de José, de Nazaré."}, {"numero": 46, "texto": "E disse-lhe Natanael: Pode haver alguma coisa boa de Nazaré? Filipe lhe disse: Vem, e vê."}, {"numero": 47, "texto": "Jesus viu Natanael vir, e disse dele: Eis verdadeiramente um israelita, em quem não há engano!"}, {"numero": 48, "texto": "Natanael lhe disse: De onde tu me conheces? Respondeu Jesus, e disse-lhe: Antes que Filipe te chamasse, estando tu debaixo da figueira, eu te vi."}, {"numero": 49, "texto": "Natanael respondeu, e disse-lhe: Rabi, tu és o Filho de Deus, tu és o Rei de Israel!"}, {"numero": 50, "texto": "Jesus respondeu, e disse-lhe: Porque te disse: Debaixo da figueira te vi, crês? Tu verás coisas maiores que estas."}, {"numero": 51, "texto": "E disse-lhe: Em verdade, em verdade vos digo, que daqui em diante vereis o céu aberto, e aos anjos de Deus subir e descer sobre o Filho do homem."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 1, 'en', '[{"numero": 1, "texto": "In the beginning was the Word, and the Word was with God, and the Word was God."}, {"numero": 2, "texto": "The same was in the beginning with God."}, {"numero": 3, "texto": "All things were made by him; and without him was not any thing made that was made."}, {"numero": 4, "texto": "In him was life; and the life was the light of men."}, {"numero": 5, "texto": "And the light shineth in darkness; and the darkness comprehended it not."}, {"numero": 6, "texto": "There was a man sent from God, whose name was John."}, {"numero": 7, "texto": "The same came for a witness, to bear witness of the Light, that all men through him might believe."}, {"numero": 8, "texto": "He was not that Light, but was sent to bear witness of that Light."}, {"numero": 9, "texto": "That was the true Light, which lighteth every man that cometh into the world."}, {"numero": 10, "texto": "He was in the world, and the world was made by him, and the world knew him not."}, {"numero": 11, "texto": "He came unto his own, and his own received him not."}, {"numero": 12, "texto": "But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:"}, {"numero": 13, "texto": "Which were born, not of blood, nor of the will of the flesh, nor of the will of man, but of God."}, {"numero": 14, "texto": "And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth."}, {"numero": 15, "texto": "John bare witness of him, and cried, saying, This was he of whom I spake, He that cometh after me is preferred before me: for he was before me."}, {"numero": 16, "texto": "And of his fulness have all we received, and grace for grace."}, {"numero": 17, "texto": "For the law was given by Moses, but grace and truth came by Jesus Christ."}, {"numero": 18, "texto": "No man hath seen God at any time, the only begotten Son, which is in the bosom of the Father, he hath declared him."}, {"numero": 19, "texto": "And this is the record of John, when the Jews sent priests and Levites from Jerusalem to ask him, Who art thou?"}, {"numero": 20, "texto": "And he confessed, and denied not; but confessed, I am not the Christ."}, {"numero": 21, "texto": "And they asked him, What then? Art thou Elias? And he saith, I am not. Art thou that prophet? And he answered, No."}, {"numero": 22, "texto": "Then said they unto him, Who art thou? that we may give an answer to them that sent us. What sayest thou of thyself?"}, {"numero": 23, "texto": "He said, I am the voice of one crying in the wilderness, Make straight the way of the Lord, as said the prophet Esaias."}, {"numero": 24, "texto": "And they which were sent were of the Pharisees."}, {"numero": 25, "texto": "And they asked him, and said unto him, Why baptizest thou then, if thou be not that Christ, nor Elias, neither that prophet?"}, {"numero": 26, "texto": "John answered them, saying, I baptize with water: but there standeth one among you, whom ye know not;"}, {"numero": 27, "texto": "He it is, who coming after me is preferred before me, whose shoe''s latchet I am not worthy to unloose."}, {"numero": 28, "texto": "These things were done in Bethabara beyond Jordan, where John was baptizing."}, {"numero": 29, "texto": "The next day John seeth Jesus coming unto him, and saith, Behold the Lamb of God, which taketh away the sin of the world."}, {"numero": 30, "texto": "This is he of whom I said, After me cometh a man which is preferred before me: for he was before me."}, {"numero": 31, "texto": "And I knew him not: but that he should be made manifest to Israel, therefore am I come baptizing with water."}, {"numero": 32, "texto": "And John bare record, saying, I saw the Spirit descending from heaven like a dove, and it abode upon him."}, {"numero": 33, "texto": "And I knew him not: but he that sent me to baptize with water, the same said unto me, Upon whom thou shalt see the Spirit descending, and remaining on him, the same is he which baptizeth with the Holy Ghost."}, {"numero": 34, "texto": "And I saw, and bare record that this is the Son of God."}, {"numero": 35, "texto": "Again the next day after John stood, and two of his disciples;"}, {"numero": 36, "texto": "And looking upon Jesus as he walked, he saith, Behold the Lamb of God!"}, {"numero": 37, "texto": "And the two disciples heard him speak, and they followed Jesus."}, {"numero": 38, "texto": "Then Jesus turned, and saw them following, and saith unto them, What seek ye? They said unto him, Rabbi, (which is to say, being interpreted, Master,) where dwellest thou?"}, {"numero": 39, "texto": "He saith unto them, Come and see. They came and saw where he dwelt, and abode with him that day: for it was about the tenth hour."}, {"numero": 40, "texto": "One of the two which heard John speak, and followed him, was Andrew, Simon Peter''s brother."}, {"numero": 41, "texto": "He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ."}, {"numero": 42, "texto": "And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone."}, {"numero": 43, "texto": "The day following Jesus would go forth into Galilee, and findeth Philip, and saith unto him, Follow me."}, {"numero": 44, "texto": "Now Philip was of Bethsaida, the city of Andrew and Peter."}, {"numero": 45, "texto": "Philip findeth Nathanael, and saith unto him, We have found him, of whom Moses in the law, and the prophets, did write, Jesus of Nazareth, the son of Joseph."}, {"numero": 46, "texto": "And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see."}, {"numero": 47, "texto": "Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!"}, {"numero": 48, "texto": "Nathanael saith unto him, Whence knowest thou me? Jesus answered and said unto him, Before that Philip called thee, when thou wast under the fig tree, I saw thee."}, {"numero": 49, "texto": "Nathanael answered and saith unto him, Rabbi, thou art the Son of God; thou art the King of Israel."}, {"numero": 50, "texto": "Jesus answered and said unto him, Because I said unto thee, I saw thee under the fig tree, believest thou? thou shalt see greater things than these."}, {"numero": 51, "texto": "And he saith unto him, Verily, verily, I say unto you, Hereafter ye shall see heaven open, and the angels of God ascending and descending upon the Son of man."}]'::jsonb, 'King James Version'),
  ('Jo', 1, 'fr', '[{"numero": 1, "texto": "Au commencement était la Parole, et la Parole était avec Dieu, et la Parole était Dieu."}, {"numero": 2, "texto": "Elle était au commencement avec Dieu."}, {"numero": 3, "texto": "Toutes choses ont été faites par elle, et rien de ce qui a été fait n''''a été fait sans elle."}, {"numero": 4, "texto": "En elle était la vie, et la vie était la lumière des hommes."}, {"numero": 5, "texto": "La lumière luit dans les ténèbres, et les ténèbres ne l''''ont point reçue."}, {"numero": 6, "texto": "Il y eut un homme envoyé de Dieu: son nom était Jean."}, {"numero": 7, "texto": "Il vint pour servir de témoin, pour rendre témoignage à la lumière, afin que tous crussent par lui."}, {"numero": 8, "texto": "Il n''''était pas la lumière, mais il parut pour rendre témoignage à la lumière."}, {"numero": 9, "texto": "Cette lumière était la véritable lumière, qui, en venant dans le monde, éclaire tout homme."}, {"numero": 10, "texto": "Elle était dans le monde, et le monde a été fait par elle, et le monde ne l''''a point connue."}, {"numero": 11, "texto": "Elle est venue chez les siens, et les siens ne l''''ont point reçue."}, {"numero": 12, "texto": "Mais à tous ceux qui l''''ont reçue, à ceux qui croient en son nom, elle a donné le pouvoir de devenir enfants de Dieu,"}, {"numero": 13, "texto": "lesquels sont nés, non du sang, ni de la volonté de la chair, ni de la volonté de l''''homme, mais de Dieu."}, {"numero": 14, "texto": "Et la parole a été faite chair, et elle a habité parmi nous, pleine de grâce et de vérité; et nous avons contemplé sa gloire, une gloire comme la gloire du Fils unique venu du Père."}, {"numero": 15, "texto": "Jean lui a rendu témoignage, et s''''est écrié: C''''est celui dont j''''ai dit: Celui qui vient après moi m''''a précédé, car il était avant moi."}, {"numero": 16, "texto": "Et nous avons tous reçu de sa plénitude, et grâce pour grâce;"}, {"numero": 17, "texto": "car la loi a été donnée par Moïse, la grâce et la vérité sont venues par Jésus-Christ."}, {"numero": 18, "texto": "Personne n''''a jamais vu Dieu; le Fils unique, qui est dans le sein du Père, est celui qui l''''a fait connaître."}, {"numero": 19, "texto": "Voici le témoignage de Jean, lorsque les Juifs envoyèrent de Jérusalem des sacrificateurs et des Lévites, pour lui demander: Toi, qui es-tu?"}, {"numero": 20, "texto": "Il déclara, et ne le nia point, il déclara qu''''il n''''était pas le Christ."}, {"numero": 21, "texto": "Et ils lui demandèrent: Quoi donc? es-tu Elie? Et il dit: Je ne le suis point. Es-tu le prophète? Et il répondit: Non."}, {"numero": 22, "texto": "Ils lui dirent alors: Qui es-tu? afin que nous donnions une réponse à ceux qui nous ont envoyés. Que dis-tu de toi-même?"}, {"numero": 23, "texto": "Moi, dit-il, je suis la voix de celui qui crie dans le désert: Aplanissez le chemin du Seigneur, comme a dit Esaïe, le prophète."}, {"numero": 24, "texto": "Ceux qui avaient été envoyés étaient des pharisiens."}, {"numero": 25, "texto": "Ils lui firent encore cette question: Pourquoi donc baptises-tu, si tu n''''es pas le Christ, ni Elie, ni le prophète?"}, {"numero": 26, "texto": "Jean leur répondit: Moi, je baptise d''''eau, mais au milieu de vous il y a quelqu''''un que vous ne connaissez pas,"}, {"numero": 27, "texto": "qui vient après moi; je ne suis pas digne de délier la courroie de ses souliers."}, {"numero": 28, "texto": "Ces choses se passèrent à Béthanie, au delà du Jourdain, où Jean baptisait."}, {"numero": 29, "texto": "Le lendemain, il vit Jésus venant à lui, et il dit: Voici l''''Agneau de Dieu, qui ôte le péché du monde."}, {"numero": 30, "texto": "C''''est celui dont j''''ai dit: Après moi vient un homme qui m''''a précédé, car il était avant moi."}, {"numero": 31, "texto": "Je ne le connaissais pas, mais c''''est afin qu''''il fût manifesté à Israël que je suis venu baptiser d''''eau."}, {"numero": 32, "texto": "Jean rendit ce témoignage: J''''ai vu l''''Esprit descendre du ciel comme une colombe et s''''arrêter sur lui."}, {"numero": 33, "texto": "Je ne le connaissais pas, mais celui qui m''''a envoyé baptiser d''''eau, celui-là m''''a dit: Celui sur qui tu verras l''''Esprit descendre et s''''arrêter, c''''est celui qui baptise du Saint-Esprit."}, {"numero": 34, "texto": "Et j''''ai vu, et j''''ai rendu témoignage qu''''il est le Fils de Dieu."}, {"numero": 35, "texto": "Le lendemain, Jean était encore là, avec deux de ses disciples;"}, {"numero": 36, "texto": "et, ayant regardé Jésus qui passait, il dit: Voilà l''''Agneau de Dieu."}, {"numero": 37, "texto": "Les deux disciples l''''entendirent prononcer ces paroles, et ils suivirent Jésus."}, {"numero": 38, "texto": "Jésus se retourna, et voyant qu''''ils le suivaient, il leur dit: Que cherchez-vous? Ils lui répondirent: Rabbi ce qui signifie Maître, où demeures-tu?"}, {"numero": 39, "texto": "Venez, leur dit-il, et voyez. Ils allèrent, et ils virent où il demeurait; et ils restèrent auprès de lui ce jour-là. C''''était environ la dixième heure."}, {"numero": 40, "texto": "André, frère de Simon Pierre, était l''''un des deux qui avaient entendu les paroles de Jean, et qui avaient suivi Jésus."}, {"numero": 41, "texto": "Ce fut lui qui rencontra le premier son frère Simon, et il lui dit: Nous avons trouvé le Messie ce qui signifie Christ."}, {"numero": 42, "texto": "Et il le conduisit vers Jésus. Jésus, l''''ayant regardé, dit: Tu es Simon, fils de Jonas; tu seras appelé Céphas ce qui signifie Pierre."}, {"numero": 43, "texto": "Le lendemain, Jésus voulut se rendre en Galilée, et il rencontra Philippe. Il lui dit: Suis-moi."}, {"numero": 44, "texto": "Philippe était de Bethsaïda, de la ville d''''André et de Pierre."}, {"numero": 45, "texto": "Philippe rencontra Nathanaël, et lui dit: Nous avons trouvé celui de qui Moïse a écrit dans la loi et dont les prophètes ont parlé, Jésus de Nazareth, fils de Joseph."}, {"numero": 46, "texto": "Nathanaël lui dit: Peut-il venir de Nazareth quelque chose de bon? Philippe lui répondit: Viens, et vois."}, {"numero": 47, "texto": "Jésus, voyant venir à lui Nathanaël, dit de lui: Voici vraiment un Israélite, dans lequel il n''''y a point de fraude."}, {"numero": 48, "texto": "D''''où me connais-tu? lui dit Nathanaël. Jésus lui répondit: Avant que Philippe t''''appelât, quand tu étais sous le figuier, je t''''ai vu."}, {"numero": 49, "texto": "Nathanaël répondit et lui dit: Rabbi, tu es le Fils de Dieu, tu es le roi d''''Israël."}, {"numero": 50, "texto": "Jésus lui répondit: Parce que je t''''ai dit que je t''''ai vu sous le figuier, tu crois; tu verras de plus grandes choses que celles-ci."}, {"numero": 51, "texto": "Et il lui dit: En vérité, en vérité, vous verrez désormais le ciel ouvert et les anges de Dieu monter et descendre sur le Fils de l''''homme."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 1, 'es', '[{"numero": 1, "texto": "EN el principio era el Verbo, y el Verbo era con Dios, y el Verbo era Dios."}, {"numero": 2, "texto": "Este era en el principio con Dios."}, {"numero": 3, "texto": "Todas las cosas por él fueron hechas; y sin él nada de lo que es hecho, fué hecho."}, {"numero": 4, "texto": "En él estaba la vida, y la vida era la luz de los hombres."}, {"numero": 5, "texto": "Y la luz en las tinieblas resplandece; mas las tinieblas no la comprendieron."}, {"numero": 6, "texto": "Fué un hombre enviado de Dios, el cual se llamaba Juan."}, {"numero": 7, "texto": "Este vino por testimonio, para que diese testimonio de la luz, para que todos creyesen por él."}, {"numero": 8, "texto": "No era él la luz, sino para que diese testimonio de la luz."}, {"numero": 9, "texto": "Aquél era la luz verdadera, que alumbra á todo hombre que viene á este mundo."}, {"numero": 10, "texto": "En el mundo estaba, y el mundo fué hecho por él; y el mundo no le conoció."}, {"numero": 11, "texto": "A lo suyo vino, y los suyos no le recibieron."}, {"numero": 12, "texto": "Mas á todos los que le recibieron, dióles potestad de ser hechos hijos de Dios, á los que creen en su nombre:"}, {"numero": 13, "texto": "Los cuales no son engendrados de sangre, ni de voluntad de carne, ni de voluntad de varón, mas de Dios."}, {"numero": 14, "texto": "Y aquel Verbo fué hecho carne, y habitó entre nosotros (y vimos su gloria, gloria como del unigénito del Padre), lleno de gracia y de verdad."}, {"numero": 15, "texto": "Juan dió testimonio de él, y clamó diciendo: Este es del que yo decía: El que viene tras mí, es antes de mí: porque es primero que yo."}, {"numero": 16, "texto": "Porque de su plenitud tomamos todos, y gracia por gracia."}, {"numero": 17, "texto": "Porque la ley por Moisés fué dada: mas la gracia y la verdad por Jesucristo fué hecha."}, {"numero": 18, "texto": "A Dios nadie le vió jamás: el unigénito Hijo, que está en el seno del Padre, él le declaró."}, {"numero": 19, "texto": "Y éste es el testimonio de Juan, cuando los Judíos enviaron de Jerusalem sacerdotes y Levitas, que le preguntasen: ¿Tú, quién eres?"}, {"numero": 20, "texto": "Y confesó, y no negó; mas declaró: No soy yo el Cristo."}, {"numero": 21, "texto": "Y le preguntaron: ¿Qué pues? ¿Eres tú Elías? Dijo: No soy. ¿Eres tú el profeta? Y respondió: No."}, {"numero": 22, "texto": "Dijéronle: ¿Pues quién eres? para que demos respuesta á los que nos enviaron. ¿Qué dices de ti mismo?"}, {"numero": 23, "texto": "Dijo: Yo soy la voz del que clama en el desierto: Enderezad el camino del Señor, como dijo Isaías profeta."}, {"numero": 24, "texto": "Y los que habían sido enviados eran de los Fariseos."}, {"numero": 25, "texto": "Y preguntáronle, y dijéronle: ¿Por qué pues bautizas, si tú no eres el Cristo, ni Elías, ni el profeta?"}, {"numero": 26, "texto": "Y Juan les respondió, diciendo: Yo bautizo con agua; mas en medio de vosotros ha estado á quien vosotros no conocéis."}, {"numero": 27, "texto": "Este es el que ha de venir tras mí, el cual es antes de mí: del cual yo no soy digno de desatar la correa del zapato."}, {"numero": 28, "texto": "Estas cosas acontecieron en Betábara, de la otra parte del Jordán, donde Juan bautizaba."}, {"numero": 29, "texto": "El siguiente día ve Juan á Jesús que venía á él, y dice: He aquí el Cordero de Dios, que quita el pecado del mundo."}, {"numero": 30, "texto": "Este es del que dije: Tras mí viene un varón, el cual es antes de mí: porque era primero que yo."}, {"numero": 31, "texto": "Y yo no le conocía; más para que fuese manifestado á Israel, por eso vine yo bautizando con agua."}, {"numero": 32, "texto": "Y Juan dió testimonio, diciendo: Vi al Espíritu que descendía del cielo como paloma, y reposó sobre él."}, {"numero": 33, "texto": "Y yo no le conocía; mas el que me envió á bautizar con agua, aquél me dijo: Sobre quien vieres descender el Espíritu, y que reposa sobre él, éste es el que bautiza con Espíritu Santo."}, {"numero": 34, "texto": "Y yo le vi, y he dado testimonio que éste es el Hijo de Dios."}, {"numero": 35, "texto": "El siguiente día otra vez estaba Juan, y dos de sus discípulos."}, {"numero": 36, "texto": "Y mirando á Jesús que andaba por allí, dijo: He aquí el Cordero de Dios."}, {"numero": 37, "texto": "Y oyéronle los dos discípulos hablar, y siguieron á Jesús."}, {"numero": 38, "texto": "Y volviéndose Jesús, y viéndolos seguirle, díceles: ¿Qué buscáis? Y ellos le dijeron: Rabbí (que declarado quiere decir Maestro) ¿dónde moras?"}, {"numero": 39, "texto": "Díceles: Venid y ved. Vinieron, y vieron donde moraba, y quedáronse con él aquel día: porque era como la hora de las diez."}, {"numero": 40, "texto": "Era Andrés, hermano de Simón Pedro, uno de los dos que habían oído de Juan, y le habían seguido."}, {"numero": 41, "texto": "Este halló primero á su hermano Simón, y díjole: Hemos hallado al Mesías (que declarado es, el Cristo)."}, {"numero": 42, "texto": "Y le trajo á Jesús. Y mirándole Jesús, dijo: Tú eres Simón, hijo de Jonás: tú serás llamado Cephas (que quiere decir, Piedra)."}, {"numero": 43, "texto": "El siguiente día quiso Jesús ir á Galilea, y halla á Felipe, al cual dijo: Sígueme."}, {"numero": 44, "texto": "Y era Felipe de Bethsaida, la ciudad de Andrés y de Pedro."}, {"numero": 45, "texto": "Felipe halló á Natanael, y dícele: Hemos hallado á aquel de quien escribió Moisés en la ley, y los profetas: á Jesús, el hijo de José, de Nazaret."}, {"numero": 46, "texto": "Y díjole Natanael: ¿De Nazaret puede haber algo de bueno? Dícele Felipe: Ven y ve."}, {"numero": 47, "texto": "Jesús vió venir á sí á Natanael, y dijo de él: He aquí un verdadero Israelita, en el cual no hay engaño."}, {"numero": 48, "texto": "Dícele Natanael: ¿De dónde me conoces? Respondió Jesús, y díjole: Antes que Felipe te llamara, cuando estabas debajo de la higuera te vi."}, {"numero": 49, "texto": "Respondió Natanael, y díjole: Rabbí, tú eres el Hijo de Dios; tú eres el Rey de Israel."}, {"numero": 50, "texto": "Respondió Jesús y díjole: ¿Porque te dije, te vi debajo de la higuera, crees? cosas mayores que éstas verás."}, {"numero": 51, "texto": "Y dícele: De cierto, de cierto os digo: De aquí adelante veréis el cielo abierto, y los ángeles de Dios que suben y descienden sobre el Hijo del hombre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 2, 'pt', '[{"numero": 1, "texto": "E no terceiro dia houve um casamento em Caná da Galileia; e a mãe de Jesus estava ali."}, {"numero": 2, "texto": "E também Jesus foi convidado com seus discípulos ao casamento."}, {"numero": 3, "texto": "E tendo faltado vinho, a mãe de Jesus lhe disse: Não têm vinho."}, {"numero": 4, "texto": "Jesus lhe disse: O que eu tenho contigo, mulher? A minha hora ainda não chegou."}, {"numero": 5, "texto": "Sua mãe disse aos serventes: Fazei tudo quanto ele vos disser."}, {"numero": 6, "texto": "E estavam ali postos seis vasos de pedra, conforme à purificação dos judeus, em cada uma cabiam duas ou três metretas. )"}, {"numero": 7, "texto": "Disse-lhes Jesus: Enchei estes vasos com água. E encheram-nas até encima."}, {"numero": 8, "texto": "E disse-lhes: Agora tirai, e a levai ao mestre de cerimônia. Então levaram."}, {"numero": 9, "texto": "E quando o mestre de cerimônia experimentou a água feita vinho (sem saber de onde era, porém os serventes que haviam tirado a água sabiam), o mestre de cerimônia chamou o noivo,"}, {"numero": 10, "texto": "E disse-lhe: Todos põem primeiro o vinho bom, e quando [os convidados] já [estão] bêbados, então [se dá] o pior; [porém] tu guardaste o bom vinho até agora."}, {"numero": 11, "texto": "Este princípio de sinais Jesus fez em Caná da Galileia, e manifestou sua glória; e seus discípulos creram nele."}, {"numero": 12, "texto": "Depois disto desceu a Cafarnaum, ele e sua mãe, seus irmãos, e seus discípulos, e ficaram ali não muitos dias."}, {"numero": 13, "texto": "E estava perto a Páscoa dos judeus, e Jesus subiu a Jerusalém."}, {"numero": 14, "texto": "E achou no Templo os que vendiam bois, ovelhas, e pombas, e os cambistas sentados."}, {"numero": 15, "texto": "E tendo feito um açoite com cordas, lançou todos para fora do Templo, assim como as ovelhas, e os bois; e espalhou o dinheiro dos cambistas, e virou as mesas."}, {"numero": 16, "texto": "E aos que vendiam pombas, disse: Tirai isto daqui; e não torneis a casa de meu Pai uma casa de comércio!"}, {"numero": 17, "texto": "E lembraram-se seus discípulos que está escrito: O zelo de tua casa me tem me devorado."}, {"numero": 18, "texto": "Responderam pois os Judeus, e disseram-lhe: Que sinal nos mostras de que fazes estas coisas?"}, {"numero": 19, "texto": "Respondeu Jesus, e disse-lhes: Derrubai este Templo, e em três dias o levantarei."}, {"numero": 20, "texto": "Os judeus, pois, disseram: [Durante] quarenta e seis anos este Templo foi edificado, e tu o levantarás tu em três dias?"}, {"numero": 21, "texto": "Porém ele falava do Templo de seu corpo."}, {"numero": 22, "texto": "Portanto, quando ressuscitou dos mortos, seus discípulos se lembraram que ele lhes tinha dito isto; e creram na Escritura, e na palavra que Jesus tinha [lhes] dito."}, {"numero": 23, "texto": "E estando ele em Jerusalém pela páscoa, na festa, muitos creram em seu nome, ao verem os sinais que ele fazia."}, {"numero": 24, "texto": "Mas o mesmo Jesus a si mesmo não confiava neles, porque conhecia a todos."}, {"numero": 25, "texto": "E não necessitava de que alguém [lhe] desse testemunho de ser humano algum, pois ele bem sabia o que havia no [interior do] ser humano."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 2, 'en', '[{"numero": 1, "texto": "And the third day there was a marriage in Cana of Galilee; and the mother of Jesus was there:"}, {"numero": 2, "texto": "And both Jesus was called, and his disciples, to the marriage."}, {"numero": 3, "texto": "And when they wanted wine, the mother of Jesus saith unto him, They have no wine."}, {"numero": 4, "texto": "Jesus saith unto her, Woman, what have I to do with thee? mine hour is not yet come."}, {"numero": 5, "texto": "His mother saith unto the servants, Whatsoever he saith unto you, do it."}, {"numero": 6, "texto": "And there were set there six waterpots of stone, after the manner of the purifying of the Jews, containing two or three firkins apiece."}, {"numero": 7, "texto": "Jesus saith unto them, Fill the waterpots with water. And they filled them up to the brim."}, {"numero": 8, "texto": "And he saith unto them, Draw out now, and bear unto the governor of the feast. And they bare it."}, {"numero": 9, "texto": "When the ruler of the feast had tasted the water that was made wine, and knew not whence it was: (but the servants which drew the water knew;) the governor of the feast called the bridegroom,"}, {"numero": 10, "texto": "And saith unto him, Every man at the beginning doth set forth good wine; and when men have well drunk, then that which is worse: but thou hast kept the good wine until now."}, {"numero": 11, "texto": "This beginning of miracles did Jesus in Cana of Galilee, and manifested forth his glory; and his disciples believed on him."}, {"numero": 12, "texto": "After this he went down to Capernaum, he, and his mother, and his brethren, and his disciples: and they continued there not many days."}, {"numero": 13, "texto": "And the Jews'' passover was at hand, and Jesus went up to Jerusalem."}, {"numero": 14, "texto": "And found in the temple those that sold oxen and sheep and doves, and the changers of money sitting:"}, {"numero": 15, "texto": "And when he had made a scourge of small cords, he drove them all out of the temple, and the sheep, and the oxen; and poured out the changers'' money, and overthrew the tables;"}, {"numero": 16, "texto": "And said unto them that sold doves, Take these things hence; make not my Father''s house an house of merchandise."}, {"numero": 17, "texto": "And his disciples remembered that it was written, The zeal of thine house hath eaten me up."}, {"numero": 18, "texto": "Then answered the Jews and said unto him, What sign shewest thou unto us, seeing that thou doest these things?"}, {"numero": 19, "texto": "Jesus answered and said unto them, Destroy this temple, and in three days I will raise it up."}, {"numero": 20, "texto": "Then said the Jews, Forty and six years was this temple in building, and wilt thou rear it up in three days?"}, {"numero": 21, "texto": "But he spake of the temple of his body."}, {"numero": 22, "texto": "When therefore he was risen from the dead, his disciples remembered that he had said this unto them; and they believed the scripture, and the word which Jesus had said."}, {"numero": 23, "texto": "Now when he was in Jerusalem at the passover, in the feast day, many believed in his name, when they saw the miracles which he did."}, {"numero": 24, "texto": "But Jesus did not commit himself unto them, because he knew all men,"}, {"numero": 25, "texto": "And needed not that any should testify of man: for he knew what was in man."}]'::jsonb, 'King James Version'),
  ('Jo', 2, 'fr', '[{"numero": 1, "texto": "Trois jours après, il y eut des noces à Cana en Galilée. La mère de Jésus était là,"}, {"numero": 2, "texto": "et Jésus fut aussi invité aux noces avec ses disciples."}, {"numero": 3, "texto": "Le vin ayant manqué, la mère de Jésus lui dit: Ils n''''ont plus de vin."}, {"numero": 4, "texto": "Jésus lui répondit: Femme, qu''''y a-t-il entre moi et toi? Mon heure n''''est pas encore venue."}, {"numero": 5, "texto": "Sa mère dit aux serviteurs: Faites ce qu''''il vous dira."}, {"numero": 6, "texto": "Or, il y avait là six vases de pierre, destinés aux purifications des Juifs, et contenant chacun deux ou trois mesures."}, {"numero": 7, "texto": "Jésus leur dit: Remplissez d''''eau ces vases. Et ils les remplirent jusqu''''au bord."}, {"numero": 8, "texto": "Puisez maintenant, leur dit-il, et portez-en à l''''ordonnateur du repas. Et ils en portèrent."}, {"numero": 9, "texto": "Quand l''''ordonnateur du repas eut goûté l''''eau changée en vin,-ne sachant d''''où venait ce vin, tandis que les serviteurs, qui avaient puisé l''''eau, le savaient bien, -il appela l''''époux,"}, {"numero": 10, "texto": "et lui dit: Tout homme sert d''''abord le bon vin, puis le moins bon après qu''''on s''''est enivré; toi, tu as gardé le bon vin jusqu''''à présent."}, {"numero": 11, "texto": "Tel fut, à Cana en Galilée, le premier des miracles que fit Jésus. Il manifesta sa gloire, et ses disciples crurent en lui."}, {"numero": 12, "texto": "Après cela, il descendit à Capernaüm, avec sa mère, ses frères et ses disciples, et ils n''''y demeurèrent que peu de jours."}, {"numero": 13, "texto": "La Pâque des Juifs était proche, et Jésus monta à Jérusalem."}, {"numero": 14, "texto": "Il trouva dans le temple les vendeurs de boeufs, de brebis et de pigeons, et les changeurs assis."}, {"numero": 15, "texto": "Ayant fait un fouet avec des cordes, il les chassa tous du temple, ainsi que les brebis et les boeufs; il dispersa la monnaie des changeurs, et renversa les tables;"}, {"numero": 16, "texto": "et il dit aux vendeurs de pigeons: Otez cela d''''ici, ne faites pas de la maison de mon Père une maison de trafic."}, {"numero": 17, "texto": "Ses disciples se souvinrent qu''''il est écrit: Le zèle de ta maison me dévore."}, {"numero": 18, "texto": "Les Juifs, prenant la parole, lui dirent: Quel miracle nous montres-tu, pour agir de la sorte?"}, {"numero": 19, "texto": "Jésus leur répondit: Détruisez ce temple, et en trois jours je le relèverai."}, {"numero": 20, "texto": "Les Juifs dirent: Il a fallu quarante-six ans pour bâtir ce temple, et toi, en trois jours tu le relèveras!"}, {"numero": 21, "texto": "Mais il parlait du temple de son corps."}, {"numero": 22, "texto": "C''''est pourquoi, lorsqu''''il fut ressuscité des morts, ses disciples se souvinrent qu''''il avait dit cela, et ils crurent à l''''Ecriture et à la parole que Jésus avait dite."}, {"numero": 23, "texto": "Pendant que Jésus était à Jérusalem, à la fête de Pâque, plusieurs crurent en son nom, voyant les miracles qu''''il faisait."}, {"numero": 24, "texto": "Mais Jésus ne se fiait point à eux, parce qu''''il les connaissait tous,"}, {"numero": 25, "texto": "et parce qu''''il n''''avait pas besoin qu''''on lui rendît témoignage d''''aucun homme; car il savait lui-même ce qui était dans l''''homme."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 2, 'es', '[{"numero": 1, "texto": "Y AL tercer día hiciéronse unas bodas en Caná de Galilea; y estaba allí la madre de Jesús."}, {"numero": 2, "texto": "Y fué también llamado Jesús y sus discípulos á las bodas."}, {"numero": 3, "texto": "Y faltando el vino, la madre de Jesús le dijo: Vino no tienen."}, {"numero": 4, "texto": "Y dícele Jesús: ¿Qué tengo yo contigo, mujer? aun no ha venido mi hora."}, {"numero": 5, "texto": "Su madre dice á los que servían: Haced todo lo que os dijere."}, {"numero": 6, "texto": "Y estaban allí seis tinajuelas de piedra para agua, conforme á la purificación de los Judíos, que cabían en cada una dos ó tres cántaros."}, {"numero": 7, "texto": "Díceles Jesús: Henchid estas tinajuelas de agua. E hinchiéronlas hasta arriba."}, {"numero": 8, "texto": "Y díceles: Sacad ahora, y presentad al maestresala. Y presentáronle."}, {"numero": 9, "texto": "Y como el maestresala gustó el agua hecha vino, que no sabía de dónde era (mas lo sabían los sirvientes que habían sacado el agua), el maestresala llama al esposo,"}, {"numero": 10, "texto": "Y dícele: Todo hombre pone primero el buen vino, y cuando están satisfechos, entonces lo que es peor; mas tú has guardado el buen vino hasta ahora."}, {"numero": 11, "texto": "Este principio de señales hizo Jesús en Caná de Galilea, y manifestó su gloria; y sus discípulos creyeron en él."}, {"numero": 12, "texto": "Después de esto descendió á Capernaum, él, y su madre, y hermanos, y discípulos; y estuvieron allí no muchos días."}, {"numero": 13, "texto": "Y estaba cerca la Pascua de los Judíos; y subió Jesús á Jerusalem."}, {"numero": 14, "texto": "Y halló en el templo á los que vendían bueyes, y ovejas, y palomas, y á los cambiadores sentados."}, {"numero": 15, "texto": "Y hecho un azote de cuerdas, echólos á todos del templo, y las ovejas, y los bueyes; y derramó los dineros de los cambiadores, y trastornó las mesas;"}, {"numero": 16, "texto": "Y á los que vendían las palomas, dijo: Quitad de aquí esto, y no hagáis la casa de mi Padre casa de mercado."}, {"numero": 17, "texto": "Entonces se acordaron sus discípulos que está escrito: El celo de tu casa me comió."}, {"numero": 18, "texto": "Y los Judíos respondieron, y dijéronle: ¿Qué señal nos muestras de que haces esto?"}, {"numero": 19, "texto": "Respondió Jesús, y díjoles: Destruid este templo, y en tres días lo levantaré."}, {"numero": 20, "texto": "Dijeron luego los Judíos: En cuarenta y seis años fué este templo edificado, ¿y tú en tres días lo levantarás?"}, {"numero": 21, "texto": "Mas él hablaba del templo de su cuerpo."}, {"numero": 22, "texto": "Por tanto, cuando resucitó de los muertos, sus discípulos se acordaron que había dicho esto; y creyeron á la Escritura, y á la palabra que Jesús había dicho."}, {"numero": 23, "texto": "Y estando en Jerusalem en la Pascua, en el día de la fiesta, muchos creyeron en su nombre, viendo las señales que hacía."}, {"numero": 24, "texto": "Mas el mismo Jesús no se confiaba á sí mismo de ellos, porque él conocía á todos,"}, {"numero": 25, "texto": "Y no tenía necesidad que alguien le diese testimonio del hombre; porque él sabía lo que había en el hombre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 3, 'pt', '[{"numero": 1, "texto": "E havia um homem dos fariseus, cujo nome era Nicodemos, chefe dos judeus."}, {"numero": 2, "texto": "Este veio a Jesus de noite, e disse-lhe: Rabi, bem sabemos que és Mestre vindo de Deus; porque ninguém pode fazer estes sinais que tu fazes, se Deus não for com ele."}, {"numero": 3, "texto": "Respondeu Jesus e disse-lhe: Em verdade, em verdade te digo, que aquele que não voltar a nascer, não pode ver o Reino de Deus."}, {"numero": 4, "texto": "Nicodemos lhe disse: Como pode o homem nascer, sendo [já] velho? Pode ele voltar a entrar no ventre de sua mãe, e nascer?"}, {"numero": 5, "texto": "Respondeu Jesus: Em verdade, em verdade te digo, que aquele que não nascer de água e [do] Espírito, não pode entrar no Reino de Deus."}, {"numero": 6, "texto": "O que é nascido de carne, carne é; e o que é nascido do Espírito, espírito é."}, {"numero": 7, "texto": "Não te maravilhes de que te disse: necessário vos é voltar a nascer."}, {"numero": 8, "texto": "O vento sopra onde quer, e ouves o seu som; porém não sabes de onde vem, nem para onde vai; assim é todo aquele que é nascido do Espírito."}, {"numero": 9, "texto": "Nicodemos respondeu, e disse-lhe: Como pode isto acontecer?"}, {"numero": 10, "texto": "Jesus respondeu, e disse-lhe: Tu és mestre de Israel, e isto não sabes?"}, {"numero": 11, "texto": "Em verdade, em verdade te digo, que o que sabemos, falamos; e o que temos visto, testemunhamos; e não aceitais nosso testemunho."}, {"numero": 12, "texto": "Se eu vos disse coisas terrenas, e não credes, como crereis, se vos disser as celestiais?"}, {"numero": 13, "texto": "E ninguém subiu ao céu, a não ser o que desceu do céu: o Filho do homem, que está no céu."}, {"numero": 14, "texto": "E como Moisés levantou a serpente no deserto, assim deve o Filho do homem ser levantado,"}, {"numero": 15, "texto": "Para que todo aquele que nele crer não pereça, mas tenha a vida eterna."}, {"numero": 16, "texto": "Porque Deus amou ao mundo de tal maneira, que deu o seu Filho unigênito; para que todo aquele que nele crê não pereça, mas tenha a vida eterna."}, {"numero": 17, "texto": "Porque Deus não mandou seu Filho ao mundo para que condenasse ao mundo; mas sim para que o mundo por ele fosse salvo;"}, {"numero": 18, "texto": "Quem nele crer não é condenado; mas quem não crê já está condenado; pois não tem crido no nome do unigênito Filho de Deus."}, {"numero": 19, "texto": "E esta é a condenação: que a luz veio ao mundo, e as pessoas amaram mais as trevas que a luz, porque suas obras eram más."}, {"numero": 20, "texto": "Porque todo aquele que faz o mal odeia a luz e não vem à luz, para que suas obras não sejam reprovadas."}, {"numero": 21, "texto": "Mas quem pratica a verdade vem à luz, para que suas obras sejam manifestas, que são feitas em Deus."}, {"numero": 22, "texto": "Depois disto Jesus veio com seus discípulos à terra da Judeia; e estava ali com eles, e batizava."}, {"numero": 23, "texto": "E João também batizava em Enom, junto a Salim, porque havia ali muitas águas; e vinham [ali] , e eram batizados,"}, {"numero": 24, "texto": "Porque João ainda não tinha sido lançado na prisão."}, {"numero": 25, "texto": "Houve pois uma discussão dos Discípulos de João com os judeus sobre a purificação."}, {"numero": 26, "texto": "E vieram a João, e disseram-lhe: Rabi, aquele que estava contigo dalém do Jordão, ao qual tu deste testemunho, eis que batiza, e todos vem a ele."}, {"numero": 27, "texto": "João respondeu, e disse: O ser humano não pode receber coisa alguma, se não lhe for dada do céu."}, {"numero": 28, "texto": "Vós mesmos me sois testemunhas, que disse: Eu não sou o Cristo; mas que sou enviado diante dele."}, {"numero": 29, "texto": "Aquele que tem a esposa, é o esposo; mas o amigo do esposo, que [o] apoia, e lhe ouve, alegra-se muito pela voz do esposo. Assim pois já este meu gozo é cumprido."}, {"numero": 30, "texto": "A ele convém crescer, porém a mim diminuir."}, {"numero": 31, "texto": "Aquele que vem de cima, é sobre todos; aquele que [vem] da terra, da terra é, e da terra fala. Aquele que vem do céu é sobre todos."}, {"numero": 32, "texto": "E daquilo que viu e ouviu, isto testemunha; e ninguém aceita seu testemunho."}, {"numero": 33, "texto": "Aquele que aceitou seu testemunho, esse selou que Deus é verdadeiro."}, {"numero": 34, "texto": "Porque aquele que Deus enviou, as palavras de Deus fala; porque não [lhe] dá Deus o Espírito por medida."}, {"numero": 35, "texto": "O Pai ama ao Filho, e todas as coisas [lhe] deu em sua mão."}, {"numero": 36, "texto": "Aquele que crê no Filho tem vida eterna; porém aquele que é desobediente ao Filho não verá a vida [eterna] , mas a ira de Deus continua sobre ele."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 3, 'en', '[{"numero": 1, "texto": "There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:"}, {"numero": 2, "texto": "The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him."}, {"numero": 3, "texto": "Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God."}, {"numero": 4, "texto": "Nicodemus saith unto him, How can a man be born when he is old? can he enter the second time into his mother''s womb, and be born?"}, {"numero": 5, "texto": "Jesus answered, Verily, verily, I say unto thee, Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God."}, {"numero": 6, "texto": "That which is born of the flesh is flesh; and that which is born of the Spirit is spirit."}, {"numero": 7, "texto": "Marvel not that I said unto thee, Ye must be born again."}, {"numero": 8, "texto": "The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit."}, {"numero": 9, "texto": "Nicodemus answered and said unto him, How can these things be?"}, {"numero": 10, "texto": "Jesus answered and said unto him, Art thou a master of Israel, and knowest not these things?"}, {"numero": 11, "texto": "Verily, verily, I say unto thee, We speak that we do know, and testify that we have seen; and ye receive not our witness."}, {"numero": 12, "texto": "If I have told you earthly things, and ye believe not, how shall ye believe, if I tell you of heavenly things?"}, {"numero": 13, "texto": "And no man hath ascended up to heaven, but he that came down from heaven, even the Son of man which is in heaven."}, {"numero": 14, "texto": "And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up:"}, {"numero": 15, "texto": "That whosoever believeth in him should not perish, but have eternal life."}, {"numero": 16, "texto": "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."}, {"numero": 17, "texto": "For God sent not his Son into the world to condemn the world; but that the world through him might be saved."}, {"numero": 18, "texto": "He that believeth on him is not condemned: but he that believeth not is condemned already, because he hath not believed in the name of the only begotten Son of God."}, {"numero": 19, "texto": "And this is the condemnation, that light is come into the world, and men loved darkness rather than light, because their deeds were evil."}, {"numero": 20, "texto": "For every one that doeth evil hateth the light, neither cometh to the light, lest his deeds should be reproved."}, {"numero": 21, "texto": "But he that doeth truth cometh to the light, that his deeds may be made manifest, that they are wrought in God."}, {"numero": 22, "texto": "After these things came Jesus and his disciples into the land of Judaea; and there he tarried with them, and baptized."}, {"numero": 23, "texto": "And John also was baptizing in Aenon near to Salim, because there was much water there: and they came, and were baptized."}, {"numero": 24, "texto": "For John was not yet cast into prison."}, {"numero": 25, "texto": "Then there arose a question between some of John''s disciples and the Jews about purifying."}, {"numero": 26, "texto": "And they came unto John, and said unto him, Rabbi, he that was with thee beyond Jordan, to whom thou barest witness, behold, the same baptizeth, and all men come to him."}, {"numero": 27, "texto": "John answered and said, A man can receive nothing, except it be given him from heaven."}, {"numero": 28, "texto": "Ye yourselves bear me witness, that I said, I am not the Christ, but that I am sent before him."}, {"numero": 29, "texto": "He that hath the bride is the bridegroom: but the friend of the bridegroom, which standeth and heareth him, rejoiceth greatly because of the bridegroom''s voice: this my joy therefore is fulfilled."}, {"numero": 30, "texto": "He must increase, but I must decrease."}, {"numero": 31, "texto": "He that cometh from above is above all: he that is of the earth is earthly, and speaketh of the earth: he that cometh from heaven is above all."}, {"numero": 32, "texto": "And what he hath seen and heard, that he testifieth; and no man receiveth his testimony."}, {"numero": 33, "texto": "He that hath received his testimony hath set to his seal that God is true."}, {"numero": 34, "texto": "For he whom God hath sent speaketh the words of God: for God giveth not the Spirit by measure unto him."}, {"numero": 35, "texto": "The Father loveth the Son, and hath given all things into his hand."}, {"numero": 36, "texto": "He that believeth on the Son hath everlasting life: and he that believeth not the Son shall not see life; but the wrath of God abideth on him."}]'::jsonb, 'King James Version'),
  ('Jo', 3, 'fr', '[{"numero": 1, "texto": "Mais il y eut un homme d''''entre les pharisiens, nommé Nicodème, un chef des Juifs,"}, {"numero": 2, "texto": "qui vint, lui, auprès de Jésus, de nuit, et lui dit: Rabbi, nous savons que tu es un docteur venu de Dieu; car personne ne peut faire ces miracles que tu fais, si Dieu n''''est avec lui."}, {"numero": 3, "texto": "Jésus lui répondit: En vérité, en vérité, je te le dis, si un homme ne naît de nouveau, il ne peut voir le royaume de Dieu."}, {"numero": 4, "texto": "Nicodème lui dit: Comment un homme peut-il naître quand il est vieux? Peut-il rentrer dans le sein de sa mère et naître?"}, {"numero": 5, "texto": "Jésus répondit: En vérité, en vérité, je te le dis, si un homme ne naît d''''eau et d''''Esprit, il ne peut entrer dans le royaume de Dieu."}, {"numero": 6, "texto": "Ce qui est né de la chair est chair, et ce qui est né de l''''Esprit est esprit."}, {"numero": 7, "texto": "Ne t''''étonne pas que je t''''aie dit: Il faut que vous naissiez de nouveau."}, {"numero": 8, "texto": "Le vent souffle où il veut, et tu en entends le bruit; mais tu ne sais d''''où il vient, ni où il va. Il en est ainsi de tout homme qui est né de l''''Esprit."}, {"numero": 9, "texto": "Nicodème lui dit: Comment cela peut-il se faire?"}, {"numero": 10, "texto": "Jésus lui répondit: Tu es le docteur d''''Israël, et tu ne sais pas ces choses!"}, {"numero": 11, "texto": "En vérité, en vérité, je te le dis, nous disons ce que nous savons, et nous rendons témoignage de ce que nous avons vu; et vous ne recevez pas notre témoignage."}, {"numero": 12, "texto": "Si vous ne croyez pas quand je vous ai parlé des choses terrestres, comment croirez-vous quand je vous parlerai des choses célestes?"}, {"numero": 13, "texto": "Personne n''''est monté au ciel, si ce n''''est celui qui est descendu du ciel, le Fils de l''''homme qui est dans le ciel."}, {"numero": 14, "texto": "Et comme Moïse éleva le serpent dans le désert, il faut de même que le Fils de l''''homme soit élevé,"}, {"numero": 15, "texto": "afin que quiconque croit en lui ait la vie éternelle."}, {"numero": 16, "texto": "Car Dieu a tant aimé le monde qu''''il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu''''il ait la vie éternelle."}, {"numero": 17, "texto": "Dieu, en effet, n''''a pas envoyé son Fils dans le monde pour qu''''il juge le monde, mais pour que le monde soit sauvé par lui."}, {"numero": 18, "texto": "Celui qui croit en lui n''''est point jugé; mais celui qui ne croit pas est déjà jugé, parce qu''''il n''''a pas cru au nom du Fils unique de Dieu."}, {"numero": 19, "texto": "Et ce jugement c''''est que, la lumière étant venue dans le monde, les hommes ont préféré les ténèbres à la lumière, parce que leurs oeuvres étaient mauvaises."}, {"numero": 20, "texto": "Car quiconque fait le mal hait la lumière, et ne vient point à la lumière, de peur que ses oeuvres ne soient dévoilées;"}, {"numero": 21, "texto": "mais celui qui agit selon la vérité vient à la lumière, afin que ses oeuvres soient manifestées, parce qu''''elles sont faites en Dieu."}, {"numero": 22, "texto": "Après cela, Jésus, accompagné de ses disciples, se rendit dans la terre de Judée; et là il demeurait avec eux, et il baptisait."}, {"numero": 23, "texto": "Jean aussi baptisait à Enon, près de Salim, parce qu''''il y avait là beaucoup d''''eau; et on y venait pour être baptisé."}, {"numero": 24, "texto": "Car Jean n''''avait pas encore été mis en prison."}, {"numero": 25, "texto": "Or, il s''''éleva de la part des disciples de Jean une dispute avec un Juif touchant la purification."}, {"numero": 26, "texto": "Ils vinrent trouver Jean, et lui dirent: Rabbi, celui qui était avec toi au delà du Jourdain, et à qui tu as rendu témoignage, voici, il baptise, et tous vont à lui."}, {"numero": 27, "texto": "Jean répondit: Un homme ne peut recevoir que ce qui lui a été donné du ciel."}, {"numero": 28, "texto": "Vous-mêmes m''''êtes témoins que j''''ai dit: Je ne suis pas le Christ, mais j''''ai été envoyé devant lui."}, {"numero": 29, "texto": "Celui à qui appartient l''''épouse, c''''est l''''époux; mais l''''ami de l''''époux, qui se tient là et qui l''''entend, éprouve une grande joie à cause de la voix de l''''époux: aussi cette joie, qui est la mienne, est parfaite."}, {"numero": 30, "texto": "Il faut qu''''il croisse, et que je diminue."}, {"numero": 31, "texto": "Celui qui vient d''''en haut est au-dessus de tous; celui qui est de la terre est de la terre, et il parle comme étant de la terre. Celui qui vient du ciel est au-dessus de tous,"}, {"numero": 32, "texto": "il rend témoignage de ce qu''''il a vu et entendu, et personne ne reçoit son témoignage."}, {"numero": 33, "texto": "Celui qui a reçu son témoignage a certifié que Dieu est vrai;"}, {"numero": 34, "texto": "car celui que Dieu a envoyé dit les paroles de Dieu, parce que Dieu ne lui donne pas l''''Esprit avec mesure."}, {"numero": 35, "texto": "Le Père aime le Fils, et il a remis toutes choses entre ses mains."}, {"numero": 36, "texto": "Celui qui croit au Fils a la vie éternelle; celui qui ne croit pas au Fils ne verra point la vie, mais la colère de Dieu demeure sur lui."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 3, 'es', '[{"numero": 1, "texto": "Y HABÍA un hombre de los Fariseos que se llamaba Nicodemo, príncipe de los Judíos."}, {"numero": 2, "texto": "Este vino á Jesús de noche, y díjole: Rabbí, sabemos que has venido de Dios por maestro; porque nadie puede hacer estas señales que tú haces, si no fuere Dios con él."}, {"numero": 3, "texto": "Respondió Jesús, y díjole: De cierto, de cierto te digo, que el que no naciere otra vez, no puede ver el reino de Dios."}, {"numero": 4, "texto": "Dícele Nicodemo: ¿Cómo puede el hombre nacer siendo viejo? ¿puede entrar otra vez en el vientre de su madre, y nacer?"}, {"numero": 5, "texto": "Respondió Jesús: De cierto, de cierto te digo, que el que no naciere de agua y del Espíritu, no puede entrar en el reino de Dios."}, {"numero": 6, "texto": "Lo que es nacido de la carne, carne es; y lo que es nacido del Espíritu, espíritu es."}, {"numero": 7, "texto": "No te maravilles de que te dije: Os es necesario nacer otra vez."}, {"numero": 8, "texto": "El viento de donde quiere sopla, y oyes su sonido; mas ni sabes de dónde viene, ni á dónde vaya: así es todo aquel que es nacido del Espíritu."}, {"numero": 9, "texto": "Respondió Nicodemo, y díjole: ¿Cómo puede esto hacerse?"}, {"numero": 10, "texto": "Respondió Jesús, y díjole: ¿Tú eres el maestro de Israel, y no sabes esto?"}, {"numero": 11, "texto": "De cierto, de cierto te digo, que lo que sabemos hablamos, y lo que hemos visto, testificamos; y no recibís nuestro testimonio."}, {"numero": 12, "texto": "Si os he dicho cosas terrenas, y no creéis, ¿cómo creeréis si os dijere las celestiales?"}, {"numero": 13, "texto": "Y nadie subió al cielo, sino el que descendió del cielo, el Hijo del hombre, que está en el cielo."}, {"numero": 14, "texto": "Y como Moisés levantó la serpiente en el desierto, así es necesario que el Hijo del hombre sea levantado;"}, {"numero": 15, "texto": "Para que todo aquel que en él creyere, no se pierda, sino que tenga vida eterna."}, {"numero": 16, "texto": "Porque de tal manera amó Dios al mundo, que ha dado á su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna."}, {"numero": 17, "texto": "Porque no envió Dios á su Hijo al mundo para que condene al mundo, mas para que el mundo sea salvo por él."}, {"numero": 18, "texto": "El que en él cree, no es condenado; mas el que no cree, ya es condenado, porque no creyó en el nombre del unigénito Hijo de Dios."}, {"numero": 19, "texto": "Y esta es la condenación: porque la luz vino al mundo, y los hombres amaron más las tinieblas que la luz; porque sus obras eran malas."}, {"numero": 20, "texto": "Porque todo aquel que hace lo malo, aborrece la luz y no viene á la luz, porque sus obras no sean redargüidas."}, {"numero": 21, "texto": "Mas el que obra verdad, viene á la luz, para que sus obras sean manifestadas que son hechas en Dios."}, {"numero": 22, "texto": "Pasado esto, vino Jesús con sus discípulos á la tierra de Judea; y estaba allí con ellos, y bautizaba."}, {"numero": 23, "texto": "Y bautizaba también Juan en Enón junto á Salim, porque había allí muchas aguas; y venían, y eran bautizados."}, {"numero": 24, "texto": "Porque Juan no había sido aún puesto en la carcel."}, {"numero": 25, "texto": "Y hubo cuestión entre los discípulos de Juan y los Judíos acerca de la purificación."}, {"numero": 26, "texto": "Y vinieron á Juan, y dijéronle: Rabbí, el que estaba contigo de la otra parte del Jordán, del cual tú diste testimonio, he aquí bautiza, y todos vienen á él."}, {"numero": 27, "texto": "Respondió Juan, y dijo: No puede el hombre recibir algo, si no le fuere dado del cielo."}, {"numero": 28, "texto": "Vosotros mismos me sois testigos que dije: Yo no soy el Cristo, sino que soy enviado delante de él."}, {"numero": 29, "texto": "El que tiene la esposa, es el esposo; mas el amigo del esposo, que está en pie y le oye, se goza grandemente de la voz del esposo; así pues, este mi gozo es cumplido."}, {"numero": 30, "texto": "A él conviene crecer, mas á mí menguar."}, {"numero": 31, "texto": "El que de arriba viene, sobre todos es: el que es de la tierra, terreno es, y cosas terrenas habla: el que viene del cielo, sobre todos es."}, {"numero": 32, "texto": "Y lo que vió y oyó, esto testifica: y nadie recibe su testimonio."}, {"numero": 33, "texto": "El que recibe su testimonio, éste signó que Dios es verdadero."}, {"numero": 34, "texto": "Porque el que Dios envió, las palabras de Dios habla: porque no da Dios el Espíritu por medida."}, {"numero": 35, "texto": "El Padre ama al Hijo, y todas las cosas dió en su mano."}, {"numero": 36, "texto": "El que cree en el Hijo, tiene vida eterna; mas el que es incrédulo al Hijo, no verá la vida, sino que la ira de Dios está sobre él."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 4, 'pt', '[{"numero": 1, "texto": "Quando, pois, o Senhor entendeu que os fariseus ouviram que Jesus fazia e batizava mais discípulos que João"}, {"numero": 2, "texto": "(ainda que Jesus mesmo não batizava, mas sim seus discípulos),"}, {"numero": 3, "texto": "Ele deixou a Judeia, e foi outra vez para a Galileia."}, {"numero": 4, "texto": "E foi necessário passar por Samaria."}, {"numero": 5, "texto": "Veio pois a uma cidade de Samaria, chamada Sicar, junto à propriedade que Jacó deu a seu filho José."}, {"numero": 6, "texto": "E ali estava a fonte de Jacó. Então Jesus, cansado do caminho, sentou-se assim junto à fonte; era isto quase à hora sexta."}, {"numero": 7, "texto": "Veio uma mulher de Samaria para tirar água; Disse-lhe Jesus: Dá-me de beber."}, {"numero": 8, "texto": "(Porque seus discípulos haviam ido à cidade para a comprar de comer)."}, {"numero": 9, "texto": "Disse-lhe pois a mulher samaritana: Como, sendo tu judeu, me pedes de beber, que sou mulher samaritana? (Porque os judeus não se comunicam com o samaritanos.)"}, {"numero": 10, "texto": "Respondeu Jesus, e disse-lhe: Se tu conhecesses o dom de Deus, e quem é o que te diz: Dá-me de beber, tu lhe pedirias, e ele te daria água viva."}, {"numero": 11, "texto": "Disse a mulher: Senhor, tu não tens com que [a] tirar, e o poço é fundo; de onde pois tens a água viva?"}, {"numero": 12, "texto": "És tu maior que nosso pai Jacó, que nos deu o poço? E ele mesmo dele bebeu, e seus filhos, e seu gado?"}, {"numero": 13, "texto": "Jesus respondeu, e disse-lhe: Todo aquele que beber desta água voltará a ter sede;"}, {"numero": 14, "texto": "Porém aquele que beber da água que eu lhe der, para sempre não terá sede, mas a água que eu lhe der se fará nele fonte de água, que salte para vida eterna."}, {"numero": 15, "texto": "Disse-lhe a mulher: Senhor, dá-me desta água, para que eu não tenha [mais] sede, nem venha aqui para tirar."}, {"numero": 16, "texto": "Disse-lhe Jesus: Vai, chama a teu marido, e vem cá."}, {"numero": 17, "texto": "A mulher respondeu, e disse: Não tenho marido. Disse-lhe Jesus: Bem disseste: Marido não tenho."}, {"numero": 18, "texto": "Porque cinco maridos tiveste, e o que agora tens não é teu marido; isto com verdade disseste."}, {"numero": 19, "texto": "Disse-lhe a mulher: Senhor, vejo que és profeta."}, {"numero": 20, "texto": "Nossos pais adoraram neste monte, e vós dizeis que em Jerusalém é o lugar onde se deve adorar."}, {"numero": 21, "texto": "Disse-lhe Jesus: Mulher, crê em mim, que a hora vem, quando nem neste monte, nem em Jerusalém, adorareis ao Pai."}, {"numero": 22, "texto": "Vós adorais o que não sabeis; nós adoramos o que sabemos, porque a salvação vem dos judeus."}, {"numero": 23, "texto": "Porém a hora vem, e agora é, quando os verdadeiros adoradores adorarão ao Pai em espírito e em verdade; porque também o Pai busca a tais que o adorem."}, {"numero": 24, "texto": "Deus é Espírito, e os que o adoram devem adorá [-lo] em espírito e em verdade."}, {"numero": 25, "texto": "Disse-lhe a mulher: Eu sei que o Messias vem (que se chama o Cristo); quando ele vier, todas as coisas nos anunciará."}, {"numero": 26, "texto": "Disse-lhe Jesus: Eu sou o que contigo falo."}, {"numero": 27, "texto": "E nisto vieram seus discípulos; e maravilharam-se de que falasse com uma mulher; mas ninguém [lhe] disse: Que perguntas? ou, O que falas com ela?"}, {"numero": 28, "texto": "Deixou, pois, a mulher seu vaso de água, e foi à cidade, e disse ao povo:"}, {"numero": 29, "texto": "Vinde, vede um homem que me disse tudo quanto tenho feito; por acaso não é este o Cristo?"}, {"numero": 30, "texto": "Saíram, pois, da cidade, e vieram a ele."}, {"numero": 31, "texto": "E enquanto isso, os discípulos lhe pediam, dizendo: Rabi, come."}, {"numero": 32, "texto": "Porém ele lhes disse: Uma comida tenho que comer, que vós não sabeis."}, {"numero": 33, "texto": "Diziam, pois, os discípulos uns aos outros: Por acaso alguém lhe trouxe de comer?"}, {"numero": 34, "texto": "Disse-lhes Jesus: Minha comida é fazer a vontade daquele que me enviou, e cumprir sua obra."}, {"numero": 35, "texto": "Não dizeis vós, que ainda há quatro meses até que venha a ceifa? Eis que vos digo: Levantai vossos olhos, e vede as terras; porque já estão brancas para a ceifa."}, {"numero": 36, "texto": "E o que ceifa, recebe recompensa, e junta fruto para vida eterna; para que ambos se alegrem, tanto o que semeia, quanto o que ceifa."}, {"numero": 37, "texto": "Porque nisto é verdadeiro o ditado, que: Um é o que semeia, e outro o que ceifa."}, {"numero": 38, "texto": "Eu vos enviei para ceifar onde vós não trabalhastes; outros trabalharam, e vós entrastes no trabalho deles."}, {"numero": 39, "texto": "E muitos dos samaritanos daquela cidade creram nele pela palavra da mulher, que testemunhava, dizendo: Ele me disse tudo quanto eu tenho feito."}, {"numero": 40, "texto": "Vindo pois os samaritanos a ele, suplicaram-lhe que ficasse com eles; e ele ficou ali dois dias."}, {"numero": 41, "texto": "E creram ainda muitos mais pela palavra dele."}, {"numero": 42, "texto": "E diziam à mulher: Já não cremos por teu dito; porque nós mesmos temos [o] ouvido, e sabemos que verdadeiramente este é o Cristo, o Salvador do mundo."}, {"numero": 43, "texto": "E depois de dois dias partiu dali, e foi-se para a Galileia."}, {"numero": 44, "texto": "Porque o mesmo Jesus testemunhou que não tem o Profeta honra em sua própria terra."}, {"numero": 45, "texto": "Vindo pois para a Galileia, os Galileus o receberam, havendo visto todas as coisas que fizera em Jerusalém no [dia] da festa, porque também eles foram ao [dia] da festa."}, {"numero": 46, "texto": "Veio pois Jesus outra vez a Caná da Galileia, onde da água fizera vinho. E estava ali um nobre, cujo filho estava enfermo em Cafarnaum."}, {"numero": 47, "texto": "Ouvindo este que Jesus vinha da Judeia para a Galileia, foi ter com ele, e suplicava-lhe que descesse, e curasse a seu filho, porque já estava à morte."}, {"numero": 48, "texto": "Disse-lhe pois Jesus: Se não virdes sinais e milagres não crereis."}, {"numero": 49, "texto": "O nobre lhe disse: Senhor, desce, antes que meu filho morra."}, {"numero": 50, "texto": "Disse-lhe Jesus: Vai, teu filho vive. E o homem creu na palavra que Jesus lhe disse, e se foi."}, {"numero": 51, "texto": "E [estando] ele já descendo, seus servos lhe saíram ao encontro, e [lhe] anunciaram, dizendo: Teu filho vive."}, {"numero": 52, "texto": "Perguntou-lhes pois, a que hora se achara melhor; e disseram-lhe: Ontem às sete horas a febre o deixou."}, {"numero": 53, "texto": "Entendeu pois o pai, que aquela era a mesma hora em que Jesus lhe disse: Teu filho vive. E creu nele, e toda sua casa."}, {"numero": 54, "texto": "Este segundo sinal Jesus voltou a fazer, quando ele veio d [a] Judeia a Galileia."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 4, 'en', '[{"numero": 1, "texto": "When therefore the Lord knew how the Pharisees had heard that Jesus made and baptized more disciples than John,"}, {"numero": 2, "texto": "(Though Jesus himself baptized not, but his disciples,)"}, {"numero": 3, "texto": "He left Judaea, and departed again into Galilee."}, {"numero": 4, "texto": "And he must needs go through Samaria."}, {"numero": 5, "texto": "Then cometh he to a city of Samaria, which is called Sychar, near to the parcel of ground that Jacob gave to his son Joseph."}, {"numero": 6, "texto": "Now Jacob''s well was there. Jesus therefore, being wearied with his journey, sat thus on the well: and it was about the sixth hour."}, {"numero": 7, "texto": "There cometh a woman of Samaria to draw water: Jesus saith unto her, Give me to drink."}, {"numero": 8, "texto": "(For his disciples were gone away unto the city to buy meat.)"}, {"numero": 9, "texto": "Then saith the woman of Samaria unto him, How is it that thou, being a Jew, askest drink of me, which am a woman of Samaria? for the Jews have no dealings with the Samaritans."}, {"numero": 10, "texto": "Jesus answered and said unto her, If thou knewest the gift of God, and who it is that saith to thee, Give me to drink; thou wouldest have asked of him, and he would have given thee living water."}, {"numero": 11, "texto": "The woman saith unto him, Sir, thou hast nothing to draw with, and the well is deep: from whence then hast thou that living water?"}, {"numero": 12, "texto": "Art thou greater than our father Jacob, which gave us the well, and drank thereof himself, and his children, and his cattle?"}, {"numero": 13, "texto": "Jesus answered and said unto her, Whosoever drinketh of this water shall thirst again:"}, {"numero": 14, "texto": "But whosoever drinketh of the water that I shall give him shall never thirst; but the water that I shall give him shall be in him a well of water springing up into everlasting life."}, {"numero": 15, "texto": "The woman saith unto him, Sir, give me this water, that I thirst not, neither come hither to draw."}, {"numero": 16, "texto": "Jesus saith unto her, Go, call thy husband, and come hither."}, {"numero": 17, "texto": "The woman answered and said, I have no husband. Jesus said unto her, Thou hast well said, I have no husband:"}, {"numero": 18, "texto": "For thou hast had five husbands; and he whom thou now hast is not thy husband: in that saidst thou truly."}, {"numero": 19, "texto": "The woman saith unto him, Sir, I perceive that thou art a prophet."}, {"numero": 20, "texto": "Our fathers worshipped in this mountain; and ye say, that in Jerusalem is the place where men ought to worship."}, {"numero": 21, "texto": "Jesus saith unto her, Woman, believe me, the hour cometh, when ye shall neither in this mountain, nor yet at Jerusalem, worship the Father."}, {"numero": 22, "texto": "Ye worship ye know not what: we know what we worship: for salvation is of the Jews."}, {"numero": 23, "texto": "But the hour cometh, and now is, when the true worshippers shall worship the Father in spirit and in truth: for the Father seeketh such to worship him."}, {"numero": 24, "texto": "God is a Spirit: and they that worship him must worship him in spirit and in truth."}, {"numero": 25, "texto": "The woman saith unto him, I know that Messias cometh, which is called Christ: when he is come, he will tell us all things."}, {"numero": 26, "texto": "Jesus saith unto her, I that speak unto thee am he."}, {"numero": 27, "texto": "And upon this came his disciples, and marvelled that he talked with the woman: yet no man said, What seekest thou? or, Why talkest thou with her?"}, {"numero": 28, "texto": "The woman then left her waterpot, and went her way into the city, and saith to the men,"}, {"numero": 29, "texto": "Come, see a man, which told me all things that ever I did: is not this the Christ?"}, {"numero": 30, "texto": "Then they went out of the city, and came unto him."}, {"numero": 31, "texto": "In the mean while his disciples prayed him, saying, Master, eat."}, {"numero": 32, "texto": "But he said unto them, I have meat to eat that ye know not of."}, {"numero": 33, "texto": "Therefore said the disciples one to another, Hath any man brought him ought to eat?"}, {"numero": 34, "texto": "Jesus saith unto them, My meat is to do the will of him that sent me, and to finish his work."}, {"numero": 35, "texto": "Say not ye, There are yet four months, and then cometh harvest? behold, I say unto you, Lift up your eyes, and look on the fields; for they are white already to harvest."}, {"numero": 36, "texto": "And he that reapeth receiveth wages, and gathereth fruit unto life eternal: that both he that soweth and he that reapeth may rejoice together."}, {"numero": 37, "texto": "And herein is that saying true, One soweth, and another reapeth."}, {"numero": 38, "texto": "I sent you to reap that whereon ye bestowed no labour: other men laboured, and ye are entered into their labours."}, {"numero": 39, "texto": "And many of the Samaritans of that city believed on him for the saying of the woman, which testified, He told me all that ever I did."}, {"numero": 40, "texto": "So when the Samaritans were come unto him, they besought him that he would tarry with them: and he abode there two days."}, {"numero": 41, "texto": "And many more believed because of his own word;"}, {"numero": 42, "texto": "And said unto the woman, Now we believe, not because of thy saying: for we have heard him ourselves, and know that this is indeed the Christ, the Saviour of the world."}, {"numero": 43, "texto": "Now after two days he departed thence, and went into Galilee."}, {"numero": 44, "texto": "For Jesus himself testified, that a prophet hath no honour in his own country."}, {"numero": 45, "texto": "Then when he was come into Galilee, the Galilaeans received him, having seen all the things that he did at Jerusalem at the feast: for they also went unto the feast."}, {"numero": 46, "texto": "So Jesus came again into Cana of Galilee, where he made the water wine. And there was a certain nobleman, whose son was sick at Capernaum."}, {"numero": 47, "texto": "When he heard that Jesus was come out of Judaea into Galilee, he went unto him, and besought him that he would come down, and heal his son: for he was at the point of death."}, {"numero": 48, "texto": "Then said Jesus unto him, Except ye see signs and wonders, ye will not believe."}, {"numero": 49, "texto": "The nobleman saith unto him, Sir, come down ere my child die."}, {"numero": 50, "texto": "Jesus saith unto him, Go thy way; thy son liveth. And the man believed the word that Jesus had spoken unto him, and he went his way."}, {"numero": 51, "texto": "And as he was now going down, his servants met him, and told him, saying, Thy son liveth."}, {"numero": 52, "texto": "Then enquired he of them the hour when he began to amend. And they said unto him, Yesterday at the seventh hour the fever left him."}, {"numero": 53, "texto": "So the father knew that it was at the same hour, in the which Jesus said unto him, Thy son liveth: and himself believed, and his whole house."}, {"numero": 54, "texto": "This is again the second miracle that Jesus did, when he was come out of Judaea into Galilee."}]'::jsonb, 'King James Version'),
  ('Jo', 4, 'fr', '[{"numero": 1, "texto": "Le Seigneur sut que les pharisiens avaient appris qu''''il faisait et baptisait plus de disciples que Jean."}, {"numero": 2, "texto": "Toutefois Jésus ne baptisait pas lui-même, mais c''''étaient ses disciples."}, {"numero": 3, "texto": "Alors il quitta la Judée, et retourna en Galilée."}, {"numero": 4, "texto": "Comme il fallait qu''''il passât par la Samarie,"}, {"numero": 5, "texto": "il arriva dans une ville de Samarie, nommée Sychar, près du champ que Jacob avait donné à Joseph, son fils."}, {"numero": 6, "texto": "Là se trouvait le puits de Jacob. Jésus, fatigué du voyage, était assis au bord du puits. C''''était environ la sixième heure."}, {"numero": 7, "texto": "Une femme de Samarie vint puiser de l''''eau. Jésus lui dit: Donne-moi à boire."}, {"numero": 8, "texto": "Car ses disciples étaient allés à la ville pour acheter des vivres."}, {"numero": 9, "texto": "La femme samaritaine lui dit: Comment toi, qui es Juif, me demandes-tu à boire, à moi qui suis une femme samaritaine? -Les Juifs, en effet, n''''ont pas de relations avec les Samaritains. -"}, {"numero": 10, "texto": "Jésus lui répondit: Si tu connaissais le don de Dieu et qui est celui qui te dit: Donne-moi à boire! tu lui aurais toi-même demandé à boire, et il t''''aurait donné de l''''eau vive."}, {"numero": 11, "texto": "Seigneur, lui dit la femme, tu n''''as rien pour puiser, et le puits est profond; d''''où aurais-tu donc cette eau vive?"}, {"numero": 12, "texto": "Es-tu plus grand que notre père Jacob, qui nous a donné ce puits, et qui en a bu lui-même, ainsi que ses fils et ses troupeaux?"}, {"numero": 13, "texto": "Jésus lui répondit: Quiconque boit de cette eau aura encore soif;"}, {"numero": 14, "texto": "mais celui qui boira de l''''eau que je lui donnerai n''''aura jamais soif, et l''''eau que je lui donnerai deviendra en lui une source d''''eau qui jaillira jusque dans la vie éternelle."}, {"numero": 15, "texto": "La femme lui dit: Seigneur, donne-moi cette eau, afin que je n''''aie plus soif, et que je ne vienne plus puiser ici."}, {"numero": 16, "texto": "Va, lui dit Jésus, appelle ton mari, et viens ici."}, {"numero": 17, "texto": "La femme répondit: Je n''''ai point de mari. Jésus lui dit: Tu as eu raison de dire: Je n''''ai point de mari."}, {"numero": 18, "texto": "Car tu as eu cinq maris, et celui que tu as maintenant n''''est pas ton mari. En cela tu as dit vrai."}, {"numero": 19, "texto": "Seigneur, lui dit la femme, je vois que tu es prophète."}, {"numero": 20, "texto": "Nos pères ont adoré sur cette montagne; et vous dites, vous, que le lieu où il faut adorer est à Jérusalem."}, {"numero": 21, "texto": "Femme, lui dit Jésus, crois-moi, l''''heure vient où ce ne sera ni sur cette montagne ni à Jérusalem que vous adorerez le Père."}, {"numero": 22, "texto": "Vous adorez ce que vous ne connaissez pas; nous, nous adorons ce que nous connaissons, car le salut vient des Juifs."}, {"numero": 23, "texto": "Mais l''''heure vient, et elle est déjà venue, où les vrais adorateurs adoreront le Père en esprit et en vérité; car ce sont là les adorateurs que le Père demande."}, {"numero": 24, "texto": "Dieu est Esprit, et il faut que ceux qui l''''adorent l''''adorent en esprit et en vérité."}, {"numero": 25, "texto": "La femme lui dit: Je sais que le Messie doit venir celui qu''''on appelle Christ; quand il sera venu, il nous annoncera toutes choses."}, {"numero": 26, "texto": "Jésus lui dit: Je le suis, moi qui te parle."}, {"numero": 27, "texto": "Là-dessus arrivèrent ses disciples, qui furent étonnés de ce qu''''il parlait avec une femme. Toutefois aucun ne dit: Que demandes-tu? ou: De quoi parles-tu avec elle?"}, {"numero": 28, "texto": "Alors la femme, ayant laissé sa cruche, s''''en alla dans la ville, et dit aux gens:"}, {"numero": 29, "texto": "Venez voir un homme qui m''''a dit tout ce que j''''ai fait; ne serait-ce point le Christ?"}, {"numero": 30, "texto": "Ils sortirent de la ville, et ils vinrent vers lui."}, {"numero": 31, "texto": "Pendant ce temps, les disciples le pressaient de manger, disant: Rabbi, mange."}, {"numero": 32, "texto": "Mais il leur dit: J''''ai à manger une nourriture que vous ne connaissez pas."}, {"numero": 33, "texto": "Les disciples se disaient donc les uns aux autres: Quelqu''''un lui aurait-il apporté à manger?"}, {"numero": 34, "texto": "Jésus leur dit: Ma nourriture est de faire la volonté de celui qui m''''a envoyé, et d''''accomplir son oeuvre."}, {"numero": 35, "texto": "Ne dites-vous pas qu''''il y a encore quatre mois jusqu''''à la moisson? Voici, je vous le dis, levez les yeux, et regardez les champs qui déjà blanchissent pour la moisson."}, {"numero": 36, "texto": "Celui qui moissonne reçoit un salaire, et amasse des fruits pour la vie éternelle, afin que celui qui sème et celui qui moissonne se réjouissent ensemble."}, {"numero": 37, "texto": "Car en ceci ce qu''''on dit est vrai: Autre est celui qui sème, et autre celui qui moissonne."}, {"numero": 38, "texto": "Je vous ai envoyés moissonner ce que vous n''''avez pas travaillé; d''''autres ont travaillé, et vous êtes entrés dans leur travail."}, {"numero": 39, "texto": "Plusieurs Samaritains de cette ville crurent en Jésus à cause de cette déclaration formelle de la femme: Il m''''a dit tout ce que j''''ai fait."}, {"numero": 40, "texto": "Aussi, quand les Samaritains vinrent le trouver, ils le prièrent de rester auprès d''''eux. Et il resta là deux jours."}, {"numero": 41, "texto": "Un beaucoup plus grand nombre crurent à cause de sa parole;"}, {"numero": 42, "texto": "et ils disaient à la femme: Ce n''''est plus à cause de ce que tu as dit que nous croyons; car nous l''''avons entendu nous-mêmes, et nous savons qu''''il est vraiment le Sauveur du monde."}, {"numero": 43, "texto": "Après ces deux jours, Jésus partit de là, pour se rendre en Galilée;"}, {"numero": 44, "texto": "car il avait déclaré lui-même qu''''un prophète n''''est pas honoré dans sa propre patrie."}, {"numero": 45, "texto": "Lorsqu''''il arriva en Galilée, il fut bien reçu des Galiléens, qui avaient vu tout ce qu''''il avait fait à Jérusalem pendant la fête; car eux aussi étaient allés à la fête."}, {"numero": 46, "texto": "Il retourna donc à Cana en Galilée, où il avait changé l''''eau en vin. Il y avait à Capernaüm un officier du roi, dont le fils était malade."}, {"numero": 47, "texto": "Ayant appris que Jésus était venu de Judée en Galilée, il alla vers lui, et le pria de descendre et de guérir son fils, qui était près de mourir."}, {"numero": 48, "texto": "Jésus lui dit: Si vous ne voyez des miracles et des prodiges, vous ne croyez point."}, {"numero": 49, "texto": "L''''officier du roi lui dit: Seigneur, descends avant que mon enfant meure."}, {"numero": 50, "texto": "Va, lui dit Jésus, ton fils vit. Et cet homme crut à la parole que Jésus lui avait dite, et il s''''en alla."}, {"numero": 51, "texto": "Comme déjà il descendait, ses serviteurs venant à sa rencontre, lui apportèrent cette nouvelle: Ton enfant vit."}, {"numero": 52, "texto": "Il leur demanda à quelle heure il s''''était trouvé mieux; et ils lui dirent: Hier, à la septième heure, la fièvre l''''a quitté."}, {"numero": 53, "texto": "Le père reconnut que c''''était à cette heure-là que Jésus lui avait dit: Ton fils vit. Et il crut, lui et toute sa maison."}, {"numero": 54, "texto": "Jésus fit encore ce second miracle lorsqu''''il fut venu de Judée en Galilée."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 4, 'es', '[{"numero": 1, "texto": "DE manera que como Jesús entendió que los Fariseos habían oído que Jesús hacía y bautizaba más discípulos que Juan,"}, {"numero": 2, "texto": "(Aunque Jesús no bautizaba, sino sus discípulos),"}, {"numero": 3, "texto": "Dejó á Judea, y fuése otra vez á Galilea."}, {"numero": 4, "texto": "Y era menester que pasase por Samaria."}, {"numero": 5, "texto": "Vino, pues, á una ciudad de Samaria que se llamaba Sichâr, junto á la heredad que Jacob dió á José su hijo."}, {"numero": 6, "texto": "Y estaba allí la fuente de Jacob. Pues Jesús, cansado del camino, así se sentó á la fuente. Era como la hora de sexta."}, {"numero": 7, "texto": "Vino una mujer de Samaria á sacar agua: y Jesús le dice: Dame de beber."}, {"numero": 8, "texto": "(Porque sus discípulos habían ido á la ciudad á comprar de comer.)"}, {"numero": 9, "texto": "Y la mujer Samaritana le dice: ¿Cómo tú, siendo Judío, me pides á mí de beber, que soy mujer Samaritana? porque los Judíos no se tratan con los Samaritanos."}, {"numero": 10, "texto": "Respondió Jesús y díjole: Si conocieses el don de Dios, y quién es el que te dice: Dame de beber: tú pedirías de él, y él te daría agua viva."}, {"numero": 11, "texto": "La mujer le dice: Señor, no tienes con qué sacarla, y el pozo es hondo: ¿de dónde, pues, tienes el agua viva?"}, {"numero": 12, "texto": "¿Eres tú mayor que nuestro padre Jacob, que nos dió este pozo, del cual él bebió, y sus hijos, y sus ganados?"}, {"numero": 13, "texto": "Respondió Jesús y díjole: Cualquiera que bebiere de esta agua, volverá á tener sed;"}, {"numero": 14, "texto": "Mas el que bebiere del agua que yo le daré, para siempre no tendrá sed: mas el agua que yo le daré, será en él una fuente de agua que salte para vida eterna."}, {"numero": 15, "texto": "La mujer le dice: Señor, dame esta agua, para que no tenga sed, ni venga acá á sacarla."}, {"numero": 16, "texto": "Jesús le dice: Ve, llama á tu marido, y ven acá."}, {"numero": 17, "texto": "Respondió la mujer, y dijo: No tengo marido. Dícele Jesús: Bien has dicho, No tengo marido;"}, {"numero": 18, "texto": "Porque cinco maridos has tenido: y el que ahora tienes no es tu marido; esto has dicho con verdad."}, {"numero": 19, "texto": "Dícele la mujer: Señor, paréceme que tú eres profeta."}, {"numero": 20, "texto": "Nuestros padres adoraron en este monte, y vosotros decís que en Jerusalem es el lugar donde es necesario adorar."}, {"numero": 21, "texto": "Dícele Jesús: Mujer, créeme, que la hora viene, cuando ni en este monte, ni en Jerusalem adoraréis al Padre."}, {"numero": 22, "texto": "Vosotros adoráis lo que no sabéis; nosotros adoramos lo que sabemos: porque la salud viene de los Judíos."}, {"numero": 23, "texto": "Mas la hora viene, y ahora es, cuando los verdaderos adoradores adorarán al Padre en espíritu y en verdad; porque también el Padre tales adoradores busca que le adoren."}, {"numero": 24, "texto": "Dios es Espíritu; y los que le adoran, en espíritu y en verdad es necesario que adoren."}, {"numero": 25, "texto": "Dícele la mujer: Sé que el Mesías ha de venir, el cual se dice el Cristo: cuando él viniere nos declarará todas las cosas."}, {"numero": 26, "texto": "Dícele Jesús: Yo soy, que hablo contigo."}, {"numero": 27, "texto": "Y en esto vinieron sus discípulos, y maravilláronse de que hablaba con mujer; mas ninguno dijo: ¿Qué preguntas? ó, ¿Qué hablas con ella?"}, {"numero": 28, "texto": "Entonces la mujer dejó su cántaro, y fué á la ciudad, y dijo á aquellos hombres:"}, {"numero": 29, "texto": "Venid, ved un hombre que me ha dicho todo lo que he hecho: ¿si quizás es éste el Cristo?"}, {"numero": 30, "texto": "Entonces salieron de la ciudad, y vinieron á él."}, {"numero": 31, "texto": "Entre tanto los discípulos le rogaban, diciendo: Rabbí, come."}, {"numero": 32, "texto": "Y él les dijo: Yo tengo una comida que comer, que vosotros no sabéis."}, {"numero": 33, "texto": "Entonces los discípulos decían el uno al otro: ¿Si le habrá traído alguien de comer?"}, {"numero": 34, "texto": "Díceles Jesús: Mi comida es que haga la voluntad del que me envió, y que acabe su obra."}, {"numero": 35, "texto": "¿No decís vosotros: Aun hay cuatro meses hasta que llegue la siega? He aquí os digo: Alzad vuestros ojos, y mirad las regiones, porque ya están blancas para la siega."}, {"numero": 36, "texto": "Y el que siega, recibe salario, y allega fruto para vida eterna; para que el que siembra también goce, y el que siega."}, {"numero": 37, "texto": "Porque en esto es el dicho verdadero: Que uno es el que siembra, y otro es el que siega."}, {"numero": 38, "texto": "Yo os he enviado á segar lo que vosotros no labrasteis: otros labraron, y vosotros habéis entrado en sus labores."}, {"numero": 39, "texto": "Y muchos de los Samaritanos de aquella ciudad creyeron en él por la palabra de la mujer, que daba testimonio, diciendo: Que me dijo todo lo que he hecho."}, {"numero": 40, "texto": "Viniendo pues los Samaritanos á él, rogáronle que se quedase allí: y se quedó allí dos días."}, {"numero": 41, "texto": "Y creyeron muchos más por la palabra de él."}, {"numero": 42, "texto": "Y decían á la mujer: Ya no creemos por tu dicho; porque nosotros mismos hemos oído, y sabemos que verdaderamente éste es el Salvador del mundo, el Cristo."}, {"numero": 43, "texto": "Y dos días después, salió de allí, y fuése á Galilea."}, {"numero": 44, "texto": "Porque el mismo Jesús dió testimonio de que el profeta en su tierra no tiene honra."}, {"numero": 45, "texto": "Y como vino á Galilea, los Galileos le recibieron, vistas todas las cosas que había hecho en Jerusalem en el día de la fiesta: porque también ellos habían ido á la fiesta."}, {"numero": 46, "texto": "Vino pues Jesús otra vez á Caná de Galilea, donde había hecho el vino del agua. Y había en Capernaum uno del rey, cuyo hijo estaba enfermo."}, {"numero": 47, "texto": "Este, como oyó que Jesús venía de Judea á Galilea, fué á él, y rogábale que descendiese, y sanase á su hijo, porque se comenzaba á morir."}, {"numero": 48, "texto": "Entonces Jesús le dijo: Si no viereis señales y milagros no creeréis."}, {"numero": 49, "texto": "El del rey le dijo: Señor, desciende antes que mi hijo muera."}, {"numero": 50, "texto": "Dícele Jesús: Ve, tu hijo vive. Y el hombre creyó á la palabra que Jesús le dijo, y se fué."}, {"numero": 51, "texto": "Y cuando ya él descendía, los siervos le salieron á recibir, y le dieron nuevas, diciendo: Tu hijo vive."}, {"numero": 52, "texto": "Entonces él les preguntó á qué hora comenzó á estar mejor. Y dijéronle: Ayer á las siete le dejó la fiebre."}, {"numero": 53, "texto": "El padre entonces entendió, que aquella hora era cuando Jesús le dijo: Tu hijo vive; y creyó él y toda su casa."}, {"numero": 54, "texto": "Esta segunda señal volvió Jesús á hacer, cuando vino de Judea á Galilea."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 5, 'pt', '[{"numero": 1, "texto": "Depois disto houve uma festa dos judeus, e subiu Jesus para Jerusalém."}, {"numero": 2, "texto": "E há em Jerusalém à [porta] das ovelhas um tanque, que em hebraico se chama Betesda, que tem cinco entradas cobertas."}, {"numero": 3, "texto": "Nestes jazia grande multidão de enfermos, cegos, mancos, [e de corpo] ressecado, aguardando o movimento da água."}, {"numero": 4, "texto": "Porque um anjo descia de vez em quando ao tanque, e agitava a água; e o primeiro que descia nele, depois do movimento da água, sarava de qualquer enfermidade que tivesse."}, {"numero": 5, "texto": "E estava ali um certo homem, que havia trinta e oito anos que estava enfermo."}, {"numero": 6, "texto": "Vendo Jesus a este deitado, e sabendo, que já havia muito tempo que [ali] jazia, disse-lhe: Queres sarar?"}, {"numero": 7, "texto": "Respondeu-lhe o enfermo: Senhor, não tenho homem algum para que, quando a água se agita, me ponha no tanque; e enquanto eu venho, outro desce antes de mim."}, {"numero": 8, "texto": "Disse-lhe Jesus: Levanta-te, toma teu leito, e anda."}, {"numero": 9, "texto": "E logo aquele homem sarou; e tomou seu leito, e andou. E era Sábado aquele dia."}, {"numero": 10, "texto": "Disseram pois os judeus para aquele que fora curado: É Sábado, não te é lícito levar o leito."}, {"numero": 11, "texto": "Respondeu-lhes ele: Aquele que me curou, esse me disse: Toma teu leito, e anda."}, {"numero": 12, "texto": "Perguntaram-lhe pois: Quem é o homem que te disse: Toma teu leito e anda?"}, {"numero": 13, "texto": "E o que fora curado, não sabia quem [o] era, porque Jesus se havia retirado, porque naquele lugar havia uma [grande] multidão."}, {"numero": 14, "texto": "Depois Jesus achou-o no Templo, e disse-lhe: Eis que já estás são; não peques mais, para que não te suceda alguma coisa pior."}, {"numero": 15, "texto": "Aquele homem foi anunciar aos judeus que Jesus era o que o curara."}, {"numero": 16, "texto": "E por isso os judeus perseguiam Jesus e procuravam matá-lo, porque ele fazia estas coisas no sábado."}, {"numero": 17, "texto": "E Jesus lhes respondeu: Meu Pai até agora trabalha, e eu [também] trabalho."}, {"numero": 18, "texto": "Por isto ainda mais procuravam os Judeus matá-lo, porque não só quebrava o sábado, mas também dizia que Deus era seu próprio Pai, fazendo-se igual a Deus."}, {"numero": 19, "texto": "Respondeu pois Jesus, e disse-lhes: Em verdade, em verdade vos digo, que não pode o Filho fazer coisa alguma de si mesmo, a não ser aquilo que ele veja o Pai fazer; porque todas as coisas que ele faz, semelhantemente o Filho também as faz."}, {"numero": 20, "texto": "Porque o Pai ama ao Filho, e todas as coisas que faz lhe mostra; e maiores obras que estas lhe mostrará, para que vós vos maravilheis."}, {"numero": 21, "texto": "Porque como o Pai aos mortos ressuscita e vivifica, assim também o Filho aos que quer vivifica."}, {"numero": 22, "texto": "Porque também o Pai a ninguém julga, mas todo o juízo deu ao Filho,"}, {"numero": 23, "texto": "Para que todos honrem ao Filho, como honram ao Pai. Quem não honra ao Filho, não honra ao Pai que o enviou."}, {"numero": 24, "texto": "Em verdade, em verdade vos digo, que quem ouve minha palavra, e crê ao que me enviou, tem vida eterna, e não virá em condenação, mas passou da morte para a vida."}, {"numero": 25, "texto": "Em verdade, em verdade vos digo, que a hora vem, e agora é, quando os mortos ouvirão a voz do Filho de Deus, e aos que ao ouvirem, viverão."}, {"numero": 26, "texto": "Porque como o Pai tem vida em si mesmo, assim deu também ao Filho que tivesse vida em si mesmo."}, {"numero": 27, "texto": "E deu-lhe poder, para fazer juízo, porque é o Filho do homem."}, {"numero": 28, "texto": "Não vos maravilheis disto; porque a hora vem, em que todos os que estão nos sepulcros ouvirão sua voz."}, {"numero": 29, "texto": "E sairão os que fizeram bem, para a ressurreição de vida; e os que fizeram mal, à ressurreição de condenação."}, {"numero": 30, "texto": "Não posso eu de mim mesmo fazer alguma coisa. Como ouço, [assim] julgo; e meu juízo é justo; porque não busco minha vontade, mas a vontade do Pai que me enviou."}, {"numero": 31, "texto": "Se eu testemunho de mim mesmo, meu testemunho não é verdadeiro."}, {"numero": 32, "texto": "Outro há que testemunha de mim, e sei que o testemunho, que testemunha de mim, é verdadeiro."}, {"numero": 33, "texto": "Vós enviastes [mensageiros] a João, e ele deu testemunho à verdade."}, {"numero": 34, "texto": "Porém eu não recebo testemunho humano; mas digo isto para que sejais salvos."}, {"numero": 35, "texto": "Ele era uma lâmpada ardente e brilhante; e vós quisestes por um pouco de tempo alegrar em sua luz."}, {"numero": 36, "texto": "Mas eu tenho maior testemunho que [o] de João; porque as obras que o Pai me deu que cumprisse, as mesmas obras que eu faço, testemunham de mim que o Pai me enviou."}, {"numero": 37, "texto": "E o Pai que me enviou, ele mesmo testemunhou de mim. Nunca ouvistes sua voz, nem vistes sua aparência."}, {"numero": 38, "texto": "E não tendes sua palavra permanecendo em vós; porque ao que ele enviou, a esse vós não credes."}, {"numero": 39, "texto": "Investigai as Escrituras; porque vós pensais que nelas tendes a vida eterna, e elas são as que de mim testemunham."}, {"numero": 40, "texto": "E não quereis vir a mim, para que tenhais vida."}, {"numero": 41, "texto": "Não recebo honra humana."}, {"numero": 42, "texto": "Mas eu bem vos conheço que não tendes o amor de Deus em vós mesmos."}, {"numero": 43, "texto": "Eu vim em nome de meu Pai, e vós não me aceitais; se outro vier em seu próprio nome, a esse aceitareis."}, {"numero": 44, "texto": "Como podeis vós crer, [se] tomais honra uns dos outros, e não buscais a honra que [vem] somente de Deus?"}, {"numero": 45, "texto": "Não penseis que eu vos tenha de acusar para com o Pai; o que vos acusa é Moisés, em quem vós esperais."}, {"numero": 46, "texto": "Porque se vós crêsseis em Moisés, [também] a mim me creríeis; porque de mim ele escreveu."}, {"numero": 47, "texto": "Mas se não credes em seus escritos, como crereis em minhas palavras?"}]'::jsonb, 'Almeida Livre'),
  ('Jo', 5, 'en', '[{"numero": 1, "texto": "After this there was a feast of the Jews; and Jesus went up to Jerusalem."}, {"numero": 2, "texto": "Now there is at Jerusalem by the sheep market a pool, which is called in the Hebrew tongue Bethesda, having five porches."}, {"numero": 3, "texto": "In these lay a great multitude of impotent folk, of blind, halt, withered, waiting for the moving of the water."}, {"numero": 4, "texto": "For an angel went down at a certain season into the pool, and troubled the water: whosoever then first after the troubling of the water stepped in was made whole of whatsoever disease he had."}, {"numero": 5, "texto": "And a certain man was there, which had an infirmity thirty and eight years."}, {"numero": 6, "texto": "When Jesus saw him lie, and knew that he had been now a long time in that case, he saith unto him, Wilt thou be made whole?"}, {"numero": 7, "texto": "The impotent man answered him, Sir, I have no man, when the water is troubled, to put me into the pool: but while I am coming, another steppeth down before me."}, {"numero": 8, "texto": "Jesus saith unto him, Rise, take up thy bed, and walk."}, {"numero": 9, "texto": "And immediately the man was made whole, and took up his bed, and walked: and on the same day was the sabbath."}, {"numero": 10, "texto": "The Jews therefore said unto him that was cured, It is the sabbath day: it is not lawful for thee to carry thy bed."}, {"numero": 11, "texto": "He answered them, He that made me whole, the same said unto me, Take up thy bed, and walk."}, {"numero": 12, "texto": "Then asked they him, What man is that which said unto thee, Take up thy bed, and walk?"}, {"numero": 13, "texto": "And he that was healed wist not who it was: for Jesus had conveyed himself away, a multitude being in that place."}, {"numero": 14, "texto": "Afterward Jesus findeth him in the temple, and said unto him, Behold, thou art made whole: sin no more, lest a worse thing come unto thee."}, {"numero": 15, "texto": "The man departed, and told the Jews that it was Jesus, which had made him whole."}, {"numero": 16, "texto": "And therefore did the Jews persecute Jesus, and sought to slay him, because he had done these things on the sabbath day."}, {"numero": 17, "texto": "But Jesus answered them, My Father worketh hitherto, and I work."}, {"numero": 18, "texto": "Therefore the Jews sought the more to kill him, because he not only had broken the sabbath, but said also that God was his Father, making himself equal with God."}, {"numero": 19, "texto": "Then answered Jesus and said unto them, Verily, verily, I say unto you, The Son can do nothing of himself, but what he seeth the Father do: for what things soever he doeth, these also doeth the Son likewise."}, {"numero": 20, "texto": "For the Father loveth the Son, and sheweth him all things that himself doeth: and he will shew him greater works than these, that ye may marvel."}, {"numero": 21, "texto": "For as the Father raiseth up the dead, and quickeneth them; even so the Son quickeneth whom he will."}, {"numero": 22, "texto": "For the Father judgeth no man, but hath committed all judgment unto the Son:"}, {"numero": 23, "texto": "That all men should honour the Son, even as they honour the Father. He that honoureth not the Son honoureth not the Father which hath sent him."}, {"numero": 24, "texto": "Verily, verily, I say unto you, He that heareth my word, and believeth on him that sent me, hath everlasting life, and shall not come into condemnation; but is passed from death unto life."}, {"numero": 25, "texto": "Verily, verily, I say unto you, The hour is coming, and now is, when the dead shall hear the voice of the Son of God: and they that hear shall live."}, {"numero": 26, "texto": "For as the Father hath life in himself; so hath he given to the Son to have life in himself;"}, {"numero": 27, "texto": "And hath given him authority to execute judgment also, because he is the Son of man."}, {"numero": 28, "texto": "Marvel not at this: for the hour is coming, in the which all that are in the graves shall hear his voice,"}, {"numero": 29, "texto": "And shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation."}, {"numero": 30, "texto": "I can of mine own self do nothing: as I hear, I judge: and my judgment is just; because I seek not mine own will, but the will of the Father which hath sent me."}, {"numero": 31, "texto": "If I bear witness of myself, my witness is not true."}, {"numero": 32, "texto": "There is another that beareth witness of me; and I know that the witness which he witnesseth of me is true."}, {"numero": 33, "texto": "Ye sent unto John, and he bare witness unto the truth."}, {"numero": 34, "texto": "But I receive not testimony from man: but these things I say, that ye might be saved."}, {"numero": 35, "texto": "He was a burning and a shining light: and ye were willing for a season to rejoice in his light."}, {"numero": 36, "texto": "But I have greater witness than that of John: for the works which the Father hath given me to finish, the same works that I do, bear witness of me, that the Father hath sent me."}, {"numero": 37, "texto": "And the Father himself, which hath sent me, hath borne witness of me. Ye have neither heard his voice at any time, nor seen his shape."}, {"numero": 38, "texto": "And ye have not his word abiding in you: for whom he hath sent, him ye believe not."}, {"numero": 39, "texto": "Search the scriptures; for in them ye think ye have eternal life: and they are they which testify of me."}, {"numero": 40, "texto": "And ye will not come to me, that ye might have life."}, {"numero": 41, "texto": "I receive not honour from men."}, {"numero": 42, "texto": "But I know you, that ye have not the love of God in you."}, {"numero": 43, "texto": "I am come in my Father''s name, and ye receive me not: if another shall come in his own name, him ye will receive."}, {"numero": 44, "texto": "How can ye believe, which receive honour one of another, and seek not the honour that cometh from God only?"}, {"numero": 45, "texto": "Do not think that I will accuse you to the Father: there is one that accuseth you, even Moses, in whom ye trust."}, {"numero": 46, "texto": "For had ye believed Moses, ye would have believed me; for he wrote of me."}, {"numero": 47, "texto": "But if ye believe not his writings, how shall ye believe my words?"}]'::jsonb, 'King James Version'),
  ('Jo', 5, 'fr', '[{"numero": 1, "texto": "Après cela, il y eut une fête des Juifs, et Jésus monta à Jérusalem."}, {"numero": 2, "texto": "Or, à Jérusalem, près de la porte des brebis, il y a une piscine qui s''''appelle en hébreu Béthesda, et qui a cinq portiques."}, {"numero": 3, "texto": "Sous ces portiques étaient couchés en grand nombre des malades, des aveugles, des boiteux, des paralytiques, qui attendaient le mouvement de l''''eau;"}, {"numero": 4, "texto": "car un ange descendait de temps en temps dans la piscine, et agitait l''''eau; et celui qui y descendait le premier après que l''''eau avait été agitée était guéri, quelle que fût sa maladie."}, {"numero": 5, "texto": "Là se trouvait un homme malade depuis trente-huit ans."}, {"numero": 6, "texto": "Jésus, l''''ayant vu couché, et sachant qu''''il était malade depuis longtemps, lui dit: Veux-tu être guéri?"}, {"numero": 7, "texto": "Le malade lui répondit: Seigneur, je n''''ai personne pour me jeter dans la piscine quand l''''eau est agitée, et, pendant que j''''y vais, un autre descend avant moi."}, {"numero": 8, "texto": "Lève-toi, lui dit Jésus, prends ton lit, et marche."}, {"numero": 9, "texto": "Aussitôt cet homme fut guéri; il prit son lit, et marcha. C''''était un jour de sabbat."}, {"numero": 10, "texto": "Les Juifs dirent donc à celui qui avait été guéri: C''''est le sabbat; il ne t''''est pas permis d''''emporter ton lit."}, {"numero": 11, "texto": "Il leur répondit: Celui qui m''''a guéri m''''a dit: Prends ton lit, et marche."}, {"numero": 12, "texto": "Ils lui demandèrent: Qui est l''''homme qui t''''a dit: Prends ton lit, et marche?"}, {"numero": 13, "texto": "Mais celui qui avait été guéri ne savait pas qui c''''était; car Jésus avait disparu de la foule qui était en ce lieu."}, {"numero": 14, "texto": "Depuis, Jésus le trouva dans le temple, et lui dit: Voici, tu as été guéri; ne pèche plus, de peur qu''''il ne t''''arrive quelque chose de pire."}, {"numero": 15, "texto": "Cet homme s''''en alla, et annonça aux Juifs que c''''était Jésus qui l''''avait guéri."}, {"numero": 16, "texto": "C''''est pourquoi les Juifs poursuivaient Jésus, parce qu''''il faisait ces choses le jour du sabbat."}, {"numero": 17, "texto": "Mais Jésus leur répondit: Mon Père agit jusqu''''à présent; moi aussi, j''''agis."}, {"numero": 18, "texto": "A cause de cela, les Juifs cherchaient encore plus à le faire mourir, non seulement parce qu''''il violait le sabbat, mais parce qu''''il appelait Dieu son propre Père, se faisant lui-même égal à Dieu."}, {"numero": 19, "texto": "Jésus reprit donc la parole, et leur dit: En vérité, en vérité, je vous le dis, le Fils ne peut rien faire de lui-même, il ne fait que ce qu''''il voit faire au Père; et tout ce que le Père fait, le Fils aussi le fait pareillement."}, {"numero": 20, "texto": "Car le Père aime le Fils, et lui montre tout ce qu''''il fait; et il lui montrera des oeuvres plus grandes que celles-ci, afin que vous soyez dans l''''étonnement."}, {"numero": 21, "texto": "Car, comme le Père ressuscite les morts et donne la vie, ainsi le Fils donne la vie à qui il veut."}, {"numero": 22, "texto": "Le Père ne juge personne, mais il a remis tout jugement au Fils,"}, {"numero": 23, "texto": "afin que tous honorent le Fils comme ils honorent le Père. Celui qui n''''honore pas le Fils n''''honore pas le Père qui l''''a envoyé."}, {"numero": 24, "texto": "En vérité, en vérité, je vous le dis, celui qui écoute ma parole, et qui croit à celui qui m''''a envoyé, a la vie éternelle et ne vient point en jugement, mais il est passé de la mort à la vie."}, {"numero": 25, "texto": "En vérité, en vérité, je vous le dis, l''''heure vient, et elle est déjà venue, où les morts entendront la voix du Fils de Dieu; et ceux qui l''''auront entendue vivront."}, {"numero": 26, "texto": "Car, comme le Père a la vie en lui-même, ainsi il a donné au Fils d''''avoir la vie en lui-même."}, {"numero": 27, "texto": "Et il lui a donné le pouvoir de juger, parce qu''''il est Fils de l''''homme."}, {"numero": 28, "texto": "Ne vous étonnez pas de cela; car l''''heure vient où tous ceux qui sont dans les sépulcres entendront sa voix,"}, {"numero": 29, "texto": "et en sortiront. Ceux qui auront fait le bien ressusciteront pour la vie, mais ceux qui auront fait le mal ressusciteront pour le jugement."}, {"numero": 30, "texto": "Je ne puis rien faire de moi-même: selon que j''''entends, je juge; et mon jugement est juste, parce que je ne cherche pas ma volonté, mais la volonté de celui qui m''''a envoyé."}, {"numero": 31, "texto": "Si c''''est moi qui rends témoignage de moi-même, mon témoignage n''''est pas vrai."}, {"numero": 32, "texto": "Il y en a un autre qui rend témoignage de moi, et je sais que le témoignage qu''''il rend de moi est vrai."}, {"numero": 33, "texto": "Vous avez envoyé vers Jean, et il a rendu témoignage à la vérité."}, {"numero": 34, "texto": "Pour moi ce n''''est pas d''''un homme que je reçois le témoignage; mais je dis ceci, afin que vous soyez sauvés."}, {"numero": 35, "texto": "Jean était la lampe qui brûle et qui luit, et vous avez voulu vous réjouir une heure à sa lumière."}, {"numero": 36, "texto": "Moi, j''''ai un témoignage plus grand que celui de Jean; car les oeuvres que le Père m''''a donné d''''accomplir, ces oeuvres mêmes que je fais, témoignent de moi que c''''est le Père qui m''''a envoyé."}, {"numero": 37, "texto": "Et le Père qui m''''a envoyé a rendu lui-même témoignage de moi. Vous n''''avez jamais entendu sa voix, vous n''''avez point vu sa face,"}, {"numero": 38, "texto": "et sa parole ne demeure point en vous, parce que vous ne croyez pas à celui qu''''il a envoyé."}, {"numero": 39, "texto": "Vous sondez les Ecritures, parce que vous pensez avoir en elles la vie éternelle: ce sont elles qui rendent témoignage de moi."}, {"numero": 40, "texto": "Et vous ne voulez pas venir à moi pour avoir la vie!"}, {"numero": 41, "texto": "Je ne tire pas ma gloire des hommes."}, {"numero": 42, "texto": "Mais je sais que vous n''''avez point en vous l''''amour de Dieu."}, {"numero": 43, "texto": "Je suis venu au nom de mon Père, et vous ne me recevez pas; si un autre vient en son propre nom, vous le recevrez."}, {"numero": 44, "texto": "Comment pouvez-vous croire, vous qui tirez votre gloire les uns des autres, et qui ne cherchez point la gloire qui vient de Dieu seul?"}, {"numero": 45, "texto": "Ne pensez pas que moi je vous accuserai devant le Père; celui qui vous accuse, c''''est Moïse, en qui vous avez mis votre espérance."}, {"numero": 46, "texto": "Car si vous croyiez Moïse, vous me croiriez aussi, parce qu''''il a écrit de moi."}, {"numero": 47, "texto": "Mais si vous ne croyez pas à ses écrits, comment croirez-vous à mes paroles?"}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 5, 'es', '[{"numero": 1, "texto": "DESPUÉS de estas cosas, era un día de fiesta de los Judíos, y subió Jesús á Jerusalem."}, {"numero": 2, "texto": "Y hay en Jerusalem á la puerta del ganado un estanque, que en hebraico es llamado Bethesda, el cual tiene cinco portales."}, {"numero": 3, "texto": "En éstos yacía multitud de enfermos, ciegos, cojos, secos, que estaban esperando el movimiento del agua."}, {"numero": 4, "texto": "Porque un ángel descendía á cierto tiempo al estanque, y revolvía el agua; y el que primero descendía en el estanque después del movimiento del agua, era sano de cualquier enfermedad que tuviese."}, {"numero": 5, "texto": "Y estaba allí un hombre que había treinta y ocho años que estaba enfermo."}, {"numero": 6, "texto": "Como Jesús vió á éste echado, y entendió que ya había mucho tiempo, dícele: ¿Quieres ser sano?"}, {"numero": 7, "texto": "Señor, le respondió el enfermo, no tengo hombre que me meta en el estanque cuando el agua fuere revuelta; porque entre tanto que yo vengo, otro antes de mí ha descendido."}, {"numero": 8, "texto": "Dícele Jesús: Levántate, toma tu lecho, y anda."}, {"numero": 9, "texto": "Y luego aquel hombre fué sano, y tomó su lecho, é íbase. Y era sábado aquel día."}, {"numero": 10, "texto": "Entonces los Judíos decían á aquel que había sido sanado: Sábado es: no te es lícito llevar tu lecho."}, {"numero": 11, "texto": "Respondióles: El que me sanó, él mismo me dijo: Toma tu lecho y anda."}, {"numero": 12, "texto": "Preguntáronle entonces: ¿Quién es el que te dijo: Toma tu lecho y anda?"}, {"numero": 13, "texto": "Y el que había sido sanado, no sabía quién fuese; porque Jesús se había apartado de la gente que estaba en aquel lugar."}, {"numero": 14, "texto": "Después le halló Jesús en el templo, y díjole: He aquí, has sido sanado; no peques más, porque no te venga alguna cosa peor."}, {"numero": 15, "texto": "El se fué, y dió aviso á los Judíos, que Jesús era el que le había sanado."}, {"numero": 16, "texto": "Y por esta causa los Judíos perseguían á Jesús, y procuraban matarle, porque hacía estas cosas en sábado."}, {"numero": 17, "texto": "Y Jesús les respondió: Mi Padre hasta ahora obra, y yo obro."}, {"numero": 18, "texto": "Entonces, por tanto, más procuraban los Judíos matarle, porque no sólo quebrantaba el sábado, sino que también á su Padre llamaba Dios, haciéndose igual á Dios."}, {"numero": 19, "texto": "Respondió entonces Jesús, y díjoles: De cierto, de cierto os digo: No puede el Hijo hacer nada de sí mismo, sino lo que viere hacer al Padre: porque todo lo que él hace, esto también hace el Hijo juntamente."}, {"numero": 20, "texto": "Porque el Padre ama al Hijo, y le muestra todas las cosas que él hace; y mayores obras que éstas le mostrará, de suerte que vosotros os maravilléis."}, {"numero": 21, "texto": "Porque como el Padre levanta los muertos, y les da vida, así también el Hijo á los que quiere da vida."}, {"numero": 22, "texto": "Porque el Padre á nadie juzga, mas todo el juicio dió al Hijo;"}, {"numero": 23, "texto": "Para que todos honren al Hijo como honran al Padre. El que no honra al Hijo, no honra al Padre que le envió."}, {"numero": 24, "texto": "De cierto, de cierto os digo: El que oye mi palabra, y cree al que me ha enviado, tiene vida eterna; y no vendrá á condenación, mas pasó de muerte á vida."}, {"numero": 25, "texto": "De cierto, de cierto os digo: Vendrá hora, y ahora es, cuando los muertos oirán la voz del Hijo de Dios: y los que oyeren vivirán."}, {"numero": 26, "texto": "Porque como el Padre tiene vida en sí mismo, así dió también al Hijo que tuviese vida en sí mismo:"}, {"numero": 27, "texto": "Y también le dió poder de hacer juicio, en cuanto es el Hijo del hombre."}, {"numero": 28, "texto": "No os maravilléis de esto; porque vendrá hora, cuando todos los que están en los sepulcros oirán su voz;"}, {"numero": 29, "texto": "Y los que hicieron bien, saldrán á resurrección de vida; mas los que hicieron mal, á resurrección de condenación."}, {"numero": 30, "texto": "No puedo yo de mí mismo hacer nada: como oigo, juzgo: y mi juicio es justo; porque no busco mi voluntad, mas la voluntad del que me envió, del Padre."}, {"numero": 31, "texto": "Si yo doy testimonio de mí mismo, mi testimonio no es verdadero."}, {"numero": 32, "texto": "Otro es el que da testimonio de mí; y sé que el testimonio que da de mí, es verdadero."}, {"numero": 33, "texto": "Vosotros enviasteis á Juan, y él dió testimonio á la verdad."}, {"numero": 34, "texto": "Empero yo no tomo el testimonio de hombre; mas digo esto, para que vosotros seáis salvos."}, {"numero": 35, "texto": "El era antorcha que ardía y alumbraba: y vosotros quisisteis recrearos por un poco á su luz."}, {"numero": 36, "texto": "Mas yo tengo mayor testimonio que el de Juan: porque las obras que el Padre me dió que cumpliese, las mismas obras que yo hago, dan testimonio de mí, que el Padre me haya enviado."}, {"numero": 37, "texto": "Y el que me envió, el Padre, él ha dado testimonio de mí. Ni nunca habéis oído su voz, ni habéis visto su parecer."}, {"numero": 38, "texto": "Ni tenéis su palabra permanente en vosotros; porque al que él envió, á éste vosotros no creéis."}, {"numero": 39, "texto": "Escudriñad las Escrituras, porque á vosotros os parece que en ellas tenéis la vida eterna; y ellas son las que dan testimonio de mí."}, {"numero": 40, "texto": "Y no queréis venir á mí, para que tengáis vida."}, {"numero": 41, "texto": "Gloria de los hombres no recibo."}, {"numero": 42, "texto": "Mas yo os conozco, que no tenéis amor de Dios en vosotros."}, {"numero": 43, "texto": "Yo he venido en nombre de mi Padre, y no me recibís: si otro viniere en su propio nombre, á aquél recibiréis."}, {"numero": 44, "texto": "¿Cómo podéis vosotros creer, pues tomáis la gloria los unos de los otros, y no buscáis la gloria que de sólo Dios viene?"}, {"numero": 45, "texto": "No penséis que yo os tengo de acusar delante del Padre; hay quien os acusa, Moisés, en quien vosotros esperáis."}, {"numero": 46, "texto": "Porque si vosotros creyeseis á Moisés, creeríais á mí; porque de mí escribió él."}, {"numero": 47, "texto": "Y si á sus escritos no creéis, ¿cómo creeréis á mis palabras?"}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 6, 'pt', '[{"numero": 1, "texto": "Depois disto Jesus partiu para a outro lado do mar da Galileia, que é o de Tibérias."}, {"numero": 2, "texto": "E uma grande multidão o seguia, porque viam seus sinais que ele fazia nos enfermos."}, {"numero": 3, "texto": "E subiu Jesus ao monte, e sentou-se ali com seus discípulos."}, {"numero": 4, "texto": "E já a Páscoa, a festa dos judeus, estava perto."}, {"numero": 5, "texto": "Levantando pois Jesus os olhos, e vendo que uma grande multidão vinha a ele, disse a Filipe: De onde comparemos pães, para que estes comam?"}, {"numero": 6, "texto": "(Mas ele disse isto para o testar; pois ele bem sabia o que havia de fazer.)"}, {"numero": 7, "texto": "Respondeu-lhe Filipe: Duzentos dinheiros de pão não lhes bastarão, para que cada um deles tome um pouco."}, {"numero": 8, "texto": "Disse-lhe um de seus discípulos, André, o irmão de Simão Pedro:"}, {"numero": 9, "texto": "Um menino está aqui que tem cinco pães de cevada e dois peixinhos; mas que é isto entre tantos?"}, {"numero": 10, "texto": "E disse Jesus: Fazei sentar as pessoas; e havia muita erva naquele lugar. Sentaram-se, pois, os homens, em número de cinco mil."}, {"numero": 11, "texto": "E tomou Jesus os pães, e havendo dado graças, repartiu-os aos discípulos, e os discípulos aos que estavam sentados, semelhantemente também dos peixes, quanto queriam."}, {"numero": 12, "texto": "E quando já estiveram fartos, disse ele a seus discípulos: Recolhei os pedaços que sobraram, para que nada se perca."}, {"numero": 13, "texto": "Então eles os recolheram, e encheram doze cestos de pedaços dos cinco pães de cevada, que sobraram aos que tinham comido."}, {"numero": 14, "texto": "Vendo, pois, aquelas pessoas o sinal que Jesus fizera, disseram: Este é verdadeiramente o Profeta que havia de vir ao mundo!"}, {"numero": 15, "texto": "Sabendo pois Jesus que viriam, e o tomariam, para fazê-lo rei, voltou a se retirar sozinho ao monte."}, {"numero": 16, "texto": "E quando veio o entardecer, seus discípulos desceram para o mar."}, {"numero": 17, "texto": "E entrando no barco, vieram do outro lado do mar para Cafarnaum. E era já escuro, e Jesus [ainda] não tinha vindo a eles."}, {"numero": 18, "texto": "E o mar se levantou, porque um grande vento soprava."}, {"numero": 19, "texto": "E havendo já navegado quase vinte e cinco, ou trinta estádios, viram a Jesus andando sobre o mar, e se aproximando do barco; e temeram."}, {"numero": 20, "texto": "Mas ele lhes disse: Sou eu, não temais."}, {"numero": 21, "texto": "Eles, então, o receberam com agrado no barco; e logo o barco chegou à terra para onde iam."}, {"numero": 22, "texto": "O dia seguinte, vendo a multidão, que estava do outro lado do mar, que não havia ali mais que um barquinho, em que seus discípulos entraram; e que Jesus não entrara com seus discípulos naquele barquinho, mas [que] seus discípulos sós se haviam ido;"}, {"numero": 23, "texto": "(Porém outros barquinhos vieram de Tibérias, perto do lugar onde comeram o pão, havendo o Senhor dado graças.)"}, {"numero": 24, "texto": "Vendo pois a multidão que Jesus não estava ali, nem seus discípulos, entraram eles também nos barcos, e vieram a Cafarnaum em busca de Jesus."}, {"numero": 25, "texto": "E achando-o do outro lado do mar, disseram: Rabi, quando chegaste aqui?"}, {"numero": 26, "texto": "Respondeu-lhes Jesus, e disse: Em verdade, em verdade vos digo, que me buscais, não pelos sinais que vistes, mas pelo pão que comestes, e vos fartastes."}, {"numero": 27, "texto": "Trabalhai não [pela] comida que perece, mas sim [pela] comida que permanece para vida eterna, a qual o Filho do homem vos dará; porque Deus Pai a este selou."}, {"numero": 28, "texto": "Disseram-lhe pois: Que faremos para trabalhar as obras de Deus?"}, {"numero": 29, "texto": "Respondeu Jesus, e disse-lhes: Esta é a obra de Deus: que creiais naquele que ele enviou."}, {"numero": 30, "texto": "Disseram-lhe pois: Que sinal, pois, fazes tu para que o vejamos, e em ti creiamos? O que tu operas?"}, {"numero": 31, "texto": "Nossos pais comeram o maná no deserto, como está escrito: Pão do céu ele lhes deu para comer."}, {"numero": 32, "texto": "Então Jesus lhes disse: Em verdade, em verdade vos digo, que Moisés não vos deu o pão do céu; mas meu Pai vos dá o verdadeiro pão do céu."}, {"numero": 33, "texto": "Porque o pão de Deus é aquele que desce do céu e dá vida ao mundo."}, {"numero": 34, "texto": "Disseram-lhe pois: Senhor, dá-nos sempre [d] este pão."}, {"numero": 35, "texto": "E Jesus lhes disse: Eu sou o pão da vida; quem vem a mim de maneira nenhuma terá fome, e quem crê em mim nunca terá sede."}, {"numero": 36, "texto": "Mas já tenho vos dito que também me vistes, e não credes."}, {"numero": 37, "texto": "Tudo o que o Pai me dá virá a mim; e ao que vem a mim, em maneira nenhuma o lançarei fora."}, {"numero": 38, "texto": "Porque eu desci do céu, não para fazer minha vontade, mas sim a vontade daquele que me enviou;"}, {"numero": 39, "texto": "E esta é a vontade do Pai, que me enviou: que de tudo quanto me deu, nada perca, mas que eu o ressuscite no último dia."}, {"numero": 40, "texto": "E esta é a vontade daquele que me enviou, que todo aquele que vê ao Filho, e nele crê, tenha a vida eterna; e eu o ressuscitarei no último dia."}, {"numero": 41, "texto": "Então os judeus murmuravam dele, porque ele tinha dito: Eu sou o pão que desceu do céu."}, {"numero": 42, "texto": "E diziam: Não é este Jesus o filho de José, cujos pai e mãe nós conhecemos? Como, pois, ele diz: Desci do céu?"}, {"numero": 43, "texto": "Respondeu, então, Jesus, e disse-lhes: Não murmureis entre vós."}, {"numero": 44, "texto": "Ninguém pode vir a mim se o Pai que me enviou não o trouxer; e eu o ressuscitarei no último dia."}, {"numero": 45, "texto": "Escrito está nos profetas: E todos serão ensinados por Deus. Portanto todo aquele que do Pai ouviu e aprendeu, esse vem a mim."}, {"numero": 46, "texto": "Não que alguém tenha visto ao Pai, a não ser aquele que é de Deus; este tem visto ao Pai."}, {"numero": 47, "texto": "Em verdade, em verdade vos digo, que aquele que crê em mim tem vida eterna."}, {"numero": 48, "texto": "Eu sou o pão da vida."}, {"numero": 49, "texto": "Vossos pais comeram o maná no deserto, e morreram."}, {"numero": 50, "texto": "Este é o pão que desceu do céu, para que o ser humano coma dele e não morra."}, {"numero": 51, "texto": "Eu sou o pão vivo, que desceu do céu; se alguém comer deste pão, para sempre viverá. E o pão que eu darei é minha carne, a qual darei pela vida do mundo."}, {"numero": 52, "texto": "Discutiam, pois, os Judeus entre si, dizendo: Como este pode nos dar [sua] carne para comer?"}, {"numero": 53, "texto": "Jesus, então, lhes disse: Em verdade, em verdade vos digo, que se não comerdes a carne do Filho do homem e beberdes seu sangue, não tereis vida em vós mesmos."}, {"numero": 54, "texto": "Quem come minha carne e bebe meu sangue tem vida eterna, e eu o ressuscitarei no último dia."}, {"numero": 55, "texto": "Porque minha carne verdadeiramente é comida; e meu sangue verdadeiramente é bebida."}, {"numero": 56, "texto": "Quem come minha carne e bebe meu sangue, em mim permanece, e eu nele."}, {"numero": 57, "texto": "Como o Pai vivo me enviou, e eu vivo pelo Pai, assim quem come a mim também por mim viverá."}, {"numero": 58, "texto": "Este é o pão que desceu do céu. Não como vossos pais, que comeram o maná e morreram; quem comer este pão viverá para sempre."}, {"numero": 59, "texto": "Estas coisas ele disse na sinagoga, ensinando em Cafarnaum."}, {"numero": 60, "texto": "Muitos pois de seus discípulos, ao ouvirem [isto] , disseram: Dura é esta palavra; quem a pode ouvir?"}, {"numero": 61, "texto": "Sabendo, pois, Jesus em si mesmo, que seus discípulos murmuravam disso, disse-lhes: Isto vos ofende?"}, {"numero": 62, "texto": "[Que seria] pois, se vísseis ao Filho do homem subir aonde estava primeiro?"}, {"numero": 63, "texto": "O Espírito é o que vivifica, a carne para nada aproveita; as palavras que eu vos digo são espírito e são vida."}, {"numero": 64, "texto": "Mas há alguns de vós que não creem.Porque Jesus já sabia desde o princípio quem eram os que não criam, e quem era o que o entregaria."}, {"numero": 65, "texto": "E dizia: Por isso tenho vos dito que ninguém pode vir a mim, se não lhe for concedido por meu Pai."}, {"numero": 66, "texto": "Desde então muitos de seus discípulos voltaram atrás, e já não andavam com ele."}, {"numero": 67, "texto": "Disse, então, Jesus aos doze: Por acaso também vós quereis ir?"}, {"numero": 68, "texto": "Respondeu-lhe pois Simão Pedro: Senhor, a quem iremos? Tu tens as palavras da vida eterna;"}, {"numero": 69, "texto": "E nós cremos e conhecemos que tu és o Cristo, o Filho do Deus vivo."}, {"numero": 70, "texto": "Jesus lhes respondeu: Por acaso não [fui] eu que vos escolhi, os doze? Porém um de vós é um diabo."}, {"numero": 71, "texto": "E ele dizia [isto] de Judas de Simão Iscariotes; porque ele o entregaria, o qual era um dos doze."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 6, 'en', '[{"numero": 1, "texto": "After these things Jesus went over the sea of Galilee, which is the sea of Tiberias."}, {"numero": 2, "texto": "And a great multitude followed him, because they saw his miracles which he did on them that were diseased."}, {"numero": 3, "texto": "And Jesus went up into a mountain, and there he sat with his disciples."}, {"numero": 4, "texto": "And the passover, a feast of the Jews, was nigh."}, {"numero": 5, "texto": "When Jesus then lifted up his eyes, and saw a great company come unto him, he saith unto Philip, Whence shall we buy bread, that these may eat?"}, {"numero": 6, "texto": "And this he said to prove him: for he himself knew what he would do."}, {"numero": 7, "texto": "Philip answered him, Two hundred pennyworth of bread is not sufficient for them, that every one of them may take a little."}, {"numero": 8, "texto": "One of his disciples, Andrew, Simon Peter''s brother, saith unto him,"}, {"numero": 9, "texto": "There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?"}, {"numero": 10, "texto": "And Jesus said, Make the men sit down. Now there was much grass in the place. So the men sat down, in number about five thousand."}, {"numero": 11, "texto": "And Jesus took the loaves; and when he had given thanks, he distributed to the disciples, and the disciples to them that were set down; and likewise of the fishes as much as they would."}, {"numero": 12, "texto": "When they were filled, he said unto his disciples, Gather up the fragments that remain, that nothing be lost."}, {"numero": 13, "texto": "Therefore they gathered them together, and filled twelve baskets with the fragments of the five barley loaves, which remained over and above unto them that had eaten."}, {"numero": 14, "texto": "Then those men, when they had seen the miracle that Jesus did, said, This is of a truth that prophet that should come into the world."}, {"numero": 15, "texto": "When Jesus therefore perceived that they would come and take him by force, to make him a king, he departed again into a mountain himself alone."}, {"numero": 16, "texto": "And when even was now come, his disciples went down unto the sea,"}, {"numero": 17, "texto": "And entered into a ship, and went over the sea toward Capernaum. And it was now dark, and Jesus was not come to them."}, {"numero": 18, "texto": "And the sea arose by reason of a great wind that blew."}, {"numero": 19, "texto": "So when they had rowed about five and twenty or thirty furlongs, they see Jesus walking on the sea, and drawing nigh unto the ship: and they were afraid."}, {"numero": 20, "texto": "But he saith unto them, It is I; be not afraid."}, {"numero": 21, "texto": "Then they willingly received him into the ship: and immediately the ship was at the land whither they went."}, {"numero": 22, "texto": "The day following, when the people which stood on the other side of the sea saw that there was none other boat there, save that one whereinto his disciples were entered, and that Jesus went not with his disciples into the boat, but that his disciples were gone away alone;"}, {"numero": 23, "texto": "(Howbeit there came other boats from Tiberias nigh unto the place where they did eat bread, after that the Lord had given thanks:)"}, {"numero": 24, "texto": "When the people therefore saw that Jesus was not there, neither his disciples, they also took shipping, and came to Capernaum, seeking for Jesus."}, {"numero": 25, "texto": "And when they had found him on the other side of the sea, they said unto him, Rabbi, when camest thou hither?"}, {"numero": 26, "texto": "Jesus answered them and said, Verily, verily, I say unto you, Ye seek me, not because ye saw the miracles, but because ye did eat of the loaves, and were filled."}, {"numero": 27, "texto": "Labour not for the meat which perisheth, but for that meat which endureth unto everlasting life, which the Son of man shall give unto you: for him hath God the Father sealed."}, {"numero": 28, "texto": "Then said they unto him, What shall we do, that we might work the works of God?"}, {"numero": 29, "texto": "Jesus answered and said unto them, This is the work of God, that ye believe on him whom he hath sent."}, {"numero": 30, "texto": "They said therefore unto him, What sign shewest thou then, that we may see, and believe thee? what dost thou work?"}, {"numero": 31, "texto": "Our fathers did eat manna in the desert; as it is written, He gave them bread from heaven to eat."}, {"numero": 32, "texto": "Then Jesus said unto them, Verily, verily, I say unto you, Moses gave you not that bread from heaven; but my Father giveth you the true bread from heaven."}, {"numero": 33, "texto": "For the bread of God is he which cometh down from heaven, and giveth life unto the world."}, {"numero": 34, "texto": "Then said they unto him, Lord, evermore give us this bread."}, {"numero": 35, "texto": "And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst."}, {"numero": 36, "texto": "But I said unto you, That ye also have seen me, and believe not."}, {"numero": 37, "texto": "All that the Father giveth me shall come to me; and him that cometh to me I will in no wise cast out."}, {"numero": 38, "texto": "For I came down from heaven, not to do mine own will, but the will of him that sent me."}, {"numero": 39, "texto": "And this is the Father''s will which hath sent me, that of all which he hath given me I should lose nothing, but should raise it up again at the last day."}, {"numero": 40, "texto": "And this is the will of him that sent me, that every one which seeth the Son, and believeth on him, may have everlasting life: and I will raise him up at the last day."}, {"numero": 41, "texto": "The Jews then murmured at him, because he said, I am the bread which came down from heaven."}, {"numero": 42, "texto": "And they said, Is not this Jesus, the son of Joseph, whose father and mother we know? how is it then that he saith, I came down from heaven?"}, {"numero": 43, "texto": "Jesus therefore answered and said unto them, Murmur not among yourselves."}, {"numero": 44, "texto": "No man can come to me, except the Father which hath sent me draw him: and I will raise him up at the last day."}, {"numero": 45, "texto": "It is written in the prophets, And they shall be all taught of God. Every man therefore that hath heard, and hath learned of the Father, cometh unto me."}, {"numero": 46, "texto": "Not that any man hath seen the Father, save he which is of God, he hath seen the Father."}, {"numero": 47, "texto": "Verily, verily, I say unto you, He that believeth on me hath everlasting life."}, {"numero": 48, "texto": "I am that bread of life."}, {"numero": 49, "texto": "Your fathers did eat manna in the wilderness, and are dead."}, {"numero": 50, "texto": "This is the bread which cometh down from heaven, that a man may eat thereof, and not die."}, {"numero": 51, "texto": "I am the living bread which came down from heaven: if any man eat of this bread, he shall live for ever: and the bread that I will give is my flesh, which I will give for the life of the world."}, {"numero": 52, "texto": "The Jews therefore strove among themselves, saying, How can this man give us his flesh to eat?"}, {"numero": 53, "texto": "Then Jesus said unto them, Verily, verily, I say unto you, Except ye eat the flesh of the Son of man, and drink his blood, ye have no life in you."}, {"numero": 54, "texto": "Whoso eateth my flesh, and drinketh my blood, hath eternal life; and I will raise him up at the last day."}, {"numero": 55, "texto": "For my flesh is meat indeed, and my blood is drink indeed."}, {"numero": 56, "texto": "He that eateth my flesh, and drinketh my blood, dwelleth in me, and I in him."}, {"numero": 57, "texto": "As the living Father hath sent me, and I live by the Father: so he that eateth me, even he shall live by me."}, {"numero": 58, "texto": "This is that bread which came down from heaven: not as your fathers did eat manna, and are dead: he that eateth of this bread shall live for ever."}, {"numero": 59, "texto": "These things said he in the synagogue, as he taught in Capernaum."}, {"numero": 60, "texto": "Many therefore of his disciples, when they had heard this, said, This is an hard saying; who can hear it?"}, {"numero": 61, "texto": "When Jesus knew in himself that his disciples murmured at it, he said unto them, Doth this offend you?"}, {"numero": 62, "texto": "What and if ye shall see the Son of man ascend up where he was before?"}, {"numero": 63, "texto": "It is the spirit that quickeneth; the flesh profiteth nothing: the words that I speak unto you, they are spirit, and they are life."}, {"numero": 64, "texto": "But there are some of you that believe not. For Jesus knew from the beginning who they were that believed not, and who should betray him."}, {"numero": 65, "texto": "And he said, Therefore said I unto you, that no man can come unto me, except it were given unto him of my Father."}, {"numero": 66, "texto": "From that time many of his disciples went back, and walked no more with him."}, {"numero": 67, "texto": "Then said Jesus unto the twelve, Will ye also go away?"}, {"numero": 68, "texto": "Then Simon Peter answered him, Lord, to whom shall we go? thou hast the words of eternal life."}, {"numero": 69, "texto": "And we believe and are sure that thou art that Christ, the Son of the living God."}, {"numero": 70, "texto": "Jesus answered them, Have not I chosen you twelve, and one of you is a devil?"}, {"numero": 71, "texto": "He spake of Judas Iscariot the son of Simon: for he it was that should betray him, being one of the twelve."}]'::jsonb, 'King James Version'),
  ('Jo', 6, 'fr', '[{"numero": 1, "texto": "Après cela, Jésus s''''en alla de l''''autre côté de la mer de Galilée, de Tibériade."}, {"numero": 2, "texto": "Une grande foule le suivait, parce qu''''elle voyait les miracles qu''''il opérait sur les malades."}, {"numero": 3, "texto": "Jésus monta sur la montagne, et là il s''''assit avec ses disciples."}, {"numero": 4, "texto": "Or, la Pâque était proche, la fête des Juifs."}, {"numero": 5, "texto": "Ayant levé les yeux, et voyant qu''''une grande foule venait à lui, Jésus dit à Philippe: Où achèterons-nous des pains, pour que ces gens aient à manger?"}, {"numero": 6, "texto": "Il disait cela pour l''''éprouver, car il savait ce qu''''il allait faire."}, {"numero": 7, "texto": "Philippe lui répondit: Les pains qu''''on aurait pour deux cents deniers ne suffiraient pas pour que chacun en reçût un peu."}, {"numero": 8, "texto": "Un de ses disciples, André, frère de Simon Pierre, lui dit:"}, {"numero": 9, "texto": "Il y a ici un jeune garçon qui a cinq pains d''''orge et deux poissons; mais qu''''est-ce que cela pour tant de gens?"}, {"numero": 10, "texto": "Jésus dit: Faites-les asseoir. Il y avait dans ce lieu beaucoup d''''herbe. Ils s''''assirent donc, au nombre d''''environ cinq mille hommes."}, {"numero": 11, "texto": "Jésus prit les pains, rendit grâces, et les distribua à ceux qui étaient assis; il leur donna de même des poissons, autant qu''''ils en voulurent."}, {"numero": 12, "texto": "Lorsqu''''ils furent rassasiés, il dit à ses disciples: Ramassez les morceaux qui restent, afin que rien ne se perde."}, {"numero": 13, "texto": "Ils les ramassèrent donc, et ils remplirent douze paniers avec les morceaux qui restèrent des cinq pains d''''orge, après que tous eurent mangé."}, {"numero": 14, "texto": "Ces gens, ayant vu le miracle que Jésus avait fait, disaient: Celui-ci est vraiment le prophète qui doit venir dans le monde."}, {"numero": 15, "texto": "Et Jésus, sachant qu''''ils allaient venir l''''enlever pour le faire roi, se retira de nouveau sur la montagne, lui seul."}, {"numero": 16, "texto": "Quand le soir fut venu, ses disciples descendirent au bord de la mer."}, {"numero": 17, "texto": "Etant montés dans une barque, ils traversaient la mer pour se rendre à Capernaüm. Il faisait déjà nuit, et Jésus ne les avait pas encore rejoints."}, {"numero": 18, "texto": "Il soufflait un grand vent, et la mer était agitée."}, {"numero": 19, "texto": "Après avoir ramé environ vingt-cinq ou trente stades, ils virent Jésus marchant sur la mer et s''''approchant de la barque. Et ils eurent peur."}, {"numero": 20, "texto": "Mais Jésus leur dit: C''''est moi; n''''ayez pas peur!"}, {"numero": 21, "texto": "Ils voulaient donc le prendre dans la barque, et aussitôt la barque aborda au lieu où ils allaient."}, {"numero": 22, "texto": "La foule qui était restée de l''''autre côté de la mer avait remarqué qu''''il ne se trouvait là qu''''une seule barque, et que Jésus n''''était pas monté dans cette barque avec ses disciples, mais qu''''ils étaient partis seuls."}, {"numero": 23, "texto": "Le lendemain, comme d''''autres barques étaient arrivées de Tibériade près du lieu où ils avaient mangé le pain après que le Seigneur eut rendu grâces,"}, {"numero": 24, "texto": "les gens de la foule, ayant vu que ni Jésus ni ses disciples n''''étaient là, montèrent eux-mêmes dans ces barques et allèrent à Capernaüm à la recherche de Jésus."}, {"numero": 25, "texto": "Et l''''ayant trouvé au delà de la mer, ils lui dirent: Rabbi, quand es-tu venu ici?"}, {"numero": 26, "texto": "Jésus leur répondit: En vérité, en vérité, je vous le dis, vous me cherchez, non parce que vous avez vu des miracles, mais parce que vous avez mangé des pains et que vous avez été rassasiés."}, {"numero": 27, "texto": "Travaillez, non pour la nourriture qui périt, mais pour celle qui subsiste pour la vie éternelle, et que le Fils de l''''homme vous donnera; car c''''est lui que le Père, que Dieu a marqué de son sceau."}, {"numero": 28, "texto": "Ils lui dirent: Que devons-nous faire, pour faire les oeuvres de Dieu?"}, {"numero": 29, "texto": "Jésus leur répondit: L''''oeuvre de Dieu, c''''est que vous croyiez en celui qu''''il a envoyé."}, {"numero": 30, "texto": "Quel miracle fais-tu donc, lui dirent-ils, afin que nous le voyions, et que nous croyions en toi? Que fais-tu?"}, {"numero": 31, "texto": "Nos pères ont mangé la manne dans le désert, selon ce qui est écrit: Il leur donna le pain du ciel à manger."}, {"numero": 32, "texto": "Jésus leur dit: En vérité, en vérité, je vous le dis, Moïse ne vous a pas donné le pain du ciel, mais mon Père vous donne le vrai pain du ciel;"}, {"numero": 33, "texto": "car le pain de Dieu, c''''est celui qui descend du ciel et qui donne la vie au monde."}, {"numero": 34, "texto": "Ils lui dirent: Seigneur, donne-nous toujours ce pain."}, {"numero": 35, "texto": "Jésus leur dit: Je suis le pain de vie. Celui qui vient à moi n''''aura jamais faim, et celui qui croit en moi n''''aura jamais soif."}, {"numero": 36, "texto": "Mais, je vous l''''ai dit, vous m''''avez vu, et vous ne croyez point."}, {"numero": 37, "texto": "Tous ceux que le Père me donne viendront à moi, et je ne mettrai pas dehors celui qui vient à moi;"}, {"numero": 38, "texto": "car je suis descendu du ciel pour faire, non ma volonté, mais la volonté de celui qui m''''a envoyé."}, {"numero": 39, "texto": "Or, la volonté de celui qui m''''a envoyé, c''''est que je ne perde rien de tout ce qu''''il m''''a donné, mais que je le ressuscite au dernier jour."}, {"numero": 40, "texto": "La volonté de mon Père, c''''est que quiconque voit le Fils et croit en lui ait la vie éternelle; et je le ressusciterai au dernier jour."}, {"numero": 41, "texto": "Les Juifs murmuraient à son sujet, parce qu''''il avait dit: Je suis le pain qui est descendu du ciel."}, {"numero": 42, "texto": "Et ils disaient: N''''est-ce pas là Jésus, le fils de Joseph, celui dont nous connaissons le père et la mère? Comment donc dit-il: Je suis descendu du ciel?"}, {"numero": 43, "texto": "Jésus leur répondit: Ne murmurez pas entre vous."}, {"numero": 44, "texto": "Nul ne peut venir à moi, si le Père qui m''''a envoyé ne l''''attire; et je le ressusciterai au dernier jour."}, {"numero": 45, "texto": "Il est écrit dans les prophètes: Ils seront tous enseignés de Dieu. Ainsi quiconque a entendu le Père et a reçu son enseignement vient à moi."}, {"numero": 46, "texto": "C''''est que nul n''''a vu le Père, sinon celui qui vient de Dieu; celui-là a vu le Père."}, {"numero": 47, "texto": "En vérité, en vérité, je vous le dis, celui qui croit en moi a la vie éternelle."}, {"numero": 48, "texto": "Je suis le pain de vie."}, {"numero": 49, "texto": "Vos pères ont mangé la manne dans le désert, et ils sont morts."}, {"numero": 50, "texto": "C''''est ici le pain qui descend du ciel, afin que celui qui en mange ne meure point."}, {"numero": 51, "texto": "Je suis le pain vivant qui est descendu du ciel. Si quelqu''''un mange de ce pain, il vivra éternellement; et le pain que je donnerai, c''''est ma chair, que je donnerai pour la vie du monde."}, {"numero": 52, "texto": "Là-dessus, les Juifs disputaient entre eux, disant: Comment peut-il nous donner sa chair à manger?"}, {"numero": 53, "texto": "Jésus leur dit: En vérité, en vérité, je vous le dis, si vous ne mangez la chair du Fils de l''''homme, et si vous ne buvez son sang, vous n''''avez point la vie en vous-mêmes."}, {"numero": 54, "texto": "Celui qui mange ma chair et qui boit mon sang a la vie éternelle; et je le ressusciterai au dernier jour."}, {"numero": 55, "texto": "Car ma chair est vraiment une nourriture, et mon sang est vraiment un breuvage."}, {"numero": 56, "texto": "Celui qui mange ma chair et qui boit mon sang demeure en moi, et je demeure en lui."}, {"numero": 57, "texto": "Comme le Père qui est vivant m''''a envoyé, et que je vis par le Père, ainsi celui qui me mange vivra par moi."}, {"numero": 58, "texto": "C''''est ici le pain qui est descendu du ciel. Il n''''en est pas comme de vos pères qui ont mangé la manne et qui sont morts: celui qui mange ce pain vivra éternellement."}, {"numero": 59, "texto": "Jésus dit ces choses dans la synagogue, enseignant à Capernaüm."}, {"numero": 60, "texto": "Plusieurs de ses disciples, après l''''avoir entendu, dirent: Cette parole est dure; qui peut l''''écouter?"}, {"numero": 61, "texto": "Jésus, sachant en lui-même que ses disciples murmuraient à ce sujet, leur dit: Cela vous scandalise-t-il?"}, {"numero": 62, "texto": "Et si vous voyez le Fils de l''''homme monter où il était auparavant?..."}, {"numero": 63, "texto": "C''''est l''''esprit qui vivifie; la chair ne sert de rien. Les paroles que je vous ai dites sont esprit et vie."}, {"numero": 64, "texto": "Mais il en est parmi vous quelques-uns qui ne croient point. Car Jésus savait dès le commencement qui étaient ceux qui ne croyaient point, et qui était celui qui le livrerait."}, {"numero": 65, "texto": "Et il ajouta: C''''est pourquoi je vous ai dit que nul ne peut venir à moi, si cela ne lui a été donné par le Père."}, {"numero": 66, "texto": "Dès ce moment, plusieurs de ses disciples se retirèrent, et ils n''''allaient plus avec lui."}, {"numero": 67, "texto": "Jésus donc dit aux douze: Et vous, ne voulez-vous pas aussi vous en aller?"}, {"numero": 68, "texto": "Simon Pierre lui répondit: Seigneur, à qui irions-nous? Tu as les paroles de la vie éternelle."}, {"numero": 69, "texto": "Et nous avons cru et nous avons connu que tu es le Christ, le Saint de Dieu."}, {"numero": 70, "texto": "Jésus leur répondit: N''''est-ce pas moi qui vous ai choisis, vous les douze? Et l''''un de vous est un démon!"}, {"numero": 71, "texto": "Il parlait de Judas Iscariot, fils de Simon; car c''''était lui qui devait le livrer, lui, l''''un des douze."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 6, 'es', '[{"numero": 1, "texto": "PASADAS estas cosas, fuése Jesús de la otra parte de la mar de Galilea, que es de Tiberias."}, {"numero": 2, "texto": "Y seguíale grande multitud, porque veían sus señales que hacía en los enfermos."}, {"numero": 3, "texto": "Y subió Jesús á un monte, y se sentó allí con sus discípulos."}, {"numero": 4, "texto": "Y estaba cerca la Pascua, la fiesta de los Judíos."}, {"numero": 5, "texto": "Y como alzó Jesús los ojos, y vió que había venido á él grande multitud, dice á Felipe: ¿De dónde compraremos pan para que coman éstos?"}, {"numero": 6, "texto": "Mas esto decía para probarle; porque él sabía lo que había de hacer."}, {"numero": 7, "texto": "Respondióle Felipe: Doscientos denarios de pan no les bastarán, para que cada uno de ellos tome un poco."}, {"numero": 8, "texto": "Dícele uno de sus discípulos, Andrés, hermano de Simón Pedro:"}, {"numero": 9, "texto": "Un muchacho está aquí que tiene cinco panes de cebada y dos pececillos; ¿mas qué es esto entre tantos?"}, {"numero": 10, "texto": "Entonces Jesús dijo: Haced recostar la gente. Y había mucha hierba en aquel lugar: y recostáronse como número de cinco mil varones."}, {"numero": 11, "texto": "Y tomó Jesús aquellos panes, y habiendo dado gracias, repartió á los discípulos, y los discípulos á los que estaban recostados: asimismo de los peces, cuanto querían."}, {"numero": 12, "texto": "Y como fueron saciados, dijo á sus discípulos: Recoged los pedazos que han quedado, porque no se pierda nada."}, {"numero": 13, "texto": "Cogieron pues, é hinchieron doce cestas de pedazos de los cinco panes de cebada, que sobraron á los que habían comido."}, {"numero": 14, "texto": "Aquellos hombres entonces, como vieron la señal que Jesús había hecho, decían: Este verdaderamente es el profeta que había de venir al mundo."}, {"numero": 15, "texto": "Y entendiendo Jesús que habían de venir para arrebatarle, y hacerle rey, volvió á retirarse al monte, él solo."}, {"numero": 16, "texto": "Y como se hizo tarde, descendieron sus discípulos á la mar;"}, {"numero": 17, "texto": "Y entrando en un barco, venían de la otra parte de la mar hacia Capernaum. Y era ya oscuro, y Jesús no había venido á ellos."}, {"numero": 18, "texto": "Y levantábase la mar con un gran viento que soplaba."}, {"numero": 19, "texto": "Y como hubieron navegado como veinticinco ó treinta estadios, ven á Jesús que andaba sobre la mar, y se acercaba al barco: y tuvieron miedo."}, {"numero": 20, "texto": "Mas él les dijo: Yo soy; no tengáis miedo."}, {"numero": 21, "texto": "Ellos entonces gustaron recibirle en el barco: y luego el barco llegó á la tierra donde iban."}, {"numero": 22, "texto": "El día siguiente, la gente que estaba de la otra parte de la mar, como vió que no había allí otra navecilla sino una, y que Jesús no había entrado con sus discípulos en ella, sino que sus discípulos se habían ido solos;"}, {"numero": 23, "texto": "Y que otras navecillas habían arribado de Tiberias junto al lugar donde habían comido el pan después de haber el Señor dado gracias;"}, {"numero": 24, "texto": "Como vió pues la gente que Jesús no estaba allí, ni sus discípulos, entraron ellos en las navecillas, y vinieron á Capernaum buscando á Jesús."}, {"numero": 25, "texto": "Y hallándole de la otra parte de la mar, dijéronle: Rabbí, ¿cuándo llegaste acá?"}, {"numero": 26, "texto": "Respondióles Jesús, y dijo: De cierto, de cierto os digo, que me buscáis, no porque habéis visto las señales, sino porque comisteis el pan y os hartasteis."}, {"numero": 27, "texto": "Trabajad no por la comida que perece, mas por la comida que á vida eterna permanece, la cual el Hijo del hombre os dará: porque á éste señaló el Padre, que es Dios."}, {"numero": 28, "texto": "Y dijéronle: ¿Qué haremos para que obremos las obras de Dios?"}, {"numero": 29, "texto": "Respondió Jesús, y díjoles: Esta es la obra de Dios, que creáis en el que él ha enviado."}, {"numero": 30, "texto": "Dijéronle entonces: ¿Qué señal pues haces tú, para que veamos, y te creamos? ¿Qué obras?"}, {"numero": 31, "texto": "Nuestros padres comieron el maná en el desierto, como está escrito: Pan del cielo les dió á comer."}, {"numero": 32, "texto": "Y Jesús les dijo: De cierto, de cierto os digo: No os dió Moisés pan del cielo; mas mi Padre os da el verdadero pan del cielo."}, {"numero": 33, "texto": "Porque el pan de Dios es aquel que descendió del cielo y da vida al mundo."}, {"numero": 34, "texto": "Y dijéronle: Señor, danos siempre este pan."}, {"numero": 35, "texto": "Y Jesús les dijo: Yo soy el pan de vida: el que á mí viene, nunca tendrá hambre; y el que en mí cree, no tendrá sed jamás."}, {"numero": 36, "texto": "Mas os he dicho, que aunque me habéis visto, no creéis."}, {"numero": 37, "texto": "Todo lo que el Padre me da, vendrá á mí; y al que á mí viene, no le hecho fuera."}, {"numero": 38, "texto": "Porque he descendido del cielo, no para hacer mi voluntad, mas la voluntad del que me envió."}, {"numero": 39, "texto": "Y esta es la voluntad del que me envió, del Padre: Que todo lo que me diere, no pierda de ello, sino que lo resucite en el día postrero."}, {"numero": 40, "texto": "Y esta es la voluntad del que me ha enviado: Que todo aquel que ve al Hijo, y cree en él, tenga vida eterna: y yo le resucitaré en el día postrero."}, {"numero": 41, "texto": "Murmuraban entonces de él los Judíos, porque había dicho: Yo soy el pan que descendí del cielo."}, {"numero": 42, "texto": "Y decían: ¿No es éste Jesús, el hijo de José, cuyo padre y madre nosotros conocemos? ¿cómo, pues, dice éste: Del cielo he descendido?"}, {"numero": 43, "texto": "Y Jesús respondió, y díjoles: No murmuréis entre vosotros."}, {"numero": 44, "texto": "Ninguno puede venir á mí, si el Padre que me envió no le trajere; y yo le resucitaré en el día postrero."}, {"numero": 45, "texto": "Escrito está en los profetas: Y serán todos enseñados de Dios. Así que, todo aquel que oyó del Padre, y aprendió, viene á mí."}, {"numero": 46, "texto": "No que alguno haya visto al Padre, sino aquel que vino de Dios, éste ha visto al Padre."}, {"numero": 47, "texto": "De cierto, de cierto os digo: El que cree en mí, tiene vida eterna."}, {"numero": 48, "texto": "Yo soy el pan de vida."}, {"numero": 49, "texto": "Vuestros padres comieron el maná en el desierto, y son muertos."}, {"numero": 50, "texto": "Este es el pan que desciende del cielo, para que el que de él comiere, no muera."}, {"numero": 51, "texto": "Yo soy el pan vivo que he descendido del cielo: si alguno comiere de este pan, vivirá para siempre; y el pan que yo daré es mi carne, la cual yo daré por la vida del mundo."}, {"numero": 52, "texto": "Entonces los Judíos contendían entre sí, diciendo: ¿Cómo puede éste darnos su carne á comer?"}, {"numero": 53, "texto": "Y Jesús les dijo: De cierto, de cierto os digo: Si no comiereis la carne del Hijo del hombre, y bebiereis su sangre, no tendréis vida en vosotros."}, {"numero": 54, "texto": "El que come mi carne y bebe mi sangre, tiene vida eterna: y yo le resucitaré en el día postrero."}, {"numero": 55, "texto": "Porque mi carne es verdadera comida, y mi sangre es verdadera bebida."}, {"numero": 56, "texto": "El que come mi carne y bebe mi sangre, en mí permanece, y yo en él."}, {"numero": 57, "texto": "Como me envió el Padre viviente, y yo vivo por el Padre, asimismo el que me come, él también vivirá por mí."}, {"numero": 58, "texto": "Este es el pan que descendió del cielo: no como vuestros padres comieron el maná, y son muertos: el que come de este pan, vivirá eternamente."}, {"numero": 59, "texto": "Estas cosas dijo en la sinagoga, enseñando en Capernaum."}, {"numero": 60, "texto": "Y muchos de sus discípulos oyéndolo, dijeron: Dura es esta palabra: ¿quién la puede oir?"}, {"numero": 61, "texto": "Y sabiendo Jesús en sí mismo que sus discípulos murmuraban de esto, díjoles: ¿Esto os escandaliza?"}, {"numero": 62, "texto": "¿Pues qué, si viereis al Hijo del hombre que sube donde estaba primero?"}, {"numero": 63, "texto": "El espíritu es el que da vida; la carne nada aprovecha: las palabras que yo os he hablado, son espíritu, y son vida."}, {"numero": 64, "texto": "Mas hay algunos de vosotros que no creen. Porque Jesús desde el principio sabía quiénes eran los que no creían, y quién le había de entregar."}, {"numero": 65, "texto": "Y dijo: Por eso os he dicho que ninguno puede venir á mí, si no le fuere dado del Padre."}, {"numero": 66, "texto": "Desde esto, muchos de sus discípulos volvieron atrás, y ya no andaban con él."}, {"numero": 67, "texto": "Dijo entonces Jesús á los doce: ¿Queréis vosotros iros también?"}, {"numero": 68, "texto": "Y respondióle Simón Pedro: Señor, ¿á quién iremos? tú tienes palabras de vida eterna."}, {"numero": 69, "texto": "Y nosotros creemos y conocemos que tú eres el Cristo, el Hijo de Dios viviente."}, {"numero": 70, "texto": "Jesús le respondió: ¿No he escogido yo á vosotros doce, y uno de vosotros es diablo?"}, {"numero": 71, "texto": "Y hablaba de Judas Iscariote, hijo de Simón, porque éste era el que le había de entregar, el cual era uno de los doce."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 7, 'pt', '[{"numero": 1, "texto": "E depois disto andava Jesus na Galileia; e já não queria andar na Judeia, porque os judeus procuravam matá-lo."}, {"numero": 2, "texto": "E já estava perto a festa dos tabernáculos dos judeus."}, {"numero": 3, "texto": "Disseram-lhe pois seus irmãos: Parti daqui, e vai-te para a Judeia, para que também teus discípulos vejam as tuas obras que fazes."}, {"numero": 4, "texto": "Pois ninguém que procura ser conhecido faz coisa alguma em oculto. Se fazes estas coisas, manifesta-te ao mundo."}, {"numero": 5, "texto": "Porque nem mesmo os seus irmãos criam nele."}, {"numero": 6, "texto": "Então Jesus lhes disse: Meu tempo ainda não é chegado; mas vosso tempo sempre está pronto."}, {"numero": 7, "texto": "O mundo não pode vos odiar, mas a mim me odeia, porque dele testemunho que suas obras são más."}, {"numero": 8, "texto": "Subi vós para esta festa; eu não subo ainda a esta festa, porque ainda meu tempo não é cumprido."}, {"numero": 9, "texto": "E havendo-lhes dito isto, ficou na Galileia."}, {"numero": 10, "texto": "Mas havendo seus irmãos já subido, então subiu ele também à festa, não abertamente, mas como em oculto."}, {"numero": 11, "texto": "Buscavam-no pois os judeus na festa, e diziam: Onde ele está?"}, {"numero": 12, "texto": "E havia grande murmuração dele nas multidões. Alguns diziam: Ele é Bom;e outros diziam: Não; ele, porém, engana a multidão."}, {"numero": 13, "texto": "Todavia ninguém falava dele abertamente, com medo dos judeus."}, {"numero": 14, "texto": "Porém no meio da festa subiu Jesus ao Templo, e ensinava."}, {"numero": 15, "texto": "E maravilhavam-se os Judeus, dizendo: Como este sabe as Escrituras, não as havendo aprendido?"}, {"numero": 16, "texto": "Respondeu-lhes Jesus, e disse: Minha doutrina não é minha, mas sim daquele que me enviou."}, {"numero": 17, "texto": "Se alguém quiser fazer sua vontade, da doutrina conhecerá, se é de Deus, ou [se] eu falo de mim mesmo."}, {"numero": 18, "texto": "Quem fala de si mesmo busca sua própria honra; mas quem busca a honra daquele que o enviou, esse é verdadeiro, e não há nele injustiça."}, {"numero": 19, "texto": "Não vos deu Moisés a Lei? Mas ninguém de vós cumpre a Lei. Por que procurais me matar?"}, {"numero": 20, "texto": "Respondeu a multidão, e disse: Tens demônio; quem procura te matar?"}, {"numero": 21, "texto": "Respondeu Jesus, e disse-lhes: Uma obra fiz, e todos vos maravilhais."}, {"numero": 22, "texto": "Por isso Moisés vos deu a circuncisão (não porque seja de Moisés, mas dois pais) e no sábado circuncidais ao homem."}, {"numero": 23, "texto": "Se o homem recebe a circuncisão no sábado, para que a Lei de Moisés não seja quebrada, irritai-vos comigo, porque no sábado curei por completo um homem?"}, {"numero": 24, "texto": "Não julgueis segundo a aparência, mas julgai juízo justo."}, {"numero": 25, "texto": "Diziam, pois, alguns dos de Jerusalém: Não é este ao que procuram matar?"}, {"numero": 26, "texto": "E eis que ele fala livremente, e nada lhe dizem; por acaso é verdade que os chefes sabem que este realmente é o Cristo?"}, {"numero": 27, "texto": "Mas este bem sabemos de onde é: Porém quando vier o Cristo, ninguém saberá de onde é."}, {"numero": 28, "texto": "Exclamava pois Jesus no Templo, ensinando, e dizendo: E a mim me conheceis, e sabeis de onde sou; e eu não vim de mim mesmo; mas aquele que me enviou é verdadeiro, ao qual vós não conheceis."}, {"numero": 29, "texto": "Porém eu o conheço, porque dele sou, e ele me enviou."}, {"numero": 30, "texto": "Procuravam pois prendê-lo, mas ninguém pôs a mão nele, porque sua hora ainda não era vinda."}, {"numero": 31, "texto": "E muitos da multidão creram nele, e diziam: Quando o Cristo vier, fará ainda mais sinais do que os que este tem feito?"}, {"numero": 32, "texto": "Ouviram os fariseus que a multidão murmurava estas coisas sobre ele; e os fariseus e os chefes dos Sacerdotes mandaram oficiais para prendê-lo."}, {"numero": 33, "texto": "Disse-lhes pois Jesus: Ainda um pouco de tempo estou convosco, e [então] me irei para aquele que me enviou."}, {"numero": 34, "texto": "Vós me buscareis, mas não [me] achareis; e onde eu estou vós não podeis vir."}, {"numero": 35, "texto": "Disseram, pois, os judeus uns aos outros: Para onde este se irá, que não o acharemos? Por acaso ele irá aos dispersos entre os gregos, e a ensinar aos gregos?"}, {"numero": 36, "texto": "Que palavra é esta que disse: Vós me buscareis, mas não [me] achareis; e onde eu estou vós não podeis vir?"}, {"numero": 37, "texto": "E no último e grande dia da festa se pôs Jesus em pé, e exclamou, dizendo: Se alguém tem sede, venha a mim, e beba."}, {"numero": 38, "texto": "Quem crê em mim, como diz a Escritura, rios de água viva correrão do interior de seu corpo."}, {"numero": 39, "texto": "(E ele disse isto do Espírito que receberiam aqueles que nele cressem; pois o Espírito Santo ainda não era [vindo] ,porque Jesus ainda não havia sido glorificado)."}, {"numero": 40, "texto": "Então muitos da multidão, ouvindo esta palavra, diziam: Verdadeiramente este é o Profeta."}, {"numero": 41, "texto": "Outros diziam: Este é o Cristo; e outros diziam: Por acaso vem o Cristo da Galileia?"}, {"numero": 42, "texto": "Não diz a Escritura que o Cristo virá da semente de Davi, e da aldeia de Belém, de onde era Davi?"}, {"numero": 43, "texto": "Por isso havia divisão de opiniões na multidão por causa dele."}, {"numero": 44, "texto": "E alguns deles queriam prendê-lo, mas ninguém pôs a mão nele."}, {"numero": 45, "texto": "Vieram pois os oficiais dos sacerdotes e fariseus; e eles lhes disseram: Por que não o trouxestes?"}, {"numero": 46, "texto": "Os oficiais responderam: Ninguém jamais falou assim como este homem."}, {"numero": 47, "texto": "Responderam-lhes, pois, os fariseus: Estais vós também enganados?"}, {"numero": 48, "texto": "Por acaso algum dos chefes ou dos fariseus creu nele?"}, {"numero": 49, "texto": "Mas esta multidão, que não sabe a Lei, maldita é."}, {"numero": 50, "texto": "Disse-lhes Nicodemos, o que viera a ele de noite, que era um deles:"}, {"numero": 51, "texto": "Por acaso nossa Lei julga ao homem sem primeiro o ouvir, e entender o que faz?"}, {"numero": 52, "texto": "Responderam eles, e disseram: És tu também da Galileia? Pesquisa, e vê que nenhum profeta se levantou da Galileia."}, {"numero": 53, "texto": "E cada um foi para sua casa."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 7, 'en', '[{"numero": 1, "texto": "After these things Jesus walked in Galilee: for he would not walk in Jewry, because the Jews sought to kill him."}, {"numero": 2, "texto": "Now the Jew''s feast of tabernacles was at hand."}, {"numero": 3, "texto": "His brethren therefore said unto him, Depart hence, and go into Judaea, that thy disciples also may see the works that thou doest."}, {"numero": 4, "texto": "For there is no man that doeth any thing in secret, and he himself seeketh to be known openly. If thou do these things, shew thyself to the world."}, {"numero": 5, "texto": "For neither did his brethren believe in him."}, {"numero": 6, "texto": "Then Jesus said unto them, My time is not yet come: but your time is alway ready."}, {"numero": 7, "texto": "The world cannot hate you; but me it hateth, because I testify of it, that the works thereof are evil."}, {"numero": 8, "texto": "Go ye up unto this feast: I go not up yet unto this feast: for my time is not yet full come."}, {"numero": 9, "texto": "When he had said these words unto them, he abode still in Galilee."}, {"numero": 10, "texto": "But when his brethren were gone up, then went he also up unto the feast, not openly, but as it were in secret."}, {"numero": 11, "texto": "Then the Jews sought him at the feast, and said, Where is he?"}, {"numero": 12, "texto": "And there was much murmuring among the people concerning him: for some said, He is a good man: others said, Nay; but he deceiveth the people."}, {"numero": 13, "texto": "Howbeit no man spake openly of him for fear of the Jews."}, {"numero": 14, "texto": "Now about the midst of the feast Jesus went up into the temple, and taught."}, {"numero": 15, "texto": "And the Jews marvelled, saying, How knoweth this man letters, having never learned?"}, {"numero": 16, "texto": "Jesus answered them, and said, My doctrine is not mine, but his that sent me."}, {"numero": 17, "texto": "If any man will do his will, he shall know of the doctrine, whether it be of God, or whether I speak of myself."}, {"numero": 18, "texto": "He that speaketh of himself seeketh his own glory: but he that seeketh his glory that sent him, the same is true, and no unrighteousness is in him."}, {"numero": 19, "texto": "Did not Moses give you the law, and yet none of you keepeth the law? Why go ye about to kill me?"}, {"numero": 20, "texto": "The people answered and said, Thou hast a devil: who goeth about to kill thee?"}, {"numero": 21, "texto": "Jesus answered and said unto them, I have done one work, and ye all marvel."}, {"numero": 22, "texto": "Moses therefore gave unto you circumcision; (not because it is of Moses, but of the fathers;) and ye on the sabbath day circumcise a man."}, {"numero": 23, "texto": "If a man on the sabbath day receive circumcision, that the law of Moses should not be broken; are ye angry at me, because I have made a man every whit whole on the sabbath day?"}, {"numero": 24, "texto": "Judge not according to the appearance, but judge righteous judgment."}, {"numero": 25, "texto": "Then said some of them of Jerusalem, Is not this he, whom they seek to kill?"}, {"numero": 26, "texto": "But, lo, he speaketh boldly, and they say nothing unto him. Do the rulers know indeed that this is the very Christ?"}, {"numero": 27, "texto": "Howbeit we know this man whence he is: but when Christ cometh, no man knoweth whence he is."}, {"numero": 28, "texto": "Then cried Jesus in the temple as he taught, saying, Ye both know me, and ye know whence I am: and I am not come of myself, but he that sent me is true, whom ye know not."}, {"numero": 29, "texto": "But I know him: for I am from him, and he hath sent me."}, {"numero": 30, "texto": "Then they sought to take him: but no man laid hands on him, because his hour was not yet come."}, {"numero": 31, "texto": "And many of the people believed on him, and said, When Christ cometh, will he do more miracles than these which this man hath done?"}, {"numero": 32, "texto": "The Pharisees heard that the people murmured such things concerning him; and the Pharisees and the chief priests sent officers to take him."}, {"numero": 33, "texto": "Then said Jesus unto them, Yet a little while am I with you, and then I go unto him that sent me."}, {"numero": 34, "texto": "Ye shall seek me, and shall not find me: and where I am, thither ye cannot come."}, {"numero": 35, "texto": "Then said the Jews among themselves, Whither will he go, that we shall not find him? will he go unto the dispersed among the Gentiles, and teach the Gentiles?"}, {"numero": 36, "texto": "What manner of saying is this that he said, Ye shall seek me, and shall not find me: and where I am, thither ye cannot come?"}, {"numero": 37, "texto": "In the last day, that great day of the feast, Jesus stood and cried, saying, If any man thirst, let him come unto me, and drink."}, {"numero": 38, "texto": "He that believeth on me, as the scripture hath said, out of his belly shall flow rivers of living water."}, {"numero": 39, "texto": "(But this spake he of the Spirit, which they that believe on him should receive: for the Holy Ghost was not yet given; because that Jesus was not yet glorified.)"}, {"numero": 40, "texto": "Many of the people therefore, when they heard this saying, said, Of a truth this is the Prophet."}, {"numero": 41, "texto": "Others said, This is the Christ. But some said, Shall Christ come out of Galilee?"}, {"numero": 42, "texto": "Hath not the scripture said, That Christ cometh of the seed of David, and out of the town of Bethlehem, where David was?"}, {"numero": 43, "texto": "So there was a division among the people because of him."}, {"numero": 44, "texto": "And some of them would have taken him; but no man laid hands on him."}, {"numero": 45, "texto": "Then came the officers to the chief priests and Pharisees; and they said unto them, Why have ye not brought him?"}, {"numero": 46, "texto": "The officers answered, Never man spake like this man."}, {"numero": 47, "texto": "Then answered them the Pharisees, Are ye also deceived?"}, {"numero": 48, "texto": "Have any of the rulers or of the Pharisees believed on him?"}, {"numero": 49, "texto": "But this people who knoweth not the law are cursed."}, {"numero": 50, "texto": "Nicodemus saith unto them, (he that came to Jesus by night, being one of them,)"}, {"numero": 51, "texto": "Doth our law judge any man, before it hear him, and know what he doeth?"}, {"numero": 52, "texto": "They answered and said unto him, Art thou also of Galilee? Search, and look: for out of Galilee ariseth no prophet."}, {"numero": 53, "texto": "And every man went unto his own house."}]'::jsonb, 'King James Version'),
  ('Jo', 7, 'fr', '[{"numero": 1, "texto": "Après cela, Jésus parcourait la Galilée, car il ne voulait pas séjourner en Judée, parce que les Juifs cherchaient à le faire mourir."}, {"numero": 2, "texto": "Or, la fête des Juifs, la fête des Tabernacles, était proche."}, {"numero": 3, "texto": "Et ses frères lui dirent: Pars d''''ici, et va en Judée, afin que tes disciples voient aussi les oeuvres que tu fais."}, {"numero": 4, "texto": "Personne n''''agit en secret, lorsqu''''il désire paraître: si tu fais ces choses, montre-toi toi-même au monde."}, {"numero": 5, "texto": "Car ses frères non plus ne croyaient pas en lui."}, {"numero": 6, "texto": "Jésus leur dit: Mon temps n''''est pas encore venu, mais votre temps est toujours prêt."}, {"numero": 7, "texto": "Le monde ne peut vous haïr; moi, il me hait, parce que je rends de lui le témoignage que ses oeuvres sont mauvaises."}, {"numero": 8, "texto": "Montez, vous, à cette fête; pour moi, je n''''y monte point, parce que mon temps n''''est pas encore accompli."}, {"numero": 9, "texto": "Après leur avoir dit cela, il resta en Galilée."}, {"numero": 10, "texto": "Lorsque ses frères furent montés à la fête, il y monta aussi lui-même, non publiquement, mais comme en secret."}, {"numero": 11, "texto": "Les Juifs le cherchaient pendant la fête, et disaient: Où est-il?"}, {"numero": 12, "texto": "Il y avait dans la foule grande rumeur à son sujet. Les uns disaient: C''''est un homme de bien. D''''autres disaient: Non, il égare la multitude."}, {"numero": 13, "texto": "Personne, toutefois, ne parlait librement de lui, par crainte des Juifs."}, {"numero": 14, "texto": "Vers le milieu de la fête, Jésus monta au temple. Et il enseignait."}, {"numero": 15, "texto": "Les Juifs s''''étonnaient, disant: Comment connaît-il les Ecritures, lui qui n''''a point étudié?"}, {"numero": 16, "texto": "Jésus leur répondit: Ma doctrine n''''est pas de moi, mais de celui qui m''''a envoyé."}, {"numero": 17, "texto": "Si quelqu''''un veut faire sa volonté, il connaîtra si ma doctrine est de Dieu, ou si je parle de mon chef."}, {"numero": 18, "texto": "Celui qui parle de son chef cherche sa propre gloire; mais celui qui cherche la gloire de celui qui l''''a envoyé, celui-là est vrai, et il n''''y a point d''''injustice en lui."}, {"numero": 19, "texto": "Moïse ne vous a-t-il pas donné la loi? Et nul de vous n''''observe la loi. Pourquoi cherchez-vous à me faire mourir?"}, {"numero": 20, "texto": "La foule répondit: Tu as un démon. Qui est-ce qui cherche à te faire mourir?"}, {"numero": 21, "texto": "Jésus leur répondit: J''''ai fait une oeuvre, et vous en êtes tous étonnés."}, {"numero": 22, "texto": "Moïse vous a donné la circoncision, -non qu''''elle vienne de Moïse, car elle vient des patriarches, -et vous circoncisez un homme le jour du sabbat."}, {"numero": 23, "texto": "Si un homme reçoit la circoncision le jour du sabbat, afin que la loi de Moïse ne soit pas violée, pourquoi vous irritez-vous contre moi de ce que j''''ai guéri un homme tout entier le jour du sabbat?"}, {"numero": 24, "texto": "Ne jugez pas selon l''''apparence, mais jugez selon la justice."}, {"numero": 25, "texto": "Quelques habitants de Jérusalem disaient: N''''est-ce pas là celui qu''''ils cherchent à faire mourir?"}, {"numero": 26, "texto": "Et voici, il parle librement, et ils ne lui disent rien! Est-ce que vraiment les chefs auraient reconnu qu''''il est le Christ?"}, {"numero": 27, "texto": "Cependant celui-ci, nous savons d''''où il est; mais le Christ, quand il viendra, personne ne saura d''''où il est."}, {"numero": 28, "texto": "Et Jésus, enseignant dans le temple, s''''écria: Vous me connaissez, et vous savez d''''où je suis! Je ne suis pas venu de moi-même: mais celui qui m''''a envoyé est vrai, et vous ne le connaissez pas."}, {"numero": 29, "texto": "Moi, je le connais; car je viens de lui, et c''''est lui qui m''''a envoyé."}, {"numero": 30, "texto": "Ils cherchaient donc à se saisir de lui, et personne ne mit la main sur lui, parce que son heure n''''était pas encore venue."}, {"numero": 31, "texto": "Plusieurs parmi la foule crurent en lui, et ils disaient: Le Christ, quand il viendra, fera-t-il plus de miracles que n''''en a fait celui-ci?"}, {"numero": 32, "texto": "Les pharisiens entendirent la foule murmurant de lui ces choses. Alors les principaux sacrificateurs et les pharisiens envoyèrent des huissiers pour le saisir."}, {"numero": 33, "texto": "Jésus dit: Je suis encore avec vous pour un peu de temps, puis je m''''en vais vers celui qui m''''a envoyé."}, {"numero": 34, "texto": "Vous me chercherez et vous ne me trouverez pas, et vous ne pouvez venir où je serai."}, {"numero": 35, "texto": "Sur quoi les Juifs dirent entre eux: Où ira-t-il, que nous ne le trouvions pas? Ira-t-il parmi ceux qui sont dispersés chez les Grecs, et enseignera-t-il les Grecs?"}, {"numero": 36, "texto": "Que signifie cette parole qu''''il a dite: Vous me chercherez et vous ne me trouverez pas, et vous ne pouvez venir où je serai?"}, {"numero": 37, "texto": "Le dernier jour, le grand jour de la fête, Jésus, se tenant debout, s''''écria: Si quelqu''''un a soif, qu''''il vienne à moi, et qu''''il boive."}, {"numero": 38, "texto": "Celui qui croit en moi, des fleuves d''''eau vive couleront de son sein, comme dit l''''Ecriture."}, {"numero": 39, "texto": "Il dit cela de l''''Esprit que devaient recevoir ceux qui croiraient en lui; car l''''Esprit n''''était pas encore, parce que Jésus n''''avait pas encore été glorifié."}, {"numero": 40, "texto": "Des gens de la foule, ayant entendu ces paroles, disaient: Celui-ci est vraiment le prophète."}, {"numero": 41, "texto": "D''''autres disaient: C''''est le Christ. Et d''''autres disaient: Est-ce bien de la Galilée que doit venir le Christ?"}, {"numero": 42, "texto": "L''''Ecriture ne dit-elle pas que c''''est de la postérité de David, et du village de Bethléhem, où était David, que le Christ doit venir?"}, {"numero": 43, "texto": "Il y eut donc, à cause de lui, division parmi la foule."}, {"numero": 44, "texto": "Quelques-uns d''''entre eux voulaient le saisir, mais personne ne mit la main sur lui."}, {"numero": 45, "texto": "Ainsi les huissiers retournèrent vers les principaux sacrificateurs et les pharisiens. Et ceux-ci leur dirent: Pourquoi ne l''''avez-vous pas amené?"}, {"numero": 46, "texto": "Les huissiers répondirent: Jamais homme n''''a parlé comme cet homme."}, {"numero": 47, "texto": "Les pharisiens leur répliquèrent: Est-ce que vous aussi, vous avez été séduits?"}, {"numero": 48, "texto": "Y a-t-il quelqu''''un des chefs ou des pharisiens qui ait cru en lui?"}, {"numero": 49, "texto": "Mais cette foule qui ne connaît pas la loi, ce sont des maudits!"}, {"numero": 50, "texto": "Nicodème, qui était venu de nuit vers Jésus, et qui était l''''un d''''entre eux, leur dit:"}, {"numero": 51, "texto": "Notre loi condamne-t-elle un homme avant qu''''on l''''entende et qu''''on sache ce qu''''il a fait?"}, {"numero": 52, "texto": "Ils lui répondirent: Es-tu aussi Galiléen? Examine, et tu verras que de la Galilée il ne sort point de prophète."}, {"numero": 53, "texto": "Et chacun s''''en retourna dans sa maison."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 7, 'es', '[{"numero": 1, "texto": "Y PASADAS estas cosas andaba Jesús en Galilea: que no quería andar en Judea, porque los Judíos procuraban matarle."}, {"numero": 2, "texto": "Y estaba cerca la fiesta de los Judíos, la de los tabernáculos."}, {"numero": 3, "texto": "Y dijéronle sus hermanos: Pásate de aquí, y vete á Judea, para que también tus discípulos vean las obras que haces."}, {"numero": 4, "texto": "Que ninguno que procura ser claro, hace algo en oculto. Si estas cosas haces, manifiéstate al mundo."}, {"numero": 5, "texto": "Porque ni aun sus hermanos creían en él."}, {"numero": 6, "texto": "Díceles entonces Jesús: Mi tiempo aun no ha venido; mas vuestro tiempo siempre está presto."}, {"numero": 7, "texto": "No puede el mundo aborreceros á vosotros; mas á mí me aborrece, porque yo doy testimonio de él, que sus obras son malas."}, {"numero": 8, "texto": "Vosotros subid á esta fiesta; yo no subo aún á esta fiesta, porque mi tiempo aun no es cumplido."}, {"numero": 9, "texto": "Y habiéndoles dicho esto, quedóse en Galilea."}, {"numero": 10, "texto": "Mas como sus hermanos hubieron subido, entonces él también subió á la fiesta, no manifiestamente, sino como en secreto."}, {"numero": 11, "texto": "Y buscábanle los Judíos en la fiesta, y decían: ¿Dónde está aquél?"}, {"numero": 12, "texto": "Y había grande murmullo de él entre la gente: porque unos decían: Bueno es; y otros decían: No, antes engaña á las gentes."}, {"numero": 13, "texto": "Mas ninguno hablaba abiertamente de él, por miedo de los Judíos."}, {"numero": 14, "texto": "Y al medio de la fiesta subió Jesús al templo, y enseñaba."}, {"numero": 15, "texto": "Y maravillábanse los Judíos, diciendo: ¿Cómo sabe éste letras, no habiendo aprendido?"}, {"numero": 16, "texto": "Respondióles Jesús, y dijo: Mi doctrina no es mía, sino de aquél que me envió."}, {"numero": 17, "texto": "El que quisiere hacer su voluntad, conocerá de la doctrina si viene de Dios, ó si yo hablo de mí mismo."}, {"numero": 18, "texto": "El que habla de sí mismo, su propia gloria busca; mas el que busca la gloria del que le envió, éste es verdadero, y no hay en él injusticia."}, {"numero": 19, "texto": "¿No os dió Moisés la ley, y ninguno de vosotros hace la ley? ¿Por qué me procuráis matar?"}, {"numero": 20, "texto": "Respondió la gente, y dijo: Demonio tienes: ¿quién te procura matar?"}, {"numero": 21, "texto": "Jesús respondió, y díjoles: Una obra hice, y todos os maravilláis."}, {"numero": 22, "texto": "Cierto, Moisés os dió la circuncisión (no porque sea de Moisés, mas de los padres); y en sábado circuncidáis al hombre."}, {"numero": 23, "texto": "Si recibe el hombre la circuncisión en sábado, para que la ley de Moisés no sea quebrantada, ¿os enojáis conmigo porque en sábado hice sano todo un hombre?"}, {"numero": 24, "texto": "No juzguéis según lo que parece, mas juzgad justo juicio."}, {"numero": 25, "texto": "Decían entonces unos de los de Jerusalem: ¿No es éste al que buscan para matarlo?"}, {"numero": 26, "texto": "Y he aquí, habla públicamente, y no le dicen nada; ¿si habrán entendido verdaderamente los príncipes, que éste es el Cristo?"}, {"numero": 27, "texto": "Mas éste, sabemos de dónde es: y cuando viniere el Cristo, nadie sabrá de dónde sea."}, {"numero": 28, "texto": "Entonces clamaba Jesús en el templo, enseñando y diciendo: Y á mí me conocéis, y sabéis de dónde soy; y no he venido de mí mismo; mas el que me envió es verdadero, al cual vosotros no conocéis."}, {"numero": 29, "texto": "Yo le conozco, porque de él soy, y él me envió."}, {"numero": 30, "texto": "Entonces procuraban prenderle; mas ninguno puso en él mano, porque aun no había venido su hora."}, {"numero": 31, "texto": "Y muchos del pueblo creyeron en él, y decían: El Cristo, cuando viniere, ¿hará más señales que las que éste hace?"}, {"numero": 32, "texto": "Los Fariseos oyeron á la gente que murmuraba de él estas cosas; y los príncipes de los sacerdotes y los Fariseos enviaron servidores que le prendiesen."}, {"numero": 33, "texto": "Y Jesús dijo: Aun un poco de tiempo estaré con vosotros, é iré al que me envió."}, {"numero": 34, "texto": "Me buscaréis, y no me hallaréis; y donde yo estaré, vosotros no podréis venir."}, {"numero": 35, "texto": "Entonces los Judíos dijeron entre sí: ¿A dónde se ha de ir éste que no le hallemos? ¿Se ha de ir á los esparcidos entre los Griegos, y á enseñar á los Griegos?"}, {"numero": 36, "texto": "¿Qué dicho es éste que dijo: Me buscaréis, y no me hallaréis; y donde yo estaré, vosotros no podréis venir?"}, {"numero": 37, "texto": "Mas en el postrer día grande de la fiesta, Jesús se ponía en pie y clamaba, diciendo: Si alguno tiene sed, venga á mí y beba."}, {"numero": 38, "texto": "El que cree en mí, como dice la Escritura, ríos de agua viva correrán de su vientre."}, {"numero": 39, "texto": "(Y esto dijo del Espíritu que habían de recibir los que creyesen en él: pues aun no había venido el Espíritu Santo; porque Jesús no estaba aún glorificado.)"}, {"numero": 40, "texto": "Entonces algunos de la multitud, oyendo este dicho, decían: Verdaderamente éste es el profeta."}, {"numero": 41, "texto": "Otros decían: Este es el Cristo. Algunos empero decían: ¿De Galilea ha de venir el Cristo?"}, {"numero": 42, "texto": "¿No dice la Escritura, que de la simiente de David, y de la aldea de Bethlehem, de donde era David, vendrá el Cristo?"}, {"numero": 43, "texto": "Así que había disensión entre la gente acerca de él."}, {"numero": 44, "texto": "Y algunos de ellos querían prenderle; mas ninguno echó sobre él manos."}, {"numero": 45, "texto": "Y los ministriles vinieron á los principales sacerdotes y á los Fariseos; y ellos les dijeron: ¿Por qué no le trajisteis?"}, {"numero": 46, "texto": "Los ministriles respondieron: Nunca ha hablado hombre así como este hombre."}, {"numero": 47, "texto": "Entonces los Fariseos les respondieron: ¿Estáis también vosotros engañados?"}, {"numero": 48, "texto": "¿Ha creído en él alguno de los príncipes, ó de los Fariseos?"}, {"numero": 49, "texto": "Mas estos comunales que no saben la ley, malditos son."}, {"numero": 50, "texto": "Díceles Nicodemo (el que vino á él de noche, el cual era uno de ellos):"}, {"numero": 51, "texto": "¿Juzga nuestra ley á hombre, si primero no oyere de él, y entendiere lo que ha hecho?"}, {"numero": 52, "texto": "Respondieron y dijéronle: ¿Eres tú también Galileo? Escudriña y ve que de Galilea nunca se levantó profeta."}, {"numero": 53, "texto": "Y fuése cada uno á su casa."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 8, 'pt', '[{"numero": 1, "texto": "Porém Jesus foi para o monte das Oliveiras."}, {"numero": 2, "texto": "E pela manhã cedo voltou ao Templo, e todo o povo veio a ele; e sentando-se, ensinava-os."}, {"numero": 3, "texto": "E trouxeram-lhe os escribas e fariseus uma mulher tomada em adultério;"}, {"numero": 4, "texto": "E pondo-a no meio, disseram-lhe: Mestre, esta mulher foi tomada no momento em que estava adulterando."}, {"numero": 5, "texto": "E na Lei nos mandou Moisés, que as tais sejam apedrejadas; tu pois que dizes?"}, {"numero": 6, "texto": "E isto diziam eles, tentando-o, para que tivessem de que o acusar. Mas inclinando-se Jesus, escrevia com o dedo na terra."}, {"numero": 7, "texto": "E enquanto continuavam lhe perguntando, ele se endireitou, e disse-lhes: Aquele de vós que está sem pecado, [seja] o primeiro que atire pedra contra ela."}, {"numero": 8, "texto": "E voltando a se inclinar, escrevia na terra."}, {"numero": 9, "texto": "Porém ouvindo eles [isto] , e acusados pela [própria] consciência, saíram um a um, começando dos mais velhos até os últimos; e Jesus ficou só, e a mulher, que estava no meio."}, {"numero": 10, "texto": "E endireitando-se Jesus, e não vendo a ninguém além da mulher, disse-lhe: Mulher, onde estão aqueles teus acusadores? Ninguém te condenou?"}, {"numero": 11, "texto": "E disse ela: Ninguém, Senhor. E disse-lhe Jesus: Nem eu também te condeno; vai, e não peques mais."}, {"numero": 12, "texto": "Falou-lhes pois Jesus outra vez, dizendo: Eu sou a luz do mundo; quem me seguir não andará em trevas, mas terá luz de vida."}, {"numero": 13, "texto": "Disseram-lhe pois os Fariseus: Tu testemunhas de ti mesmo; teu testemunho não é verdadeiro."}, {"numero": 14, "texto": "Respondeu Jesus, e disse-lhes: Ainda que eu testemunho de mim mesmo, meu testemunho é verdadeiro; porque sei de onde vim, e para onde vou; porém vós não sabeis, de onde venho, nem para onde vou."}, {"numero": 15, "texto": "Vós julgais segundo a carne, eu não julgo a ninguém."}, {"numero": 16, "texto": "E se eu também julgo, meu juízo é verdadeiro; porque não sou eu só, mas eu, e o Pai que me enviou."}, {"numero": 17, "texto": "E também em vossa Lei está escrito que o testemunho de duas pessoas é verdadeiro."}, {"numero": 18, "texto": "Eu sou o que testemunho de mim mesmo; e [também] de mim testemunha o Pai, que me enviou."}, {"numero": 19, "texto": "Disseram-lhe pois: Onde está teu Pai? Respondeu Jesus: Nem a mim me conheceis, nem a meu Pai; se vós a mim conhecêsseis, também conheceríeis a meu Pai."}, {"numero": 20, "texto": "Estas palavras falou Jesus junto à arca do tesouro, ensinando no Templo; e ninguém o prendeu, porque sua hora ainda não era chegada."}, {"numero": 21, "texto": "Disse-lhes pois Jesus outra vez: Eu me vou, e me buscareis, e morrereis em vosso pecado; para onde eu vou vós não podeis vir."}, {"numero": 22, "texto": "Diziam, pois, os Judeus: Ele, por acaso, matará a si mesmo? Pois diz: Para onde eu vou vós não podeis vir."}, {"numero": 23, "texto": "E ele lhes dizia: Vós sois de baixo, eu sou de cima; vós sois deste mundo, eu não sou deste mundo."}, {"numero": 24, "texto": "Por isso eu vos disse, que morrereis em vossos pecados; porque se não credes que eu sou, morrereis em vossos pecados."}, {"numero": 25, "texto": "Disseram-lhe pois: Quem és tu? Jesus lhes disse: [Sou] o mesmo que desde o princípio tenho vos dito."}, {"numero": 26, "texto": "Muitas coisas tenho que dizer e julgar de vós; mas verdadeiro é aquele que me enviou; e eu, o que dele tenho ouvido, isso falo ao mundo."}, {"numero": 27, "texto": "[Mas] não entenderam que ele estava lhes falando do Pai."}, {"numero": 28, "texto": "Jesus, então, lhes disse: Quando levantardes ao Filho do homem, então entendereis que eu sou, e que nada faço de mim mesmo; mas isto digo, como meu Pai me ensinou."}, {"numero": 29, "texto": "E aquele que me enviou está comigo. O Pai não me tem deixado só, porque sempre faço o que lhe agrada."}, {"numero": 30, "texto": "Falando ele estas coisas, muitos creram nele."}, {"numero": 31, "texto": "Dizia, pois, Jesus aos judeus que criam nele: Se vós permanecerdes em minha palavra, verdadeiramente sereis meus discípulos."}, {"numero": 32, "texto": "E conhecereis a verdade, e a verdade vos libertará."}, {"numero": 33, "texto": "Responderam-lhe: Somos descendência de Abraão, e nunca servimos a ninguém; como, [pois] , dizes: Sereis livres?"}, {"numero": 34, "texto": "Respondeu-lhes Jesus: Em verdade, em verdade vos digo, que todo aquele que comete pecado é servo do pecado."}, {"numero": 35, "texto": "E o servo não fica em casa para sempre; o Filho fica para sempre."}, {"numero": 36, "texto": "Portanto, se o Filho vos libertar, verdadeiramente sereis livres."}, {"numero": 37, "texto": "Bem sei que sois descendência de Abraão; porém procurais matar-me, porque minha palavra não encontra lugar em vós."}, {"numero": 38, "texto": "Eu, o que vi junto a meu Pai, [isso] falo; e vós, o que também vistes junto a vosso pai [isso] fazeis."}, {"numero": 39, "texto": "Responderam, e lhe disseram: Nosso pai é Abraão. Disse-lhes Jesus: Se fôsseis filhos de Abraão, faríeis as obras de Abraão."}, {"numero": 40, "texto": "Porém agora procurais matar a mim, o homem que tenho vos falado a verdade que de Deus tenho ouvido; Abraão não fez isto."}, {"numero": 41, "texto": "Vós fazeis as obras de vosso pai.Disseram-lhe pois: Nós não somos nascidos de pecado sexual; nós temos um Pai: Deus."}, {"numero": 42, "texto": "Disse-lhes pois Jesus: Se Deus fosse vosso Pai, verdadeiramente me amaríeis; porque eu saí e venho de Deus; pois não vim de mim mesmo, porém ele me enviou."}, {"numero": 43, "texto": "Por que não entendeis meu discurso? Porque não podeis ouvir minha palavra."}, {"numero": 44, "texto": "Vós sois [filhos] de [vosso] pai, o Diabo, e quereis fazer os desejos de vosso pai; ele foi homicida desde o princípio, e não permaneceu na verdade, porque nele não há verdade; quando fala mentira, fala do seu próprio; porque é mentiroso, e pai da [mentira] ."}, {"numero": 45, "texto": "Porém a mim, porque [vos] digo a verdade, não credes em mim."}, {"numero": 46, "texto": "Quem de vós me convence de pecado? E se digo a verdade, por que não credes em mim?"}, {"numero": 47, "texto": "Quem é de Deus, ouve as palavras de Deus; portanto vós não [as] ouvis porque não sois de Deus."}, {"numero": 48, "texto": "Responderam, pois, os Judeus, e lhe disseram: Nós não dizemos com razão que és samaritano, e tens o demônio?"}, {"numero": 49, "texto": "Respondeu Jesus: Eu não tenho demônio, antes honro a meu Pai; e vós me desonrais."}, {"numero": 50, "texto": "Mas eu não busco minha glória; há quem a busque, e julgue."}, {"numero": 51, "texto": "Em verdade, em verdade vos digo, que se alguém guardar minha palavra, jamais verá a morte."}, {"numero": 52, "texto": "Disseram-lhe pois os Judeus: Agora conhecemos que tens o demônio. Abraão e os profetas morreram; e tu dizes: Se alguém guardar minha palavra, jamais experimentará a morte."}, {"numero": 53, "texto": "És tu maior que nosso pai Abraão, que morreu? Os profetas também morreram. Quem tu dizes ser?"}, {"numero": 54, "texto": "Respondeu Jesus: Se eu me glorifico a mim mesmo, minha glória é nada; meu Pai, o qual vós dizeis ser vosso Deus, ele é o que me glorifica."}, {"numero": 55, "texto": "E vós não o conheceis, mas eu o conheço; e se disser que não o conheço, serei mentiroso como vós; mas eu o conheço, e guardo sua palavra."}, {"numero": 56, "texto": "Abraão, vosso pai, saltou de alegria por ver o meu dia; ele viu, e se alegrou."}, {"numero": 57, "texto": "Disseram-lhe, pois. os Judeus: Ainda não tens cinquenta anos, e viste a Abraão?"}, {"numero": 58, "texto": "Jesus lhes disse: Em verdade, em verdade vos digo, que antes que Abraão fosse, eu sou."}, {"numero": 59, "texto": "Então tomaram pedras para atirarem nele. Mas Jesus se escondeu, e saiu do Templo, atravessando por meio deles, e assim se foi."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 8, 'en', '[{"numero": 1, "texto": "Jesus went unto the mount of Olives."}, {"numero": 2, "texto": "And early in the morning he came again into the temple, and all the people came unto him; and he sat down, and taught them."}, {"numero": 3, "texto": "And the scribes and Pharisees brought unto him a woman taken in adultery; and when they had set her in the midst,"}, {"numero": 4, "texto": "They say unto him, Master, this woman was taken in adultery, in the very act."}, {"numero": 5, "texto": "Now Moses in the law commanded us, that such should be stoned: but what sayest thou?"}, {"numero": 6, "texto": "This they said, tempting him, that they might have to accuse him. But Jesus stooped down, and with his finger wrote on the ground, as though he heard them not."}, {"numero": 7, "texto": "So when they continued asking him, he lifted up himself, and said unto them, He that is without sin among you, let him first cast a stone at her."}, {"numero": 8, "texto": "And again he stooped down, and wrote on the ground."}, {"numero": 9, "texto": "And they which heard it, being convicted by their own conscience, went out one by one, beginning at the eldest, even unto the last: and Jesus was left alone, and the woman standing in the midst."}, {"numero": 10, "texto": "When Jesus had lifted up himself, and saw none but the woman, he said unto her, Woman, where are those thine accusers? hath no man condemned thee?"}, {"numero": 11, "texto": "She said, No man, Lord. And Jesus said unto her, Neither do I condemn thee: go, and sin no more."}, {"numero": 12, "texto": "Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life."}, {"numero": 13, "texto": "The Pharisees therefore said unto him, Thou bearest record of thyself; thy record is not true."}, {"numero": 14, "texto": "Jesus answered and said unto them, Though I bear record of myself, yet my record is true: for I know whence I came, and whither I go; but ye cannot tell whence I come, and whither I go."}, {"numero": 15, "texto": "Ye judge after the flesh; I judge no man."}, {"numero": 16, "texto": "And yet if I judge, my judgment is true: for I am not alone, but I and the Father that sent me."}, {"numero": 17, "texto": "It is also written in your law, that the testimony of two men is true."}, {"numero": 18, "texto": "I am one that bear witness of myself, and the Father that sent me beareth witness of me."}, {"numero": 19, "texto": "Then said they unto him, Where is thy Father? Jesus answered, Ye neither know me, nor my Father: if ye had known me, ye should have known my Father also."}, {"numero": 20, "texto": "These words spake Jesus in the treasury, as he taught in the temple: and no man laid hands on him; for his hour was not yet come."}, {"numero": 21, "texto": "Then said Jesus again unto them, I go my way, and ye shall seek me, and shall die in your sins: whither I go, ye cannot come."}, {"numero": 22, "texto": "Then said the Jews, Will he kill himself? because he saith, Whither I go, ye cannot come."}, {"numero": 23, "texto": "And he said unto them, Ye are from beneath; I am from above: ye are of this world; I am not of this world."}, {"numero": 24, "texto": "I said therefore unto you, that ye shall die in your sins: for if ye believe not that I am he, ye shall die in your sins."}, {"numero": 25, "texto": "Then said they unto him, Who art thou? And Jesus saith unto them, Even the same that I said unto you from the beginning."}, {"numero": 26, "texto": "I have many things to say and to judge of you: but he that sent me is true; and I speak to the world those things which I have heard of him."}, {"numero": 27, "texto": "They understood not that he spake to them of the Father."}, {"numero": 28, "texto": "Then said Jesus unto them, When ye have lifted up the Son of man, then shall ye know that I am he, and that I do nothing of myself; but as my Father hath taught me, I speak these things."}, {"numero": 29, "texto": "And he that sent me is with me: the Father hath not left me alone; for I do always those things that please him."}, {"numero": 30, "texto": "As he spake these words, many believed on him."}, {"numero": 31, "texto": "Then said Jesus to those Jews which believed on him, If ye continue in my word, then are ye my disciples indeed;"}, {"numero": 32, "texto": "And ye shall know the truth, and the truth shall make you free."}, {"numero": 33, "texto": "They answered him, We be Abraham''s seed, and were never in bondage to any man: how sayest thou, Ye shall be made free?"}, {"numero": 34, "texto": "Jesus answered them, Verily, verily, I say unto you, Whosoever committeth sin is the servant of sin."}, {"numero": 35, "texto": "And the servant abideth not in the house for ever: but the Son abideth ever."}, {"numero": 36, "texto": "If the Son therefore shall make you free, ye shall be free indeed."}, {"numero": 37, "texto": "I know that ye are Abraham''s seed; but ye seek to kill me, because my word hath no place in you."}, {"numero": 38, "texto": "I speak that which I have seen with my Father: and ye do that which ye have seen with your father."}, {"numero": 39, "texto": "They answered and said unto him, Abraham is our father. Jesus saith unto them, If ye were Abraham''s children, ye would do the works of Abraham."}, {"numero": 40, "texto": "But now ye seek to kill me, a man that hath told you the truth, which I have heard of God: this did not Abraham."}, {"numero": 41, "texto": "Ye do the deeds of your father. Then said they to him, We be not born of fornication; we have one Father, even God."}, {"numero": 42, "texto": "Jesus said unto them, If God were your Father, ye would love me: for I proceeded forth and came from God; neither came I of myself, but he sent me."}, {"numero": 43, "texto": "Why do ye not understand my speech? even because ye cannot hear my word."}, {"numero": 44, "texto": "Ye are of your father the devil, and the lusts of your father ye will do. He was a murderer from the beginning, and abode not in the truth, because there is no truth in him. When he speaketh a lie, he speaketh of his own: for he is a liar, and the father of it."}, {"numero": 45, "texto": "And because I tell you the truth, ye believe me not."}, {"numero": 46, "texto": "Which of you convinceth me of sin? And if I say the truth, why do ye not believe me?"}, {"numero": 47, "texto": "He that is of God heareth God''s words: ye therefore hear them not, because ye are not of God."}, {"numero": 48, "texto": "Then answered the Jews, and said unto him, Say we not well that thou art a Samaritan, and hast a devil?"}, {"numero": 49, "texto": "Jesus answered, I have not a devil; but I honour my Father, and ye do dishonour me."}, {"numero": 50, "texto": "And I seek not mine own glory: there is one that seeketh and judgeth."}, {"numero": 51, "texto": "Verily, verily, I say unto you, If a man keep my saying, he shall never see death."}, {"numero": 52, "texto": "Then said the Jews unto him, Now we know that thou hast a devil. Abraham is dead, and the prophets; and thou sayest, If a man keep my saying, he shall never taste of death."}, {"numero": 53, "texto": "Art thou greater than our father Abraham, which is dead? and the prophets are dead: whom makest thou thyself?"}, {"numero": 54, "texto": "Jesus answered, If I honour myself, my honour is nothing: it is my Father that honoureth me; of whom ye say, that he is your God:"}, {"numero": 55, "texto": "Yet ye have not known him; but I know him: and if I should say, I know him not, I shall be a liar like unto you: but I know him, and keep his saying."}, {"numero": 56, "texto": "Your father Abraham rejoiced to see my day: and he saw it, and was glad."}, {"numero": 57, "texto": "Then said the Jews unto him, Thou art not yet fifty years old, and hast thou seen Abraham?"}, {"numero": 58, "texto": "Jesus said unto them, Verily, verily, I say unto you, Before Abraham was, I am."}, {"numero": 59, "texto": "Then took they up stones to cast at him: but Jesus hid himself, and went out of the temple, going through the midst of them, and so passed by."}]'::jsonb, 'King James Version'),
  ('Jo', 8, 'fr', '[{"numero": 1, "texto": "Jésus se rendit à la montagne des oliviers."}, {"numero": 2, "texto": "Mais, dès le matin, il alla de nouveau dans le temple, et tout le peuple vint à lui. S''''étant assis, il les enseignait."}, {"numero": 3, "texto": "Alors les scribes et les pharisiens amenèrent une femme surprise en adultère; et, la plaçant au milieu du peuple,"}, {"numero": 4, "texto": "ils dirent à Jésus: Maître, cette femme a été surprise en flagrant délit d''''adultère."}, {"numero": 5, "texto": "Moïse, dans la loi, nous a ordonné de lapider de telles femmes: toi donc, que dis-tu?"}, {"numero": 6, "texto": "Ils disaient cela pour l''''éprouver, afin de pouvoir l''''accuser. Mais Jésus, s''''étant baissé, écrivait avec le doigt sur la terre."}, {"numero": 7, "texto": "Comme ils continuaient à l''''interroger, il se releva et leur dit: Que celui de vous qui est sans péché jette le premier la pierre contre elle."}, {"numero": 8, "texto": "Et s''''étant de nouveau baissé, il écrivait sur la terre."}, {"numero": 9, "texto": "Quand ils entendirent cela, accusés par leur conscience, ils se retirèrent un à un, depuis les plus âgés jusqu''''aux derniers; et Jésus resta seul avec la femme qui était là au milieu."}, {"numero": 10, "texto": "Alors s''''étant relevé, et ne voyant plus que la femme, Jésus lui dit: Femme, où sont ceux qui t''''accusaient? Personne ne t''''a-t-il condamnée?"}, {"numero": 11, "texto": "Elle répondit: Non, Seigneur. Et Jésus lui dit: Je ne te condamne pas non plus: va, et ne pèche plus."}, {"numero": 12, "texto": "Jésus leur parla de nouveau, et dit: Je suis la lumière du monde; celui qui me suit ne marchera pas dans les ténèbres, mais il aura la lumière de la vie."}, {"numero": 13, "texto": "Là-dessus, les pharisiens lui dirent: Tu rends témoignage de toi-même; ton témoignage n''''est pas vrai."}, {"numero": 14, "texto": "Jésus leur répondit: Quoique je rende témoignage de moi-même, mon témoignage est vrai, car je sais d''''où je suis venu et où je vais; mais vous, vous ne savez d''''où je viens ni où je vais."}, {"numero": 15, "texto": "Vous jugez selon la chair; moi, je ne juge personne."}, {"numero": 16, "texto": "Et si je juge, mon jugement est vrai, car je ne suis pas seul; mais le Père qui m''''a envoyé est avec moi."}, {"numero": 17, "texto": "Il est écrit dans votre loi que le témoignage de deux hommes est vrai;"}, {"numero": 18, "texto": "je rends témoignage de moi-même, et le Père qui m''''a envoyé rend témoignage de moi."}, {"numero": 19, "texto": "Ils lui dirent donc: Où est ton Père? Jésus répondit: Vous ne connaissez ni moi, ni mon Père. Si vous me connaissiez, vous connaîtriez aussi mon Père."}, {"numero": 20, "texto": "Jésus dit ces paroles, enseignant dans le temple, au lieu où était le trésor; et personne ne le saisit, parce que son heure n''''était pas encore venue."}, {"numero": 21, "texto": "Jésus leur dit encore: Je m''''en vais, et vous me chercherez, et vous mourrez dans votre péché; vous ne pouvez venir où je vais."}, {"numero": 22, "texto": "Sur quoi les Juifs dirent: Se tuera-t-il lui-même, puisqu''''il dit: Vous ne pouvez venir où je vais?"}, {"numero": 23, "texto": "Et il leur dit: Vous êtes d''''en bas; moi, je suis d''''en haut. Vous êtes de ce monde; moi, je ne suis pas de ce monde."}, {"numero": 24, "texto": "C''''est pourquoi je vous ai dit que vous mourrez dans vos péchés; car si vous ne croyez pas ce que je suis, vous mourrez dans vos péchés."}, {"numero": 25, "texto": "Qui es-tu? lui dirent-ils. Jésus leur répondit: Ce que je vous dis dès le commencement."}, {"numero": 26, "texto": "J''''ai beaucoup de choses à dire de vous et à juger en vous; mais celui qui m''''a envoyé est vrai, et ce que j''''ai entendu de lui, je le dis au monde."}, {"numero": 27, "texto": "Ils ne comprirent point qu''''il leur parlait du Père."}, {"numero": 28, "texto": "Jésus donc leur dit: Quand vous aurez élevé le Fils de l''''homme, alors vous connaîtrez ce que je suis, et que je ne fais rien de moi-même, mais que je parle selon ce que le Père m''''a enseigné."}, {"numero": 29, "texto": "Celui qui m''''a envoyé est avec moi; il ne m''''a pas laissé seul, parce que je fais toujours ce qui lui est agréable."}, {"numero": 30, "texto": "Comme Jésus parlait ainsi, plusieurs crurent en lui."}, {"numero": 31, "texto": "Et il dit aux Juifs qui avaient cru en lui: Si vous demeurez dans ma parole, vous êtes vraiment mes disciples;"}, {"numero": 32, "texto": "vous connaîtrez la vérité, et la vérité vous affranchira."}, {"numero": 33, "texto": "Ils lui répondirent: Nous sommes la postérité d''''Abraham, et nous ne fûmes jamais esclaves de personne; comment dis-tu: Vous deviendrez libres?"}, {"numero": 34, "texto": "En vérité, en vérité, je vous le dis, leur répliqua Jésus, quiconque se livre au péché est esclave du péché."}, {"numero": 35, "texto": "Or, l''''esclave ne demeure pas toujours dans la maison; le fils y demeure toujours."}, {"numero": 36, "texto": "Si donc le Fils vous affranchit, vous serez réellement libres."}, {"numero": 37, "texto": "Je sais que vous êtes la postérité d''''Abraham; mais vous cherchez à me faire mourir, parce que ma parole ne pénètre pas en vous."}, {"numero": 38, "texto": "Je dis ce que j''''ai vu chez mon Père; et vous, vous faites ce que vous avez entendu de la part de votre père."}, {"numero": 39, "texto": "Ils lui répondirent: Notre père, c''''est Abraham. Jésus leur dit: Si vous étiez enfants d''''Abraham, vous feriez les oeuvres d''''Abraham."}, {"numero": 40, "texto": "Mais maintenant vous cherchez à me faire mourir, moi qui vous ai dit la vérité que j''''ai entendue de Dieu. Cela, Abraham ne l''''a point fait."}, {"numero": 41, "texto": "Vous faites les oeuvres de votre père. Ils lui dirent: Nous ne sommes pas des enfants illégitimes; nous avons un seul Père, Dieu."}, {"numero": 42, "texto": "Jésus leur dit: Si Dieu était votre Père, vous m''''aimeriez, car c''''est de Dieu que je suis sorti et que je viens; je ne suis pas venu de moi-même, mais c''''est lui qui m''''a envoyé."}, {"numero": 43, "texto": "Pourquoi ne comprenez-vous pas mon langage? Parce que vous ne pouvez écouter ma parole."}, {"numero": 44, "texto": "Vous avez pour père le diable, et vous voulez accomplir les désirs de votre père. Il a été meurtrier dès le commencement, et il ne se tient pas dans la vérité, parce qu''''il n''''y a pas de vérité en lui. Lorsqu''''il profère le mensonge, il parle de son propre fonds; car il est menteur et le père du mensonge."}, {"numero": 45, "texto": "Et moi, parce que je dis la vérité, vous ne me croyez pas."}, {"numero": 46, "texto": "Qui de vous me convaincra de péché? Si je dis la vérité, pourquoi ne me croyez-vous pas?"}, {"numero": 47, "texto": "Celui qui est de Dieu, écoute les paroles de Dieu; vous n''''écoutez pas, parce que vous n''''êtes pas de Dieu."}, {"numero": 48, "texto": "Les Juifs lui répondirent: N''''avons-nous pas raison de dire que tu es un Samaritain, et que tu as un démon?"}, {"numero": 49, "texto": "Jésus répliqua: Je n''''ai point de démon; mais j''''honore mon Père, et vous m''''outragez."}, {"numero": 50, "texto": "Je ne cherche point ma gloire; il en est un qui la cherche et qui juge."}, {"numero": 51, "texto": "En vérité, en vérité, je vous le dis, si quelqu''''un garde ma parole, il ne verra jamais la mort."}, {"numero": 52, "texto": "Maintenant, lui dirent les Juifs, nous connaissons que tu as un démon. Abraham est mort, les prophètes aussi, et tu dis: Si quelqu''''un garde ma parole, il ne verra jamais la mort."}, {"numero": 53, "texto": "Es-tu plus grand que notre père Abraham, qui est mort? Les prophètes aussi sont morts. Qui prétends-tu être?"}, {"numero": 54, "texto": "Jésus répondit: Si je me glorifie moi-même, ma gloire n''''est rien. C''''est mon Père qui me glorifie, lui que vous dites être votre Dieu,"}, {"numero": 55, "texto": "et que vous ne connaissez pas. Pour moi, je le connais; et, si je disais que je ne le connais pas, je serais semblable à vous, un menteur. Mais je le connais, et je garde sa parole."}, {"numero": 56, "texto": "Abraham, votre père, a tressailli de joie de ce qu''''il verrait mon jour: il l''''a vu, et il s''''est réjoui."}, {"numero": 57, "texto": "Les Juifs lui dirent: Tu n''''as pas encore cinquante ans, et tu as vu Abraham!"}, {"numero": 58, "texto": "Jésus leur dit: En vérité, en vérité, je vous le dis, avant qu''''Abraham fût, je suis."}, {"numero": 59, "texto": "Là-dessus, ils prirent des pierres pour les jeter contre lui; mais Jésus se cacha, et il sortit du temple."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 8, 'es', '[{"numero": 1, "texto": "Y JESÚS se fué al monte de las Olivas."}, {"numero": 2, "texto": "Y por la mañana volvió al templo, y todo el pueblo vino á él: y sentado él, los enseñaba."}, {"numero": 3, "texto": "Entonces los escribas y los Fariseos le traen una mujer tomada en adulterio; y poniéndola en medio,"}, {"numero": 4, "texto": "Dícenle: Maestro, esta mujer ha sido tomada en el mismo hecho, adulterando;"}, {"numero": 5, "texto": "Y en la ley Moisés nos mandó apedrear á las tales: tú pues, ¿qué dices?"}, {"numero": 6, "texto": "Mas esto decían tentándole, para poder acusarle. Empero Jesús, inclinado hacia abajo, escribía en tierra con el dedo."}, {"numero": 7, "texto": "Y como perseverasen preguntándole, enderezóse, y díjoles: El que de vosotros esté sin pecado, arroje contra ella la piedra el primero."}, {"numero": 8, "texto": "Y volviéndose á inclinar hacia abajo, escribía en tierra."}, {"numero": 9, "texto": "Oyendo, pues, ellos, redargüidos de la conciencia, salíanse uno á uno, comenzando desde los más viejos hasta los postreros: y quedó solo Jesús, y la mujer que estaba en medio."}, {"numero": 10, "texto": "Y enderezándose Jesús, y no viendo á nadie más que á la mujer, díjole: ¿Mujer, dónde están los que te acusaban? ¿Ninguno te ha condenado?"}, {"numero": 11, "texto": "Y ella dijo: Señor, ninguno. Entonces Jesús le dijo: Ni yo te condeno: vete, y no peques más."}, {"numero": 12, "texto": "Y hablóles Jesús otra vez, diciendo: Yo soy la luz del mundo: el que me sigue, no andará en tinieblas, mas tendrá la lumbre de la vida."}, {"numero": 13, "texto": "Entonces los Fariseos le dijeron: Tú de ti mismo das testimonio: tu testimonio no es verdadero."}, {"numero": 14, "texto": "Respondió Jesús, y díjoles: Aunque yo doy testimonio de mí mismo, mi testimonio es verdadero, porque sé de dónde he venido y á dónde voy; mas vosotros no sabéis de dónde vengo, y á dónde voy."}, {"numero": 15, "texto": "Vosotros según la carne juzgáis; mas yo no juzgo á nadie."}, {"numero": 16, "texto": "Y si yo juzgo, mi juicio es verdadero; porque no soy solo, sino yo y el que me envió, el Padre."}, {"numero": 17, "texto": "Y en vuestra ley está escrito que el testimonio de dos hombres es verdadero."}, {"numero": 18, "texto": "Yo soy el que doy testimonio de mí mismo: y da testimonio de mí el que me envió, el Padre."}, {"numero": 19, "texto": "Y decíanle: ¿Dónde está tu Padre? Respondió Jesús: Ni á mí me conocéis, ni á mi Padre; si á mí me conocieseis, á mi Padre también conocierais."}, {"numero": 20, "texto": "Estas palabras habló Jesús en el lugar de las limosnas, enseñando en el templo: y nadie le prendió; porque aun no había venido su hora."}, {"numero": 21, "texto": "Y díjoles otra vez Jesús: Yo me voy, y me buscaréis, mas en vuestro pecado moriréis: á donde yo voy, vosotros no podéis venir."}, {"numero": 22, "texto": "Decían entonces los Judíos: ¿Hase de matar á sí mismo, que dice: A donde yo voy, vosotros no podéis venir?"}, {"numero": 23, "texto": "Y decíales: Vosotros sois de abajo, yo soy de arriba; vosotros sois de este mundo, yo no soy de este mundo."}, {"numero": 24, "texto": "Por eso os dije que moriréis en vuestros pecados; porque si no creyereis que yo soy, en vuestros pecados moriréis."}, {"numero": 25, "texto": "Y decíanle: ¿Tú quién eres? Entonces Jesús les dijo: El que al principio también os he dicho."}, {"numero": 26, "texto": "Muchas cosas tengo que decir y juzgar de vosotros: mas el que me envió, es verdadero: y yo, lo que he oído de él, esto hablo en el mundo."}, {"numero": 27, "texto": "Mas no entendieron que él les hablaba del Padre."}, {"numero": 28, "texto": "Díjoles pues, Jesús: Cuando levantareis al Hijo del hombre, entonces entenderéis que yo soy, y que nada hago de mí mismo; mas como el Padre me enseñó, esto hablo."}, {"numero": 29, "texto": "Porque el que me envió, conmigo está; no me ha dejado solo el Padre; porque yo, lo que á él agrada, hago siempre."}, {"numero": 30, "texto": "Hablando él estas cosas, muchos creyeron en él."}, {"numero": 31, "texto": "Y decía Jesús á los Judíos que le habían creído: Si vosotros permaneciereis en mi palabra, seréis verdaderamente mis discípulos;"}, {"numero": 32, "texto": "Y conoceréis la verdad, y la verdad os libertará."}, {"numero": 33, "texto": "Y respondiéronle: Simiente de Abraham somos, y jamás servimos á nadie: ¿cómo dices tú: Seréis libres?"}, {"numero": 34, "texto": "Jesús les respondió: De cierto, de cierto os digo, que todo aquel que hace pecado, es siervo de pecado."}, {"numero": 35, "texto": "Y el siervo no queda en casa para siempre: el hijo queda para siempre."}, {"numero": 36, "texto": "Así que, si el Hijo os libertare, seréis verdaderamente libres."}, {"numero": 37, "texto": "Sé que sois simiente de Abraham, mas procuráis matarme, porque mi palabra no cabe en vosotros."}, {"numero": 38, "texto": "Yo hablo lo que he visto cerca del Padre; y vosotros hacéis lo que habéis oído cerca de vuestro padre."}, {"numero": 39, "texto": "Respondieron y dijéronle: Nuestro padre es Abraham. Díceles Jesús: Si fuerais hijos de Abraham, las obras de Abraham haríais."}, {"numero": 40, "texto": "Empero ahora procuráis matarme, hombre que os he hablado la verdad, la cual he oído de Dios: no hizo esto Abraham."}, {"numero": 41, "texto": "Vosotros hacéis las obras de vuestro padre. Dijéronle entonces: Nosotros no somos nacidos de fornicación; un padre tenemos, que es Dios."}, {"numero": 42, "texto": "Jesús entonces les dijo: Si vuestro padre fuera Dios, ciertamente me amaríais: porque yo de Dios he salido, y he venido; que no he venido de mí mismo, mas él me envió."}, {"numero": 43, "texto": "¿Por qué no reconocéis mi lenguaje? porque no podéis oir mi palabra."}, {"numero": 44, "texto": "Vosotros de vuestro padre el diablo sois, y los deseos de vuestro padre queréis cumplir. El, homicida ha sido desde el principio, y no permaneció en la verdad, porque no hay verdad en él. Cuando habla mentira, de suyo habla; porque es mentiroso, y padre de mentira."}, {"numero": 45, "texto": "Y porque yo digo verdad, no me creéis."}, {"numero": 46, "texto": "¿Quién de vosotros me redarguye de pecado? Pues si digo verdad, ¿por qué vosotros no me creéis?"}, {"numero": 47, "texto": "El que es de Dios, las palabras de Dios oye: por esto no las oís vosotros, porque no sois de Dios."}, {"numero": 48, "texto": "Respondieron entonces los Judíos, y dijéronle: ¿No decimos bien nosotros, que tú eres Samaritano, y tienes demonio?"}, {"numero": 49, "texto": "Respondió Jesús: Yo no tengo demonio, antes honro á mi Padre; y vosotros me habéis deshonrado."}, {"numero": 50, "texto": "Y no busco mi gloria: hay quien la busque, y juzgue."}, {"numero": 51, "texto": "De cierto, de cierto os digo, que el que guardare mi palabra, no verá muerte para siempre."}, {"numero": 52, "texto": "Entonces los Judíos le dijeron: Ahora conocemos que tienes demonio. Abraham murió, y los profetas, y tú dices: El que guardare mi palabra, no gustará muerte para siempre."}, {"numero": 53, "texto": "¿Eres tú mayor que nuestro padre Abraham, el cual murió? y los profetas murieron: ¿quién te haces á ti mismo?"}, {"numero": 54, "texto": "Respondió Jesús: Si yo me glorifico á mí mismo, mi gloria es nada: mi Padre es el que me glorifica; el que vosotros decís que es vuestro Dios;"}, {"numero": 55, "texto": "Y no le conocéis: mas yo le conozco; y si dijere que no le conozco, seré como vosotros mentiroso: mas le conozco, y guardo su palabra."}, {"numero": 56, "texto": "Abraham vuestro padre se gozó por ver mi día; y lo vió, y se gozó."}, {"numero": 57, "texto": "Dijéronle entonces los Judíos: Aun no tienes cincuenta años, ¿y has visto á Abraham?"}, {"numero": 58, "texto": "Díjoles Jesús: De cierto, de cierto os digo: Antes que Abraham fuese, yo soy."}, {"numero": 59, "texto": "Tomaron entonces piedras para tirarle: mas Jesús se encubrió, y salió del templo; y atravesando por medio de ellos, se fué."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 9, 'pt', '[{"numero": 1, "texto": "E indo [Jesus] passando, viu a um homem cego desde o nascimento."}, {"numero": 2, "texto": "E seus discípulos lhe perguntaram, dizendo: Rabi, quem pecou? Este, ou seus pais, para que nascesse cego?"}, {"numero": 3, "texto": "Respondeu Jesus: Nem este pecou, nem seus pais; mas sim para que as obras de Deus nele se manifestem."}, {"numero": 4, "texto": "A mim me convém trabalhar as obras daquele que me enviou, enquanto é dia; a noite vem, quando ninguém pode trabalhar."}, {"numero": 5, "texto": "Enquanto estiver no mundo, eu sou a luz do mundo."}, {"numero": 6, "texto": "Dito isto, cuspiu em terra, e fez lama do cuspe, e untou com aquela lama os olhos do cego."}, {"numero": 7, "texto": "E disse-lhe: Vai, lava-te no tanque de Siloé (que se traduz Enviado). Foi pois, e lavou-se; e voltou vendo."}, {"numero": 8, "texto": "Então os vizinhos, e os que de antes o viram que era cego, diziam: Não é este aquele que estava sentado, e mendigava?"}, {"numero": 9, "texto": "Outros diziam: É este. E outros: Parece-se com ele. Ele dizia: Sou eu."}, {"numero": 10, "texto": "Então lhe diziam: Como teus olhos se abriram?"}, {"numero": 11, "texto": "Respondeu ele, e disse: Aquele homem chamado Jesus fez lama, untou meus olhos, e me disse: Vai ao tanque de Siloé, e lava-te. E fui, e me lavei, e vi."}, {"numero": 12, "texto": "Disseram-lhe, pois: Onde ele está? Disse ele: Não sei."}, {"numero": 13, "texto": "Levaram aos Fariseus o ex-cego."}, {"numero": 14, "texto": "E era sábado, quando Jesus fez a lama, e abriu os olhos dele."}, {"numero": 15, "texto": "Então voltaram também os Fariseus a perguntar-lhe como vira, e ele lhes disse: Pôs lama sobre os meus olhos, e me lavei, e vejo."}, {"numero": 16, "texto": "Então que alguns dos Fariseus diziam: Este homem não é de Deus, pois não guarda o sábado. Outros diziam: Como pode um homem pecador fazer tais sinais? E havia divisão entre eles."}, {"numero": 17, "texto": "Voltaram a dizer ao cego: Tu que dizes dele, que abriu teus olhos? E ele disse: Que é profeta."}, {"numero": 18, "texto": "Portanto os judeus não criam nele, de que houvesse sido cego, e [passasse a] ver, até que chamaram aos pais dos que [passou a] ver."}, {"numero": 19, "texto": "E perguntaram-lhes, dizendo: É este vosso filho, aquele que dizeis que nasceu cego? Como pois agora vê?"}, {"numero": 20, "texto": "Responderam-lhes seus pais, e disseram: Sabemos que este é nosso filho, e que nasceu cego;"}, {"numero": 21, "texto": "Mas como agora ele vê, não sabemos; ou, quem lhe abriu os olhos, não sabemos; ele tem idade [suficiente] ,perguntai a ele, ele falará por si mesmo."}, {"numero": 22, "texto": "Isto disseram seus pais, pois temiam aos judeus. Porque já os Judeus tinham combinado, que se alguém confessasse que ele era o Cristo, seria expulso da sinagoga."}, {"numero": 23, "texto": "Por isso disseram seus pais: Ele tem idade [suficiente] ,perguntai a ele."}, {"numero": 24, "texto": "Chamaram pois segunda vez ao homem que era cego, e disseram-lhe: Dá glória a Deus; nós sabemos que esse homem é pecador."}, {"numero": 25, "texto": "Respondeu pois ele, e disse: Se é pecador, não o sei; uma coisa sei, que havendo eu sido cego, agora vejo."}, {"numero": 26, "texto": "E voltaram a lhe dizer: O que ele te fez? Como ele abriu os teus olhos?"}, {"numero": 27, "texto": "Ele lhes respondeu: Eu já vos disse, e ainda não o ouvistes; para que quereis voltar a ouvir? Por acaso vós também quereis ser discípulos dele?"}, {"numero": 28, "texto": "Então lhe insultaram, e disseram: Tu sejas discípulo dele; mas nós somos discípulos de Moisés."}, {"numero": 29, "texto": "Bem sabemos nós que Deus falou a Moisés; mas este nem de onde é, não sabemos."}, {"numero": 30, "texto": "Aquele homem respondeu, e disse-lhes: Porque nisto está a maravilha: que vós não sabeis de onde ele é; e a mim abriu meus olhos!"}, {"numero": 31, "texto": "E bem sabemos que Deus não dá ouvidos aos pecadores; mas se alguém é temente a Deus, e faz sua vontade, a este dá ouvidos."}, {"numero": 32, "texto": "Desde o princípio dos tempos nunca se ouviu de que alguém que tenha aberto os olhos de um que tenha nascido cego."}, {"numero": 33, "texto": "Se este não fosse vindo de Deus, nada poderia fazer."}, {"numero": 34, "texto": "Eles responderam, e lhe disseram: Tu és todo nascido em pecados, e nos ensina? E o lançaram fora."}, {"numero": 35, "texto": "Ouviu Jesus que o haviam lançado fora, e achando-o, disse-lhe: Crês tu no Filho de Deus?"}, {"numero": 36, "texto": "Respondeu ele, e disse: Quem é, Senhor, para que nele creia?"}, {"numero": 37, "texto": "E disse-lhe Jesus: Tu já o tens visto; e este é o que fala contigo."}, {"numero": 38, "texto": "E ele disse: Creio, Senhor; E adorou-o."}, {"numero": 39, "texto": "E disse Jesus: Eu vim a este mundo para juízo, para os que não veem, vejam; e os que veem, ceguem."}, {"numero": 40, "texto": "E ouviram isto [alguns] dos fariseus, que estavam com ele; e lhe disseram: Também nós somos cegos?"}, {"numero": 41, "texto": "Disse-lhes Jesus: Se fôsseis cegos, não teríeis pecado; mas agora dizeis: Vemos; portanto vosso pecado permanece."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 9, 'en', '[{"numero": 1, "texto": "And as Jesus passed by, he saw a man which was blind from his birth."}, {"numero": 2, "texto": "And his disciples asked him, saying, Master, who did sin, this man, or his parents, that he was born blind?"}, {"numero": 3, "texto": "Jesus answered, Neither hath this man sinned, nor his parents: but that the works of God should be made manifest in him."}, {"numero": 4, "texto": "I must work the works of him that sent me, while it is day: the night cometh, when no man can work."}, {"numero": 5, "texto": "As long as I am in the world, I am the light of the world."}, {"numero": 6, "texto": "When he had thus spoken, he spat on the ground, and made clay of the spittle, and he anointed the eyes of the blind man with the clay,"}, {"numero": 7, "texto": "And said unto him, Go, wash in the pool of Siloam, (which is by interpretation, Sent.) He went his way therefore, and washed, and came seeing."}, {"numero": 8, "texto": "The neighbours therefore, and they which before had seen him that he was blind, said, Is not this he that sat and begged?"}, {"numero": 9, "texto": "Some said, This is he: others said, He is like him: but he said, I am he."}, {"numero": 10, "texto": "Therefore said they unto him, How were thine eyes opened?"}, {"numero": 11, "texto": "He answered and said, A man that is called Jesus made clay, and anointed mine eyes, and said unto me, Go to the pool of Siloam, and wash: and I went and washed, and I received sight."}, {"numero": 12, "texto": "Then said they unto him, Where is he? He said, I know not."}, {"numero": 13, "texto": "They brought to the Pharisees him that aforetime was blind."}, {"numero": 14, "texto": "And it was the sabbath day when Jesus made the clay, and opened his eyes."}, {"numero": 15, "texto": "Then again the Pharisees also asked him how he had received his sight. He said unto them, He put clay upon mine eyes, and I washed, and do see."}, {"numero": 16, "texto": "Therefore said some of the Pharisees, This man is not of God, because he keepeth not the sabbath day. Others said, How can a man that is a sinner do such miracles? And there was a division among them."}, {"numero": 17, "texto": "They say unto the blind man again, What sayest thou of him, that he hath opened thine eyes? He said, He is a prophet."}, {"numero": 18, "texto": "But the Jews did not believe concerning him, that he had been blind, and received his sight, until they called the parents of him that had received his sight."}, {"numero": 19, "texto": "And they asked them, saying, Is this your son, who ye say was born blind? how then doth he now see?"}, {"numero": 20, "texto": "His parents answered them and said, We know that this is our son, and that he was born blind:"}, {"numero": 21, "texto": "But by what means he now seeth, we know not; or who hath opened his eyes, we know not: he is of age; ask him: he shall speak for himself."}, {"numero": 22, "texto": "These words spake his parents, because they feared the Jews: for the Jews had agreed already, that if any man did confess that he was Christ, he should be put out of the synagogue."}, {"numero": 23, "texto": "Therefore said his parents, He is of age; ask him."}, {"numero": 24, "texto": "Then again called they the man that was blind, and said unto him, Give God the praise: we know that this man is a sinner."}, {"numero": 25, "texto": "He answered and said, Whether he be a sinner or no, I know not: one thing I know, that, whereas I was blind, now I see."}, {"numero": 26, "texto": "Then said they to him again, What did he to thee? how opened he thine eyes?"}, {"numero": 27, "texto": "He answered them, I have told you already, and ye did not hear: wherefore would ye hear it again? will ye also be his disciples?"}, {"numero": 28, "texto": "Then they reviled him, and said, Thou art his disciple; but we are Moses'' disciples."}, {"numero": 29, "texto": "We know that God spake unto Moses: as for this fellow, we know not from whence he is."}, {"numero": 30, "texto": "The man answered and said unto them, Why herein is a marvellous thing, that ye know not from whence he is, and yet he hath opened mine eyes."}, {"numero": 31, "texto": "Now we know that God heareth not sinners: but if any man be a worshipper of God, and doeth his will, him he heareth."}, {"numero": 32, "texto": "Since the world began was it not heard that any man opened the eyes of one that was born blind."}, {"numero": 33, "texto": "If this man were not of God, he could do nothing."}, {"numero": 34, "texto": "They answered and said unto him, Thou wast altogether born in sins, and dost thou teach us? And they cast him out."}, {"numero": 35, "texto": "Jesus heard that they had cast him out; and when he had found him, he said unto him, Dost thou believe on the Son of God?"}, {"numero": 36, "texto": "He answered and said, Who is he, Lord, that I might believe on him?"}, {"numero": 37, "texto": "And Jesus said unto him, Thou hast both seen him, and it is he that talketh with thee."}, {"numero": 38, "texto": "And he said, Lord, I believe. And he worshipped him."}, {"numero": 39, "texto": "And Jesus said, For judgment I am come into this world, that they which see not might see; and that they which see might be made blind."}, {"numero": 40, "texto": "And some of the Pharisees which were with him heard these words, and said unto him, Are we blind also?"}, {"numero": 41, "texto": "Jesus said unto them, If ye were blind, ye should have no sin: but now ye say, We see; therefore your sin remaineth."}]'::jsonb, 'King James Version'),
  ('Jo', 9, 'fr', '[{"numero": 1, "texto": "Jésus vit, en passant, un homme aveugle de naissance."}, {"numero": 2, "texto": "Ses disciples lui firent cette question: Rabbi, qui a péché, cet homme ou ses parents, pour qu''''il soit né aveugle?"}, {"numero": 3, "texto": "Jésus répondit: Ce n''''est pas que lui ou ses parents aient péché; mais c''''est afin que les oeuvres de Dieu soient manifestées en lui."}, {"numero": 4, "texto": "Il faut que je fasse, tandis qu''''il est jour, les oeuvres de celui qui m''''a envoyé; la nuit vient, où personne ne peut travailler."}, {"numero": 5, "texto": "Pendant que je suis dans le monde, je suis la lumière du monde."}, {"numero": 6, "texto": "Après avoir dit cela, il cracha à terre, et fit de la boue avec sa salive. Puis il appliqua cette boue sur les yeux de l''''aveugle,"}, {"numero": 7, "texto": "et lui dit: Va, et lave-toi au réservoir de Siloé nom qui signifie envoyé). Il y alla, se lava, et s''''en retourna voyant clair."}, {"numero": 8, "texto": "Ses voisins et ceux qui auparavant l''''avaient connu comme un mendiant disaient: N''''est-ce pas là celui qui se tenait assis et qui mendiait?"}, {"numero": 9, "texto": "Les uns disaient: C''''est lui. D''''autres disaient: Non, mais il lui ressemble. Et lui-même disait: C''''est moi."}, {"numero": 10, "texto": "Ils lui dirent donc: Comment tes yeux ont-ils été ouverts?"}, {"numero": 11, "texto": "Il répondit: L''''homme qu''''on appelle Jésus a fait de la boue, a oint mes yeux, et m''''a dit: Va au réservoir de Siloé, et lave-toi. J''''y suis allé, je me suis lavé, et j''''ai recouvré la vue."}, {"numero": 12, "texto": "Ils lui dirent: Où est cet homme? Il répondit: Je ne sais."}, {"numero": 13, "texto": "Ils menèrent vers les pharisiens celui qui avait été aveugle."}, {"numero": 14, "texto": "Or, c''''était un jour de sabbat que Jésus avait fait de la boue, et lui avait ouvert les yeux."}, {"numero": 15, "texto": "De nouveau, les pharisiens aussi lui demandèrent comment il avait recouvré la vue. Et il leur dit: Il a appliqué de la boue sur mes yeux, je me suis lavé, et je vois."}, {"numero": 16, "texto": "Sur quoi quelques-uns des pharisiens dirent: Cet homme ne vient pas de Dieu, car il n''''observe pas le sabbat. D''''autres dirent: Comment un homme pécheur peut-il faire de tels miracles? Et il y eut division parmi eux."}, {"numero": 17, "texto": "Ils dirent encore à l''''aveugle: Toi, que dis-tu de lui, sur ce qu''''il t''''a ouvert les yeux? Il répondit: C''''est un prophète."}, {"numero": 18, "texto": "Les Juifs ne crurent point qu''''il eût été aveugle et qu''''il eût recouvré la vue jusqu''''à ce qu''''ils eussent fait venir ses parents."}, {"numero": 19, "texto": "Et ils les interrogèrent, disant: Est-ce là votre fils, que vous dites être né aveugle? Comment donc voit-il maintenant?"}, {"numero": 20, "texto": "Ses parents répondirent: Nous savons que c''''est notre fils, et qu''''il est né aveugle;"}, {"numero": 21, "texto": "mais comment il voit maintenant, ou qui lui a ouvert les yeux, c''''est ce que nous ne savons. Interrogez-le lui-même, il a de l''''âge, il parlera de ce qui le concerne."}, {"numero": 22, "texto": "Ses parents dirent cela parce qu''''ils craignaient les Juifs; car les Juifs étaient déjà convenus que, si quelqu''''un reconnaissait Jésus pour le Christ, il serait exclu de la synagogue."}, {"numero": 23, "texto": "C''''est pourquoi ses parents dirent: Il a de l''''âge, interrogez-le lui-même."}, {"numero": 24, "texto": "Les pharisiens appelèrent une seconde fois l''''homme qui avait été aveugle, et ils lui dirent: Donne gloire à Dieu; nous savons que cet homme est un pécheur."}, {"numero": 25, "texto": "Il répondit: S''''il est un pécheur, je ne sais; je sais une chose, c''''est que j''''étais aveugle et que maintenant je vois."}, {"numero": 26, "texto": "Ils lui dirent: Que t''''a-t-il fait? Comment t''''a-t-il ouvert les yeux?"}, {"numero": 27, "texto": "Il leur répondit: Je vous l''''ai déjà dit, et vous n''''avez pas écouté; pourquoi voulez-vous l''''entendre encore? Voulez-vous aussi devenir ses disciples?"}, {"numero": 28, "texto": "Ils l''''injurièrent et dirent: C''''est toi qui es son disciple; nous, nous sommes disciples de Moïse."}, {"numero": 29, "texto": "Nous savons que Dieu a parlé à Moïse; mais celui-ci, nous ne savons d''''où il est."}, {"numero": 30, "texto": "Cet homme leur répondit: Il est étonnant que vous ne sachiez d''''où il est; et cependant il m''''a ouvert les yeux."}, {"numero": 31, "texto": "Nous savons que Dieu n''''exauce point les pécheurs; mais, si quelqu''''un l''''honore et fait sa volonté, c''''est celui là qu''''il exauce."}, {"numero": 32, "texto": "Jamais on n''''a entendu dire que quelqu''''un ait ouvert les yeux d''''un aveugle-né."}, {"numero": 33, "texto": "Si cet homme ne venait pas de Dieu, il ne pourrait rien faire."}, {"numero": 34, "texto": "Ils lui répondirent: Tu es né tout entier dans le péché, et tu nous enseignes! Et ils le chassèrent."}, {"numero": 35, "texto": "Jésus apprit qu''''ils l''''avaient chassé; et, l''''ayant rencontré, il lui dit: Crois-tu au Fils de Dieu?"}, {"numero": 36, "texto": "Il répondit: Et qui est-il, Seigneur, afin que je croie en lui?"}, {"numero": 37, "texto": "Tu l''''as vu, lui dit Jésus, et celui qui te parle, c''''est lui."}, {"numero": 38, "texto": "Et il dit: Je crois, Seigneur. Et il se prosterna devant lui."}, {"numero": 39, "texto": "Puis Jésus dit: Je suis venu dans ce monde pour un jugement, pour que ceux qui ne voient point voient, et que ceux qui voient deviennent aveugles."}, {"numero": 40, "texto": "Quelques pharisiens qui étaient avec lui, ayant entendu ces paroles, lui dirent: Nous aussi, sommes-nous aveugles?"}, {"numero": 41, "texto": "Jésus leur répondit: Si vous étiez aveugles, vous n''''auriez pas de péché. Mais maintenant vous dites: Nous voyons. C''''est pour cela que votre péché subsiste."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 9, 'es', '[{"numero": 1, "texto": "Y PASANDO Jesús, vió un hombre ciego desde su nacimiento."}, {"numero": 2, "texto": "Y preguntáronle sus discípulos, diciendo: Rabbí, ¿quién pecó, éste ó sus padres, para que naciese ciego?"}, {"numero": 3, "texto": "Respondió Jesús: Ni éste pecó, ni sus padres: mas para que las obras de Dios se manifiesten en él."}, {"numero": 4, "texto": "Conviéneme obrar las obras del que me envió, entre tanto que el día dura: la noche viene, cuando nadie puede obrar."}, {"numero": 5, "texto": "Entre tanto que estuviere en el mundo, luz soy del mundo."}, {"numero": 6, "texto": "Esto dicho, escupió en tierra, é hizo lodo con la saliva, y untó con el lodo sobre los ojos del ciego,"}, {"numero": 7, "texto": "Y díjole: Ve, lávate en el estanque de Siloé (que significa, si lo interpretares, Enviado). Y fué entonces, y lavóse, y volvió viendo."}, {"numero": 8, "texto": "Entonces los vecinos, y los que antes le habían visto que era ciego, decían: ¿No es éste el que se sentaba y mendigaba?"}, {"numero": 9, "texto": "Unos decían: Este es; y otros: A él se parece. El decía: Yo soy."}, {"numero": 10, "texto": "Y dijéronle: ¿Cómo te fueron abiertos los ojos?"}, {"numero": 11, "texto": "Respondió él y dijo: El hombre que se llama Jesús, hizo lodo, y me untó los ojos, y me dijo: Ve al Siloé, y lávate: y fuí, y me lavé, y recibí la vista."}, {"numero": 12, "texto": "Entonces le dijeron: ¿Dónde está aquél? El dijo: No sé."}, {"numero": 13, "texto": "Llevaron á los Fariseos al que antes había sido ciego."}, {"numero": 14, "texto": "Y era sábado cuando Jesús había hecho el lodo, y le había abierto los ojos."}, {"numero": 15, "texto": "Y volviéronle á preguntar también los Fariseos de qué manera había recibido la vista. Y él les dijo: Púsome lodo sobre los ojos, y me lavé, y veo."}, {"numero": 16, "texto": "Entonces unos de los Fariseos decían: Este hombre no es de Dios, que no guarda el sábado. Otros decían: ¿Cómo puede un hombre pecador hacer estas señales? Y había disensión entre ellos."}, {"numero": 17, "texto": "Vuelven á decir al ciego: ¿Tú, qué dices del que te abrió los ojos? Y él dijo: Que es profeta."}, {"numero": 18, "texto": "Mas los Judíos no creían de él, que había sido ciego, y hubiese recibido la vista, hasta que llamaron á los padres del que había recibido la vista;"}, {"numero": 19, "texto": "Y preguntáronles, diciendo: ¿Es éste vuestro hijo, el que vosotros decís que nació ciego? ¿Cómo, pues, ve ahora?"}, {"numero": 20, "texto": "Respondiéronles sus padres y dijeron: Sabemos que éste es nuestro hijo, y que nació ciego:"}, {"numero": 21, "texto": "Mas cómo vea ahora, no sabemos; ó quién le haya abierto los ojos, nosotros no lo sabemos; él tiene edad, preguntadle á él; él hablará de sí."}, {"numero": 22, "texto": "Esto dijeron sus padres, porque tenían miedo de los Judíos: porque ya los Judíos habían resuelto que si alguno confesase ser él el Mesías, fuese fuera de la sinagoga."}, {"numero": 23, "texto": "Por eso dijeron sus padres: Edad tiene, preguntadle á él."}, {"numero": 24, "texto": "Así que, volvieron á llamar al hombre que había sido ciego, y dijéronle: Da gloria á Dios: nosotros sabemos que este hombre es pecador."}, {"numero": 25, "texto": "Entonces él respondió, y dijo: Si es pecador, no lo sé: una cosa sé, que habiendo yo sido ciego, ahora veo."}, {"numero": 26, "texto": "Y volviéronle á decir: ¿Qué te hizo? ¿Cómo te abrió los ojos?"}, {"numero": 27, "texto": "Respondióles: Ya os lo he dicho, y no habéis atendido: ¿por qué lo queréis otra vez oir? ¿queréis también vosotros haceros sus discípulos?"}, {"numero": 28, "texto": "Y le ultrajaron, y dijeron: Tú eres su discípulo; pero nosotros discípulos de Moisés somos."}, {"numero": 29, "texto": "Nosotros sabemos que á Moisés habló Dios: mas éste no sabemos de dónde es."}, {"numero": 30, "texto": "Respondió aquel hombre, y díjoles: Por cierto, maravillosa cosa es ésta, que vosotros no sabéis de dónde sea, y á mí me abrió los ojos."}, {"numero": 31, "texto": "Y sabemos que Dios no oye á los pecadores: mas si alguno es temeroso de Dios, y hace su voluntad, á éste oye."}, {"numero": 32, "texto": "Desde el siglo no fué oído, que abriese alguno los ojos de uno que nació ciego."}, {"numero": 33, "texto": "Si éste no fuera de Dios, no pudiera hacer nada."}, {"numero": 34, "texto": "Respondieron, y dijéronle: En pecados eres nacido todo, ¿y tú nos enseñas? Y echáronle fuera."}, {"numero": 35, "texto": "Oyó Jesús que le habían echado fuera; y hallándole, díjole: ¿Crees tú en el Hijo de Dios?"}, {"numero": 36, "texto": "Respondió él, y dijo: ¿Quién es, Señor, para que crea en él?"}, {"numero": 37, "texto": "Y díjole Jesús: Y le has visto, y el que habla contigo, él es."}, {"numero": 38, "texto": "Y él dice: Creo, Señor; y adoróle."}, {"numero": 39, "texto": "Y dijo Jesús: Yo, para juicio he venido á este mundo: para que los que no ven, vean; y los que ven, sean cegados."}, {"numero": 40, "texto": "Y ciertos de los Fariseos que estaban con él oyeron esto, y dijéronle: ¿Somos nosotros también ciegos?"}, {"numero": 41, "texto": "Díjoles Jesús: Si fuerais ciegos, no tuvierais pecado: mas ahora porque decís, Vemos, por tanto vuestro pecado permanece."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 10, 'pt', '[{"numero": 1, "texto": "Em verdade, em verdade vos digo, que aquele que no curral das ovelhas não entra pela porta, mas sobe por outra parte, é ladrão, e assaltante."}, {"numero": 2, "texto": "Mas aquele que entra pela porta é o pastor de ovelhas."}, {"numero": 3, "texto": "A este o porteiro abre, e as ovelhas ouvem sua voz, e a suas ovelhas chama nome por nome, e as leva fora."}, {"numero": 4, "texto": "E quando tira fora suas ovelhas, vai adiante delas, e as ovelhas o seguem, porque conhecem sua voz."}, {"numero": 5, "texto": "Mas ao estranho em maneira nenhuma seguirão, ao invés disso dele fugirão; porque não conhecem a voz dos estranhos."}, {"numero": 6, "texto": "Esta parábola Jesus lhes disse; porém eles não entenderam que era o que lhes falava."}, {"numero": 7, "texto": "Voltou pois Jesus a lhes dizer: Em verdade, em verdade vos digo, que sou a porta das ovelhas."}, {"numero": 8, "texto": "Todos quantos vieram antes de mim, são ladrões e assaltantes; mas as ovelhas não os ouviram."}, {"numero": 9, "texto": "Eu sou a porta; se alguém entrar por mim, será salvo; e entrará, e sairá, e achará pasto."}, {"numero": 10, "texto": "O ladrão não vem, senão para roubar, matar, e destruir; eu vim para que tenham vida, e [a] tenham em abundância."}, {"numero": 11, "texto": "Eu sou o bom Pastor; o bom Pastor dá sua vida pelas ovelhas."}, {"numero": 12, "texto": "Mas o contratado a dinheiro, e que não é o pastor, a quem as ovelhas não pertencem, vê o lobo vir, deixa as ovelhas, e foge; o lobo as captura, e dispersa as ovelhas."}, {"numero": 13, "texto": "E o contratado foge, porque é contratado, e não tem cuidado das ovelhas."}, {"numero": 14, "texto": "Eu sou o bom Pastor, e conheço as minhas, e pelas minhas sou conhecido."}, {"numero": 15, "texto": "Como o Pai me conhece, assim também também eu conheço o Pai; e dou a minha vida pelas ovelhas."}, {"numero": 16, "texto": "Ainda tenho outras ovelhas que não são deste curral; a estas também me convém trazer, e ouvirão minha voz, e haverá um rebanho, [e] um pastor."}, {"numero": 17, "texto": "Por isso o Pai me ama, porque dou a minha vida para tomá-la de volta."}, {"numero": 18, "texto": "Ninguém a tira de mim, mas eu de mim mesmo a dou; tenho poder para a dar, e tenho poder para tomá-la de volta. Este mandamento recebi de meu Pai."}, {"numero": 19, "texto": "Voltou, pois, a haver divisão entre os judeus, por causa dessas palavras."}, {"numero": 20, "texto": "E muitos deles diziam: Ele tem demônio, e está fora de si; para que o ouvis?"}, {"numero": 21, "texto": "Outros diziam: Estas palavras não são de um endemoninhado; por acaso pode um demônio dar vista aos cegos?"}, {"numero": 22, "texto": "E era a festa da renovação [do Templo] em Jerusalém, e era inverno."}, {"numero": 23, "texto": "E andava Jesus passeando no Templo, na entrada de Salomão."}, {"numero": 24, "texto": "Rodearam-no, então, os Judeus, e lhe disseram: Até quando farás nossa alma em dúvida? Se tu és o Cristo, dize-nos abertamente."}, {"numero": 25, "texto": "Respondeu-lhes Jesus: Já vos tenho dito, e não credes. As obras que eu faço em nome de meu Pai, essas testemunham de mim."}, {"numero": 26, "texto": "Mas vós não credes, porque não sois de minhas ovelhas, como já vos tenho dito."}, {"numero": 27, "texto": "Minhas ovelhas ouvem minha voz, e eu as conheço, e elas me seguem."}, {"numero": 28, "texto": "E eu lhes dou a vida eterna, e para sempre não perecerão, e ninguém as arrancará de minha mão."}, {"numero": 29, "texto": "Meu Pai, que [as] deu para mim, é maior que todos; e ninguém pode arrancá-las da mão de meu Pai."}, {"numero": 30, "texto": "Eu e o Pai somos um."}, {"numero": 31, "texto": "Voltaram pois os Judeus a tomar pedras para o apedrejarem."}, {"numero": 32, "texto": "Respondeu-lhes Jesus: Muitas boas obras de meu Pai vos tenho mostrado; por qual obra destas me apedrejais?"}, {"numero": 33, "texto": "Responderam-lhe os judeus dizendo: Por boa obra não te apedrejamos, mas pela blasfêmia; e porque sendo tu homem, a ti mesmo te fazes Deus."}, {"numero": 34, "texto": "Respondeu-lhes Jesus: Não está escrito em vossa Lei: Eu disse: Sois deuses?"}, {"numero": 35, "texto": "Pois se [a Lei] chamou deuses a aqueles, para quem a palavra de Deus foi feita, (e a Escritura não pode ser quebrada);"}, {"numero": 36, "texto": "[A mim] ,a quem o Pai santificou, e ao mundo enviou, dizeis vós: Blasfemas; porque disse: Sou Filho de Deus?"}, {"numero": 37, "texto": "Se não faço as obras de meu Pai, não creiais em mim."}, {"numero": 38, "texto": "Porém se eu as faço, e não credes em mim, crede nas obras; para que conheçais e creiais que o Pai está em mim, e eu nele."}, {"numero": 39, "texto": "Então procuravam outra vez prendê-lo; e ele saiu de suas mãos."}, {"numero": 40, "texto": "E voltou a ir para o outro lado do Jordão, ao lugar onde João primeiro batizava; e ficou ali."}, {"numero": 41, "texto": "E muitos vinham a ele, e diziam: Em verdade que nenhum sinal fez João; mas tudo quanto João disse deste era verdade."}, {"numero": 42, "texto": "E muitos ali creram nele."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 10, 'en', '[{"numero": 1, "texto": "Verily, verily, I say unto you, He that entereth not by the door into the sheepfold, but climbeth up some other way, the same is a thief and a robber."}, {"numero": 2, "texto": "But he that entereth in by the door is the shepherd of the sheep."}, {"numero": 3, "texto": "To him the porter openeth; and the sheep hear his voice: and he calleth his own sheep by name, and leadeth them out."}, {"numero": 4, "texto": "And when he putteth forth his own sheep, he goeth before them, and the sheep follow him: for they know his voice."}, {"numero": 5, "texto": "And a stranger will they not follow, but will flee from him: for they know not the voice of strangers."}, {"numero": 6, "texto": "This parable spake Jesus unto them: but they understood not what things they were which he spake unto them."}, {"numero": 7, "texto": "Then said Jesus unto them again, Verily, verily, I say unto you, I am the door of the sheep."}, {"numero": 8, "texto": "All that ever came before me are thieves and robbers: but the sheep did not hear them."}, {"numero": 9, "texto": "I am the door: by me if any man enter in, he shall be saved, and shall go in and out, and find pasture."}, {"numero": 10, "texto": "The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly."}, {"numero": 11, "texto": "I am the good shepherd: the good shepherd giveth his life for the sheep."}, {"numero": 12, "texto": "But he that is an hireling, and not the shepherd, whose own the sheep are not, seeth the wolf coming, and leaveth the sheep, and fleeth: and the wolf catcheth them, and scattereth the sheep."}, {"numero": 13, "texto": "The hireling fleeth, because he is an hireling, and careth not for the sheep."}, {"numero": 14, "texto": "I am the good shepherd, and know my sheep, and am known of mine."}, {"numero": 15, "texto": "As the Father knoweth me, even so know I the Father: and I lay down my life for the sheep."}, {"numero": 16, "texto": "And other sheep I have, which are not of this fold: them also I must bring, and they shall hear my voice; and there shall be one fold, and one shepherd."}, {"numero": 17, "texto": "Therefore doth my Father love me, because I lay down my life, that I might take it again."}, {"numero": 18, "texto": "No man taketh it from me, but I lay it down of myself. I have power to lay it down, and I have power to take it again. This commandment have I received of my Father."}, {"numero": 19, "texto": "There was a division therefore again among the Jews for these sayings."}, {"numero": 20, "texto": "And many of them said, He hath a devil, and is mad; why hear ye him?"}, {"numero": 21, "texto": "Others said, These are not the words of him that hath a devil. Can a devil open the eyes of the blind?"}, {"numero": 22, "texto": "And it was at Jerusalem the feast of the dedication, and it was winter."}, {"numero": 23, "texto": "And Jesus walked in the temple in Solomon''s porch."}, {"numero": 24, "texto": "Then came the Jews round about him, and said unto him, How long dost thou make us to doubt? If thou be the Christ, tell us plainly."}, {"numero": 25, "texto": "Jesus answered them, I told you, and ye believed not: the works that I do in my Father''s name, they bear witness of me."}, {"numero": 26, "texto": "But ye believe not, because ye are not of my sheep, as I said unto you."}, {"numero": 27, "texto": "My sheep hear my voice, and I know them, and they follow me:"}, {"numero": 28, "texto": "And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand."}, {"numero": 29, "texto": "My Father, which gave them me, is greater than all; and no man is able to pluck them out of my Father''s hand."}, {"numero": 30, "texto": "I and my Father are one."}, {"numero": 31, "texto": "Then the Jews took up stones again to stone him."}, {"numero": 32, "texto": "Jesus answered them, Many good works have I shewed you from my Father; for which of those works do ye stone me?"}, {"numero": 33, "texto": "The Jews answered him, saying, For a good work we stone thee not; but for blasphemy; and because that thou, being a man, makest thyself God."}, {"numero": 34, "texto": "Jesus answered them, Is it not written in your law, I said, Ye are gods?"}, {"numero": 35, "texto": "If he called them gods, unto whom the word of God came, and the scripture cannot be broken;"}, {"numero": 36, "texto": "Say ye of him, whom the Father hath sanctified, and sent into the world, Thou blasphemest; because I said, I am the Son of God?"}, {"numero": 37, "texto": "If I do not the works of my Father, believe me not."}, {"numero": 38, "texto": "But if I do, though ye believe not me, believe the works: that ye may know, and believe, that the Father is in me, and I in him."}, {"numero": 39, "texto": "Therefore they sought again to take him: but he escaped out of their hand,"}, {"numero": 40, "texto": "And went away again beyond Jordan into the place where John at first baptized; and there he abode."}, {"numero": 41, "texto": "And many resorted unto him, and said, John did no miracle: but all things that John spake of this man were true."}, {"numero": 42, "texto": "And many believed on him there."}]'::jsonb, 'King James Version'),
  ('Jo', 10, 'fr', '[{"numero": 1, "texto": "En vérité, en vérité, je vous le dis, celui qui n''''entre pas par la porte dans la bergerie, mais qui y monte par ailleurs, est un voleur et un brigand."}, {"numero": 2, "texto": "Mais celui qui entre par la porte est le berger des brebis."}, {"numero": 3, "texto": "Le portier lui ouvre, et les brebis entendent sa voix; il appelle par leur nom les brebis qui lui appartiennent, et il les conduit dehors."}, {"numero": 4, "texto": "Lorsqu''''il a fait sortir toutes ses propres brebis, il marche devant elles; et les brebis le suivent, parce qu''''elles connaissent sa voix."}, {"numero": 5, "texto": "Elles ne suivront point un étranger; mais elles fuiront loin de lui, parce qu''''elles ne connaissent pas la voix des étrangers."}, {"numero": 6, "texto": "Jésus leur dit cette parabole, mais ils ne comprirent pas de quoi il leur parlait."}, {"numero": 7, "texto": "Jésus leur dit encore: En vérité, en vérité, je vous le dis, je suis la porte des brebis."}, {"numero": 8, "texto": "Tous ceux qui sont venus avant moi sont des voleurs et des brigands; mais les brebis ne les ont point écoutés."}, {"numero": 9, "texto": "Je suis la porte. Si quelqu''''un entre par moi, il sera sauvé; il entrera et il sortira, et il trouvera des pâturages."}, {"numero": 10, "texto": "Le voleur ne vient que pour dérober, égorger et détruire; moi, je suis venu afin que les brebis aient la vie, et qu''''elles soient dans l''''abondance."}, {"numero": 11, "texto": "Je suis le bon berger. Le bon berger donne sa vie pour ses brebis."}, {"numero": 12, "texto": "Mais le mercenaire, qui n''''est pas le berger, et à qui n''''appartiennent pas les brebis, voit venir le loup, abandonne les brebis, et prend la fuite; et le loup les ravit et les disperse."}, {"numero": 13, "texto": "Le mercenaire s''''enfuit, parce qu''''il est mercenaire, et qu''''il ne se met point en peine des brebis."}, {"numero": 14, "texto": "Je suis le bon berger. Je connais mes brebis, et elles me connaissent,"}, {"numero": 15, "texto": "comme le Père me connaît et comme je connais le Père; et je donne ma vie pour mes brebis."}, {"numero": 16, "texto": "J''''ai encore d''''autres brebis, qui ne sont pas de cette bergerie; celles-là, il faut que je les amène; elles entendront ma voix, et il y aura un seul troupeau, un seul berger."}, {"numero": 17, "texto": "Le Père m''''aime, parce que je donne ma vie, afin de la reprendre."}, {"numero": 18, "texto": "Personne ne me l''''ôte, mais je la donne de moi-même; j''''ai le pouvoir de la donner, et j''''ai le pouvoir de la reprendre: tel est l''''ordre que j''''ai reçu de mon Père."}, {"numero": 19, "texto": "Il y eut de nouveau, à cause de ces paroles, division parmi les Juifs."}, {"numero": 20, "texto": "Plusieurs d''''entre eux disaient: Il a un démon, il est fou; pourquoi l''''écoutez-vous?"}, {"numero": 21, "texto": "D''''autres disaient: Ce ne sont pas les paroles d''''un démoniaque; un démon peut-il ouvrir les yeux des aveugles?"}, {"numero": 22, "texto": "On célébrait à Jérusalem la fête de la Dédicace. C''''était l''''hiver."}, {"numero": 23, "texto": "Et Jésus se promenait dans le temple, sous le portique de Salomon."}, {"numero": 24, "texto": "Les Juifs l''''entourèrent, et lui dirent: Jusques à quand tiendras-tu notre esprit en suspens? Si tu es le Christ, dis-le nous franchement."}, {"numero": 25, "texto": "Jésus leur répondit: Je vous l''''ai dit, et vous ne croyez pas. Les oeuvres que je fais au nom de mon Père rendent témoignage de moi."}, {"numero": 26, "texto": "Mais vous ne croyez pas, parce que vous n''''êtes pas de mes brebis."}, {"numero": 27, "texto": "Mes brebis entendent ma voix; je les connais, et elles me suivent."}, {"numero": 28, "texto": "Je leur donne la vie éternelle; et elles ne périront jamais, et personne ne les ravira de ma main."}, {"numero": 29, "texto": "Mon Père, qui me les a données, est plus grand que tous; et personne ne peut les ravir de la main de mon Père."}, {"numero": 30, "texto": "Moi et le Père nous sommes un."}, {"numero": 31, "texto": "Alors les Juifs prirent de nouveau des pierres pour le lapider."}, {"numero": 32, "texto": "Jésus leur dit: Je vous ai fait voir plusieurs bonnes oeuvres venant de mon Père: pour laquelle me lapidez-vous?"}, {"numero": 33, "texto": "Les Juifs lui répondirent: Ce n''''est point pour une bonne oeuvre que nous te lapidons, mais pour un blasphème, et parce que toi, qui es un homme, tu te fais Dieu."}, {"numero": 34, "texto": "Jésus leur répondit: N''''est-il pas écrit dans votre loi: J''''ai dit: Vous êtes des dieux?"}, {"numero": 35, "texto": "Si elle a appelé dieux ceux à qui la parole de Dieu a été adressée, et si l''''Ecriture ne peut être anéantie,"}, {"numero": 36, "texto": "celui que le Père a sanctifié et envoyé dans le monde, vous lui dites: Tu blasphèmes! Et cela parce que j''''ai dit: Je suis le Fils de Dieu."}, {"numero": 37, "texto": "Si je ne fais pas les oeuvres de mon Père, ne me croyez pas."}, {"numero": 38, "texto": "Mais si je les fais, quand même vous ne me croyez point, croyez à ces oeuvres, afin que vous sachiez et reconnaissiez que le Père est en moi et que je suis dans le Père."}, {"numero": 39, "texto": "Là-dessus, ils cherchèrent encore à le saisir, mais il s''''échappa de leurs mains."}, {"numero": 40, "texto": "Jésus s''''en alla de nouveau au delà du Jourdain, dans le lieu où Jean avait d''''abord baptisé. Et il y demeura."}, {"numero": 41, "texto": "Beaucoup de gens vinrent à lui, et ils disaient: Jean n''''a fait aucun miracle; mais tout ce que Jean a dit de cet homme était vrai."}, {"numero": 42, "texto": "Et, dans ce lieu-là, plusieurs crurent en lui."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 10, 'es', '[{"numero": 1, "texto": "DE cierto, de cierto os digo: El que no entra por la puerta en el corral de las ovejas, mas sube por otra parte, el tal es ladrón y robador."}, {"numero": 2, "texto": "Mas el que entra por la puerta, el pastor de las ovejas es."}, {"numero": 3, "texto": "A éste abre el portero, y las ovejas oyen su voz: y á sus ovejas llama por nombre, y las saca."}, {"numero": 4, "texto": "Y como ha sacado fuera todas las propias, va delante de ellas; y las ovejas le siguen, porque conocen su voz."}, {"numero": 5, "texto": "Mas al extraño no seguirán, antes huirán de él: porque no conocen la voz de los extraños."}, {"numero": 6, "texto": "Esta parábola les dijo Jesús; mas ellos no entendieron qué era lo que les decía."}, {"numero": 7, "texto": "Volvióles, pues, Jesús á decir: De cierto, de cierto os digo: Yo soy la puerta de las ovejas."}, {"numero": 8, "texto": "Todos los que antes de mí vinieron, ladrones son y robadores; mas no los oyeron las ovejas."}, {"numero": 9, "texto": "Yo soy la puerta: el que por mí entrare, será salvo; y entrará, y saldrá, y hallará pastos."}, {"numero": 10, "texto": "El ladrón no viene sino para hurtar, y matar, y destruir: yo he venido para que tengan vida, y para que la tengan en abundancia."}, {"numero": 11, "texto": "Yo soy el buen pastor: el buen pastor su vida da por las ovejas."}, {"numero": 12, "texto": "Mas el asalariado, y que no es el pastor, de quien no son propias las ovejas, ve al lobo que viene, y deja las ovejas, y huye, y el lobo las arrebata, y esparce las ovejas."}, {"numero": 13, "texto": "Así que, el asalariado, huye, porque es asalariado, y no tiene cuidado de las ovejas."}, {"numero": 14, "texto": "Yo soy el buen pastor; y conozco mis ovejas, y las mías me conocen."}, {"numero": 15, "texto": "Como el Padre me conoce, y yo conozco al Padre; y pongo mi vida por las ovejas."}, {"numero": 16, "texto": "También tengo otras ovejas que no son de este redil; aquéllas también me conviene traer, y oirán mi voz; y habrá un rebaño, y un pastor."}, {"numero": 17, "texto": "Por eso me ama el Padre, porque yo pongo mi vida, para volverla á tomar."}, {"numero": 18, "texto": "Nadie me la quita, mas yo la pongo de mí mismo. Tengo poder para ponerla, y tengo poder para volverla á tomar. Este mandamiento recibí de mi Padre."}, {"numero": 19, "texto": "Y volvió á haber disensión entre los Judíos por estas palabras."}, {"numero": 20, "texto": "Y muchos de ellos decían: Demonio tiene, y está fuera de sí; ¿para qué le oís?"}, {"numero": 21, "texto": "Decían otros: Estas palabras no son de endemoniado: ¿puede el demonio abrir los ojos de los ciegos?"}, {"numero": 22, "texto": "Y se hacía la fiesta de la dedicación en Jerusalem; y era invierno;"}, {"numero": 23, "texto": "Y Jesús andaba en el templo por el portal de Salomón."}, {"numero": 24, "texto": "Y rodeáronle los Judíos y dijéronle: ¿Hasta cuándo nos has de turbar el alma? Si tú eres el Cristo, dínoslo abiertamente."}, {"numero": 25, "texto": "Respondióles Jesús: Os lo he dicho, y no creéis: las obras que yo hago en nombre de mi Padre, ellas dan testimonio de mí;"}, {"numero": 26, "texto": "Mas vosotros no creéis, porque no sois de mis ovejas, como os he dicho."}, {"numero": 27, "texto": "Mis ovejas oyen mi voz, y yo las conozco, y me siguen;"}, {"numero": 28, "texto": "Y yo les doy vida eterna: y no perecerán para siempre, ni nadie las arrebatará de mi mano."}, {"numero": 29, "texto": "Mi Padre que me las dió, mayor que todos es: y nadie las puede arrebatar de la mano de mi Padre."}, {"numero": 30, "texto": "Yo y el Padre una cosa somos."}, {"numero": 31, "texto": "Entonces volvieron á tomar piedras los Judíos para apedrearle."}, {"numero": 32, "texto": "Respondióles Jesús: Muchas buenas obras os he mostrado de mi Padre; ¿por cuál obra de esas me apedreáis?"}, {"numero": 33, "texto": "Respondiéronle los Judíos, diciendo: Por buena obra no te apedreamos, sino por la blasfemia; y porque tú, siendo hombre, te haces Dios."}, {"numero": 34, "texto": "Respondióles Jesús: ¿No está escrito en vuestra ley: Yo dije, Dioses sois?"}, {"numero": 35, "texto": "Si dijo, dioses, á aquellos á los cuales fué hecha palabra de Dios (y la Escritura no puede ser quebrantada);"}, {"numero": 36, "texto": "¿A quien el Padre santificó y envió al mundo, vosotros decís: Tú blasfemas, porque dije: Hijo de Dios soy?"}, {"numero": 37, "texto": "Si no hago obras de mi Padre, no me creáis."}, {"numero": 38, "texto": "Mas si las hago, aunque á mí no creáis, creed á las obras; para que conozcáis y creáis que el Padre está en mí, y yo en el Padre."}, {"numero": 39, "texto": "Y procuraban otra vez prenderle; mas él se salió de sus manos;"}, {"numero": 40, "texto": "Y volvióse tras el Jordán, á aquel lugar donde primero había estado bautizando Juan; y estúvose allí."}, {"numero": 41, "texto": "Y muchos venían á él, y decían: Juan, á la verdad, ninguna señal hizo; mas todo lo que Juan dijo de éste, era verdad."}, {"numero": 42, "texto": "Y muchos creyeron allí en él."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 11, 'pt', '[{"numero": 1, "texto": "E estava doente um certo Lázaro, de Betânia, a aldeia de Maria e de sua irmã Marta."}, {"numero": 2, "texto": "(E era Maria a que ungiu ao Senhor com o óleo, e com seus cabelos lhe limpou os pés; [a que] cujo irmão Lázaro era o que estava doente)."}, {"numero": 3, "texto": "Enviaram pois suas irmãs [uma mensagem] a ele, dizendo: Senhor, eis que aquele a quem [tu] amas está doente."}, {"numero": 4, "texto": "E ouvindo Jesus, disse: Esta doença não é para morte, mas para glória de Deus; para que o Filho de Deus seja por ela glorificado."}, {"numero": 5, "texto": "E Jesus amava a Marta, e a sua irmã, e a Lázaro."}, {"numero": 6, "texto": "Quando, pois, ele ouviu que estava doente, ficou ainda dois dias no lugar onde estava."}, {"numero": 7, "texto": "Então depois disto voltou a dizer aos discípulos: Vamos outra vez à Judeia."}, {"numero": 8, "texto": "Disseram-lhe os discípulos: Rabi, ainda agora os Judeus procuravam te apedrejar; e tu voltas novamente para lá?"}, {"numero": 9, "texto": "Respondeu Jesus: Não há doze horas no dia? Se alguém anda de dia, não tropeça, porque vê a luz deste mundo."}, {"numero": 10, "texto": "Mas se alguém anda de noite, tropeça; porque nele não há luz."}, {"numero": 11, "texto": "Ele falou estas coisas; e depois disto, disse-lhes: Lázaro, nosso amigo, dorme; mas vou para despertá-lo do sono."}, {"numero": 12, "texto": "Disseram pois seus discípulos: Senhor, se [ele] dorme, será salvo."}, {"numero": 13, "texto": "Mas Jesus dizia [isto] de sua morte; porém eles pensavam que falava do repouso do sono."}, {"numero": 14, "texto": "Então pois lhes disse Jesus claramente: Lázaro está morto."}, {"numero": 15, "texto": "E me alegro, por causa de vós, que eu não estivesse lá, para que creiais; porém vamos até ele."}, {"numero": 16, "texto": "Disse pois Tomé, chamado o Dídimo, aos colegas discípulos: Vamos nós também, para que com ele morramos."}, {"numero": 17, "texto": "Vindo pois Jesus, encontrou que já havia quatro dias que estava na sepultura."}, {"numero": 18, "texto": "(E Betânia era como quase quinze estádios de Jerusalém)."}, {"numero": 19, "texto": "E muitos dos judeus tinham vindo até Marta e Maria, para consolá-las por seu irmão."}, {"numero": 20, "texto": "Ouvindo pois Marta que Jesus vinha, saiu-lhe ao encontro; mas Maria ficou sentada em casa."}, {"numero": 21, "texto": "Disse pois Marta a Jesus: Senhor, se tu estivesses aqui, meu irmão não teria morrido."}, {"numero": 22, "texto": "Porém também sei agora, que tudo quanto pedires a Deus, Deus o dará a ti."}, {"numero": 23, "texto": "Disse-lhe Jesus: Teu irmão ressuscitará."}, {"numero": 24, "texto": "Marta lhe disse: Eu sei que ele ressuscitará, na ressurreição, no último dia."}, {"numero": 25, "texto": "Disse-lhe Jesus: Eu sou a ressurreição, e a vida; quem crê em mim, ainda que esteja morto, viverá."}, {"numero": 26, "texto": "E todo aquele que vive, e crê em mim, para sempre não morrerá. Crês nisto?"}, {"numero": 27, "texto": "Disse-lhe ela: Sim, Senhor; já cri que tu és o Cristo, o Filho de Deus, que viria ao mundo."}, {"numero": 28, "texto": "E dito isto, [ela] se foi, e chamou em segredo a Maria, sua irmã, dizendo: Aqui está o Mestre, e ele te chama."}, {"numero": 29, "texto": "Ouvindo ela [isto] ,logo se levantou, e foi até ele."}, {"numero": 30, "texto": "(Porque Jesus ainda não havia chegado à aldeia; mas estava no lugar onde Marta lhe saíra ao encontro)."}, {"numero": 31, "texto": "Vendo pois os judeus que com ela estavam em casa, e a consolavam, que Maria com pressa se levantara, e saíra, seguiram-na, dizendo: Ela vai para a sepultura, para chorar lá."}, {"numero": 32, "texto": "Vindo pois Maria aonde Jesus estava, e vendo-o, caiu a seus pés, dizendo-lhe: Senhor, se tu estivesses aqui, meu irmão não teria morrido."}, {"numero": 33, "texto": "Quando Jesus a viu chorar, e aos judeus, que vinham chorando com ela, comoveu-se em espírito, e ficou perturbado."}, {"numero": 34, "texto": "E disse: Onde o pusestes? Disseram-lhe: Senhor, vem, e vê."}, {"numero": 35, "texto": "Jesus chorou."}, {"numero": 36, "texto": "Disseram pois os Judeus: Vede como ele o amava!"}, {"numero": 37, "texto": "E alguns deles disseram: Não podia este, que abriu os olhos ao cego, ter feito também que este não morresse?"}, {"numero": 38, "texto": "Comovendo-se pois Jesus outra vez em si mesmo, veio à sepultura; e era [esta] uma caverna, e estava uma pedra posta sobre ela."}, {"numero": 39, "texto": "Disse Jesus: Tirai a pedra. Marta, a irmã do morto, disse-lhe: Senhor, já cheira mal, porque já é de quatro dias."}, {"numero": 40, "texto": "Jesus disse-lhe: Não te disse, que se creres, verás a glória de Deus?"}, {"numero": 41, "texto": "Tiraram, pois, a pedra de onde o morto jazia. E Jesus levantou os olhos para cima, e disse: Pai, graças te dou, porque me tens ouvido."}, {"numero": 42, "texto": "Porém eu bem sabia que sempre me ouves; mas por causa da multidão, que está ao redor, [assim] disse; para que creiam que tu me enviaste."}, {"numero": 43, "texto": "E havendo dito isto, clamou com grande voz: Lázaro, sai fora."}, {"numero": 44, "texto": "E o que estava morto saiu, [com] as mãos e os pés atados, e seu rosto envolto em um lenço. Disse-lhes Jesus: Desatai-o, e deixai-o ir."}, {"numero": 45, "texto": "Pelo que, muitos dos Judeus, que tinham vindo a Maria, e haviam visto o que Jesus fizera, creram nele."}, {"numero": 46, "texto": "Mas alguns deles foram aos fariseus, e lhes disseram o que Jesus havia feito."}, {"numero": 47, "texto": "Então os sacerdotes e os fariseus juntaram o supremo conselho, e disseram: Que faremos? Porque este homem faz muitos sinais."}, {"numero": 48, "texto": "Se assim o deixamos, todos crerão nele, e virão os romanos, e nos tomarão tanto o lugar quanto a nação."}, {"numero": 49, "texto": "E Caifás, um deles, que era sumo sacerdote daquele ano, lhes disse: Vós nada sabeis;"}, {"numero": 50, "texto": "Nem considerais que nos convém, que um homem morra pelo povo, e toda a nação não pereça."}, {"numero": 51, "texto": "E ele não disse isto de si mesmo; mas que, como era o sumo sacerdote daquele ano, profetizou que Jesus morreria pelo povo."}, {"numero": 52, "texto": "E não somente por aquele povo, mas também para que juntasse em um aos filhos de Deus, que estavam dispersos."}, {"numero": 53, "texto": "Então desde aquele dia se aconselhavam juntos para o matarem."}, {"numero": 54, "texto": "De maneira que Jesus já não andava mais abertamente entre os judeus, mas foi-se dali para a terra junto ao deserto, a uma cidade chamada Efraim; e ali andava com seus discípulos."}, {"numero": 55, "texto": "E estava perto a páscoa dos judeus, e muitos daquela terra subiram a Jerusalém antes da páscoa, para se purificarem."}, {"numero": 56, "texto": "Buscavam pois a Jesus, e diziam uns aos outros estando no Templo: Que vos parece? Que ele não virá à festa?"}, {"numero": 57, "texto": "E os sacerdotes e os fariseus tinham dado ordem de que, se alguém soubesse onde ele estava, o denunciasse, para que o pudessem prender."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 11, 'en', '[{"numero": 1, "texto": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha."}, {"numero": 2, "texto": "(It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}, {"numero": 3, "texto": "Therefore his sisters sent unto him, saying, Lord, behold, he whom thou lovest is sick."}, {"numero": 4, "texto": "When Jesus heard that, he said, This sickness is not unto death, but for the glory of God, that the Son of God might be glorified thereby."}, {"numero": 5, "texto": "Now Jesus loved Martha, and her sister, and Lazarus."}, {"numero": 6, "texto": "When he had heard therefore that he was sick, he abode two days still in the same place where he was."}, {"numero": 7, "texto": "Then after that saith he to his disciples, Let us go into Judaea again."}, {"numero": 8, "texto": "His disciples say unto him, Master, the Jews of late sought to stone thee; and goest thou thither again?"}, {"numero": 9, "texto": "Jesus answered, Are there not twelve hours in the day? If any man walk in the day, he stumbleth not, because he seeth the light of this world."}, {"numero": 10, "texto": "But if a man walk in the night, he stumbleth, because there is no light in him."}, {"numero": 11, "texto": "These things said he: and after that he saith unto them, Our friend Lazarus sleepeth; but I go, that I may awake him out of sleep."}, {"numero": 12, "texto": "Then said his disciples, Lord, if he sleep, he shall do well."}, {"numero": 13, "texto": "Howbeit Jesus spake of his death: but they thought that he had spoken of taking of rest in sleep."}, {"numero": 14, "texto": "Then said Jesus unto them plainly, Lazarus is dead."}, {"numero": 15, "texto": "And I am glad for your sakes that I was not there, to the intent ye may believe; nevertheless let us go unto him."}, {"numero": 16, "texto": "Then said Thomas, which is called Didymus, unto his fellowdisciples, Let us also go, that we may die with him."}, {"numero": 17, "texto": "Then when Jesus came, he found that he had lain in the grave four days already."}, {"numero": 18, "texto": "Now Bethany was nigh unto Jerusalem, about fifteen furlongs off:"}, {"numero": 19, "texto": "And many of the Jews came to Martha and Mary, to comfort them concerning their brother."}, {"numero": 20, "texto": "Then Martha, as soon as she heard that Jesus was coming, went and met him: but Mary sat still in the house."}, {"numero": 21, "texto": "Then said Martha unto Jesus, Lord, if thou hadst been here, my brother had not died."}, {"numero": 22, "texto": "But I know, that even now, whatsoever thou wilt ask of God, God will give it thee."}, {"numero": 23, "texto": "Jesus saith unto her, Thy brother shall rise again."}, {"numero": 24, "texto": "Martha saith unto him, I know that he shall rise again in the resurrection at the last day."}, {"numero": 25, "texto": "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:"}, {"numero": 26, "texto": "And whosoever liveth and believeth in me shall never die. Believest thou this?"}, {"numero": 27, "texto": "She saith unto him, Yea, Lord: I believe that thou art the Christ, the Son of God, which should come into the world."}, {"numero": 28, "texto": "And when she had so said, she went her way, and called Mary her sister secretly, saying, The Master is come, and calleth for thee."}, {"numero": 29, "texto": "As soon as she heard that, she arose quickly, and came unto him."}, {"numero": 30, "texto": "Now Jesus was not yet come into the town, but was in that place where Martha met him."}, {"numero": 31, "texto": "The Jews then which were with her in the house, and comforted her, when they saw Mary, that she rose up hastily and went out, followed her, saying, She goeth unto the grave to weep there."}, {"numero": 32, "texto": "Then when Mary was come where Jesus was, and saw him, she fell down at his feet, saying unto him, Lord, if thou hadst been here, my brother had not died."}, {"numero": 33, "texto": "When Jesus therefore saw her weeping, and the Jews also weeping which came with her, he groaned in the spirit, and was troubled."}, {"numero": 34, "texto": "And said, Where have ye laid him? They said unto him, Lord, come and see."}, {"numero": 35, "texto": "Jesus wept."}, {"numero": 36, "texto": "Then said the Jews, Behold how he loved him!"}, {"numero": 37, "texto": "And some of them said, Could not this man, which opened the eyes of the blind, have caused that even this man should not have died?"}, {"numero": 38, "texto": "Jesus therefore again groaning in himself cometh to the grave. It was a cave, and a stone lay upon it."}, {"numero": 39, "texto": "Jesus said, Take ye away the stone. Martha, the sister of him that was dead, saith unto him, Lord, by this time he stinketh: for he hath been dead four days."}, {"numero": 40, "texto": "Jesus saith unto her, Said I not unto thee, that, if thou wouldest believe, thou shouldest see the glory of God?"}, {"numero": 41, "texto": "Then they took away the stone from the place where the dead was laid. And Jesus lifted up his eyes, and said, Father, I thank thee that thou hast heard me."}, {"numero": 42, "texto": "And I knew that thou hearest me always: but because of the people which stand by I said it, that they may believe that thou hast sent me."}, {"numero": 43, "texto": "And when he thus had spoken, he cried with a loud voice, Lazarus, come forth."}, {"numero": 44, "texto": "And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go."}, {"numero": 45, "texto": "Then many of the Jews which came to Mary, and had seen the things which Jesus did, believed on him."}, {"numero": 46, "texto": "But some of them went their ways to the Pharisees, and told them what things Jesus had done."}, {"numero": 47, "texto": "Then gathered the chief priests and the Pharisees a council, and said, What do we? for this man doeth many miracles."}, {"numero": 48, "texto": "If we let him thus alone, all men will believe on him: and the Romans shall come and take away both our place and nation."}, {"numero": 49, "texto": "And one of them, named Caiaphas, being the high priest that same year, said unto them, Ye know nothing at all,"}, {"numero": 50, "texto": "Nor consider that it is expedient for us, that one man should die for the people, and that the whole nation perish not."}, {"numero": 51, "texto": "And this spake he not of himself: but being high priest that year, he prophesied that Jesus should die for that nation;"}, {"numero": 52, "texto": "And not for that nation only, but that also he should gather together in one the children of God that were scattered abroad."}, {"numero": 53, "texto": "Then from that day forth they took counsel together for to put him to death."}, {"numero": 54, "texto": "Jesus therefore walked no more openly among the Jews; but went thence unto a country near to the wilderness, into a city called Ephraim, and there continued with his disciples."}, {"numero": 55, "texto": "And the Jews'' passover was nigh at hand: and many went out of the country up to Jerusalem before the passover, to purify themselves."}, {"numero": 56, "texto": "Then sought they for Jesus, and spake among themselves, as they stood in the temple, What think ye, that he will not come to the feast?"}, {"numero": 57, "texto": "Now both the chief priests and the Pharisees had given a commandment, that, if any man knew where he were, he should shew it, that they might take him."}]'::jsonb, 'King James Version'),
  ('Jo', 11, 'fr', '[{"numero": 1, "texto": "Il y avait un homme malade, Lazare, de Béthanie, village de Marie et de Marthe, sa soeur."}, {"numero": 2, "texto": "C''''était cette Marie qui oignit de parfum le Seigneur et qui lui essuya les pieds avec ses cheveux, et c''''était son frère Lazare qui était malade."}, {"numero": 3, "texto": "Les soeurs envoyèrent dire à Jésus: Seigneur, voici, celui que tu aimes est malade."}, {"numero": 4, "texto": "Après avoir entendu cela, Jésus dit: Cette maladie n''''est point à la mort; mais elle est pour la gloire de Dieu, afin que le Fils de Dieu soit glorifié par elle."}, {"numero": 5, "texto": "Or, Jésus aimait Marthe, et sa soeur, et Lazare."}, {"numero": 6, "texto": "Lors donc qu''''il eut appris que Lazare était malade, il resta deux jours encore dans le lieu où il était,"}, {"numero": 7, "texto": "et il dit ensuite aux disciples: Retournons en Judée."}, {"numero": 8, "texto": "Les disciples lui dirent: Rabbi, les Juifs tout récemment cherchaient à te lapider, et tu retournes en Judée!"}, {"numero": 9, "texto": "Jésus répondit: N''''y a-t-il pas douze heures au jour? Si quelqu''''un marche pendant le jour, il ne bronche point, parce qu''''il voit la lumière de ce monde;"}, {"numero": 10, "texto": "mais, si quelqu''''un marche pendant la nuit, il bronche, parce que la lumière n''''est pas en lui."}, {"numero": 11, "texto": "Après ces paroles, il leur dit: Lazare, notre ami, dort; mais je vais le réveiller."}, {"numero": 12, "texto": "Les disciples lui dirent: Seigneur, s''''il dort, il sera guéri."}, {"numero": 13, "texto": "Jésus avait parlé de sa mort, mais ils crurent qu''''il parlait de l''''assoupissement du sommeil."}, {"numero": 14, "texto": "Alors Jésus leur dit ouvertement: Lazare est mort."}, {"numero": 15, "texto": "Et, à cause de vous, afin que vous croyiez, je me réjouis de ce que je n''''étais pas là. Mais allons vers lui."}, {"numero": 16, "texto": "Sur quoi Thomas, appelé Didyme, dit aux autres disciples: Allons aussi, afin de mourir avec lui."}, {"numero": 17, "texto": "Jésus, étant arrivé, trouva que Lazare était déjà depuis quatre jours dans le sépulcre."}, {"numero": 18, "texto": "Et, comme Béthanie était près de Jérusalem, à quinze stades environ,"}, {"numero": 19, "texto": "beaucoup de Juifs étaient venus vers Marthe et Marie, pour les consoler de la mort de leur frère."}, {"numero": 20, "texto": "Lorsque Marthe apprit que Jésus arrivait, elle alla au-devant de lui, tandis que Marie se tenait assise à la maison."}, {"numero": 21, "texto": "Marthe dit à Jésus: Seigneur, si tu eusses été ici, mon frère ne serait pas mort."}, {"numero": 22, "texto": "Mais, maintenant même, je sais que tout ce que tu demanderas à Dieu, Dieu te l''''accordera."}, {"numero": 23, "texto": "Jésus lui dit: Ton frère ressuscitera."}, {"numero": 24, "texto": "Je sais, lui répondit Marthe, qu''''il ressuscitera à la résurrection, au dernier jour."}, {"numero": 25, "texto": "Jésus lui dit: Je suis la résurrection et la vie. Celui qui croit en moi vivra, quand même il serait mort;"}, {"numero": 26, "texto": "et quiconque vit et croit en moi ne mourra jamais. Crois-tu cela?"}, {"numero": 27, "texto": "Elle lui dit: Oui, Seigneur, je crois que tu es le Christ, le Fils de Dieu, qui devait venir dans le monde."}, {"numero": 28, "texto": "Ayant ainsi parlé, elle s''''en alla. Puis elle appela secrètement Marie, sa soeur, et lui dit: Le maître est ici, et il te demande."}, {"numero": 29, "texto": "Dès que Marie eut entendu, elle se leva promptement, et alla vers lui."}, {"numero": 30, "texto": "Car Jésus n''''était pas encore entré dans le village, mais il était dans le lieu où Marthe l''''avait rencontré."}, {"numero": 31, "texto": "Les Juifs qui étaient avec Marie dans la maison et qui la consolaient, l''''ayant vue se lever promptement et sortir, la suivirent, disant: Elle va au sépulcre, pour y pleurer."}, {"numero": 32, "texto": "Lorsque Marie fut arrivée là où était Jésus, et qu''''elle le vit, elle tomba à ses pieds, et lui dit: Seigneur, si tu eusses été ici, mon frère ne serait pas mort."}, {"numero": 33, "texto": "Jésus, la voyant pleurer, elle et les Juifs qui étaient venus avec elle, frémit en son esprit, et fut tout ému."}, {"numero": 34, "texto": "Et il dit: Où l''''avez-vous mis? Seigneur, lui répondirent-ils, viens et vois."}, {"numero": 35, "texto": "Jésus pleura."}, {"numero": 36, "texto": "Sur quoi les Juifs dirent: Voyez comme il l''''aimait."}, {"numero": 37, "texto": "Et quelques-uns d''''entre eux dirent: Lui qui a ouvert les yeux de l''''aveugle, ne pouvait-il pas faire aussi que cet homme ne mourût point?"}, {"numero": 38, "texto": "Jésus frémissant de nouveau en lui-même, se rendit au sépulcre. C''''était une grotte, et une pierre était placée devant."}, {"numero": 39, "texto": "Jésus dit: Otez la pierre. Marthe, la soeur du mort, lui dit: Seigneur, il sent déjà, car il y a quatre jours qu''''il est là."}, {"numero": 40, "texto": "Jésus lui dit: Ne t''''ai-je pas dit que, si tu crois, tu verras la gloire de Dieu?"}, {"numero": 41, "texto": "Ils ôtèrent donc la pierre. Et Jésus leva les yeux en haut, et dit: Père, je te rends grâces de ce que tu m''''as exaucé."}, {"numero": 42, "texto": "Pour moi, je savais que tu m''''exauces toujours; mais j''''ai parlé à cause de la foule qui m''''entoure, afin qu''''ils croient que c''''est toi qui m''''as envoyé."}, {"numero": 43, "texto": "Ayant dit cela, il cria d''''une voix forte: Lazare, sors!"}, {"numero": 44, "texto": "Et le mort sortit, les pieds et les mains liés de bandes, et le visage enveloppé d''''un linge. Jésus leur dit: Déliez-le, et laissez-le aller."}, {"numero": 45, "texto": "Plusieurs des Juifs qui étaient venus vers Marie, et qui virent ce que fit Jésus, crurent en lui."}, {"numero": 46, "texto": "Mais quelques-uns d''''entre eux allèrent trouver les pharisiens, et leur dirent ce que Jésus avait fait."}, {"numero": 47, "texto": "Alors les principaux sacrificateurs et les pharisiens assemblèrent le sanhédrin, et dirent: Que ferons-nous? Car cet homme fait beaucoup de miracles."}, {"numero": 48, "texto": "Si nous le laissons faire, tous croiront en lui, et les Romains viendront détruire et notre ville et notre nation."}, {"numero": 49, "texto": "L''''un d''''eux, Caïphe, qui était souverain sacrificateur cette année-là, leur dit: Vous n''''y entendez rien;"}, {"numero": 50, "texto": "vous ne réfléchissez pas qu''''il est dans votre intérêt qu''''un seul homme meure pour le peuple, et que la nation entière ne périsse pas."}, {"numero": 51, "texto": "Or, il ne dit pas cela de lui-même; mais étant souverain sacrificateur cette année-là, il prophétisa que Jésus devait mourir pour la nation."}, {"numero": 52, "texto": "Et ce n''''était pas pour la nation seulement; c''''était aussi afin de réunir en un seul corps les enfants de Dieu dispersés."}, {"numero": 53, "texto": "Dès ce jour, ils résolurent de le faire mourir."}, {"numero": 54, "texto": "C''''est pourquoi Jésus ne se montra plus ouvertement parmi les Juifs; mais il se retira dans la contrée voisine du désert, dans une ville appelée Ephraïm; et là il demeurait avec ses disciples."}, {"numero": 55, "texto": "La Pâque des Juifs était proche. Et beaucoup de gens du pays montèrent à Jérusalem avant la Pâque, pour se purifier."}, {"numero": 56, "texto": "Ils cherchaient Jésus, et ils se disaient les uns aux autres dans le temple: Que vous en semble? Ne viendra-t-il pas à la fête?"}, {"numero": 57, "texto": "Or, les principaux sacrificateurs et les pharisiens avaient donné l''''ordre que, si quelqu''''un savait où il était, il le déclarât, afin qu''''on se saisît de lui."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 11, 'es', '[{"numero": 1, "texto": "ESTABA entonces enfermo uno llamado Lázaro, de Bethania, la aldea de María y de Marta su hermana."}, {"numero": 2, "texto": "(Y María, cuyo hermano Lázaro estaba enfermo, era la que ungió al Señor con ungüento, y limpió sus pies con sus cabellos.)"}, {"numero": 3, "texto": "Enviaron, pues, sus hermanas á él, diciendo: Señor, he aquí, el que amas está enfermo."}, {"numero": 4, "texto": "Y oyéndolo Jesús, dijo: Esta enfermedad no es para muerte, mas por gloria de Dios, para que el Hijo de Dios sea glorificado por ella."}, {"numero": 5, "texto": "Y amaba Jesús á Marta, y á su hermana, y á Lázaro."}, {"numero": 6, "texto": "Como oyó pues que estaba enfermo, quedóse aún dos días en aquel lugar donde estaba."}, {"numero": 7, "texto": "Luego, después de esto, dijo á los discípulos: Vamos á Judea otra vez."}, {"numero": 8, "texto": "Dícenle los discípulos: Rabbí, ahora procuraban los Judíos apedrearte, ¿y otra vez vas allá?"}, {"numero": 9, "texto": "Respondió Jesús: ¿No tiene el día doce horas? El que anduviere de día, no tropieza, porque ve la luz de este mundo."}, {"numero": 10, "texto": "Mas el que anduviere de noche, tropieza, porque no hay luz en él."}, {"numero": 11, "texto": "Dicho esto, díceles después: Lázaro nuestro amigo duerme; mas voy á despertarle del sueño."}, {"numero": 12, "texto": "Dijeron entonces sus discípulos: Señor, si duerme, salvo estará."}, {"numero": 13, "texto": "Mas esto decía Jesús de la muerte de él: y ellos pensaron que hablaba del reposar del sueño."}, {"numero": 14, "texto": "Entonces, pues, Jesús les dijo claramente: Lázaro es muerto;"}, {"numero": 15, "texto": "Y huélgome por vosotros, que yo no haya estado allí, para que creáis: mas vamos á él."}, {"numero": 16, "texto": "Dijo entonces Tomás, el que se dice el Dídimo, á sus condiscípulos: Vamos también nosotros, para que muramos con él."}, {"numero": 17, "texto": "Vino pues Jesús, y halló que había ya cuatro días que estaba en el sepulcro."}, {"numero": 18, "texto": "Y Bethania estaba cerca de Jerusalem, como quince estadios;"}, {"numero": 19, "texto": "Y muchos de los Judíos habían venido á Marta y á María, á consolarlas de su hermano."}, {"numero": 20, "texto": "Entonces Marta, como oyó que Jesús venía, salió á encontrarle; mas María se estuvo en casa."}, {"numero": 21, "texto": "Y Marta dijo á Jesús: Señor, si hubieses estado aquí, mi hermano no fuera muerto;"}, {"numero": 22, "texto": "Mas también sé ahora, que todo lo que pidieres de Dios, te dará Dios."}, {"numero": 23, "texto": "Dícele Jesús: Resucitará tu hermano."}, {"numero": 24, "texto": "Marta le dice: Yo sé que resucitará en la resurrección en el día postrero."}, {"numero": 25, "texto": "Dícele Jesús: Yo soy la resurrección y la vida: el que cree en mí, aunque esté muerto, vivirá."}, {"numero": 26, "texto": "Y todo aquel que vive y cree en mí, no morirá eternamente. ¿Crees esto?"}, {"numero": 27, "texto": "Dícele: Sí, Señor; yo he creído que tú eres el Cristo, el Hijo de Dios, que has venido al mundo."}, {"numero": 28, "texto": "Y esto dicho, fuése, y llamó en secreto á María su hermana, diciendo: El Maestro está aquí y te llama."}, {"numero": 29, "texto": "Ella, como lo oyó, levántase prestamente y viene á él."}, {"numero": 30, "texto": "(Que aun no había llegado Jesús á la aldea, mas estaba en aquel lugar donde Marta le había encontrado.)"}, {"numero": 31, "texto": "Entonces los Judíos que estaban en casa con ella, y la consolaban, como vieron que María se había levantado prestamente, y había salido, siguiéronla, diciendo: Va al sepulcro á llorar allí."}, {"numero": 32, "texto": "Mas María, como vino donde estaba Jesús, viéndole, derribóse á sus pies, diciéndole: Señor, si hubieras estado aquí, no fuera muerto mi hermano."}, {"numero": 33, "texto": "Jesús entonces, como la vió llorando, y á los Judíos que habían venido juntamente con ella llorando, se conmovió en espíritu, y turbóse,"}, {"numero": 34, "texto": "Y dijo: ¿Dónde le pusisteis? Dícenle: Señor, ven, y ve."}, {"numero": 35, "texto": "Y lloró Jesús."}, {"numero": 36, "texto": "Dijeron entonces los Judíos: Mirad cómo le amaba."}, {"numero": 37, "texto": "Y algunos de ellos dijeron: ¿No podía éste que abrió los ojos al ciego, hacer que éste no muriera?"}, {"numero": 38, "texto": "Y Jesús, conmoviéndose otra vez en sí mismo, vino al sepulcro. Era una cueva, la cual tenía una piedra encima."}, {"numero": 39, "texto": "Dice Jesús: Quitad la piedra. Marta, la hermana del que se había muerto, le dice: Señor, hiede ya, que es de cuatro días."}, {"numero": 40, "texto": "Jesús le dice: ¿No te he dicho que, si creyeres, verás la gloria de Dios?"}, {"numero": 41, "texto": "Entonces quitaron la piedra de donde el muerto había sido puesto. Y Jesús, alzando los ojos arriba, dijo: Padre, gracias te doy que me has oído."}, {"numero": 42, "texto": "Que yo sabía que siempre me oyes; mas por causa de la compañía que está alrededor, lo dije, para que crean que tú me has enviado."}, {"numero": 43, "texto": "Y habiendo dicho estas cosas, clamó á gran voz: Lázaro, ven fuera."}, {"numero": 44, "texto": "Y el que había estado muerto, salió, atadas las manos y los pies con vendas; y su rostro estaba envuelto en un sudario. Díceles Jesús: Desatadle, y dejadle ir."}, {"numero": 45, "texto": "Entonces muchos de los Judíos que habían venido á María, y habían visto lo que había hecho Jesús, creyeron en él."}, {"numero": 46, "texto": "Mas algunos de ellos fueron á los Fariseos, y dijéronles lo que Jesús había hecho."}, {"numero": 47, "texto": "Entonces los pontífices y los Fariseos juntaron concilio, y decían: ¿Qué hacemos? porque este hombre hace muchas señales."}, {"numero": 48, "texto": "Si le dejamos así, todos creerán en él: y vendrán los Romanos, y quitarán nuestro lugar y la nación."}, {"numero": 49, "texto": "Y Caifás, uno de ellos, sumo pontífice de aquel año, les dijo: Vosotros no sabéis nada;"}, {"numero": 50, "texto": "Ni pensáis que nos conviene que un hombre muera por el pueblo, y no que toda la nación se pierda."}, {"numero": 51, "texto": "Mas esto no lo dijo de sí mismo; sino que, como era el sumo pontífice de aquel año, profetizó que Jesús había de morir por la nación:"}, {"numero": 52, "texto": "Y no solamente por aquella nación, mas también para que juntase en uno los hijos de Dios que estaban derramados."}, {"numero": 53, "texto": "Así que, desde aquel día consultaban juntos de matarle."}, {"numero": 54, "texto": "Por tanto, Jesús ya no andaba manifiestamente entre los Judíos; mas fuése de allí á la tierra que está junto al desierto, á una ciudad que se llama Ephraim: y estábase allí con sus discípulos."}, {"numero": 55, "texto": "Y la Pascua de los Judíos estaba cerca: y muchos subieron de aquella tierra á Jerusalem antes de la Pascua, para purificarse;"}, {"numero": 56, "texto": "Y buscaban á Jesús, y hablaban los unos con los otros estando en el templo: ¿Qué os parece, que no vendrá á la fiesta?"}, {"numero": 57, "texto": "Y los pontífices y los Fariseos habían dado mandamiento, que si alguno supiese dónde estuviera, lo manifestase, para que le prendiesen."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 12, 'pt', '[{"numero": 1, "texto": "Veio, pois, Jesus seis dias antes da páscoa a Betânia, onde estava Lázaro, o que havia morrido, a quem ressuscitara dos mortos."}, {"numero": 2, "texto": "Fizeram-lhe, pois, ali uma ceia, e Marta servia; e Lázaro era um dos que juntamente com ele estavam sentados [à mesa] ."}, {"numero": 3, "texto": "Tomando então Maria um arrátel de óleo perfumado de nardo puro, de muito preço, ungiu os pés de Jesus, e limpou os pés dele com seus cabelos; e encheu-se a casa do cheiro do óleo perfumado."}, {"numero": 4, "texto": "Então disse Judas de Simão Iscariotes, um de seus discípulos, o que o trairia:"}, {"numero": 5, "texto": "Por que se não vendeu este óleo perfumado por trezentos dinheiros, e se deu aos pobres?"}, {"numero": 6, "texto": "E isto disse ele, não pelo cuidado que tivesse dos pobres; mas porque era ladrão, e tinha a bolsa, e trazia o que se lançava [nela] ."}, {"numero": 7, "texto": "Disse pois Jesus: Deixa-a; para o dia de meu sepultamento guardou isto."}, {"numero": 8, "texto": "Porque aos pobres sempre os tendes convosco; porém a mim não me tendes sempre."}, {"numero": 9, "texto": "Muita gente dos judeus soube pois, que ele estava ali; e vieram, não somente por causa de Jesus, mas também para verem a Lázaro, a quem ressuscitara dos mortos."}, {"numero": 10, "texto": "E os chefes dos sacerdotes se aconselharam de também matarem a Lázaro,"}, {"numero": 11, "texto": "Porque muitos dos judeus iam por causa dele, e criam em Jesus."}, {"numero": 12, "texto": "No dia seguinte, ouvindo uma grande multidão, que viera à festa, que Jesus vinha a Jerusalém,"}, {"numero": 13, "texto": "Tomaram ramos de plantas e lhe saíram ao encontro, e clamavam: Hosana! Bendito aquele que vem no nome do Senhor, o Rei de Israel!"}, {"numero": 14, "texto": "E Jesus achou um jumentinho, e sentou-se sobre ele, como está escrito:"}, {"numero": 15, "texto": "Não temas, ó filha de Sião; eis que teu Rei vem sentado sobre o filhote de uma jumenta."}, {"numero": 16, "texto": "Porém seus discípulos não entenderam isto ao princípio; mas sendo Jesus já glorificado, então se lembraram que isto dele estava escrito, e [que] isto lhe fizeram."}, {"numero": 17, "texto": "A multidão pois, que estava com ele, testemunhava, que a Lázaro chamara da sepultura, e o ressuscitara dos mortos."}, {"numero": 18, "texto": "Pelo que também a multidão lhe saiu ao encontro, porque ouvira que fizera este sinal."}, {"numero": 19, "texto": "Disseram pois os fariseus entre si: Vedes que nada aproveitais? Eis que o mundo vai após ele."}, {"numero": 20, "texto": "E havia alguns gregos dos que haviam subido para adorarem na festa."}, {"numero": 21, "texto": "Estes pois vieram a Filipe, que era de Betsaida de Galileia, e rogaram-lhe, dizendo: Senhor, queríamos ver a Jesus."}, {"numero": 22, "texto": "Veio Filipe, e disse-o a André; e André então e Filipe o disseram a Jesus."}, {"numero": 23, "texto": "Porém Jesus lhes respondeu, dizendo: Chegada é a hora em que o Filho do homem será glorificado."}, {"numero": 24, "texto": "Em verdade, em verdade vos digo, se o grão de trigo, ao cair na terra, não morrer, ele fica só; porém se morrer, dá muito fruto."}, {"numero": 25, "texto": "Quem ama sua vida a perderá; e quem neste mundo odeia sua vida, a guardará para a vida eterna."}, {"numero": 26, "texto": "Se alguém me serve, siga-me; e onde eu estiver, ali estará também meu servo. E se alguém me servir, o Pai o honrará."}, {"numero": 27, "texto": "Agora minha alma está perturbada; e que direi? Pai, salva-me desta hora; mas por isso vim a esta hora."}, {"numero": 28, "texto": "Pai, glorifica teu Nome. Veio, pois, uma voz do céu, [que dizia] : E já [o] tenho glorificado, e outra vez [o] glorificarei."}, {"numero": 29, "texto": "A multidão pois que ali estava, e [a] ouviu, dizia que havia sido trovão. Outros diziam: Algum anjo falou com ele."}, {"numero": 30, "texto": "Respondeu Jesus e disse: Esta voz não veio por causa de mim, mas sim por causa de vós."}, {"numero": 31, "texto": "Agora é o juízo deste mundo; agora será lançado fora o príncipe deste mundo."}, {"numero": 32, "texto": "E eu, quando for levantado da terra, trarei todos a mim."}, {"numero": 33, "texto": "(E isto dizia, indicando de que morte [ele] morreria.)"}, {"numero": 34, "texto": "Respondeu-lhe a multidão: Temos ouvido da Lei que o Cristo permanece para sempre; e como tu dizes que convém que o Filho do homem seja levantado? Quem é este Filho do homem?"}, {"numero": 35, "texto": "Disse-lhes pois Jesus: Ainda por um pouco de tempo a luz está convosco; andai enquanto tendes luz, para que as trevas vos não apanhem. E quem anda em trevas não sabe para onde vai."}, {"numero": 36, "texto": "Enquanto tendes luz, crede na luz, para que sejais filhos da luz.Estas coisas falou Jesus, e indo-se, escondeu-se deles."}, {"numero": 37, "texto": "E ainda que perante eles tinha feito tantos sinais, não criam nele."}, {"numero": 38, "texto": "Para que se cumprisse a palavra do profeta Isaías, que disse: Senhor, quem creu em nossa pregação? E a quem o braço do Senhor foi revelado?"}, {"numero": 39, "texto": "Por isso não podiam crer, porque outra vez Isaías disse:"}, {"numero": 40, "texto": "Os olhos lhes cegou, e o coração lhes endureceu; para não acontecer que vejam dos olhos, e entendam do coração, e se convertam, e eu os cure."}, {"numero": 41, "texto": "Isto disse Isaías, quando viu sua glória, e falou dele."}, {"numero": 42, "texto": "Contudo ainda até muitos dos chefes também creram nele; mas não o confessavam por causa dos fariseus; para não serem expulsos da sinagoga."}, {"numero": 43, "texto": "Porque amavam mais a glória humana do que a glória de Deus."}, {"numero": 44, "texto": "E exclamou Jesus, e disse: Quem crê em mim, não crê [somente] em mim, mas [também] naquele que me enviou."}, {"numero": 45, "texto": "E quem vê a mim, vê a aquele que me enviou."}, {"numero": 46, "texto": "Eu sou a luz que vim ao mundo, para que todo aquele que crê em mim, não permaneça em trevas."}, {"numero": 47, "texto": "E se alguém ouvir minhas palavras, e não crer, eu não o julgo; porque não vim para julgar o mundo, mas sim para salvar o mundo."}, {"numero": 48, "texto": "Quem me rejeitar e não receber minhas palavras, já tem quem o julgue: a palavra que eu tenho falado, essa o julgará no último dia."}, {"numero": 49, "texto": "Porque eu não tenho falado de mim mesmo; porém o Pai que me enviou, ele me deu mandamento do que devo dizer, e do que devo falar."}, {"numero": 50, "texto": "E sei que seu mandamento é vida eterna. Portanto o que eu falo, falo assim como o Pai tem me dito."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 12, 'en', '[{"numero": 1, "texto": "Then Jesus six days before the passover came to Bethany, where Lazarus was, which had been dead, whom he raised from the dead."}, {"numero": 2, "texto": "There they made him a supper; and Martha served: but Lazarus was one of them that sat at the table with him."}, {"numero": 3, "texto": "Then took Mary a pound of ointment of spikenard, very costly, and anointed the feet of Jesus, and wiped his feet with her hair: and the house was filled with the odour of the ointment."}, {"numero": 4, "texto": "Then saith one of his disciples, Judas Iscariot, Simon''s son, which should betray him,"}, {"numero": 5, "texto": "Why was not this ointment sold for three hundred pence, and given to the poor?"}, {"numero": 6, "texto": "This he said, not that he cared for the poor; but because he was a thief, and had the bag, and bare what was put therein."}, {"numero": 7, "texto": "Then said Jesus, Let her alone: against the day of my burying hath she kept this."}, {"numero": 8, "texto": "For the poor always ye have with you; but me ye have not always."}, {"numero": 9, "texto": "Much people of the Jews therefore knew that he was there: and they came not for Jesus'' sake only, but that they might see Lazarus also, whom he had raised from the dead."}, {"numero": 10, "texto": "But the chief priests consulted that they might put Lazarus also to death;"}, {"numero": 11, "texto": "Because that by reason of him many of the Jews went away, and believed on Jesus."}, {"numero": 12, "texto": "On the next day much people that were come to the feast, when they heard that Jesus was coming to Jerusalem,"}, {"numero": 13, "texto": "Took branches of palm trees, and went forth to meet him, and cried, Hosanna: Blessed is the King of Israel that cometh in the name of the Lord."}, {"numero": 14, "texto": "And Jesus, when he had found a young ass, sat thereon; as it is written,"}, {"numero": 15, "texto": "Fear not, daughter of Sion: behold, thy King cometh, sitting on an ass''s colt."}, {"numero": 16, "texto": "These things understood not his disciples at the first: but when Jesus was glorified, then remembered they that these things were written of him, and that they had done these things unto him."}, {"numero": 17, "texto": "The people therefore that was with him when he called Lazarus out of his grave, and raised him from the dead, bare record."}, {"numero": 18, "texto": "For this cause the people also met him, for that they heard that he had done this miracle."}, {"numero": 19, "texto": "The Pharisees therefore said among themselves, Perceive ye how ye prevail nothing? behold, the world is gone after him."}, {"numero": 20, "texto": "And there were certain Greeks among them that came up to worship at the feast:"}, {"numero": 21, "texto": "The same came therefore to Philip, which was of Bethsaida of Galilee, and desired him, saying, Sir, we would see Jesus."}, {"numero": 22, "texto": "Philip cometh and telleth Andrew: and again Andrew and Philip tell Jesus."}, {"numero": 23, "texto": "And Jesus answered them, saying, The hour is come, that the Son of man should be glorified."}, {"numero": 24, "texto": "Verily, verily, I say unto you, Except a corn of wheat fall into the ground and die, it abideth alone: but if it die, it bringeth forth much fruit."}, {"numero": 25, "texto": "He that loveth his life shall lose it; and he that hateth his life in this world shall keep it unto life eternal."}, {"numero": 26, "texto": "If any man serve me, let him follow me; and where I am, there shall also my servant be: if any man serve me, him will my Father honour."}, {"numero": 27, "texto": "Now is my soul troubled; and what shall I say? Father, save me from this hour: but for this cause came I unto this hour."}, {"numero": 28, "texto": "Father, glorify thy name. Then came there a voice from heaven, saying, I have both glorified it, and will glorify it again."}, {"numero": 29, "texto": "The people therefore, that stood by, and heard it, said that it thundered: others said, An angel spake to him."}, {"numero": 30, "texto": "Jesus answered and said, This voice came not because of me, but for your sakes."}, {"numero": 31, "texto": "Now is the judgment of this world: now shall the prince of this world be cast out."}, {"numero": 32, "texto": "And I, if I be lifted up from the earth, will draw all men unto me."}, {"numero": 33, "texto": "This he said, signifying what death he should die."}, {"numero": 34, "texto": "The people answered him, We have heard out of the law that Christ abideth for ever: and how sayest thou, The Son of man must be lifted up? who is this Son of man?"}, {"numero": 35, "texto": "Then Jesus said unto them, Yet a little while is the light with you. Walk while ye have the light, lest darkness come upon you: for he that walketh in darkness knoweth not whither he goeth."}, {"numero": 36, "texto": "While ye have light, believe in the light, that ye may be the children of light. These things spake Jesus, and departed, and did hide himself from them."}, {"numero": 37, "texto": "But though he had done so many miracles before them, yet they believed not on him:"}, {"numero": 38, "texto": "That the saying of Esaias the prophet might be fulfilled, which he spake, Lord, who hath believed our report? and to whom hath the arm of the Lord been revealed?"}, {"numero": 39, "texto": "Therefore they could not believe, because that Esaias said again,"}, {"numero": 40, "texto": "He hath blinded their eyes, and hardened their heart; that they should not see with their eyes, nor understand with their heart, and be converted, and I should heal them."}, {"numero": 41, "texto": "These things said Esaias, when he saw his glory, and spake of him."}, {"numero": 42, "texto": "Nevertheless among the chief rulers also many believed on him; but because of the Pharisees they did not confess him, lest they should be put out of the synagogue:"}, {"numero": 43, "texto": "For they loved the praise of men more than the praise of God."}, {"numero": 44, "texto": "Jesus cried and said, He that believeth on me, believeth not on me, but on him that sent me."}, {"numero": 45, "texto": "And he that seeth me seeth him that sent me."}, {"numero": 46, "texto": "I am come a light into the world, that whosoever believeth on me should not abide in darkness."}, {"numero": 47, "texto": "And if any man hear my words, and believe not, I judge him not: for I came not to judge the world, but to save the world."}, {"numero": 48, "texto": "He that rejecteth me, and receiveth not my words, hath one that judgeth him: the word that I have spoken, the same shall judge him in the last day."}, {"numero": 49, "texto": "For I have not spoken of myself; but the Father which sent me, he gave me a commandment, what I should say, and what I should speak."}, {"numero": 50, "texto": "And I know that his commandment is life everlasting: whatsoever I speak therefore, even as the Father said unto me, so I speak."}]'::jsonb, 'King James Version'),
  ('Jo', 12, 'fr', '[{"numero": 1, "texto": "Six jours avant la Pâque, Jésus arriva à Béthanie, où était Lazare, qu''''il avait ressuscité des morts."}, {"numero": 2, "texto": "Là, on lui fit un souper; Marthe servait, et Lazare était un de ceux qui se trouvaient à table avec lui."}, {"numero": 3, "texto": "Marie, ayant pris une livre d''''un parfum de nard pur de grand prix, oignit les pieds de Jésus, et elle lui essuya les pieds avec ses cheveux; et la maison fut remplie de l''''odeur du parfum."}, {"numero": 4, "texto": "Un de ses disciples, Judas Iscariot, fils de Simon, celui qui devait le livrer, dit:"}, {"numero": 5, "texto": "Pourquoi n''''a-t-on pas vendu ce parfum trois cents deniers, pour les donner aux pauvres?"}, {"numero": 6, "texto": "Il disait cela, non qu''''il se mît en peine des pauvres, mais parce qu''''il était voleur, et que, tenant la bourse, il prenait ce qu''''on y mettait."}, {"numero": 7, "texto": "Mais Jésus dit: Laisse-la garder ce parfum pour le jour de ma sépulture."}, {"numero": 8, "texto": "Vous avez toujours les pauvres avec vous, mais vous ne m''''avez pas toujours."}, {"numero": 9, "texto": "Une grande multitude de Juifs apprirent que Jésus était à Béthanie; et ils y vinrent, non pas seulement à cause de lui, mais aussi pour voir Lazare, qu''''il avait ressuscité des morts."}, {"numero": 10, "texto": "Les principaux sacrificateurs délibérèrent de faire mourir aussi Lazare,"}, {"numero": 11, "texto": "parce que beaucoup de Juifs se retiraient d''''eux à cause de lui, et croyaient en Jésus."}, {"numero": 12, "texto": "Le lendemain, une foule nombreuse de gens venus à la fête ayant entendu dire que Jésus se rendait à Jérusalem,"}, {"numero": 13, "texto": "prirent des branches de palmiers, et allèrent au-devant de lui, en criant: Hosanna! Béni soit celui qui vient au nom du Seigneur, le roi d''''Israël!"}, {"numero": 14, "texto": "Jésus trouva un ânon, et s''''assit dessus, selon ce qui est écrit:"}, {"numero": 15, "texto": "Ne crains point, fille de Sion; Voici, ton roi vient, Assis sur le petit d''''une ânesse."}, {"numero": 16, "texto": "Ses disciples ne comprirent pas d''''abord ces choses; mais, lorsque Jésus eut été glorifié, ils se souvinrent qu''''elles étaient écrites de lui, et qu''''ils les avaient accomplies à son égard."}, {"numero": 17, "texto": "Tous ceux qui étaient avec Jésus, quand il appela Lazare du sépulcre et le ressuscita des morts, lui rendaient témoignage;"}, {"numero": 18, "texto": "et la foule vint au-devant de lui, parce qu''''elle avait appris qu''''il avait fait ce miracle."}, {"numero": 19, "texto": "Les pharisiens se dirent donc les uns aux autres: Vous voyez que vous ne gagnez rien; voici, le monde est allé après lui."}, {"numero": 20, "texto": "Quelques Grecs, du nombre de ceux qui étaient montés pour adorer pendant la fête,"}, {"numero": 21, "texto": "s''''adressèrent à Philippe, de Bethsaïda en Galilée, et lui dirent avec instance: Seigneur, nous voudrions voir Jésus."}, {"numero": 22, "texto": "Philippe alla le dire à André, puis André et Philippe le dirent à Jésus."}, {"numero": 23, "texto": "Jésus leur répondit: L''''heure est venue où le Fils de l''''homme doit être glorifié."}, {"numero": 24, "texto": "En vérité, en vérité, je vous le dis, si le grain de blé qui est tombé en terre ne meurt, il reste seul; mais, s''''il meurt, il porte beaucoup de fruit."}, {"numero": 25, "texto": "Celui qui aime sa vie la perdra, et celui qui hait sa vie dans ce monde la conservera pour la vie éternelle."}, {"numero": 26, "texto": "Si quelqu''''un me sert, qu''''il me suive; et là où je suis, là aussi sera mon serviteur. Si quelqu''''un me sert, le Père l''''honorera."}, {"numero": 27, "texto": "Maintenant mon âme est troublée. Et que dirai-je?... Père, délivre-moi de cette heure?... Mais c''''est pour cela que je suis venu jusqu''''à cette heure."}, {"numero": 28, "texto": "Père, glorifie ton nom! Et une voix vint du ciel: Je l''''ai glorifié, et je le glorifierai encore."}, {"numero": 29, "texto": "La foule qui était là, et qui avait entendu, disait que c''''était un tonnerre. D''''autres disaient: Un ange lui a parlé."}, {"numero": 30, "texto": "Jésus dit: Ce n''''est pas à cause de moi que cette voix s''''est fait entendre; c''''est à cause de vous."}, {"numero": 31, "texto": "Maintenant a lieu le jugement de ce monde; maintenant le prince de ce monde sera jeté dehors."}, {"numero": 32, "texto": "Et moi, quand j''''aurai été élevé de la terre, j''''attirerai tous les hommes à moi."}, {"numero": 33, "texto": "En parlant ainsi, il indiquait de quelle mort il devait mourir. -"}, {"numero": 34, "texto": "La foule lui répondit: Nous avons appris par la loi que le Christ demeure éternellement; comment donc dis-tu: Il faut que le Fils de l''''homme soit élevé? Qui est ce Fils de l''''homme?"}, {"numero": 35, "texto": "Jésus leur dit: La lumière est encore pour un peu de temps au milieu de vous. Marchez, pendant que vous avez la lumière, afin que les ténèbres ne vous surprennent point: celui qui marche dans les ténèbres ne sait où il va."}, {"numero": 36, "texto": "Pendant que vous avez la lumière, croyez en la lumière, afin que vous soyez des enfants de lumière. Jésus dit ces choses, puis il s''''en alla, et se cacha loin d''''eux."}, {"numero": 37, "texto": "Malgré tant de miracles qu''''il avait faits en leur présence, ils ne croyaient pas en lui,"}, {"numero": 38, "texto": "afin que s''''accomplît la parole qu''''Esaïe, le prophète, a prononcée: Seigneur, Qui a cru à notre prédication? Et à qui le bras du Seigneur a-t-il été révélé?"}, {"numero": 39, "texto": "Aussi ne pouvaient-ils croire, parce qu''''Esaïe a dit encore:"}, {"numero": 40, "texto": "Il a aveuglé leurs yeux; et il a endurci leur coeur, De peur qu''''ils ne voient des yeux, Qu''''ils ne comprennent du coeur, Qu''''ils ne se convertissent, et que je ne les guérisse."}, {"numero": 41, "texto": "Esaïe dit ces choses, lorsqu''''il vit sa gloire, et qu''''il parla de lui."}, {"numero": 42, "texto": "Cependant, même parmi les chefs, plusieurs crurent en lui; mais, à cause des pharisiens, ils n''''en faisaient pas l''''aveu, dans la crainte d''''être exclus de la synagogue."}, {"numero": 43, "texto": "Car ils aimèrent la gloire des hommes plus que la gloire de Dieu."}, {"numero": 44, "texto": "Or, Jésus s''''était écrié: Celui qui croit en moi croit, non pas en moi, mais en celui qui m''''a envoyé;"}, {"numero": 45, "texto": "et celui qui me voit voit celui qui m''''a envoyé."}, {"numero": 46, "texto": "Je suis venu comme une lumière dans le monde, afin que quiconque croit en moi ne demeure pas dans les ténèbres."}, {"numero": 47, "texto": "Si quelqu''''un entend mes paroles et ne les garde point, ce n''''est pas moi qui le juge; car je suis venu non pour juger le monde, mais pour sauver le monde."}, {"numero": 48, "texto": "Celui qui me rejette et qui ne reçoit pas mes paroles a son juge; la parole que j''''ai annoncée, c''''est elle qui le jugera au dernier jour."}, {"numero": 49, "texto": "Car je n''''ai point parlé de moi-même; mais le Père, qui m''''a envoyé, m''''a prescrit lui-même ce que je dois dire et annoncer."}, {"numero": 50, "texto": "Et je sais que son commandement est la vie éternelle. C''''est pourquoi les choses que je dis, je les dis comme le Père me les a dites."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 12, 'es', '[{"numero": 1, "texto": "Y JESÚS, seis días antes de la Pascua, vino á Bethania, donde estaba Lázaro, que había sido muerto, al cual había resucitado de los muertos."}, {"numero": 2, "texto": "E hiciéronle allí una cena: y Marta servía, y Lázaro era uno de los que estaban sentados á la mesa juntamente con él."}, {"numero": 3, "texto": "Entonces María tomó una libra de ungüento de nardo líquido de mucho precio, y ungió los pies de Jesús, y limpió sus pies con sus cabellos: y la casa se llenó del olor del ungüento."}, {"numero": 4, "texto": "Y dijo uno de sus discípulos, Judas Iscariote, hijo de Simón, el que le había de entregar:"}, {"numero": 5, "texto": "¿Por qué no se ha vendido este ungüento por trescientos dineros, y se dió á los pobres?"}, {"numero": 6, "texto": "Mas dijo esto, no por el cuidado que él tenía de los pobres; sino porque era ladrón, y tenía la bolsa, y traía lo que se echaba en ella."}, {"numero": 7, "texto": "Entonces Jesús dijo: Déjala: para el día de mi sepultura ha guardado esto;"}, {"numero": 8, "texto": "Porque á los pobres siempre los tenéis con vosotros, mas á mí no siempre me tenéis."}, {"numero": 9, "texto": "Entonces mucha gente de los Judíos entendió que él estaba allí; y vinieron no solamente por causa de Jesús, mas también por ver á Lázaro, al cual había resucitado de los muertos."}, {"numero": 10, "texto": "Consultaron asimismo los príncipes de los sacerdotes, de matar también á Lázaro;"}, {"numero": 11, "texto": "Porque muchos de los Judíos iban y creían en Jesús por causa de él."}, {"numero": 12, "texto": "El siguiente día, mucha gente que había venido á la fiesta, como oyeron que Jesús venía á Jerusalem,"}, {"numero": 13, "texto": "Tomaron ramos de palmas, y salieron á recibirle, y clamaban: ¡Hosanna, Bendito el que viene en el nombre del Señor, el Rey de Israel!"}, {"numero": 14, "texto": "Y halló Jesús un asnillo, y se sentó sobre él, como está escrito:"}, {"numero": 15, "texto": "No temas, hija de Sión: he aquí tu Rey viene, sentado sobre un pollino de asna."}, {"numero": 16, "texto": "Estas cosas no las entendieron sus discípulos de primero: empero cuando Jesús fué glorificado, entonces se acordaron de que estas cosas estaban escritas de él, y que le hicieron estas cosas."}, {"numero": 17, "texto": "Y la gente que estaba con él, daba testimonio de cuando llamó á Lázaro del sepulcro, y le resucitó de los muertos."}, {"numero": 18, "texto": "Por lo cual también había venido la gente á recibirle, porque había oído que él había hecho esta señal;"}, {"numero": 19, "texto": "Mas los Fariseos dijeron entre sí: ¿Veis que nada aprovecháis? he aquí, el mundo se va tras de él."}, {"numero": 20, "texto": "Y había ciertos Griegos de los que habían subido á adorar en la fiesta:"}, {"numero": 21, "texto": "Estos pues, se llegaron á Felipe, que era de Bethsaida de Galilea, y rogáronle, diciendo: Señor, querríamos ver á Jesús."}, {"numero": 22, "texto": "Vino Felipe, y díjolo á Andrés: Andrés entonces, y Felipe, lo dicen á Jesús."}, {"numero": 23, "texto": "Entonces Jesús les respondió, diciendo: La hora viene en que el Hijo del hombre ha de ser glorificado."}, {"numero": 24, "texto": "De cierto, de cierto os digo, que si el grano de trigo no cae en la tierra y muere, él solo queda; mas si muriere, mucho fruto lleva."}, {"numero": 25, "texto": "El que ama su vida, la perderá; y el que aborrece su vida en este mundo, para vida eterna la guardará."}, {"numero": 26, "texto": "Si alguno me sirve, sígame: y donde yo estuviere, allí también estará mi servidor. Si alguno me sirviere, mi Padre le honrará."}, {"numero": 27, "texto": "Ahora está turbada mi alma; ¿y qué diré? Padre, sálvame de esta hora. Mas por esto he venido en esta hora."}, {"numero": 28, "texto": "Padre, glorifica tu nombre. Entonces vino una voz del cielo: Y lo he glorificado, y lo glorificaré otra vez."}, {"numero": 29, "texto": "Y la gente que estaba presente, y había oído, decía que había sido trueno. Otros decían: Angel le ha hablado."}, {"numero": 30, "texto": "Respondió Jesús, y dijo: No ha venido esta voz por mi causa, mas por causa de vosotros."}, {"numero": 31, "texto": "Ahora es el juicio de este mundo: ahora el príncipe de este mundo será echado fuera."}, {"numero": 32, "texto": "Y yo, si fuere levantado de la tierra, á todos traeré á mí mismo."}, {"numero": 33, "texto": "Y esto decía dando á entender de qué muerte había de morir."}, {"numero": 34, "texto": "Respondióle la gente: Nosotros hemos oído de la ley, que el Cristo permanece para siempre: ¿cómo pues dices tú: Conviene que el Hijo del hombre sea levantado? ¿Quién es este Hijo del hombre?"}, {"numero": 35, "texto": "Entonces Jesús les dice: Aun por un poco estará la luz entre vosotros: andad entre tanto que tenéis luz, porque no os sorprendan las tinieblas; porque el que anda en tinieblas, no sabe dónde va."}, {"numero": 36, "texto": "Entre tanto que tenéis la luz, creed en la luz, para que seáis hijos de luz. Estas cosas habló Jesús, y fuése, y escondióse de ellos."}, {"numero": 37, "texto": "Empero habiendo hecho delante de ellos tantas señales, no creían en él."}, {"numero": 38, "texto": "Para que se cumpliese el dicho que dijo el profeta Isaías: ¿Señor, quién ha creído á nuestro dicho? ¿y el brazo del Señor, á quién es revelado?"}, {"numero": 39, "texto": "Por esto no podían creer, porque otra vez dijo Isaías:"}, {"numero": 40, "texto": "Cegó los ojos de ellos, y endureció su corazón; porque no vean con los ojos, y entiendan de corazón, y se conviertan, y yo los sane."}, {"numero": 41, "texto": "Estas cosas dijo Isaías cuando vió su gloria, y habló de él."}, {"numero": 42, "texto": "Con todo eso, aun de los príncipes, muchos creyeron en él; mas por causa de los Fariseos no lo confesaban, por no ser echados de la sinagoga."}, {"numero": 43, "texto": "Porque amaban más la gloria de los hombres que la gloria de Dios."}, {"numero": 44, "texto": "Mas Jesús clamó y dijo: El que cree en mí, no cree en mí, sino en el que me envió;"}, {"numero": 45, "texto": "Y el que me ve, ve al que me envió."}, {"numero": 46, "texto": "Yo la luz he venido al mundo, para que todo aquel que cree en mí no permanezca en tinieblas."}, {"numero": 47, "texto": "Y el que oyere mis palabras, y no las creyere, yo no le juzgo; porque no he venido á juzgar al mundo, sino á salvar al mundo."}, {"numero": 48, "texto": "El que me desecha, y no recibe mis palabras, tiene quien le juzgue: la palabra que he hablado, ella le juzgará en el día postrero."}, {"numero": 49, "texto": "Porque yo no he hablado de mí mismo: mas el Padre que me envió, él me dió mandamiento de lo que he de decir, y de lo que he de hablar."}, {"numero": 50, "texto": "Y sé que su mandamiento es vida eterna: así que, lo que yo hablo, como el Padre me lo ha dicho, así hablo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 13, 'pt', '[{"numero": 1, "texto": "E antes da festa da páscoa, sabendo Jesus que sua hora já era vinda, para que deste mundo passasse para o Pai, havendo amado aos seus, que estavam no mundo, até o fim os amou."}, {"numero": 2, "texto": "E terminada a ceia, o diabo já havia metido no coração de Judas de Simão Iscariotes, que o traísse."}, {"numero": 3, "texto": "Sabendo Jesus que o Pai já tinha lhe dado todas as coisas nas mãos, e que ele era vindo de Deus, e para Deus ele iria,"}, {"numero": 4, "texto": "Levantou-se da ceia, e tirou as roupas, e tomando uma toalha, envolveu- [a] em si;"}, {"numero": 5, "texto": "Depois pôs água em uma bacia, e começou a lavar os pés dos discípulos, e limpá-los com a toalha com que estava envolto."}, {"numero": 6, "texto": "Veio, pois, a Simão Pedro; e ele lhe disse: Senhor, tu a mim lavas meus pés?"}, {"numero": 7, "texto": "Respondeu Jesus, e disse-lhe: O que eu faço tu não o sabes agora; mas depois o entenderás."}, {"numero": 8, "texto": "Disse-lhe Pedro: Nunca lavarás meus pés. Respondeu-lhe então Jesus: Se eu não te lavar, não tens parte comigo."}, {"numero": 9, "texto": "Disse-lhe Simão Pedro: Senhor, [lava] não só meus pés, mas também as mãos e a cabeça."}, {"numero": 10, "texto": "Disse-lhe Jesus: Aquele que está lavado não necessita lavar, a não ser os pés, mas está todo limpo. E vós limpos estais, porém não todos."}, {"numero": 11, "texto": "Porque ele bem sabia quem o trairia; por isso disse: Nem todos estais limpos."}, {"numero": 12, "texto": "Quando então, tendo eles lavado os pés, e tomado suas roupas, voltou a se sentar [à mesa] ,e disse-lhes: Entendeis o que vos tenho feito?"}, {"numero": 13, "texto": "Vós me chamais Mestre, e Senhor, e bem dizeis; que eu o sou;"}, {"numero": 14, "texto": "Pois se eu, o Senhor, e o Mestre, tenho lavado vossos pés, também vós deveis lavar vossos pés uns aos outros."}, {"numero": 15, "texto": "Porque vos tenho dado exemplo, para que como eu vos tenho feito, façais vós também."}, {"numero": 16, "texto": "Em verdade, em verdade vos digo, [que] o servo não é maior que seu senhor; nem enviado maior que aquele que o enviou."}, {"numero": 17, "texto": "Se sabeis estas coisas, sereis bem-aventurados se as fizerdes."}, {"numero": 18, "texto": "Não digo de todos; bem sei eu aos que tenho escolhido; mas para que se cumpra a Escritura, [que diz] : O que come comigo, levantou contra mim seu calcanhar."}, {"numero": 19, "texto": "Desde agora, antes que se faça, digo-o a vós, para que, quando se fizer, creiais que eu sou."}, {"numero": 20, "texto": "Em verdade, em verdade vos digo, [que] se alguém receber ao [que] eu enviar, a mim me recebe; e quem a mim me receber, recebe a aquele que me enviou."}, {"numero": 21, "texto": "Havendo Jesus dito isto, perturbou-se em espírito, e testemunhou, e disse: Em verdade, em verdade vos digo, que um de vós me trairá."}, {"numero": 22, "texto": "Pelo que os discípulos se olhavam uns para os outros, duvidando de quem ele dizia."}, {"numero": 23, "texto": "E um dos discípulos, a quem Jesus amava, estava sentado [à mesa encostado] no seio de Jesus."}, {"numero": 24, "texto": "A este pois fez sinal Simão Pedro, que perguntasse quem era aquele de quem ele dizia."}, {"numero": 25, "texto": "E declinando-se ele ao peito de Jesus, disse-lhe: Senhor, quem é?"}, {"numero": 26, "texto": "Respondeu Jesus: Aquele a quem eu der o pedaço molhado de pão. E molhando o pedaço de pão, deu-o a Judas de Simão Iscariotes."}, {"numero": 27, "texto": "E após o pedaço de pão, entrou nele Satanás. Disse-lhe pois Jesus: O que fazes, faze-o depressa."}, {"numero": 28, "texto": "E nenhum dos que estavam sentados [à mesa] entendeu para que ele lhe dissera."}, {"numero": 29, "texto": "Pois alguns pensavam que, porque Judas tinha a bolsa, Jesus havia lhe dito: Compra o que para o que nos é necessário para a festa; ou que alguma coisa desse aos pobres."}, {"numero": 30, "texto": "Havendo ele pois tomado o pedaço de pão, logo saiu. E já era noite."}, {"numero": 31, "texto": "Tendo, pois, ele saído, disse Jesus: Agora o Filho do homem é glorificado, e Deus é glorificado nele."}, {"numero": 32, "texto": "Se Deus nele é glorificado, também Deus o glorificará em si mesmo, e logo o glorificará."}, {"numero": 33, "texto": "Filhinhos, ainda um pouco estou convosco. Vós me buscareis; e tal como eu aos Judeus: Para onde eu vou, vós não podeis vir; assim também o digo a vós agora."}, {"numero": 34, "texto": "Um novo mandamento vos dou: que vos ameis uns aos outros; tal como eu vos amei, também ameis vós uns aos outros."}, {"numero": 35, "texto": "Nisto todos conhecerão que sois meus discípulos: se vós tiverdes amor uns aos outros."}, {"numero": 36, "texto": "Disse-lhe Simão Pedro: Senhor, para onde vais? Respondeu-lhe Jesus: Para onde eu vou tu não podes me seguir agora; porém depois me seguirás."}, {"numero": 37, "texto": "Disse-lhe Pedro: Senhor, por que agora não posso te seguir? Por ti eu darei minha vida."}, {"numero": 38, "texto": "Respondeu-lhe Jesus: Por mim darás tua vida? Em verdade, em verdade te digo, que o galo não cantará, até que três vezes me negues."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 13, 'en', '[{"numero": 1, "texto": "Now before the feast of the passover, when Jesus knew that his hour was come that he should depart out of this world unto the Father, having loved his own which were in the world, he loved them unto the end."}, {"numero": 2, "texto": "And supper being ended, the devil having now put into the heart of Judas Iscariot, Simon''s son, to betray him;"}, {"numero": 3, "texto": "Jesus knowing that the Father had given all things into his hands, and that he was come from God, and went to God;"}, {"numero": 4, "texto": "He riseth from supper, and laid aside his garments; and took a towel, and girded himself."}, {"numero": 5, "texto": "After that he poureth water into a bason, and began to wash the disciples'' feet, and to wipe them with the towel wherewith he was girded."}, {"numero": 6, "texto": "Then cometh he to Simon Peter: and Peter saith unto him, Lord, dost thou wash my feet?"}, {"numero": 7, "texto": "Jesus answered and said unto him, What I do thou knowest not now; but thou shalt know hereafter."}, {"numero": 8, "texto": "Peter saith unto him, Thou shalt never wash my feet. Jesus answered him, If I wash thee not, thou hast no part with me."}, {"numero": 9, "texto": "Simon Peter saith unto him, Lord, not my feet only, but also my hands and my head."}, {"numero": 10, "texto": "Jesus saith to him, He that is washed needeth not save to wash his feet, but is clean every whit: and ye are clean, but not all."}, {"numero": 11, "texto": "For he knew who should betray him; therefore said he, Ye are not all clean."}, {"numero": 12, "texto": "So after he had washed their feet, and had taken his garments, and was set down again, he said unto them, Know ye what I have done to you?"}, {"numero": 13, "texto": "Ye call me Master and Lord: and ye say well; for so I am."}, {"numero": 14, "texto": "If I then, your Lord and Master, have washed your feet; ye also ought to wash one another''s feet."}, {"numero": 15, "texto": "For I have given you an example, that ye should do as I have done to you."}, {"numero": 16, "texto": "Verily, verily, I say unto you, The servant is not greater than his lord; neither he that is sent greater than he that sent him."}, {"numero": 17, "texto": "If ye know these things, happy are ye if ye do them."}, {"numero": 18, "texto": "I speak not of you all: I know whom I have chosen: but that the scripture may be fulfilled, He that eateth bread with me hath lifted up his heel against me."}, {"numero": 19, "texto": "Now I tell you before it come, that, when it is come to pass, ye may believe that I am he."}, {"numero": 20, "texto": "Verily, verily, I say unto you, He that receiveth whomsoever I send receiveth me; and he that receiveth me receiveth him that sent me."}, {"numero": 21, "texto": "When Jesus had thus said, he was troubled in spirit, and testified, and said, Verily, verily, I say unto you, that one of you shall betray me."}, {"numero": 22, "texto": "Then the disciples looked one on another, doubting of whom he spake."}, {"numero": 23, "texto": "Now there was leaning on Jesus'' bosom one of his disciples, whom Jesus loved."}, {"numero": 24, "texto": "Simon Peter therefore beckoned to him, that he should ask who it should be of whom he spake."}, {"numero": 25, "texto": "He then lying on Jesus'' breast saith unto him, Lord, who is it?"}, {"numero": 26, "texto": "Jesus answered, He it is, to whom I shall give a sop, when I have dipped it. And when he had dipped the sop, he gave it to Judas Iscariot, the son of Simon."}, {"numero": 27, "texto": "And after the sop Satan entered into him. Then said Jesus unto him, That thou doest, do quickly."}, {"numero": 28, "texto": "Now no man at the table knew for what intent he spake this unto him."}, {"numero": 29, "texto": "For some of them thought, because Judas had the bag, that Jesus had said unto him, Buy those things that we have need of against the feast; or, that he should give something to the poor."}, {"numero": 30, "texto": "He then having received the sop went immediately out: and it was night."}, {"numero": 31, "texto": "Therefore, when he was gone out, Jesus said, Now is the Son of man glorified, and God is glorified in him."}, {"numero": 32, "texto": "If God be glorified in him, God shall also glorify him in himself, and shall straightway glorify him."}, {"numero": 33, "texto": "Little children, yet a little while I am with you. Ye shall seek me: and as I said unto the Jews, Whither I go, ye cannot come; so now I say to you."}, {"numero": 34, "texto": "A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another."}, {"numero": 35, "texto": "By this shall all men know that ye are my disciples, if ye have love one to another."}, {"numero": 36, "texto": "Simon Peter said unto him, Lord, whither goest thou? Jesus answered him, Whither I go, thou canst not follow me now; but thou shalt follow me afterwards."}, {"numero": 37, "texto": "Peter said unto him, Lord, why cannot I follow thee now? I will lay down my life for thy sake."}, {"numero": 38, "texto": "Jesus answered him, Wilt thou lay down thy life for my sake? Verily, verily, I say unto thee, The cock shall not crow, till thou hast denied me thrice."}]'::jsonb, 'King James Version'),
  ('Jo', 13, 'fr', '[{"numero": 1, "texto": "Avant la fête de Pâque, Jésus, sachant que son heure était venue de passer de ce monde au Père, et ayant aimé les siens qui étaient dans le monde, mit le comble à son amour pour eux."}, {"numero": 2, "texto": "Pendant le souper, lorsque le diable avait déjà inspiré au coeur de Judas Iscariot, fils de Simon, le dessein de le livrer,"}, {"numero": 3, "texto": "Jésus, qui savait que le Père avait remis toutes choses entre ses mains, qu''''il était venu de Dieu, et qu''''il s''''en allait à Dieu,"}, {"numero": 4, "texto": "se leva de table, ôta ses vêtements, et prit un linge, dont il se ceignit."}, {"numero": 5, "texto": "Ensuite il versa de l''''eau dans un bassin, et il se mit à laver les pieds des disciples, et à les essuyer avec le linge dont il était ceint."}, {"numero": 6, "texto": "Il vint donc à Simon Pierre; et Pierre lui dit: Toi, Seigneur, tu me laves les pieds!"}, {"numero": 7, "texto": "Jésus lui répondit: Ce que je fais, tu ne le comprends pas maintenant, mais tu le comprendras bientôt."}, {"numero": 8, "texto": "Pierre lui dit: Non, jamais tu ne me laveras les pieds. Jésus lui répondit: Si je ne te lave, tu n''''auras point de part avec moi."}, {"numero": 9, "texto": "Simon Pierre lui dit: Seigneur, non seulement les pieds, mais encore les mains et la tête."}, {"numero": 10, "texto": "Jésus lui dit: Celui qui est lavé n''''a besoin que de se laver les pieds pour être entièrement pur; et vous êtes purs, mais non pas tous."}, {"numero": 11, "texto": "Car il connaissait celui qui le livrait; c''''est pourquoi il dit: Vous n''''êtes pas tous purs."}, {"numero": 12, "texto": "Après qu''''il leur eut lavé les pieds, et qu''''il eut pris ses vêtements, il se remit à table, et leur dit: Comprenez-vous ce que je vous ai fait?"}, {"numero": 13, "texto": "Vous m''''appelez Maître et Seigneur; et vous dites bien, car je le suis."}, {"numero": 14, "texto": "Si donc je vous ai lavé les pieds, moi, le Seigneur et le Maître, vous devez aussi vous laver les pieds les uns aux autres;"}, {"numero": 15, "texto": "car je vous ai donné un exemple, afin que vous fassiez comme je vous ai fait."}, {"numero": 16, "texto": "En vérité, en vérité, je vous le dis, le serviteur n''''est pas plus grand que son seigneur, ni l''''apôtre plus grand que celui qui l''''a envoyé."}, {"numero": 17, "texto": "Si vous savez ces choses, vous êtes heureux, pourvu que vous les pratiquiez."}, {"numero": 18, "texto": "Ce n''''est pas de vous tous que je parle; je connais ceux que j''''ai choisis. Mais il faut que l''''Ecriture s''''accomplisse: Celui qui mange avec moi le pain A levé son talon contre moi."}, {"numero": 19, "texto": "Dès à présent je vous le dis, avant que la chose arrive, afin que, lorsqu''''elle arrivera, vous croyiez à ce que je suis."}, {"numero": 20, "texto": "En vérité, en vérité, je vous le dis, celui qui reçoit celui que j''''aurai envoyé me reçoit, et celui qui me reçoit, reçoit celui qui m''''a envoyé."}, {"numero": 21, "texto": "Ayant ainsi parlé, Jésus fut troublé en son esprit, et il dit expressément: En vérité, en vérité, je vous le dis, l''''un de vous me livrera."}, {"numero": 22, "texto": "Les disciples se regardaient les uns les autres, ne sachant de qui il parlait."}, {"numero": 23, "texto": "Un des disciples, celui que Jésus aimait, était couché sur le sein de Jésus."}, {"numero": 24, "texto": "Simon Pierre lui fit signe de demander qui était celui dont parlait Jésus."}, {"numero": 25, "texto": "Et ce disciple, s''''étant penché sur la poitrine de Jésus, lui dit: Seigneur, qui est-ce?"}, {"numero": 26, "texto": "Jésus répondit: C''''est celui à qui je donnerai le morceau trempé. Et, ayant trempé le morceau, il le donna à Judas, fils de Simon, l''''Iscariot."}, {"numero": 27, "texto": "Dès que le morceau fut donné, Satan entra dans Judas. Jésus lui dit: Ce que tu fais, fais-le promptement."}, {"numero": 28, "texto": "Mais aucun de ceux qui étaient à table ne comprit pourquoi il lui disait cela;"}, {"numero": 29, "texto": "car quelques-uns pensaient que, comme Judas avait la bourse, Jésus voulait lui dire: Achète ce dont nous avons besoin pour la fête, ou qu''''il lui commandait de donner quelque chose aux pauvres."}, {"numero": 30, "texto": "Judas, ayant pris le morceau, se hâta de sortir. Il était nuit."}, {"numero": 31, "texto": "Lorsque Judas fut sorti, Jésus dit: Maintenant, le Fils de l''''homme a été glorifié, et Dieu a été glorifié en lui."}, {"numero": 32, "texto": "Si Dieu a été glorifié en lui, Dieu aussi le glorifiera en lui-même, et il le glorifiera bientôt."}, {"numero": 33, "texto": "Mes petits enfants, je suis pour peu de temps encore avec vous. Vous me chercherez; et, comme j''''ai dit aux Juifs: Vous ne pouvez venir où je vais, je vous le dis aussi maintenant."}, {"numero": 34, "texto": "Je vous donne un commandement nouveau: Aimez-vous les uns les autres; comme je vous ai aimés, vous aussi, aimez-vous les uns les autres."}, {"numero": 35, "texto": "A ceci tous connaîtront que vous êtes mes disciples, si vous avez de l''''amour les uns pour les autres."}, {"numero": 36, "texto": "Simon Pierre lui dit: Seigneur, où vas-tu? Jésus répondit: Tu ne peux pas maintenant me suivre où je vais, mais tu me suivras plus tard."}, {"numero": 37, "texto": "Seigneur, lui dit Pierre, pourquoi ne puis-je pas te suivre maintenant? Je donnerai ma vie pour toi."}, {"numero": 38, "texto": "Jésus répondit: Tu donneras ta vie pour moi! En vérité, en vérité, je te le dis, le coq ne chantera pas que tu ne m''''aies renié trois fois."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 13, 'es', '[{"numero": 1, "texto": "ANTES de la fiesta de la Pascua, sabiendo Jesús que su hora había venido para que pasase de este mundo al Padre, como había amado á los suyos que estaban en el mundo, amólos hasta el fin."}, {"numero": 2, "texto": "Y la cena acabada, como el diablo ya había metido en el corazón de Judas, hijo de Simón Iscariote, que le entregase,"}, {"numero": 3, "texto": "Sabiendo Jesús que el Padre le había dado todas las cosas en las manos, y que había salido de Dios, y á Dios iba,"}, {"numero": 4, "texto": "Levántase de la cena, y quítase su ropa, y tomando una toalla, ciñóse."}, {"numero": 5, "texto": "Luego puso agua en un lebrillo, y comenzó á lavar los pies de los discípulos, y á limpiarlos con la toalla con que estaba ceñido."}, {"numero": 6, "texto": "Entonces vino á Simón Pedro; y Pedro le dice: ¿Señor, tú me lavas los pies?"}, {"numero": 7, "texto": "Respondió Jesús, y díjole: Lo que yo hago, tú no entiendes ahora; mas lo entenderás después."}, {"numero": 8, "texto": "Dícele Pedro: No me lavarás los pies jamás. Respondióle Jesús: Si no te lavare, no tendrás parte conmigo."}, {"numero": 9, "texto": "Dícele Simón Pedro: Señor, no sólo mis pies, mas aun las manos y la cabeza."}, {"numero": 10, "texto": "Dícele Jesús: El que está lavado, no necesita sino que lave los pies, mas está todo limpio: y vosotros limpios estáis, aunque no todos."}, {"numero": 11, "texto": "Porque sabía quién le había de entregar; por eso dijo: No estáis limpios todos."}, {"numero": 12, "texto": "Así que, después que les hubo lavado los pies, y tomado su ropa, volviéndose á sentar á la mesa, díjoles: ¿Sabéis lo que os he hecho?"}, {"numero": 13, "texto": "Vosotros me llamáis, Maestro, y, Señor: y decís bien; porque lo soy."}, {"numero": 14, "texto": "Pues si yo, el Señor y el Maestro, he lavado vuestros pies, vosotros también debéis lavar los pies los unos á los otros."}, {"numero": 15, "texto": "Porque ejemplo os he dado, para que como yo os he hecho, vosotros también hagáis."}, {"numero": 16, "texto": "De cierto, de cierto os digo: El siervo no es mayor que su señor, ni el apóstol es mayor que el que le envió."}, {"numero": 17, "texto": "Si sabéis estas cosas, bienaventurados seréis, si las hiciereis."}, {"numero": 18, "texto": "No hablo de todos vosotros: yo sé los que he elegido: mas para que se cumpla la Escritura: El que come pan conmigo, levantó contra mí su calcañar."}, {"numero": 19, "texto": "Desde ahora os lo digo antes que se haga, para que cuando se hiciere, creáis que yo soy."}, {"numero": 20, "texto": "De cierto, de cierto os digo: El que recibe al que yo enviare, á mí recibe; y el que á mí recibe, recibe al que me envió."}, {"numero": 21, "texto": "Como hubo dicho Jesús esto, fué conmovido en el espíritu, y protestó, y dijo: De cierto, de cierto os digo, que uno de vosotros me ha de entregar."}, {"numero": 22, "texto": "Entonces los discípulos mirábanse los unos á los otros, dudando de quién decía."}, {"numero": 23, "texto": "Y uno de sus discípulos, al cual Jesús amaba, estaba recostado en el seno de Jesús."}, {"numero": 24, "texto": "A éste, pues, hizo señas Simón Pedro, para que preguntase quién era aquél de quien decía."}, {"numero": 25, "texto": "El entonces recostándose sobre el pecho de Jesús, dícele: Señor, ¿quién es?"}, {"numero": 26, "texto": "Respondió Jesús: Aquél es, á quien yo diere el pan mojado. Y mojando el pan, diólo á Judas Iscariote, hijo de Simón."}, {"numero": 27, "texto": "Y tras el bocado Satanás entró en él. Entonces Jesús le dice: Lo que haces, hazlo más presto."}, {"numero": 28, "texto": "Mas ninguno de los que estaban á la mesa entendió á qué propósito le dijo esto."}, {"numero": 29, "texto": "Porque los unos pensaban, porque Judas tenía la bolsa, que Jesús le decía: Compra lo que necesitamos para la fiesta: ó, que diese algo á los pobres."}, {"numero": 30, "texto": "Como él pues hubo tomado el bocado, luego salió: y era ya noche."}, {"numero": 31, "texto": "Entonces como él salió, dijo Jesús: Ahora es glorificado el Hijo del hombre, y Dios es glorificado en él."}, {"numero": 32, "texto": "Si Dios es glorificado en él, Dios también le glorificará en sí mismo, y luego le glorificará."}, {"numero": 33, "texto": "Hijitos, aun un poco estoy con vosotros. Me buscaréis; mas, como dije á los Judíos: Donde yo voy, vosotros no podéis venir; así digo á vosotros ahora."}, {"numero": 34, "texto": "Un mandamiento nuevo os doy: Que os améis unos á otros: como os he amado, que también os améis los unos á los otros."}, {"numero": 35, "texto": "En esto conocerán todos que sois mis discípulos, si tuviereis amor los unos con los otros."}, {"numero": 36, "texto": "Dícele Simón Pedro: Señor, ¿adónde vas? Respondióle Jesús: Donde yo voy, no me puedes ahora seguir; mas me seguirás después."}, {"numero": 37, "texto": "Dícele Pedro: Señor, ¿por qué no te puedo seguir ahora? mi alma pondré por ti."}, {"numero": 38, "texto": "Respondióle Jesús: ¿Tu alma pondrás por mí? De cierto, de cierto te digo: No cantará el gallo, sin que me hayas negado tres veces."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 14, 'pt', '[{"numero": 1, "texto": "Não se perturbe vosso coração; credes em Deus, crede também em mim."}, {"numero": 2, "texto": "Na casa de meu Pai há muitas moradas; senão, eu vos diria; vou para vos preparar lugar."}, {"numero": 3, "texto": "E quando eu for, e vos preparar lugar, outra vez virei, e vos tomarei comigo, para que vós também estejais onde eu estiver."}, {"numero": 4, "texto": "E já sabeis para onde vou, e sabeis o caminho."}, {"numero": 5, "texto": "Disse-lhe Tomé: Senhor, não sabemos para onde vais; e como podemos saber o caminho?"}, {"numero": 6, "texto": "Jesus lhe disse: Eu sou o caminho, e a verdade, e a vida. Ninguém vem ao Pai, a não ser por mim."}, {"numero": 7, "texto": "Se vós conhecêsseis a mim, também conheceríeis a meu Pai; e desde agora já o conheceis, e o tendes visto."}, {"numero": 8, "texto": "Disse-lhe Filipe: Senhor, mostra-nos ao Pai, e basta-nos."}, {"numero": 9, "texto": "Jesus lhe disse: Tanto tempo [há que] estou convosco, e [ainda] não me tens conhecido, Filipe? Quem a mim tem visto, já tem visto ao Pai; e como dizes tu: Mostra-nos ao Pai?"}, {"numero": 10, "texto": "Não crês tu que eu [estou] no Pai, e que o Pai está em mim? As palavras que eu vos falo, não as falo de mim mesmo, mas o Pai que está em mim, ele [é o que] faz as obras."}, {"numero": 11, "texto": "Crede em mim que eu [estou] no Pai, e [que] o Pai está em mim; e quando não, crede em mim por causa das próprias obras."}, {"numero": 12, "texto": "Em verdade, em verdade vos digo, que aquele que crê em mim, as obras que eu faço também ele as fará; e fará maiores que estas. Porque eu vou a meu Pai."}, {"numero": 13, "texto": "E tudo quanto pedirdes em meu nome, eu o farei; para que o Pai seja glorificado no Filho."}, {"numero": 14, "texto": "Se alguma coisa pedirdes em meu nome, eu [a] farei."}, {"numero": 15, "texto": "Se me amais, guardai meus mandamentos."}, {"numero": 16, "texto": "E eu rogarei ao Pai, e ele vos dará outro Consolador, para que fique sempre convosco;"}, {"numero": 17, "texto": "Ao Espírito de verdade, a quem o mundo não pode receber; porque não o vê, nem o conhece; mas vós o conheceis, porque habita convosco, e estará em vós."}, {"numero": 18, "texto": "Não vos deixarei órfãos; eu virei a vós."}, {"numero": 19, "texto": "Ainda um pouco, e o mundo não me verá mais; mas vós me vereis; porque eu vivo, e vós vivereis."}, {"numero": 20, "texto": "Naquele dia conhecereis que [estou] em meu Pai, e vós em mim, e eu em vós."}, {"numero": 21, "texto": "Quem tem meus mandamentos, e os guarda, esse é o que me ama; e quem a mim me ama, será amado de meu Pai, e eu o amarei, e a ele me manifestarei."}, {"numero": 22, "texto": "Disse-lhe Judas (não o Iscariotes): Senhor, que há, porque a nós te manifestarás, e não ao mundo?"}, {"numero": 23, "texto": "Respondeu Jesus, e disse-lhe: Se alguém me ama, guardará minha palavra, e meu Pai o amará, e viremos a ele, e faremos morada com ele."}, {"numero": 24, "texto": "Quem não me ama, não guarda minhas palavras. E a palavra que ouvis não é minha, mas sim do Pai que me enviou."}, {"numero": 25, "texto": "Estas coisas tenho dito a vós, estando [ainda] convosco."}, {"numero": 26, "texto": "Mas aquele Consolador, o Espírito Santo, ao qual o Pai enviará em meu nome, esse vos ensinará tudo, e tudo quanto tenho dito vós, [ele] vos fará lembrar."}, {"numero": 27, "texto": "A paz vos deixo, minha paz vos dou; vou dá- [la] a vós, não como o mundo [a] dá. Não se perturbe vosso coração, nem se atemorize."}, {"numero": 28, "texto": "Já ouvistes que vos tenho dito: Vou, e venho a vós. Se me amásseis, verdadeiramente vos alegraríeis, porque tenho dito: Vou ao Pai; pois meu Pai maior é que eu."}, {"numero": 29, "texto": "E já agora o disse a vós antes que aconteça, para que quando acontecer, [o] creiais."}, {"numero": 30, "texto": "Já não falarei muito convosco; pois o príncipe deste mundo já vem, e ele nada tem em mim."}, {"numero": 31, "texto": "Mas para que o mundo saiba que eu amo ao Pai, e assim faço como o Pai me mandou; levantai-vos, vamos embora daqui."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 14, 'en', '[{"numero": 1, "texto": "Let not your heart be troubled: ye believe in God, believe also in me."}, {"numero": 2, "texto": "In my Father''s house are many mansions: if it were not so, I would have told you. I go to prepare a place for you."}, {"numero": 3, "texto": "And if I go and prepare a place for you, I will come again, and receive you unto myself; that where I am, there ye may be also."}, {"numero": 4, "texto": "And whither I go ye know, and the way ye know."}, {"numero": 5, "texto": "Thomas saith unto him, Lord, we know not whither thou goest; and how can we know the way?"}, {"numero": 6, "texto": "Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me."}, {"numero": 7, "texto": "If ye had known me, ye should have known my Father also: and from henceforth ye know him, and have seen him."}, {"numero": 8, "texto": "Philip saith unto him, Lord, show us the Father, and it sufficeth us."}, {"numero": 9, "texto": "Jesus saith unto him, Have I been so long time with you, and yet hast thou not known me, Philip? he that hath seen me hath seen the Father; and how sayest thou then, Show us the Father?"}, {"numero": 10, "texto": "Believest thou not that I am in the Father, and the Father in me? the words that I speak unto you I speak not of myself: but the Father that dwelleth in me, he doeth the works."}, {"numero": 11, "texto": "Believe me that I am in the Father, and the Father in me: or else believe me for the very works'' sake."}, {"numero": 12, "texto": "Verily, verily, I say unto you, He that believeth on me, the works that I do shall he do also; and greater works than these shall he do; because I go unto my Father."}, {"numero": 13, "texto": "And whatsoever ye shall ask in my name, that will I do, that the Father may be glorified in the Son."}, {"numero": 14, "texto": "If ye shall ask any thing in my name, I will do it."}, {"numero": 15, "texto": "If ye love me, keep my commandments."}, {"numero": 16, "texto": "And I will pray the Father, and he shall give you another Comforter, that he may abide with you for ever;"}, {"numero": 17, "texto": "Even the Spirit of truth; whom the world cannot receive, because it seeth him not, neither knoweth him: but ye know him; for he dwelleth with you, and shall be in you."}, {"numero": 18, "texto": "I will not leave you comfortless: I will come to you."}, {"numero": 19, "texto": "Yet a little while, and the world seeth me no more; but ye see me: because I live, ye shall live also."}, {"numero": 20, "texto": "At that day ye shall know that I am in my Father, and ye in me, and I in you."}, {"numero": 21, "texto": "He that hath my commandments, and keepeth them, he it is that loveth me: and he that loveth me shall be loved of my Father, and I will love him, and will manifest myself to him."}, {"numero": 22, "texto": "Judas saith unto him, not Iscariot, Lord, how is it that thou wilt manifest thyself unto us, and not unto the world?"}, {"numero": 23, "texto": "Jesus answered and said unto him, If a man love me, he will keep my words: and my Father will love him, and we will come unto him, and make our abode with him."}, {"numero": 24, "texto": "He that loveth me not keepeth not my sayings: and the word which ye hear is not mine, but the Father''s which sent me."}, {"numero": 25, "texto": "These things have I spoken unto you, being yet present with you."}, {"numero": 26, "texto": "But the Comforter, which is the Holy Ghost, whom the Father will send in my name, he shall teach you all things, and bring all things to your remembrance, whatsoever I have said unto you."}, {"numero": 27, "texto": "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid."}, {"numero": 28, "texto": "Ye have heard how I said unto you, I go away, and come again unto you. If ye loved me, ye would rejoice, because I said, I go unto the Father: for my Father is greater than I."}, {"numero": 29, "texto": "And now I have told you before it come to pass, that, when it is come to pass, ye might believe."}, {"numero": 30, "texto": "Hereafter I will not talk much with you: for the prince of this world cometh, and hath nothing in me."}, {"numero": 31, "texto": "But that the world may know that I love the Father; and as the Father gave me commandment, even so I do. Arise, let us go hence."}]'::jsonb, 'King James Version'),
  ('Jo', 14, 'fr', '[{"numero": 1, "texto": "Que votre coeur ne se trouble point. Croyez en Dieu, et croyez en moi."}, {"numero": 2, "texto": "Il y a plusieurs demeures dans la maison de mon Père. Si cela n''''était pas, je vous l''''aurais dit. Je vais vous préparer une place."}, {"numero": 3, "texto": "Et, lorsque je m''''en serai allé, et que je vous aurai préparé une place, je reviendrai, et je vous prendrai avec moi, afin que là où je suis vous y soyez aussi."}, {"numero": 4, "texto": "Vous savez où je vais, et vous en savez le chemin."}, {"numero": 5, "texto": "Thomas lui dit: Seigneur, nous ne savons où tu vas; comment pouvons-nous en savoir le chemin?"}, {"numero": 6, "texto": "Jésus lui dit: Je suis le chemin, la vérité, et la vie. Nul ne vient au Père que par moi."}, {"numero": 7, "texto": "Si vous me connaissiez, vous connaîtriez aussi mon Père. Et dès maintenant vous le connaissez, et vous l''''avez vu."}, {"numero": 8, "texto": "Philippe lui dit: Seigneur, montre-nous le Père, et cela nous suffit."}, {"numero": 9, "texto": "Jésus lui dit: Il y a si longtemps que je suis avec vous, et tu ne m''''as pas connu, Philippe! Celui qui m''''a vu a vu le Père; comment dis-tu: Montre-nous le Père?"}, {"numero": 10, "texto": "Ne crois-tu pas que je suis dans le Père, et que le Père est en moi? Les paroles que je vous dis, je ne les dis pas de moi-même; et le Père qui demeure en moi, c''''est lui qui fait les oeuvres."}, {"numero": 11, "texto": "Croyez-moi, je suis dans le Père, et le Père est en moi; croyez du moins à cause de ces oeuvres."}, {"numero": 12, "texto": "En vérité, en vérité, je vous le dis, celui qui croit en moi fera aussi les oeuvres que je fais, et il en fera de plus grandes, parce que je m''''en vais au Père;"}, {"numero": 13, "texto": "et tout ce que vous demanderez en mon nom, je le ferai, afin que le Père soit glorifié dans le Fils."}, {"numero": 14, "texto": "Si vous demandez quelque chose en mon nom, je le ferai."}, {"numero": 15, "texto": "Si vous m''''aimez, gardez mes commandements."}, {"numero": 16, "texto": "Et moi, je prierai le Père, et il vous donnera un autre consolateur, afin qu''''il demeure éternellement avec vous,"}, {"numero": 17, "texto": "l''''Esprit de vérité, que le monde ne peut recevoir, parce qu''''il ne le voit point et ne le connaît point; mais vous, vous le connaissez, car il demeure avec vous, et il sera en vous."}, {"numero": 18, "texto": "Je ne vous laisserai pas orphelins, je viendrai à vous."}, {"numero": 19, "texto": "Encore un peu de temps, et le monde ne me verra plus; mais vous, vous me verrez, car je vis, et vous vivrez aussi."}, {"numero": 20, "texto": "En ce jour-là, vous connaîtrez que je suis en mon Père, que vous êtes en moi, et que je suis en vous."}, {"numero": 21, "texto": "Celui qui a mes commandements et qui les garde, c''''est celui qui m''''aime; et celui qui m''''aime sera aimé de mon Père, je l''''aimerai, et je me ferai connaître à lui."}, {"numero": 22, "texto": "Jude, non pas l''''Iscariot, lui dit: Seigneur, d''''où vient que tu te feras connaître à nous, et non au monde?"}, {"numero": 23, "texto": "Jésus lui répondit: Si quelqu''''un m''''aime, il gardera ma parole, et mon Père l''''aimera; nous viendrons à lui, et nous ferons notre demeure chez lui."}, {"numero": 24, "texto": "Celui qui ne m''''aime pas ne garde point mes paroles. Et la parole que vous entendez n''''est pas de moi, mais du Père qui m''''a envoyé."}, {"numero": 25, "texto": "Je vous ai dit ces choses pendant que je demeure avec vous."}, {"numero": 26, "texto": "Mais le consolateur, l''''Esprit-Saint, que le Père enverra en mon nom, vous enseignera toutes choses, et vous rappellera tout ce que je vous ai dit."}, {"numero": 27, "texto": "Je vous laisse la paix, je vous donne ma paix. Je ne vous donne pas comme le monde donne. Que votre coeur ne se trouble point, et ne s''''alarme point."}, {"numero": 28, "texto": "Vous avez entendu que je vous ai dit: Je m''''en vais, et je reviens vers vous. Si vous m''''aimiez, vous vous réjouiriez de ce que je vais au Père; car le Père est plus grand que moi."}, {"numero": 29, "texto": "Et maintenant je vous ai dit ces choses avant qu''''elles arrivent, afin que, lorsqu''''elles arriveront, vous croyiez."}, {"numero": 30, "texto": "Je ne parlerai plus guère avec vous; car le prince du monde vient. Il n''''a rien en moi;"}, {"numero": 31, "texto": "mais afin que le monde sache que j''''aime le Père, et que j''''agis selon l''''ordre que le Père m''''a donné, levez-vous, partons d''''ici."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 14, 'es', '[{"numero": 1, "texto": "NO se turbe vuestro corazón: creéis en Dios, creed también en mí."}, {"numero": 2, "texto": "En la casa de mi Padre muchas moradas hay: de otra manera os lo hubiera dicho: voy, pues, á preparar lugar para vosotros."}, {"numero": 3, "texto": "Y si me fuere, y os aparejare lugar, vendré otra vez, y os tomaré á mí mismo: para que donde yo estoy, vosotros también estéis."}, {"numero": 4, "texto": "Y sabéis á dónde yo voy; y sabéis el camino."}, {"numero": 5, "texto": "Dícele Tomás: Señor, no sabemos á dónde vas: ¿cómo, pues, podemos saber el camino?"}, {"numero": 6, "texto": "Jesús le dice: Yo soy el camino, y la verdad, y la vida: nadie viene al Padre, sino por mí."}, {"numero": 7, "texto": "Si me conocieseis, también á mi Padre conocierais: y desde ahora le conocéis, y le habéis visto."}, {"numero": 8, "texto": "Dícele Felipe: Señor, muéstranos el Padre, y nos basta."}, {"numero": 9, "texto": "Jesús le dice: ¿Tanto tiempo ha que estoy con vosotros, y no me has conocido, Felipe? El que me ha visto, ha visto al Padre; ¿cómo, pues, dices tú: Muéstranos el Padre?"}, {"numero": 10, "texto": "¿No crees que yo soy en el Padre, y el Padre en mí? Las palabras que yo os hablo, no las hablo de mí mismo: mas el Padre que está en mí, él hace las obras."}, {"numero": 11, "texto": "Creedme que yo soy en el Padre, y el Padre en mí: de otra manera, creedme por las mismas obras."}, {"numero": 12, "texto": "De cierto, de cierto os digo: El que en mí cree, las obras que yo hago también él las hará; y mayores que éstas hará; porque yo voy al Padre."}, {"numero": 13, "texto": "Y todo lo que pidiereis al Padre en mi nombre, esto haré, para que el Padre sea glorificado en el Hijo."}, {"numero": 14, "texto": "Si algo pidiereis en mi nombre, yo lo haré."}, {"numero": 15, "texto": "Si me amáis, guardad mis mandamientos;"}, {"numero": 16, "texto": "Y yo rogaré al Padre, y os dará otro Consolador, para que esté con vosotros para siempre:"}, {"numero": 17, "texto": "Al Espíritu de verdad, al cual el mundo no puede recibir, porque no le ve, ni le conoce: mas vosotros le conocéis; porque está con vosotros, y será en vosotros."}, {"numero": 18, "texto": "No os dejaré huérfanos: vendré á vosotros."}, {"numero": 19, "texto": "Aun un poquito, y el mundo no me verá más; empero vosotros me veréis; porque yo vivo, y vosotros también viviréis."}, {"numero": 20, "texto": "En aquel día vosotros conoceréis que yo estoy en mi Padre, y vosotros en mí, y yo en vosotros."}, {"numero": 21, "texto": "El que tiene mis mandamientos, y los guarda, aquél es el que me ama; y el que me ama, será amado de mi Padre, y yo le amaré, y me manifestaré á él."}, {"numero": 22, "texto": "Dícele Judas, no el Iscariote: Señor, ¿qué hay porque te hayas de manifestar á nosotros, y no al mundo?"}, {"numero": 23, "texto": "Respondió Jesús, y díjole: El que me ama, mi palabra guardará; y mi Padre le amará, y vendremos á él, y haremos con él morada."}, {"numero": 24, "texto": "El que no me ama, no guarda mis palabras: y la palabra que habéis oído, no es mía, sino del Padre que me envió."}, {"numero": 25, "texto": "Estas cosas os he hablado estando con vosotros."}, {"numero": 26, "texto": "Mas el Consolador, el Espíritu Santo, al cual el Padre enviará en mi nombre, él os enseñará todas las cosas, y os recordará todas las cosas que os he dicho."}, {"numero": 27, "texto": "La paz os dejo, mi paz os doy: no como el mundo la da, yo os la doy. No se turbe vuestro corazón, ni tenga miedo."}, {"numero": 28, "texto": "Habéis oído cómo yo os he dicho: Voy, y vengo á vosotros. Si me amaseis, ciertamente os gozaríais, porque he dicho que voy al Padre: porque el Padre mayor es que yo."}, {"numero": 29, "texto": "Y ahora os lo he dicho antes que se haga; para que cuando se hiciere, creáis."}, {"numero": 30, "texto": "Ya no hablaré mucho con vosotros: porque viene el príncipe de este mundo; mas no tiene nada en mí."}, {"numero": 31, "texto": "Empero para que conozca el mundo que amo al Padre, y como el Padre me dió el mandamiento, así hago. Levantaos, vamos de aquí."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 15, 'pt', '[{"numero": 1, "texto": "Eu sou a videira verdadeira, e meu Pai é o lavrador."}, {"numero": 2, "texto": "Todo ramo que em mim não dá fruto, ele o tira; e todo o que da fruto, ele o limpa, para que dê mais fruto."}, {"numero": 3, "texto": "Vós já estais limpos pela palavra que vos tenho falado."}, {"numero": 4, "texto": "Estai em mim, e eu em vós; como o ramo de si mesmo não pode dar fruto, se não estiver na videira, assim vós também não, se não estiverdes em mim."}, {"numero": 5, "texto": "Eu sou a videira, vós [sois] os ramos; quem está em mim, e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer."}, {"numero": 6, "texto": "Se alguém não estiver em mim, é lançado fora, como o ramo, e seca-se; e os colhem , e os lançam no fogo, e ardem."}, {"numero": 7, "texto": "Se vós estiverdes em mim, e minhas palavras estiverem em vós, tudo o que quiserdes pedireis, e será feito para vós."}, {"numero": 8, "texto": "Nisto é glorificado meu Pai, em que deis muito fruto; e [assim] sereis meus discípulos."}, {"numero": 9, "texto": "Como o Pai me amou, também eu vos amei; estai neste meu amor."}, {"numero": 10, "texto": "Se guardardes meus mandamentos, estareis em meu amor. Como eu tenho guardado os mandamentos de meu Pai, e estou em seu amor."}, {"numero": 11, "texto": "Estas coisas eu tenho vos dito para que minha alegria esteja em vós, e vossa alegria seja completa."}, {"numero": 12, "texto": "Este é meu mandamento: que vos ameis uns aos outros, assim como eu vos amei."}, {"numero": 13, "texto": "Ninguém tem maior amor que este: que alguém ponha sua vida por seus amigos."}, {"numero": 14, "texto": "Vós sois meus amigos, se fizerdes o que eu vos mando."}, {"numero": 15, "texto": "Já não vos chamo mais servos; porque o servo não sabe o que faz seu senhor; mas eu tenho vos chamado de amigos, porque tudo quanto ouvi de meu Pai eu tenho vos feito conhecer."}, {"numero": 16, "texto": "Não [fostes] vós [que] me escolhestes, porém eu vos escolhi, e tenho vos posto para que vades, e deis fruto, e vosso fruto permaneça; para que tudo quanto pedirdes ao Pai em meu nome, ele vos dê."}, {"numero": 17, "texto": "Isto vos mando, para que vos ameis uns aos outros."}, {"numero": 18, "texto": "Se o mundo vos odeia, sabei que odiou a mim antes que a vós."}, {"numero": 19, "texto": "Se vós fôsseis do mundo, o mundo amaria ao seu; mas porque não sois do mundo, antes eu vos escolhi do mundo, por isso o mundo vos odeia."}, {"numero": 20, "texto": "Lembrai-vos da palavra que vos tenho dito: não é o servo maior que seu senhor. Se me perseguiram, também vos perseguirão; se guardaram minha palavra, também guardarão a vossa."}, {"numero": 21, "texto": "Mas tudo isto vos farão por causa do meu nome; porque não conhecem a aquele que me enviou."}, {"numero": 22, "texto": "Se eu não tivesse vindo, nem lhes houvesse falado, não teriam pecado; mas agora já não têm pretexto pelo seu pecado."}, {"numero": 23, "texto": "Quem me odeia, também odeia a meu Pai."}, {"numero": 24, "texto": "Se eu entre eles não tivesse feito obras, que nenhum outro fizera, não teriam pecado; mas agora as viram, e [contudo] odiaram a mim, e a meu Pai."}, {"numero": 25, "texto": "Mas [isto é] para que se cumpra a palavra que está escrita em sua Lei: Sem causa me odiaram."}, {"numero": 26, "texto": "Mas quando vier o Consolador, que eu do Pai vos enviarei, aquele Espírito de verdade, que sai do Pai, ele testemunhará de mim."}, {"numero": 27, "texto": "E também vós testemunhareis, pois estivestes comigo desde o princípio."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 15, 'en', '[{"numero": 1, "texto": "I am the true vine, and my Father is the husbandman."}, {"numero": 2, "texto": "Every branch in me that beareth not fruit he taketh away: and every branch that beareth fruit, he purgeth it, that it may bring forth more fruit."}, {"numero": 3, "texto": "Now ye are clean through the word which I have spoken unto you."}, {"numero": 4, "texto": "Abide in me, and I in you. As the branch cannot bear fruit of itself, except it abide in the vine; no more can ye, except ye abide in me."}, {"numero": 5, "texto": "I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing."}, {"numero": 6, "texto": "If a man abide not in me, he is cast forth as a branch, and is withered; and men gather them, and cast them into the fire, and they are burned."}, {"numero": 7, "texto": "If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you."}, {"numero": 8, "texto": "Herein is my Father glorified, that ye bear much fruit; so shall ye be my disciples."}, {"numero": 9, "texto": "As the Father hath loved me, so have I loved you: continue ye in my love."}, {"numero": 10, "texto": "If ye keep my commandments, ye shall abide in my love; even as I have kept my Father''s commandments, and abide in his love."}, {"numero": 11, "texto": "These things have I spoken unto you, that my joy might remain in you, and that your joy might be full."}, {"numero": 12, "texto": "This is my commandment, That ye love one another, as I have loved you."}, {"numero": 13, "texto": "Greater love hath no man than this, that a man lay down his life for his friends."}, {"numero": 14, "texto": "Ye are my friends, if ye do whatsoever I command you."}, {"numero": 15, "texto": "Henceforth I call you not servants; for the servant knoweth not what his lord doeth: but I have called you friends; for all things that I have heard of my Father I have made known unto you."}, {"numero": 16, "texto": "Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you."}, {"numero": 17, "texto": "These things I command you, that ye love one another."}, {"numero": 18, "texto": "If the world hate you, ye know that it hated me before it hated you."}, {"numero": 19, "texto": "If ye were of the world, the world would love his own: but because ye are not of the world, but I have chosen you out of the world, therefore the world hateth you."}, {"numero": 20, "texto": "Remember the word that I said unto you, The servant is not greater than his lord. If they have persecuted me, they will also persecute you; if they have kept my saying, they will keep yours also."}, {"numero": 21, "texto": "But all these things will they do unto you for my name''s sake, because they know not him that sent me."}, {"numero": 22, "texto": "If I had not come and spoken unto them, they had not had sin: but now they have no cloak for their sin."}, {"numero": 23, "texto": "He that hateth me hateth my Father also."}, {"numero": 24, "texto": "If I had not done among them the works which none other man did, they had not had sin: but now have they both seen and hated both me and my Father."}, {"numero": 25, "texto": "But this cometh to pass, that the word might be fulfilled that is written in their law, They hated me without a cause."}, {"numero": 26, "texto": "But when the Comforter is come, whom I will send unto you from the Father, even the Spirit of truth, which proceedeth from the Father, he shall testify of me:"}, {"numero": 27, "texto": "And ye also shall bear witness, because ye have been with me from the beginning."}]'::jsonb, 'King James Version'),
  ('Jo', 15, 'fr', '[{"numero": 1, "texto": "Je suis le vrai cep, et mon Père est le vigneron."}, {"numero": 2, "texto": "Tout sarment qui est en moi et qui ne porte pas de fruit, il le retranche; et tout sarment qui porte du fruit, il l''''émonde, afin qu''''il porte encore plus de fruit."}, {"numero": 3, "texto": "Déjà vous êtes purs, à cause de la parole que je vous ai annoncée."}, {"numero": 4, "texto": "Demeurez en moi, et je demeurerai en vous. Comme le sarment ne peut de lui-même porter du fruit, s''''il ne demeure attaché au cep, ainsi vous ne le pouvez non plus, si vous ne demeurez en moi."}, {"numero": 5, "texto": "Je suis le cep, vous êtes les sarments. Celui qui demeure en moi et en qui je demeure porte beaucoup de fruit, car sans moi vous ne pouvez rien faire."}, {"numero": 6, "texto": "Si quelqu''''un ne demeure pas en moi, il est jeté dehors, comme le sarment, et il sèche; puis on ramasse les sarments, on les jette au feu, et ils brûlent."}, {"numero": 7, "texto": "Si vous demeurez en moi, et que mes paroles demeurent en vous, demandez ce que vous voudrez, et cela vous sera accordé."}, {"numero": 8, "texto": "Si vous portez beaucoup de fruit, c''''est ainsi que mon Père sera glorifié, et que vous serez mes disciples."}, {"numero": 9, "texto": "Comme le Père m''''a aimé, je vous ai aussi aimés. Demeurez dans mon amour."}, {"numero": 10, "texto": "Si vous gardez mes commandements, vous demeurerez dans mon amour, de même que j''''ai gardé les commandements de mon Père, et que je demeure dans son amour."}, {"numero": 11, "texto": "Je vous ai dit ces choses, afin que ma joie soit en vous, et que votre joie soit parfaite."}, {"numero": 12, "texto": "C''''est ici mon commandement: Aimez-vous les uns les autres, comme je vous ai aimés."}, {"numero": 13, "texto": "Il n''''y a pas de plus grand amour que de donner sa vie pour ses amis."}, {"numero": 14, "texto": "Vous êtes mes amis, si vous faites ce que je vous commande."}, {"numero": 15, "texto": "Je ne vous appelle plus serviteurs, parce que le serviteur ne sait pas ce que fait son maître; mais je vous ai appelés amis, parce que je vous ai fait connaître tout ce que j''''ai appris de mon Père."}, {"numero": 16, "texto": "Ce n''''est pas vous qui m''''avez choisi; mais moi, je vous ai choisis, et je vous ai établis, afin que vous alliez, et que vous portiez du fruit, et que votre fruit demeure, afin que ce que vous demanderez au Père en mon nom, il vous le donne."}, {"numero": 17, "texto": "Ce que je vous commande, c''''est de vous aimer les uns les autres."}, {"numero": 18, "texto": "Si le monde vous hait, sachez qu''''il m''''a haï avant vous."}, {"numero": 19, "texto": "Si vous étiez du monde, le monde aimerait ce qui est à lui; mais parce que vous n''''êtes pas du monde, et que je vous ai choisis du milieu du monde, à cause de cela le monde vous hait."}, {"numero": 20, "texto": "Souvenez-vous de la parole que je vous ai dite: Le serviteur n''''est pas plus grand que son maître. S''''ils m''''ont persécuté, ils vous persécuteront aussi; s''''ils ont gardé ma parole, ils garderont aussi la vôtre."}, {"numero": 21, "texto": "Mais ils vous feront toutes ces choses à cause de mon nom, parce qu''''ils ne connaissent pas celui qui m''''a envoyé."}, {"numero": 22, "texto": "Si je n''''étais pas venu et que je ne leur eusse point parlé, ils n''''auraient pas de péché; mais maintenant ils n''''ont aucune excuse de leur péché."}, {"numero": 23, "texto": "Celui qui me hait, hait aussi mon Père."}, {"numero": 24, "texto": "Si je n''''avais pas fait parmi eux des oeuvres que nul autre n''''a faites, ils n''''auraient pas de péché; mais maintenant ils les ont vues, et ils ont haï et moi et mon Père."}, {"numero": 25, "texto": "Mais cela est arrivé afin que s''''accomplît la parole qui est écrite dans leur loi: Ils m''''ont haï sans cause."}, {"numero": 26, "texto": "Quand sera venu le consolateur, que je vous enverrai de la part du Père, l''''Esprit de vérité, qui vient du Père, il rendra témoignage de moi;"}, {"numero": 27, "texto": "et vous aussi, vous rendrez témoignage, parce que vous êtes avec moi dès le commencement."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 15, 'es', '[{"numero": 1, "texto": "YO soy la vid verdadera, y mi Padre es el labrador."}, {"numero": 2, "texto": "Todo pámpano que en mí no lleva fruto, le quitará: y todo aquel que lleva fruto, le limpiará, para que lleve más fruto."}, {"numero": 3, "texto": "Ya vosotros sois limpios por la palabra que os he hablado."}, {"numero": 4, "texto": "Estad en mí, y yo en vosotros. Como el pámpano no puede llevar fruto de sí mismo, si no estuviere en la vid; así ni vosotros, si no estuviereis en mí."}, {"numero": 5, "texto": "Yo soy la vid, vosotros los pámpanos: el que está en mí, y yo en él, éste lleva mucho fruto; porque sin mí nada podéis hacer."}, {"numero": 6, "texto": "El que en mí no estuviere, será echado fuera como mal pámpano, y se secará; y los cogen, y los echan en el fuego, y arden."}, {"numero": 7, "texto": "Si estuviereis en mí, y mis palabras estuvieren en vosotros, pedid todo lo que quisiereis, y os será hecho."}, {"numero": 8, "texto": "En esto es glorificado mi Padre, en que llevéis mucho fruto, y seáis así mis discípulos."}, {"numero": 9, "texto": "Como el Padre me amó, también yo os he amado: estad en mi amor."}, {"numero": 10, "texto": "Si guardareis mis mandamientos, estaréis en mi amor; como yo también he guardado los mandamientos de mi Padre, y estoy en su amor."}, {"numero": 11, "texto": "Estas cosas os he hablado, para que mi gozo esté en vosotros, y vuestro gozo sea cumplido."}, {"numero": 12, "texto": "Este es mi mandamiento: Que os améis los unos á los otros, como yo os he amado."}, {"numero": 13, "texto": "Nadie tiene mayor amor que este, que ponga alguno su vida por sus amigos."}, {"numero": 14, "texto": "Vosotros sois mis amigos, si hiciereis las cosas que yo os mando."}, {"numero": 15, "texto": "Ya no os llamaré siervos, porque el siervo no sabe lo que hace su señor: mas os he llamado amigos, porque todas las cosas que oí de mi Padre, os he hecho notorias."}, {"numero": 16, "texto": "No me elegisteis vosotros á mí, mas yo os elegí á vosotros; y os he puesto para que vayáis y llevéis fruto, y vuestro fruto permanezca: para que todo lo que pidiereis del Padre en mi nombre, él os lo dé."}, {"numero": 17, "texto": "Esto os mando: Que os améis los unos á los otros."}, {"numero": 18, "texto": "Si el mundo os aborrece, sabed que á mí me aborreció antes que á vosotros."}, {"numero": 19, "texto": "Si fuerais del mundo, el mundo amaría lo suyo; mas porque no sois del mundo, antes yo os elegí del mundo, por eso os aborrece el mundo."}, {"numero": 20, "texto": "Acordaos de la palabra que yo os he dicho: No es el siervo mayor que su señor. Si á mí me han perseguido, también á vosotros perseguirán: si han guardado mi palabra, también guardarán la vuestra."}, {"numero": 21, "texto": "Mas todo esto os harán por causa de mi nombre, porque no conocen al que me ha enviado."}, {"numero": 22, "texto": "Si no hubiera venido, ni les hubiera hablado, no tendrían pecado, mas ahora no tienen excusa de su pecado."}, {"numero": 23, "texto": "El que me aborrece, también á mi Padre aborrece."}, {"numero": 24, "texto": "Si no hubiese hecho entre ellos obras cuales ningún otro ha hecho, no tendrían pecado; mas ahora, y las han visto, y me aborrecen á mí y á mi Padre."}, {"numero": 25, "texto": "Mas para que se cumpla la palabra que está escrita en su ley: Que sin causa me aborrecieron."}, {"numero": 26, "texto": "Empero cuando viniere el Consolador, el cual yo os enviaré del Padre, el Espíritu de verdad, el cual procede del Padre, él dará testimonio de mí."}, {"numero": 27, "texto": "Y vosotros daréis testimonio, porque estáis conmigo desde el principio."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 16, 'pt', '[{"numero": 1, "texto": "Estas coisas tenho vos dito para que não tropeceis na fé."}, {"numero": 2, "texto": "Expulsarão a vós das sinagogas; mas a hora vem, quando qualquer que vos matar, pensará fazer serviço a Deus."}, {"numero": 3, "texto": "E estas coisas vos farão, porque nem ao Pai, nem a mim me conheceram."}, {"numero": 4, "texto": "Porém tenho vos dito isto para que, quando aquela hora vier, disso vos lembreis, que já o dissera a vós; mas isto eu não vos disse desde o princípio, porque eu estava convosco."}, {"numero": 5, "texto": "E agora vou para aquele que me enviou; e nenhum de vós me pergunta: Para onde vais?"}, {"numero": 6, "texto": "Porém, porque vos disse estas coisas, a tristeza encheu vosso coração."}, {"numero": 7, "texto": "Mas vos digo a verdade, que vos convém que eu vá; porque se eu não for, o Consolador não virá a vós; porém se eu for, eu o enviarei a vós."}, {"numero": 8, "texto": "E vindo ele, convencerá ao mundo do pecado, e da justiça, e do juízo."}, {"numero": 9, "texto": "Do pecado, porque não creem em mim;"}, {"numero": 10, "texto": "E da justiça, porque vou para meu Pai, e não me vereis mais;"}, {"numero": 11, "texto": "E do juízo, porque o Príncipe deste mundo já está julgado."}, {"numero": 12, "texto": "Ainda tenho muitas coisas que vos dizer, mas agora [ainda] não podeis suportá-las."}, {"numero": 13, "texto": "Porém quando vier aquele Espírito de verdade, ele vos guiará em toda verdade. Porque de si mesmo não falará; mas falará tudo o que ouvir; E ele vos anunciará as coisas que virão."}, {"numero": 14, "texto": "Ele me glorificará, porque tomará do [que é] meu, e vos anunciará."}, {"numero": 15, "texto": "Tudo quanto tem o Pai é meu; por isso eu disse, que tomará do [que é] meu, e vos anunciará."}, {"numero": 16, "texto": "Um pouco, e não me vereis; e mais um pouco, e me vereis; porque vou ao Pai."}, {"numero": 17, "texto": "Disseram pois [alguns] de seus discípulos uns aos outros: Que é isto que ele nos diz: Um pouco, e não me vereis; e mais um pouco, e me vereis; e porque vou ao Pai?"}, {"numero": 18, "texto": "Então diziam: Que é isto que ele diz? Um pouco? Não sabemos o que diz."}, {"numero": 19, "texto": "Conheceu pois Jesus que lhe queriam perguntar, e disse-lhes: Perguntais entre vós sobre isto que disse: Um pouco, e não me vereis; e mais um pouco, e me vereis?"}, {"numero": 20, "texto": "Em verdade, em verdade vos digo, que vós chorareis, e lamentareis, e o mundo se alegrará, e vós estareis tristes; mas vossa tristeza se tornará em alegria."}, {"numero": 21, "texto": "A mulher quando está no parto tem tristeza, porque sua hora é vinda; mas havendo nascido a criança, já não se lembra da aflição, pela alegria de um homem ter nascido no mundo."}, {"numero": 22, "texto": "Assim também vós agora na verdade tendes tristeza; mas novamente vos verei, e vosso coração se alegrará, e ninguém tirará vossa alegria de vós."}, {"numero": 23, "texto": "E naquele dia nada me perguntareis. Em verdade, em verdade vos digo, que tudo quanto pedirdes a meu Pai em meu nome, ele vos dará."}, {"numero": 24, "texto": "Até agora nada pedistes em meu nome; pedi, e recebereis, para que vossa alegria seja completa."}, {"numero": 25, "texto": "Estas coisas vos falei por parábolas; porém a hora vem quando não mais vos falarei por parábolas; mas vos falarei abertamente sobre o Pai."}, {"numero": 26, "texto": "Naquele dia pedireis em meu nome; e não vos digo, que eu suplicarei ao Pai por vós."}, {"numero": 27, "texto": "Pois o próprio Pai vos ama, porque vós me amastes, e crestes que eu saí de Deus."}, {"numero": 28, "texto": "Saí do Pai, e vim ao mundo; novamente deixo o mundo, e vou ao Pai."}, {"numero": 29, "texto": "Disseram-lhe seus Discípulos: Eis que agora falas abertamente, e nenhuma parábola dizes."}, {"numero": 30, "texto": "Agora sabemos que sabes todas as coisas; e não necessitas que ninguém te pergunte. Por isso cremos que saíste de Deus."}, {"numero": 31, "texto": "Respondeu-lhes Jesus: Agora credes?"}, {"numero": 32, "texto": "Eis que a hora vem, e já é chegada, quando sereis dispersos, cada um por si, e me deixareis só. Porém não estou só, porque o Pai está comigo."}, {"numero": 33, "texto": "Estas coisas tenho vos dito para que tenhais paz em mim; no mundo tereis aflição; mas tende bom ânimo; eu venci o mundo."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 16, 'en', '[{"numero": 1, "texto": "These things have I spoken unto you, that ye should not be offended."}, {"numero": 2, "texto": "They shall put you out of the synagogues: yea, the time cometh, that whosoever killeth you will think that he doeth God service."}, {"numero": 3, "texto": "And these things will they do unto you, because they have not known the Father, nor me."}, {"numero": 4, "texto": "But these things have I told you, that when the time shall come, ye may remember that I told you of them. And these things I said not unto you at the beginning, because I was with you."}, {"numero": 5, "texto": "But now I go my way to him that sent me; and none of you asketh me, Whither goest thou?"}, {"numero": 6, "texto": "But because I have said these things unto you, sorrow hath filled your heart."}, {"numero": 7, "texto": "Nevertheless I tell you the truth; It is expedient for you that I go away: for if I go not away, the Comforter will not come unto you; but if I depart, I will send him unto you."}, {"numero": 8, "texto": "And when he is come, he will reprove the world of sin, and of righteousness, and of judgment:"}, {"numero": 9, "texto": "Of sin, because they believe not on me;"}, {"numero": 10, "texto": "Of righteousness, because I go to my Father, and ye see me no more;"}, {"numero": 11, "texto": "Of judgment, because the prince of this world is judged."}, {"numero": 12, "texto": "I have yet many things to say unto you, but ye cannot bear them now."}, {"numero": 13, "texto": "Howbeit when he, the Spirit of truth, is come, he will guide you into all truth: for he shall not speak of himself; but whatsoever he shall hear, that shall he speak: and he will shew you things to come."}, {"numero": 14, "texto": "He shall glorify me: for he shall receive of mine, and shall shew it unto you."}, {"numero": 15, "texto": "All things that the Father hath are mine: therefore said I, that he shall take of mine, and shall shew it unto you."}, {"numero": 16, "texto": "A little while, and ye shall not see me: and again, a little while, and ye shall see me, because I go to the Father."}, {"numero": 17, "texto": "Then said some of his disciples among themselves, What is this that he saith unto us, A little while, and ye shall not see me: and again, a little while, and ye shall see me: and, Because I go to the Father?"}, {"numero": 18, "texto": "They said therefore, What is this that he saith, A little while? we cannot tell what he saith."}, {"numero": 19, "texto": "Now Jesus knew that they were desirous to ask him, and said unto them, Do ye enquire among yourselves of that I said, A little while, and ye shall not see me: and again, a little while, and ye shall see me?"}, {"numero": 20, "texto": "Verily, verily, I say unto you, That ye shall weep and lament, but the world shall rejoice: and ye shall be sorrowful, but your sorrow shall be turned into joy."}, {"numero": 21, "texto": "A woman when she is in travail hath sorrow, because her hour is come: but as soon as she is delivered of the child, she remembereth no more the anguish, for joy that a man is born into the world."}, {"numero": 22, "texto": "And ye now therefore have sorrow: but I will see you again, and your heart shall rejoice, and your joy no man taketh from you."}, {"numero": 23, "texto": "And in that day ye shall ask me nothing. Verily, verily, I say unto you, Whatsoever ye shall ask the Father in my name, he will give it you."}, {"numero": 24, "texto": "Hitherto have ye asked nothing in my name: ask, and ye shall receive, that your joy may be full."}, {"numero": 25, "texto": "These things have I spoken unto you in proverbs: but the time cometh, when I shall no more speak unto you in proverbs, but I shall shew you plainly of the Father."}, {"numero": 26, "texto": "At that day ye shall ask in my name: and I say not unto you, that I will pray the Father for you:"}, {"numero": 27, "texto": "For the Father himself loveth you, because ye have loved me, and have believed that I came out from God."}, {"numero": 28, "texto": "I came forth from the Father, and am come into the world: again, I leave the world, and go to the Father."}, {"numero": 29, "texto": "His disciples said unto him, Lo, now speakest thou plainly, and speakest no proverb."}, {"numero": 30, "texto": "Now are we sure that thou knowest all things, and needest not that any man should ask thee: by this we believe that thou camest forth from God."}, {"numero": 31, "texto": "Jesus answered them, Do ye now believe?"}, {"numero": 32, "texto": "Behold, the hour cometh, yea, is now come, that ye shall be scattered, every man to his own, and shall leave me alone: and yet I am not alone, because the Father is with me."}, {"numero": 33, "texto": "These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world."}]'::jsonb, 'King James Version'),
  ('Jo', 16, 'fr', '[{"numero": 1, "texto": "Je vous ai dit ces choses, afin qu''''elles ne soient pas pour vous une occasion de chute."}, {"numero": 2, "texto": "Ils vous excluront des synagogues; et même l''''heure vient où quiconque vous fera mourir croira rendre un culte à Dieu."}, {"numero": 3, "texto": "Et ils agiront ainsi, parce qu''''ils n''''ont connu ni le Père ni moi."}, {"numero": 4, "texto": "Je vous ai dit ces choses, afin que, lorsque l''''heure sera venue, vous vous souveniez que je vous les ai dites. Je ne vous en ai pas parlé dès le commencement, parce que j''''étais avec vous."}, {"numero": 5, "texto": "Maintenant je m''''en vais vers celui qui m''''a envoyé, et aucun de vous ne me demande: Où vas-tu?"}, {"numero": 6, "texto": "Mais, parce que je vous ai dit ces choses, la tristesse a rempli votre coeur."}, {"numero": 7, "texto": "Cependant je vous dis la vérité: il vous est avantageux que je m''''en aille, car si je ne m''''en vais pas, le consolateur ne viendra pas vers vous; mais, si je m''''en vais, je vous l''''enverrai."}, {"numero": 8, "texto": "Et quand il sera venu, il convaincra le monde en ce qui concerne le péché, la justice, et le jugement:"}, {"numero": 9, "texto": "en ce qui concerne le péché, parce qu''''ils ne croient pas en moi;"}, {"numero": 10, "texto": "la justice, parce que je vais au Père, et que vous ne me verrez plus;"}, {"numero": 11, "texto": "le jugement, parce que le prince de ce monde est jugé."}, {"numero": 12, "texto": "J''''ai encore beaucoup de choses à vous dire, mais vous ne pouvez pas les porter maintenant."}, {"numero": 13, "texto": "Quand le consolateur sera venu, l''''Esprit de vérité, il vous conduira dans toute la vérité; car il ne parlera pas de lui-même, mais il dira tout ce qu''''il aura entendu, et il vous annoncera les choses à venir."}, {"numero": 14, "texto": "Il me glorifiera, parce qu''''il prendra de ce qui est à moi, et vous l''''annoncera."}, {"numero": 15, "texto": "Tout ce que le Père a est à moi; c''''est pourquoi j''''ai dit qu''''il prend de ce qui est à moi, et qu''''il vous l''''annoncera."}, {"numero": 16, "texto": "Encore un peu de temps, et vous ne me verrez plus; et puis encore un peu de temps, et vous me verrez, parce que je vais au Père."}, {"numero": 17, "texto": "Là-dessus, quelques-uns de ses disciples dirent entre eux: Que signifie ce qu''''il nous dit: Encore un peu de temps, et vous ne me verrez plus; et puis encore un peu de temps, et vous me verrez? et: Parce que je vais au Père?"}, {"numero": 18, "texto": "Ils disaient donc: Que signifie ce qu''''il dit: Encore un peu de temps? Nous ne savons de quoi il parle."}, {"numero": 19, "texto": "Jésus, connut qu''''ils voulaient l''''interroger, leur dit: Vous vous questionnez les uns les autres sur ce que j''''ai dit: Encore un peu de temps, et vous ne me verrez plus; et puis encore un peu de temps, et vous me verrez."}, {"numero": 20, "texto": "En vérité, en vérité, je vous le dis, vous pleurerez et vous vous lamenterez, et le monde se réjouira: vous serez dans la tristesse, mais votre tristesse se changera en joie."}, {"numero": 21, "texto": "La femme, lorsqu''''elle enfante, éprouve de la tristesse, parce que son heure est venue; mais, lorsqu''''elle a donné le jour à l''''enfant, elle ne se souvient plus de la souffrance, à cause de la joie qu''''elle a de ce qu''''un homme est né dans le monde."}, {"numero": 22, "texto": "Vous donc aussi, vous êtes maintenant dans la tristesse; mais je vous reverrai, et votre coeur se réjouira, et nul ne vous ravira votre joie."}, {"numero": 23, "texto": "En ce jour-là, vous ne m''''interrogerez plus sur rien. En vérité, en vérité, je vous le dis, ce que vous demanderez au Père, il vous le donnera en mon nom."}, {"numero": 24, "texto": "Jusqu''''à présent vous n''''avez rien demandé en mon nom. Demandez, et vous recevrez, afin que votre joie soit parfaite."}, {"numero": 25, "texto": "Je vous ai dit ces choses en paraboles. L''''heure vient où je ne vous parlerai plus en paraboles, mais où je vous parlerai ouvertement du Père."}, {"numero": 26, "texto": "En ce jour, vous demanderez en mon nom, et je ne vous dis pas que je prierai le Père pour vous;"}, {"numero": 27, "texto": "car le Père lui-même vous aime, parce que vous m''''avez aimé, et que vous avez cru que je suis sorti de Dieu."}, {"numero": 28, "texto": "Je suis sorti du Père, et je suis venu dans le monde; maintenant je quitte le monde, et je vais au Père."}, {"numero": 29, "texto": "Ses disciples lui dirent: Voici, maintenant tu parles ouvertement, et tu n''''emploies aucune parabole."}, {"numero": 30, "texto": "Maintenant nous savons que tu sais toutes choses, et que tu n''''as pas besoin que personne t''''interroge; c''''est pourquoi nous croyons que tu es sorti de Dieu."}, {"numero": 31, "texto": "Jésus leur répondit: Vous croyez maintenant."}, {"numero": 32, "texto": "Voici, l''''heure vient, et elle est déjà venue, où vous serez dispersés chacun de son côté, et où vous me laisserez seul; mais je ne suis pas seul, car le Père est avec moi."}, {"numero": 33, "texto": "Je vous ai dit ces choses, afin que vous ayez la paix en moi. Vous aurez des tribulations dans le monde; mais prenez courage, j''''ai vaincu le monde."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 16, 'es', '[{"numero": 1, "texto": "ESTAS cosas os he hablado, para que no os escandalicéis."}, {"numero": 2, "texto": "Os echarán de las sinagogas; y aun viene la hora, cuando cualquiera que os matare, pensará que hace servicio á Dios."}, {"numero": 3, "texto": "Y estas cosas os harán, porque no conocen al Padre ni á mí."}, {"numero": 4, "texto": "Mas os he dicho esto, para que cuando aquella hora viniere, os acordéis que yo os lo había dicho. Esto empero no os lo dije al principio, porque yo estaba con vosotros."}, {"numero": 5, "texto": "Mas ahora voy al que me envió; y ninguno de vosotros me pregunta: ¿Adónde vas?"}, {"numero": 6, "texto": "Antes, porque os he hablado estas cosas, tristeza ha henchido vuestro corazón."}, {"numero": 7, "texto": "Empero yo os digo la verdad: Os es necesario que yo vaya: porque si yo no fuese, el Consolador no vendría á vosotros; mas si yo fuere, os le enviaré."}, {"numero": 8, "texto": "Y cuando él viniere redargüirá al mundo de pecado, y de justicia, y de juicio:"}, {"numero": 9, "texto": "De pecado ciertamente, por cuanto no creen en mí;"}, {"numero": 10, "texto": "Y de justicia, por cuanto voy al Padre, y no me veréis más;"}, {"numero": 11, "texto": "Y de juicio, por cuanto el príncipe de este mundo es juzgado."}, {"numero": 12, "texto": "Aun tengo muchas cosas que deciros, mas ahora no las podéis llevar."}, {"numero": 13, "texto": "Pero cuando viniere aquel Espíritu de verdad, él os guiará á toda verdad; porque no hablará de sí mismo, sino que hablará todo lo que oyere, y os hará saber las cosas que han de venir."}, {"numero": 14, "texto": "El me glorificará: porque tomará de lo mío, y os lo hará saber."}, {"numero": 15, "texto": "Todo lo que tiene el Padre, mío es: por eso dije que tomará de lo mío, y os lo hará saber."}, {"numero": 16, "texto": "Un poquito, y no me veréis; y otra vez un poquito, y me veréis: porque yo voy al Padre."}, {"numero": 17, "texto": "Entonces dijeron algunos de sus discípulos unos á otros: ¿Qué es esto que nos dice: Un poquito, y no me veréis; y otra vez un poquito, y me veréis: y, porque yo voy al Padre?"}, {"numero": 18, "texto": "Decían pues: ¿Qué es esto que dice: Un poquito? No entendemos lo que habla."}, {"numero": 19, "texto": "Y conoció Jesús que le querían preguntar, y díjoles: ¿Preguntáis entre vosotros de esto que dije: Un poquito, y no me veréis, y otra vez un poquito, y me veréis?"}, {"numero": 20, "texto": "De cierto, de cierto os digo, que vosotros lloraréis y lamentaréis, y el mundo se alegrará: empero aunque vosotros estaréis tristes, vuestra tristeza se tornará en gozo."}, {"numero": 21, "texto": "La mujer cuando pare, tiene dolor, porque es venida su hora; mas después que ha parido un niño, ya no se acuerda de la angustia, por el gozo de que haya nacido un hombre en el mundo."}, {"numero": 22, "texto": "También, pues, vosotros ahora ciertamente tenéis tristeza; mas otra vez os veré, y se gozará vuestro corazón, y nadie quitará de vosotros vuestro gozo."}, {"numero": 23, "texto": "Y aquel día no me preguntaréis nada. De cierto, de cierto os digo, que todo cuanto pidiereis al Padre en mi nombre, os lo dará."}, {"numero": 24, "texto": "Hasta ahora nada habéis pedido en mi nombre: pedid, y recibiréis, para que vuestro gozo sea cumplido."}, {"numero": 25, "texto": "Estas cosas os he hablado en proverbios: la hora viene cuando ya no os hablaré por proverbios, pero claramente os anunciaré del Padre."}, {"numero": 26, "texto": "Aquel día pediréis en mi nombre: y no os digo, que yo rogaré al Padre por vosotros;"}, {"numero": 27, "texto": "Pues el mismo Padre os ama, porque vosotros me amasteis, y habéis creído que yo salí de Dios."}, {"numero": 28, "texto": "Salí del Padre, y he venido al mundo: otra vez dejo el mundo, y voy al Padre."}, {"numero": 29, "texto": "Dícenle sus discípulos: He aquí, ahora hablas claramente, y ningún proverbio dices."}, {"numero": 30, "texto": "Ahora entendemos que sabes todas las cosas, y no necesitas que nadie te pregunte: en esto creemos que has salido de Dios."}, {"numero": 31, "texto": "Respondióles Jesús: ¿Ahora creéis?"}, {"numero": 32, "texto": "He aquí, la hora viene, y ha venido, que seréis esparcidos cada uno por su parte, y me dejaréis solo: mas no estoy solo, porque el Padre está conmigo."}, {"numero": 33, "texto": "Estas cosas os he hablado, para que en mí tengáis paz. En el mundo tendréis aflicción: mas confiad, yo he vencido al mundo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 17, 'pt', '[{"numero": 1, "texto": "Jesus falou estas coisas, levantou seus olhos ao céu, e disse: Pai, chegada é a hora; glorifica a teu Filho, para que também teu Filho glorifique a ti."}, {"numero": 2, "texto": "Assim como lhe deste poder sobre toda carne, para que a todos quantos lhe deste, lhes dê a vida eterna."}, {"numero": 3, "texto": "E esta é a vida eterna: que conheçam a ti, o único Deus verdadeiro, e a Jesus Cristo, a quem tens enviado."}, {"numero": 4, "texto": "Eu já te glorifiquei na terra; consumado tenho a obra que me deste para eu fazer."}, {"numero": 5, "texto": "E agora glorifica-me tu, ó Pai, junto de ti mesmo, com aquela glória que eu tinha junto de ti, antes que o mundo existisse."}, {"numero": 6, "texto": "Manifestei teu nome aos seres humanos que me deste do mundo. Eles eram teus, e tu os deste a mim; e eles guardaram tua palavra."}, {"numero": 7, "texto": "Agora eles sabem que tudo quanto me deste vem de ti."}, {"numero": 8, "texto": "Porque as palavras que tu me deste eu lhes dei; e eles [as] receberam, e verdadeiramente reconheceram que eu saí de ti, e creram que tu me enviaste."}, {"numero": 9, "texto": "Eu rogo por eles; não rogo pelo mundo, mas sim por aqueles que tu me deste, porque são teus."}, {"numero": 10, "texto": "E todas as minhas coisas são tuas; e as tuas coisas são minhas; e nelas sou glorificado."}, {"numero": 11, "texto": "E eu já não estou no mundo; porém estes [ainda] estão no mundo, e eu venho a ti. Pai Santo, guarda-os em teu nome, a aqueles que tens me dado, para que sejam um, como nós [somos] ."}, {"numero": 12, "texto": "Quando eu com eles estava no mundo, em teu nome eu os guardava. A aqueles que tu me deste eu os tenho guardado; e nenhum deles se perdeu, a não ser o filho da perdição, para que a Escritura se cumpra."}, {"numero": 13, "texto": "Mas agora venho a ti, e falo isto no mundo, para que em si mesmos tenham minha alegria completa."}, {"numero": 14, "texto": "Tua palavra lhes dei, e o mundo os odiou, porque não são do mundo, assim como eu não sou do mundo."}, {"numero": 15, "texto": "Não suplico que os tires do mundo, mas que os guardes do maligno."}, {"numero": 16, "texto": "Eles não são do mundo, assim como eu não sou do mundo."}, {"numero": 17, "texto": "Santifica-os em tua verdade; tua palavra é a verdade."}, {"numero": 18, "texto": "Assim como tu me enviaste, eu os enviei ao mundo."}, {"numero": 19, "texto": "E por eles a mim mesmo me santifico, para que também eles seja santificados em verdade."}, {"numero": 20, "texto": "E não suplico somente por estes, mas também por aqueles que crerão em mim, por sua palavra."}, {"numero": 21, "texto": "Para que todos sejam um; como tu, Pai, em mim, e eu em ti, que também eles em nós sejam um; para que o mundo creia que tu tens me enviado."}, {"numero": 22, "texto": "E eu tenho lhes dado a glória que tu me deste, para que sejam um, tal como nós somos um."}, {"numero": 23, "texto": "Eu neles, e tu em mim; para que sejam completos em um; e para que o mundo conheça que tu me enviaste, e que tu os amaste, assim como me amaste."}, {"numero": 24, "texto": "Pai, aqueles que tens me dado, quero que onde eu estiver, eles também estejam comigo; para que vejam minha glória, que tens me dado, pois tu me amaste desde antes da fundação do mundo."}, {"numero": 25, "texto": "Pai justo, o mundo também não tem te conhecido, e estes têm conhecido que tu me enviaste."}, {"numero": 26, "texto": "E eu fiz teu nome ser conhecido por eles, e eu farei com que seja conhecido, para que o amor com que me amaste esteja neles, e eu neles."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 17, 'en', '[{"numero": 1, "texto": "These words spake Jesus, and lifted up his eyes to heaven, and said, Father, the hour is come; glorify thy Son, that thy Son also may glorify thee:"}, {"numero": 2, "texto": "As thou hast given him power over all flesh, that he should give eternal life to as many as thou hast given him."}, {"numero": 3, "texto": "And this is life eternal, that they might know thee the only true God, and Jesus Christ, whom thou hast sent."}, {"numero": 4, "texto": "I have glorified thee on the earth: I have finished the work which thou gavest me to do."}, {"numero": 5, "texto": "And now, O Father, glorify thou me with thine own self with the glory which I had with thee before the world was."}, {"numero": 6, "texto": "I have manifested thy name unto the men which thou gavest me out of the world: thine they were, and thou gavest them me; and they have kept thy word."}, {"numero": 7, "texto": "Now they have known that all things whatsoever thou hast given me are of thee."}, {"numero": 8, "texto": "For I have given unto them the words which thou gavest me; and they have received them, and have known surely that I came out from thee, and they have believed that thou didst send me."}, {"numero": 9, "texto": "I pray for them: I pray not for the world, but for them which thou hast given me; for they are thine."}, {"numero": 10, "texto": "And all mine are thine, and thine are mine; and I am glorified in them."}, {"numero": 11, "texto": "And now I am no more in the world, but these are in the world, and I come to thee. Holy Father, keep through thine own name those whom thou hast given me, that they may be one, as we are."}, {"numero": 12, "texto": "While I was with them in the world, I kept them in thy name: those that thou gavest me I have kept, and none of them is lost, but the son of perdition; that the scripture might be fulfilled."}, {"numero": 13, "texto": "And now come I to thee; and these things I speak in the world, that they might have my joy fulfilled in themselves."}, {"numero": 14, "texto": "I have given them thy word; and the world hath hated them, because they are not of the world, even as I am not of the world."}, {"numero": 15, "texto": "I pray not that thou shouldest take them out of the world, but that thou shouldest keep them from the evil."}, {"numero": 16, "texto": "They are not of the world, even as I am not of the world."}, {"numero": 17, "texto": "Sanctify them through thy truth: thy word is truth."}, {"numero": 18, "texto": "As thou hast sent me into the world, even so have I also sent them into the world."}, {"numero": 19, "texto": "And for their sakes I sanctify myself, that they also might be sanctified through the truth."}, {"numero": 20, "texto": "Neither pray I for these alone, but for them also which shall believe on me through their word;"}, {"numero": 21, "texto": "That they all may be one; as thou, Father, art in me, and I in thee, that they also may be one in us: that the world may believe that thou hast sent me."}, {"numero": 22, "texto": "And the glory which thou gavest me I have given them; that they may be one, even as we are one:"}, {"numero": 23, "texto": "I in them, and thou in me, that they may be made perfect in one; and that the world may know that thou hast sent me, and hast loved them, as thou hast loved me."}, {"numero": 24, "texto": "Father, I will that they also, whom thou hast given me, be with me where I am; that they may behold my glory, which thou hast given me: for thou lovedst me before the foundation of the world."}, {"numero": 25, "texto": "O righteous Father, the world hath not known thee: but I have known thee, and these have known that thou hast sent me."}, {"numero": 26, "texto": "And I have declared unto them thy name, and will declare it: that the love wherewith thou hast loved me may be in them, and I in them."}]'::jsonb, 'King James Version'),
  ('Jo', 17, 'fr', '[{"numero": 1, "texto": "Après avoir ainsi parlé, Jésus leva les yeux au ciel, et dit: Père, l''''heure est venue! Glorifie ton Fils, afin que ton Fils te glorifie,"}, {"numero": 2, "texto": "selon que tu lui as donné pouvoir sur toute chair, afin qu''''il accorde la vie éternelle à tous ceux que tu lui as donnés."}, {"numero": 3, "texto": "Or, la vie éternelle, c''''est qu''''ils te connaissent, toi, le seul vrai Dieu, et celui que tu as envoyé, Jésus-Christ."}, {"numero": 4, "texto": "Je t''''ai glorifié sur la terre, j''''ai achevé l''''oeuvre que tu m''''as donnée à faire."}, {"numero": 5, "texto": "Et maintenant toi, Père, glorifie-moi auprès de toi-même de la gloire que j''''avais auprès de toi avant que le monde fût."}, {"numero": 6, "texto": "J''''ai fait connaître ton nom aux hommes que tu m''''as donnés du milieu du monde. Ils étaient à toi, et tu me les as donnés; et ils ont gardé ta parole."}, {"numero": 7, "texto": "Maintenant ils ont connu que tout ce que tu m''''as donné vient de toi."}, {"numero": 8, "texto": "Car je leur ai donné les paroles que tu m''''as données; et ils les ont reçues, et ils ont vraiment connu que je suis sorti de toi, et ils ont cru que tu m''''as envoyé."}, {"numero": 9, "texto": "C''''est pour eux que je prie. Je ne prie pas pour le monde, mais pour ceux que tu m''''as donnés, parce qu''''ils sont à toi; -"}, {"numero": 10, "texto": "et tout ce qui est à moi est à toi, et ce qui est à toi est à moi; -et je suis glorifié en eux."}, {"numero": 11, "texto": "Je ne suis plus dans le monde, et ils sont dans le monde, et je vais à toi. Père saint, garde en ton nom ceux que tu m''''as donnés, afin qu''''ils soient un comme nous."}, {"numero": 12, "texto": "Lorsque j''''étais avec eux dans le monde, je les gardais en ton nom. J''''ai gardé ceux que tu m''''as donnés, et aucun d''''eux ne s''''est perdu, sinon le fils de perdition, afin que l''''Ecriture fût accomplie."}, {"numero": 13, "texto": "Et maintenant je vais à toi, et je dis ces choses dans le monde, afin qu''''ils aient en eux ma joie parfaite."}, {"numero": 14, "texto": "Je leur ai donné ta parole; et le monde les a haïs, parce qu''''ils ne sont pas du monde, comme moi je ne suis pas du monde."}, {"numero": 15, "texto": "Je ne te prie pas de les ôter du monde, mais de les préserver du mal."}, {"numero": 16, "texto": "Ils ne sont pas du monde, comme moi je ne suis pas du monde."}, {"numero": 17, "texto": "Sanctifie-les par ta vérité: ta parole est la vérité."}, {"numero": 18, "texto": "Comme tu m''''as envoyé dans le monde, je les ai aussi envoyés dans le monde."}, {"numero": 19, "texto": "Et je me sanctifie moi-même pour eux, afin qu''''eux aussi soient sanctifiés par la vérité."}, {"numero": 20, "texto": "Ce n''''est pas pour eux seulement que je prie, mais encore pour ceux qui croiront en moi par leur parole,"}, {"numero": 21, "texto": "afin que tous soient un, comme toi, Père, tu es en moi, et comme je suis en toi, afin qu''''eux aussi soient un en nous, pour que le monde croie que tu m''''as envoyé."}, {"numero": 22, "texto": "Je leur ai donné la gloire que tu m''''as donnée, afin qu''''ils soient un comme nous sommes un, -"}, {"numero": 23, "texto": "moi en eux, et toi en moi, -afin qu''''ils soient parfaitement un, et que le monde connaisse que tu m''''as envoyé et que tu les as aimés comme tu m''''as aimé."}, {"numero": 24, "texto": "Père, je veux que là où je suis ceux que tu m''''as donnés soient aussi avec moi, afin qu''''ils voient ma gloire, la gloire que tu m''''as donnée, parce que tu m''''as aimé avant la fondation du monde."}, {"numero": 25, "texto": "Père juste, le monde ne t''''a point connu; mais moi je t''''ai connu, et ceux-ci ont connu que tu m''''as envoyé."}, {"numero": 26, "texto": "Je leur ai fait connaître ton nom, et je le leur ferai connaître, afin que l''''amour dont tu m''''as aimé soit en eux, et que je sois en eux."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 17, 'es', '[{"numero": 1, "texto": "ESTAS cosas habló Jesús, y levantados los ojos al cielo, dijo: Padre, la hora es llegada; glorifica á tu Hijo, para que también tu Hijo te glorifique á ti;"}, {"numero": 2, "texto": "Como le has dado la potestad de toda carne, para que dé vida eterna á todos los que le diste."}, {"numero": 3, "texto": "Esta empero es la vida eterna: que te conozcan el solo Dios verdadero, y á Jesucristo, al cual has enviado."}, {"numero": 4, "texto": "Yo te he glorificado en la tierra: he acabado la obra que me diste que hiciese."}, {"numero": 5, "texto": "Ahora pues, Padre, glorifícame tú cerca de ti mismo con aquella gloria que tuve cerca de ti antes que el mundo fuese."}, {"numero": 6, "texto": "He manifestado tu nombre á los hombres que del mundo me diste: tuyos eran, y me los diste, y guardaron tu palabra."}, {"numero": 7, "texto": "Ahora han conocido que todas las cosas que me diste, son de ti;"}, {"numero": 8, "texto": "Porque las palabras que me diste, les he dado; y ellos las recibieron, y han conocido verdaderamente que salí de ti, y han creído que tú me enviaste."}, {"numero": 9, "texto": "Yo ruego por ellos: no ruego por el mundo, sino por los que me diste; porque tuyos son:"}, {"numero": 10, "texto": "Y todas mis cosas son tus cosas, y tus cosas son mis cosas: y he sido glorificado en ellas."}, {"numero": 11, "texto": "Y ya no estoy en el mundo; mas éstos están en el mundo, y yo á ti vengo. Padre santo, á los que me has dado, guárdalos por tu nombre, para que sean una cosa, como también nosotros."}, {"numero": 12, "texto": "Cuando estaba con ellos en el mundo, yo los guardaba en tu nombre; á los que me diste, yo los guardé, y ninguno de ellos se perdió, sino el hijo de perdición; para que la Escritura se cumpliese."}, {"numero": 13, "texto": "Mas ahora vengo á ti; y hablo esto en el mundo, para que tengan mi gozo cumplido en sí mismos."}, {"numero": 14, "texto": "Yo les he dado tu palabra; y el mundo los aborreció, porque no son del mundo, como tampoco yo soy del mundo."}, {"numero": 15, "texto": "No ruego que los quites del mundo, sino que los guardes del mal."}, {"numero": 16, "texto": "No son del mundo, como tampoco yo soy del mundo."}, {"numero": 17, "texto": "Santifícalos en tu verdad: tu palabra es verdad."}, {"numero": 18, "texto": "Como tú me enviaste al mundo, también los he enviado al mundo."}, {"numero": 19, "texto": "Y por ellos yo me santifico á mí mismo, para que también ellos sean santificados en verdad."}, {"numero": 20, "texto": "Mas no ruego solamente por éstos, sino también por los que han de creer en mí por la palabra de ellos."}, {"numero": 21, "texto": "Para que todos sean una cosa; como tú, oh Padre, en mí, y yo en ti, que también ellos sean en nosotros una cosa: para que el mundo crea que tú me enviaste."}, {"numero": 22, "texto": "Y yo, la gloria que me diste les he dado; para que sean una cosa, como también nosotros somos una cosa."}, {"numero": 23, "texto": "Yo en ellos, y tú en mí, para que sean consumadamente una cosa; que el mundo conozca que tú me enviaste, y que los has amado, como también á mí me has amado."}, {"numero": 24, "texto": "Padre, aquellos que me has dado, quiero que donde yo estoy, ellos estén también conmigo; para que vean mi gloria que me has dado: por cuanto me has amado desde antes de la constitución del mundo."}, {"numero": 25, "texto": "Padre justo, el mundo no te ha conocido, mas yo te he conocido; y éstos han conocido que tú me enviaste;"}, {"numero": 26, "texto": "Y yo les he manifestado tu nombre, y manifestarélo aún; para que el amor con que me has amado, esté en ellos, y yo en ellos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 18, 'pt', '[{"numero": 1, "texto": "Havendo Jesus dito estas coisas, saiu com seus discípulos para além do ribeiro de Cedrom, onde havia um jardim, em que ele entrou ele, e seus discípulos."}, {"numero": 2, "texto": "E também Judas, o que o traía, conhecia aquele lugar; porque muitas vezes se juntara ali Jesus com seus discípulos."}, {"numero": 3, "texto": "Tendo Judas, pois, tomado a tropa e [alguns dos] oficiais dos sacerdotes e dos fariseus, veio ali com lanternas, tochas, e armas."}, {"numero": 4, "texto": "Sabendo pois Jesus todas as coisas que viriam sobre ele, adiantou-se, e disse-lhes: A quem buscais?"}, {"numero": 5, "texto": "Responderam-lhe: A Jesus Nazareno. Disse-lhes Jesus: Eu sou. E Judas, o que o traía, também estava com eles."}, {"numero": 6, "texto": "Quando pois lhes disse: Eu sou, voltaram para trás, e caíram em terra."}, {"numero": 7, "texto": "Voltou pois a lhes perguntar: A quem buscais? E eles disseram: A Jesus Nazareno."}, {"numero": 8, "texto": "Respondeu Jesus: Já vos disse que eu sou. Portanto se buscais a mim, deixai a estes irem."}, {"numero": 9, "texto": "Para que se cumprisse a palavra, que tinha dito: Dos que me deste, a nenhum deles perdi."}, {"numero": 10, "texto": "Simão Pedro, pois, que tinha espada, puxou dela, e feriu ao servo do sacerdote, e cortou a sua orelha direita. E era o nome do servo Malco."}, {"numero": 11, "texto": "Disse pois Jesus a Pedro: Põe tua espada na bainha; não beberei eu o copo que o Pai tem me dado?"}, {"numero": 12, "texto": "O grupo de soldados pois, e o comandante, e os oficiais dos judeus juntamente tomaram a Jesus, e o amarraram."}, {"numero": 13, "texto": "E o levaram primeiramente a Anás, porque era sogro de Caifás, o qual era o sumo sacerdote daquele ano."}, {"numero": 14, "texto": "E era Caifás o que havia aconselhado aos judeus de que convinha que um homem morresse pelo povo."}, {"numero": 15, "texto": "E Simão Pedro seguia a Jesus com outro discípulo. E este discípulo era conhecido do sacerdote, e entrou com Jesus no pátio do sumo sacerdote."}, {"numero": 16, "texto": "E Pedro estava fora à porta. Saiu pois o outro discípulo, que era conhecido do sacerdote, e falou à porteira, e pôs dentro a Pedro."}, {"numero": 17, "texto": "Disse pois a serva porteira a Pedro: Não és tu também dos discípulos deste homem? Disse ele: Não sou."}, {"numero": 18, "texto": "E estavam [ali] os servos, e os oficiais, que haviam feito [uma fogueira de] brasas, porque fazia frio, e se esquentavam. Estava Pedro com eles, e se esquentava."}, {"numero": 19, "texto": "Perguntou pois o sacerdote a Jesus sobre seus discípulos, e sobre sua doutrina."}, {"numero": 20, "texto": "Jesus lhe respondeu: Eu abertamente falei ao mundo; eu sempre ensinei na sinagoga e no Templo, onde os Judeus de todos os lugares se juntam, e nada falei em oculto."}, {"numero": 21, "texto": "Por que perguntas a mim? Pergunta aos que o ouviram, que é o que lhes falei. Eis que estes sabem que é o que tenho dito."}, {"numero": 22, "texto": "E dizendo ele isto, um dos oficiais, que ali estava, deu a Jesus uma bofetada, dizendo: Assim respondes ao sumo sacerdote?"}, {"numero": 23, "texto": "Respondeu-lhe Jesus: Se falei mal, dá testemunho do mal; e se bem, por que me feres?"}, {"numero": 24, "texto": "(Pois Anás o mandara amarrado ao sumo sacerdote Caifás.)"}, {"numero": 25, "texto": "E Simão Pedro estava ali, e se esquentava; disseram-lhe pois: Não és tu também de seus discípulos? Ele negou, e disse: Não sou."}, {"numero": 26, "texto": "Disse um dos servos do sacerdote, parente daquele a quem Pedro cortara a orelha: Eu não te vi no jardim com ele?"}, {"numero": 27, "texto": "Pedro negou pois outra vez, e logo cantou o galo."}, {"numero": 28, "texto": "Levaram pois a Jesus de Caifás para o tribunal. E era pela manhã; e não entraram no tribunal, para que não se contaminassem, mas que pudessem comer a Páscoa."}, {"numero": 29, "texto": "Saiu pois Pilatos até eles fora, e disse: Que acusação trazeis contra este homem?"}, {"numero": 30, "texto": "Responderam, e disseram-lhe: Se este não fosse malfeitor, não o entregaríamos a ti."}, {"numero": 31, "texto": "Disse-lhes pois Pilatos: Tomai-o vós, e julgai-o segundo vossa lei. Disseram-lhe pois os Judeus: Não nos é lícito matar a alguém."}, {"numero": 32, "texto": "Para que se cumprisse a palavra de Jesus, que tinha dito, dando a entender de que morte havia de morrer."}, {"numero": 33, "texto": "Então Pilatos voltou a entrar no tribunal, e chamou a Jesus, e disse-lhe: És tu o Rei dos Judeus?"}, {"numero": 34, "texto": "Respondeu-lhe Jesus: Tu dizes isso de ti mesmo, ou outros te disseram de mim?"}, {"numero": 35, "texto": "Pilatos respondeu: Por acaso eu sou Judeu? Tua gente e os chefes dos sacerdotes te entregaram a mim; que fizeste?"}, {"numero": 36, "texto": "Respondeu Jesus: Meu Reino não é deste mundo; se meu Reino fosse deste mundo, meus trabalhadores lutariam, para que eu não fosse entregue aos Judeus; mas agora meu Reino não é daqui."}, {"numero": 37, "texto": "Disse-lhe pois Pilatos: Logo tu és Rei? Respondeu Jesus: Tu dizes que eu sou Rei. Para isto eu nasci, e para isto vim ao mundo: para dar testemunho à verdade. Todo aquele que é da verdade ouve minha voz."}, {"numero": 38, "texto": "Disse-lhe Pilatos: O que é a verdade? E havendo dito isto, voltou a sair aos Judeus, e disse-lhes: Nenhum crime acho nele."}, {"numero": 39, "texto": "Mas vós tendes por costume que eu vos solte um pela páscoa. Quereis pois que vos solte ao Rei dos Judeus?"}, {"numero": 40, "texto": "Voltaram pois todos a clamar, dizendo: Não a este, mas a Barrabás!E Barrabás era um ladrão."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 18, 'en', '[{"numero": 1, "texto": "When Jesus had spoken these words, he went forth with his disciples over the brook Cedron, where was a garden, into the which he entered, and his disciples."}, {"numero": 2, "texto": "And Judas also, which betrayed him, knew the place: for Jesus ofttimes resorted thither with his disciples."}, {"numero": 3, "texto": "Judas then, having received a band of men and officers from the chief priests and Pharisees, cometh thither with lanterns and torches and weapons."}, {"numero": 4, "texto": "Jesus therefore, knowing all things that should come upon him, went forth, and said unto them, Whom seek ye?"}, {"numero": 5, "texto": "They answered him, Jesus of Nazareth. Jesus saith unto them, I am he. And Judas also, which betrayed him, stood with them."}, {"numero": 6, "texto": "As soon then as he had said unto them, I am he, they went backward, and fell to the ground."}, {"numero": 7, "texto": "Then asked he them again, Whom seek ye? And they said, Jesus of Nazareth."}, {"numero": 8, "texto": "Jesus answered, I have told you that I am he: if therefore ye seek me, let these go their way:"}, {"numero": 9, "texto": "That the saying might be fulfilled, which he spake, Of them which thou gavest me have I lost none."}, {"numero": 10, "texto": "Then Simon Peter having a sword drew it, and smote the high priest''s servant, and cut off his right ear. The servant''s name was Malchus."}, {"numero": 11, "texto": "Then said Jesus unto Peter, Put up thy sword into the sheath: the cup which my Father hath given me, shall I not drink it?"}, {"numero": 12, "texto": "Then the band and the captain and officers of the Jews took Jesus, and bound him,"}, {"numero": 13, "texto": "And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year."}, {"numero": 14, "texto": "Now Caiaphas was he, which gave counsel to the Jews, that it was expedient that one man should die for the people."}, {"numero": 15, "texto": "And Simon Peter followed Jesus, and so did another disciple: that disciple was known unto the high priest, and went in with Jesus into the palace of the high priest."}, {"numero": 16, "texto": "But Peter stood at the door without. Then went out that other disciple, which was known unto the high priest, and spake unto her that kept the door, and brought in Peter."}, {"numero": 17, "texto": "Then saith the damsel that kept the door unto Peter, Art not thou also one of this man''s disciples? He saith, I am not."}, {"numero": 18, "texto": "And the servants and officers stood there, who had made a fire of coals; for it was cold: and they warmed themselves: and Peter stood with them, and warmed himself."}, {"numero": 19, "texto": "The high priest then asked Jesus of his disciples, and of his doctrine."}, {"numero": 20, "texto": "Jesus answered him, I spake openly to the world; I ever taught in the synagogue, and in the temple, whither the Jews always resort; and in secret have I said nothing."}, {"numero": 21, "texto": "Why askest thou me? ask them which heard me, what I have said unto them: behold, they know what I said."}, {"numero": 22, "texto": "And when he had thus spoken, one of the officers which stood by struck Jesus with the palm of his hand, saying, Answerest thou the high priest so?"}, {"numero": 23, "texto": "Jesus answered him, If I have spoken evil, bear witness of the evil: but if well, why smitest thou me?"}, {"numero": 24, "texto": "Now Annas had sent him bound unto Caiaphas the high priest."}, {"numero": 25, "texto": "And Simon Peter stood and warmed himself. They said therefore unto him, Art not thou also one of his disciples? He denied it, and said, I am not."}, {"numero": 26, "texto": "One of the servants of the high priest, being his kinsman whose ear Peter cut off, saith, Did not I see thee in the garden with him?"}, {"numero": 27, "texto": "Peter then denied again: and immediately the cock crew."}, {"numero": 28, "texto": "Then led they Jesus from Caiaphas unto the hall of judgment: and it was early; and they themselves went not into the judgment hall, lest they should be defiled; but that they might eat the passover."}, {"numero": 29, "texto": "Pilate then went out unto them, and said, What accusation bring ye against this man?"}, {"numero": 30, "texto": "They answered and said unto him, If he were not a malefactor, we would not have delivered him up unto thee."}, {"numero": 31, "texto": "Then said Pilate unto them, Take ye him, and judge him according to your law. The Jews therefore said unto him, It is not lawful for us to put any man to death:"}, {"numero": 32, "texto": "That the saying of Jesus might be fulfilled, which he spake, signifying what death he should die."}, {"numero": 33, "texto": "Then Pilate entered into the judgment hall again, and called Jesus, and said unto him, Art thou the King of the Jews?"}, {"numero": 34, "texto": "Jesus answered him, Sayest thou this thing of thyself, or did others tell it thee of me?"}, {"numero": 35, "texto": "Pilate answered, Am I a Jew? Thine own nation and the chief priests have delivered thee unto me: what hast thou done?"}, {"numero": 36, "texto": "Jesus answered, My kingdom is not of this world: if my kingdom were of this world, then would my servants fight, that I should not be delivered to the Jews: but now is my kingdom not from hence."}, {"numero": 37, "texto": "Pilate therefore said unto him, Art thou a king then? Jesus answered, Thou sayest that I am a king. To this end was I born, and for this cause came I into the world, that I should bear witness unto the truth. Every one that is of the truth heareth my voice."}, {"numero": 38, "texto": "Pilate saith unto him, What is truth? And when he had said this, he went out again unto the Jews, and saith unto them, I find in him no fault at all."}, {"numero": 39, "texto": "But ye have a custom, that I should release unto you one at the passover: will ye therefore that I release unto you the King of the Jews?"}, {"numero": 40, "texto": "Then cried they all again, saying, Not this man, but Barabbas. Now Barabbas was a robber."}]'::jsonb, 'King James Version'),
  ('Jo', 18, 'fr', '[{"numero": 1, "texto": "Lorsqu''''il eut dit ces choses, Jésus alla avec ses disciples de l''''autre côté du torrent du Cédron, où se trouvait un jardin, dans lequel il entra, lui et ses disciples."}, {"numero": 2, "texto": "Judas, qui le livrait, connaissait ce lieu, parce que Jésus et ses disciples s''''y étaient souvent réunis."}, {"numero": 3, "texto": "Judas donc, ayant pris la cohorte, et des huissiers qu''''envoyèrent les principaux sacrificateurs et les pharisiens, vint là avec des lanternes, des flambeaux et des armes."}, {"numero": 4, "texto": "Jésus, sachant tout ce qui devait lui arriver, s''''avança, et leur dit: Qui cherchez-vous?"}, {"numero": 5, "texto": "Ils lui répondirent: Jésus de Nazareth. Jésus leur dit: C''''est moi. Et Judas, qui le livrait, était avec eux."}, {"numero": 6, "texto": "Lorsque Jésus leur eut dit: C''''est moi, ils reculèrent et tombèrent par terre."}, {"numero": 7, "texto": "Il leur demanda de nouveau: Qui cherchez-vous? Et ils dirent: Jésus de Nazareth."}, {"numero": 8, "texto": "Jésus répondit: Je vous ai dit que c''''est moi. Si donc c''''est moi que vous cherchez, laissez aller ceux-ci."}, {"numero": 9, "texto": "Il dit cela, afin que s''''accomplît la parole qu''''il avait dite: Je n''''ai perdu aucun de ceux que tu m''''as donnés."}, {"numero": 10, "texto": "Simon Pierre, qui avait une épée, la tira, frappa le serviteur du souverain sacrificateur, et lui coupa l''''oreille droite. Ce serviteur s''''appelait Malchus."}, {"numero": 11, "texto": "Jésus dit à Pierre: Remets ton épée dans le fourreau. Ne boirai-je pas la coupe que le Père m''''a donnée à boire?"}, {"numero": 12, "texto": "La cohorte, le tribun, et les huissiers des Juifs, se saisirent alors de Jésus, et le lièrent."}, {"numero": 13, "texto": "Ils l''''emmenèrent d''''abord chez Anne; car il était le beau-père de Caïphe, qui était souverain sacrificateur cette année-là."}, {"numero": 14, "texto": "Et Caïphe était celui qui avait donné ce conseil aux Juifs: Il est avantageux qu''''un seul homme meure pour le peuple."}, {"numero": 15, "texto": "Simon Pierre, avec un autre disciple, suivait Jésus. Ce disciple était connu du souverain sacrificateur, et il entra avec Jésus dans la cour du souverain sacrificateur;"}, {"numero": 16, "texto": "mais Pierre resta dehors près de la porte. L''''autre disciple, qui était connu du souverain sacrificateur, sortit, parla à la portière, et fit entrer Pierre."}, {"numero": 17, "texto": "Alors la servante, la portière, dit à Pierre: Toi aussi, n''''es-tu pas des disciples de cet homme? Il dit: Je n''''en suis point."}, {"numero": 18, "texto": "Les serviteurs et les huissiers, qui étaient là, avaient allumé un brasier, car il faisait froid, et ils se chauffaient. Pierre se tenait avec eux, et se chauffait."}, {"numero": 19, "texto": "Le souverain sacrificateur interrogea Jésus sur ses disciples et sur sa doctrine."}, {"numero": 20, "texto": "Jésus lui répondit: J''''ai parlé ouvertement au monde; j''''ai toujours enseigné dans la synagogue et dans le temple, où tous les Juifs s''''assemblent, et je n''''ai rien dit en secret."}, {"numero": 21, "texto": "Pourquoi m''''interroges-tu? Interroge sur ce que je leur ai dit ceux qui m''''ont entendu; voici, ceux-là savent ce que j''''ai dit."}, {"numero": 22, "texto": "A ces mots, un des huissiers, qui se trouvait là, donna un soufflet à Jésus, en disant: Est-ce ainsi que tu réponds au souverain sacrificateur?"}, {"numero": 23, "texto": "Jésus lui dit: Si j''''ai mal parlé, fais voir ce que j''''ai dit de mal; et si j''''ai bien parlé, pourquoi me frappes-tu?"}, {"numero": 24, "texto": "Anne l''''envoya lié à Caïphe, le souverain sacrificateur."}, {"numero": 25, "texto": "Simon Pierre était là, et se chauffait. On lui dit: Toi aussi, n''''es-tu pas de ses disciples? Il le nia, et dit: Je n''''en suis point."}, {"numero": 26, "texto": "Un des serviteurs du souverain sacrificateur, parent de celui à qui Pierre avait coupé l''''oreille, dit: Ne t''''ai-je pas vu avec lui dans le jardin?"}, {"numero": 27, "texto": "Pierre le nia de nouveau. Et aussitôt le coq chanta."}, {"numero": 28, "texto": "Ils conduisirent Jésus de chez Caïphe au prétoire: c''''était le matin. Ils n''''entrèrent point eux-mêmes dans le prétoire, afin de ne pas se souiller, et de pouvoir manger la Pâque."}, {"numero": 29, "texto": "Pilate sortit donc pour aller à eux, et il dit: Quelle accusation portez-vous contre cet homme?"}, {"numero": 30, "texto": "Ils lui répondirent: Si ce n''''était pas un malfaiteur, nous ne te l''''aurions pas livré."}, {"numero": 31, "texto": "Sur quoi Pilate leur dit: Prenez-le vous-mêmes, et jugez-le selon votre loi. Les Juifs lui dirent: Il ne nous est pas permis de mettre personne à mort."}, {"numero": 32, "texto": "C''''était afin que s''''accomplît la parole que Jésus avait dite, lorsqu''''il indiqua de quelle mort il devait mourir."}, {"numero": 33, "texto": "Pilate rentra dans le prétoire, appela Jésus, et lui dit: Es-tu le roi des Juifs?"}, {"numero": 34, "texto": "Jésus répondit: Est-ce de toi-même que tu dis cela, ou d''''autres te l''''ont-ils dit de moi?"}, {"numero": 35, "texto": "Pilate répondit: Moi, suis-je Juif? Ta nation et les principaux sacrificateurs t''''ont livré à moi: qu''''as-tu fait?"}, {"numero": 36, "texto": "Mon royaume n''''est pas de ce monde, répondit Jésus. Si mon royaume était de ce monde, mes serviteurs auraient combattu pour moi afin que je ne fusse pas livré aux Juifs; mais maintenant mon royaume n''''est point d''''ici-bas."}, {"numero": 37, "texto": "Pilate lui dit: Tu es donc roi? Jésus répondit: Tu le dis, je suis roi. Je suis né et je suis venu dans le monde pour rendre témoignage à la vérité. Quiconque est de la vérité écoute ma voix."}, {"numero": 38, "texto": "Pilate lui dit: Qu''''est-ce que la vérité? Après avoir dit cela, il sortit de nouveau pour aller vers les Juifs, et il leur dit: Je ne trouve aucun crime en lui."}, {"numero": 39, "texto": "Mais, comme c''''est parmi vous une coutume que je vous relâche quelqu''''un à la fête de Pâque, voulez-vous que je vous relâche le roi des Juifs?"}, {"numero": 40, "texto": "Alors de nouveau tous s''''écrièrent: Non pas lui, mais Barabbas. Or, Barabbas était un brigand."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 18, 'es', '[{"numero": 1, "texto": "COMO Jesús hubo dicho estas cosas, salióse con sus discípulos tras el arroyo de Cedrón, donde estaba un huerto, en el cual entró Jesús y sus discípulos."}, {"numero": 2, "texto": "Y también Judas, el que le entregaba, sabía aquel lugar; porque muchas veces Jesús se juntaba allí con sus discípulos."}, {"numero": 3, "texto": "Judas pues tomando una compañía, y ministros de los pontífices y de los Fariseos, vino allí con linternas y antorchas, y con armas."}, {"numero": 4, "texto": "Empero Jesús, sabiendo todas las cosas que habían de venir sobre él, salió delante, y díjoles: ¿A quién buscáis?"}, {"numero": 5, "texto": "Respondiéronle: A Jesús Nazareno. Díceles Jesús: Yo soy. (Y estaba también con ellos Judas, el que le entregaba.)"}, {"numero": 6, "texto": "Y como les dijo, Yo soy, volvieron atrás, y cayeron en tierra."}, {"numero": 7, "texto": "Volvióles, pues, á preguntar: ¿A quién buscáis? Y ellos dijeron: A Jesús Nazareno."}, {"numero": 8, "texto": "Respondió Jesús: Os he dicho que yo soy: pues si á mí buscáis, dejad ir á éstos."}, {"numero": 9, "texto": "Para que se cumpliese la palabra que había dicho: De los que me diste, ninguno de ellos perdí."}, {"numero": 10, "texto": "Entonces Simón Pedro, que tenía espada, sacóla, é hirió al siervo del pontífice, y le cortó la oreja derecha. Y el siervo se llamaba Malco."}, {"numero": 11, "texto": "Jesús entonces dijo á Pedro: Mete tu espada en la vaina: el vaso que el Padre me ha dado, ¿no lo tengo de beber?"}, {"numero": 12, "texto": "Entonces la compañía y el tribuno, y los ministros de los Judíos, prendieron á Jesús y le ataron,"}, {"numero": 13, "texto": "Y lleváronle primeramente á Anás; porque era suegro de Caifás, el cual era pontífice de aquel año."}, {"numero": 14, "texto": "Y era Caifás el que había dado el consejo á los Judíos, que era necesario que un hombre muriese por el pueblo."}, {"numero": 15, "texto": "Y seguía á Jesús Simón Pedro, y otro discípulo. Y aquel discípulo era conocido del pontífice, y entró con Jesús al atrio del pontífice;"}, {"numero": 16, "texto": "Mas Pedro estaba fuera á la puerta. Y salió aquel discípulo que era conocido del pontífice, y habló á la portera, y metió dentro á Pedro."}, {"numero": 17, "texto": "Entonces la criada portera dijo á Pedro: ¿No eres tú también de los discípulos de este hombre? Dice él: No soy."}, {"numero": 18, "texto": "Y estaban en pie los siervos y los ministros que habían allegado las ascuas; porque hacía frío, y calentábanse: y estaba también con ellos Pedro en pie, calentándose."}, {"numero": 19, "texto": "Y el pontífice preguntó á Jesús acerca de sus discípulos y de su doctrina."}, {"numero": 20, "texto": "Jesús le respondió: Yo manifiestamente he hablado al mundo: yo siempre he enseñado en la sinagoga y en el templo, donde se juntan todos los Judíos, y nada he hablado en oculto."}, {"numero": 21, "texto": "¿Qué me preguntas á mí? Pregunta á los que han oído, qué les haya yo hablado: he aquí, ésos saben lo que yo he dicho."}, {"numero": 22, "texto": "Y como él hubo dicho esto, uno de los criados que estaba allí, dió una bofetada á Jesús, diciendo: ¿Así respondes al pontífice?"}, {"numero": 23, "texto": "Respondióle Jesús: Si he hablado mal, da testimonio del mal: y si bien, ¿por qué me hieres?"}, {"numero": 24, "texto": "Y Anás le había enviado atado á Caifás pontífice."}, {"numero": 25, "texto": "Estaba pues Pedro en pie calentándose. Y dijéronle: ¿No eres tú de sus discípulos? El negó, y dijo: No soy."}, {"numero": 26, "texto": "Uno de los siervos del pontífice, pariente de aquél á quien Pedro había cortado la oreja, le dice: ¿No te vi yo en el huerto con él?"}, {"numero": 27, "texto": "Y negó Pedro otra vez: y luego el gallo cantó."}, {"numero": 28, "texto": "Y llevaron á Jesús de Caifás al pretorio: y era por la mañana: y ellos no entraron en el pretorio por no ser contaminados, sino que comiesen la pascua."}, {"numero": 29, "texto": "Entonces salió Pilato á ellos fuera, y dijo: ¿Qué acusación traéis contra este hombre?"}, {"numero": 30, "texto": "Respondieron y dijéronle: Si éste no fuera malhechor, no te le habríamos entregado."}, {"numero": 31, "texto": "Díceles entonces Pilato: Tomadle vosotros, y juzgadle según vuestra ley. Y los Judíos le dijeron: A nosotros no es lícito matar á nadie:"}, {"numero": 32, "texto": "Para que se cumpliese el dicho de Jesús, que había dicho, dando á entender de qué muerte había de morir."}, {"numero": 33, "texto": "Así que, Pilato volvió á entrar en el pretorio, y llamó á Jesús, y díjole: ¿Eres tú el Rey de los Judíos?"}, {"numero": 34, "texto": "Respondióle Jesús: ¿Dices tú esto de ti mismo, ó te lo han dicho otros de mí?"}, {"numero": 35, "texto": "Pilato respondió: ¿Soy yo Judío? Tu gente, y los pontífices, te han entregado á mí: ¿qué has hecho?"}, {"numero": 36, "texto": "Respondió Jesús: Mi reino no es de este mundo: si de este mundo fuera mi reino, mis servidores pelearían para que yo no fuera entregado á los Judíos: ahora, pues, mi reino no es de aquí."}, {"numero": 37, "texto": "Díjole entonces Pilato: ¿Luego rey eres tú? Respondió Jesús: Tú dices que yo soy rey. Yo para esto he nacido, y para esto he venido al mundo, para dar testimonio á la verdad. Todo aquél que es de la verdad, oye mi voz."}, {"numero": 38, "texto": "Dícele Pilato: ¿Qué cosa es verdad? Y como hubo dicho esto, salió otra vez á los Judíos, y díceles: Yo no hallo en él ningún crimen."}, {"numero": 39, "texto": "Empero vosotros tenéis costumbre, que os suelte uno en la Pascua: ¿queréis, pues, que os suelte al Rey de los Judíos?"}, {"numero": 40, "texto": "Entonces todos dieron voces otra vez, diciendo: No á éste, sino á Barrabás. Y Barrabás era ladrón."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 19, 'pt', '[{"numero": 1, "texto": "Então Pilatos tomou a Jesus, e [o] açoitou."}, {"numero": 2, "texto": "E trançando os soldados uma coroa de espinhos, puseram-na sobre sua cabeça, e o vestiram de uma roupa vermelha."}, {"numero": 3, "texto": "E diziam: Tenhas alegria, Rei dos Judeus! E davam-lhe bofetadas."}, {"numero": 4, "texto": "Saiu pois Pilatos outra vez fora, e disse-lhes: Eis que eu o trago para fora [até] vós, para que saibais que nenhum crime acho nele."}, {"numero": 5, "texto": "Jesus foi pois trazido para fora, levando a coroa de espinhos, e a roupa vermelha-roxa. E [Pilatos] disse-lhes: Eis aqui o homem."}, {"numero": 6, "texto": "Quando então os chefes dos sacerdotes e os trabalhadores o viram, eles clamaram, dizendo: Crucifica [-o] ! Crucifica [-o] ! Disse-lhes Pilatos: Tomai-o vós, e crucificai [-o] ; porque eu nenhum crime acho nele."}, {"numero": 7, "texto": "Responderam-lhe os Judeus: Nós temos Lei, e segundo nossa Lei ele deve morrer, porque se fez Filho de Deus."}, {"numero": 8, "texto": "Quando pois Pilatos ouviu esta palavra, ficou mais atemorizado."}, {"numero": 9, "texto": "E entrou outra vez no tribunal, e disse a Jesus: De onde és tu? Mas Jesus não lhe deu resposta."}, {"numero": 10, "texto": "Disse-lhe pois Pilatos: Não falas comigo? Não sabes que tenho poder para te crucificar, e tenho poder para te soltar?"}, {"numero": 11, "texto": "Respondeu Jesus: Nenhum poder terias contra mim, se não te fosse dado de cima; portanto o que me entregou a ti tem maior pecado."}, {"numero": 12, "texto": "Desde então Pilatos procurava soltá-lo; mas os Judeus clamavam, dizendo: Se soltas a este, não és amigo de César; qualquer que se faz Rei, contradiz a César."}, {"numero": 13, "texto": "Então Pilatos, ouvindo este dito, levou fora a Jesus, e sentou-se no tribunal, no lugar chamado Litóstrotos, [ou pavimento] ,e em hebraico Gabatá."}, {"numero": 14, "texto": "E era a preparação da páscoa, e quase à hora sexta, e disse aos Judeus: Eis aqui vosso Rei!"}, {"numero": 15, "texto": "Mas eles bradaram: Tira, tira, crucifica-o! Disse-lhes Pilatos: Crucificarei a vosso Rei?Responderam os chefes dos sacerdotes: Não temos [outro] rei, a não ser César."}, {"numero": 16, "texto": "Então o entregou a eles, para que fosse crucificado. E tomaram a Jesus, e levaram [-no] ."}, {"numero": 17, "texto": "E levando ele sua cruz, saiu para o [lugar] chamado a Caveira, que em hebraico se chama Gólgota."}, {"numero": 18, "texto": "Onde o crucificaram, e com ele outros dois, um de cada lado, e a Jesus no meio."}, {"numero": 19, "texto": "E Pilatos também escreveu um título, e o pôs encima da cruz, e estava [nele] escrito: JESUS NAZARENO, REI DOS JUDEUS."}, {"numero": 20, "texto": "Leram pois muitos dos Judeus este título; porque o lugar onde Jesus estava crucificado era perto da cidade; e estava escrito em hebraico, em grego, [e] em latim."}, {"numero": 21, "texto": "Diziam pois os chefes dos sacerdotes dos judeus a Pilatos: Não escrevas: Rei dos Judeus, mas que disse: Sou Rei dos Judeus."}, {"numero": 22, "texto": "Respondeu Pilatos: O que escrevi, escrevi."}, {"numero": 23, "texto": "Havendo pois os soldados crucificado a Jesus, tomaram suas roupas, e fizeram quatro partes, para cada soldado uma parte, e a túnica. E era a túnica sem costura, toda tecida desde cima [até baixo] ."}, {"numero": 24, "texto": "Disseram pois uns aos outros: Não a partamos, mas lancemos sortes sobre ela, de quem será; para que se cumprisse a Escritura, que diz: Entre si partiram minhas roupas, e sobre minha veste lançaram sortes. Os soldados, pois, fizeram isto."}, {"numero": 25, "texto": "E estavam junto à cruz de Jesus, sua mãe, e a irmã de sua mãe, Maria [mulher] de Cleofas, e Maria Madalena."}, {"numero": 26, "texto": "E vendo Jesus a [sua] mãe, e ao discípulo a quem amava, que ali estava, disse a sua mãe: Mulher, eis aí teu filho."}, {"numero": 27, "texto": "Depois disse ao discípulo: Eis aí tua mãe. E desde aquela hora o discípulo a recebeu em sua [casa] ."}, {"numero": 28, "texto": "Depois disto, sabendo Jesus que já todas as coisas estavam feitas, para que a Escritura se cumprisse, ele disse: Tenho sede."}, {"numero": 29, "texto": "Estava pois ali um vaso cheio de vinagre, e encheram uma esponja de vinagre, e envolvendo-a com hissopo, levaram-na a sua boca."}, {"numero": 30, "texto": "Quando pois Jesus tomou o vinagre, disse: Está consumado; e abaixando a cabeça, deu o Espírito."}, {"numero": 31, "texto": "Os Judeus pois, para que os corpos não ficassem no sábado na cruz, pois era a preparação (porque era o grande dia do Sábado), suplicaram a Pilatos que as pernas deles fossem quebradas, e fossem tirados."}, {"numero": 32, "texto": "Vieram pois os soldados, e na verdade quebraram as pernas do primeiro, e do outro, que fora crucificado com ele."}, {"numero": 33, "texto": "Mas vindo a Jesus, [e] vendo-o já morto, não quebraram as suas pernas."}, {"numero": 34, "texto": "Mas um dos soldados lhe furou com uma lança o lado, e logo saiu sangue e água."}, {"numero": 35, "texto": "E o que viu isto, o testemunhou; e seu testemunho é verdadeiro, e sabe que é verdade o que diz, para que vós também creiais."}, {"numero": 36, "texto": "Porque estas coisas aconteceram para que se cumprisse a Escritura [que diz] : Osso dele não será quebrado."}, {"numero": 37, "texto": "E além disso, outra Escritura diz: Verão [aquele] a quem perfuraram."}, {"numero": 38, "texto": "E depois José de Arimateia, (que era discípulo de Jesus, porém oculto por medo dos Judeus) suplicou a Pilatos que pudesse tirar o corpo de Jesus; e Pilatos permitiu. Veio pois e tirou o corpo de Jesus."}, {"numero": 39, "texto": "E veio também Nicodemos, (aquele que antes de noite tinha vindo a Jesus) trazendo um composto de mirra e aloés, de quase cem arráteis."}, {"numero": 40, "texto": "Tomaram pois o corpo de Jesus, e o envolveram em lençóis com as especiarias, como é costume dos judeus sepultarem."}, {"numero": 41, "texto": "E havia um jardim naquele lugar onde fora crucificado; e no jardim [havia] um sepulcro novo, em que ainda nunca alguém havia sido posto."}, {"numero": 42, "texto": "Ali pois (por causa da preparação [da páscoa] dos Judeus, e porque aquele sepulcro estava perto) puseram a Jesus."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 19, 'en', '[{"numero": 1, "texto": "Then Pilate therefore took Jesus, and scourged him."}, {"numero": 2, "texto": "And the soldiers platted a crown of thorns, and put it on his head, and they put on him a purple robe,"}, {"numero": 3, "texto": "And said, Hail, King of the Jews! and they smote him with their hands."}, {"numero": 4, "texto": "Pilate therefore went forth again, and saith unto them, Behold, I bring him forth to you, that ye may know that I find no fault in him."}, {"numero": 5, "texto": "Then came Jesus forth, wearing the crown of thorns, and the purple robe. And Pilate saith unto them, Behold the man!"}, {"numero": 6, "texto": "When the chief priests therefore and officers saw him, they cried out, saying, Crucify him, crucify him. Pilate saith unto them, Take ye him, and crucify him: for I find no fault in him."}, {"numero": 7, "texto": "The Jews answered him, We have a law, and by our law he ought to die, because he made himself the Son of God."}, {"numero": 8, "texto": "When Pilate therefore heard that saying, he was the more afraid;"}, {"numero": 9, "texto": "And went again into the judgment hall, and saith unto Jesus, Whence art thou? But Jesus gave him no answer."}, {"numero": 10, "texto": "Then saith Pilate unto him, Speakest thou not unto me? knowest thou not that I have power to crucify thee, and have power to release thee?"}, {"numero": 11, "texto": "Jesus answered, Thou couldest have no power at all against me, except it were given thee from above: therefore he that delivered me unto thee hath the greater sin."}, {"numero": 12, "texto": "And from thenceforth Pilate sought to release him: but the Jews cried out, saying, If thou let this man go, thou art not Caesar''s friend: whosoever maketh himself a king speaketh against Caesar."}, {"numero": 13, "texto": "When Pilate therefore heard that saying, he brought Jesus forth, and sat down in the judgment seat in a place that is called the Pavement, but in the Hebrew, Gabbatha."}, {"numero": 14, "texto": "And it was the preparation of the passover, and about the sixth hour: and he saith unto the Jews, Behold your King!"}, {"numero": 15, "texto": "But they cried out, Away with him, away with him, crucify him. Pilate saith unto them, Shall I crucify your King? The chief priests answered, We have no king but Caesar."}, {"numero": 16, "texto": "Then delivered he him therefore unto them to be crucified. And they took Jesus, and led him away."}, {"numero": 17, "texto": "And he bearing his cross went forth into a place called the place of a skull, which is called in the Hebrew Golgotha:"}, {"numero": 18, "texto": "Where they crucified him, and two other with him, on either side one, and Jesus in the midst."}, {"numero": 19, "texto": "And Pilate wrote a title, and put it on the cross. And the writing was Jesus Of Nazareth The King Of The Jews."}, {"numero": 20, "texto": "This title then read many of the Jews: for the place where Jesus was crucified was nigh to the city: and it was written in Hebrew, and Greek, and Latin."}, {"numero": 21, "texto": "Then said the chief priests of the Jews to Pilate, Write not, The King of the Jews; but that he said, I am King of the Jews."}, {"numero": 22, "texto": "Pilate answered, What I have written I have written."}, {"numero": 23, "texto": "Then the soldiers, when they had crucified Jesus, took his garments, and made four parts, to every soldier a part; and also his coat: now the coat was without seam, woven from the top throughout."}, {"numero": 24, "texto": "They said therefore among themselves, Let us not rend it, but cast lots for it, whose it shall be: that the scripture might be fulfilled, which saith, They parted my raiment among them, and for my vesture they did cast lots. These things therefore the soldiers did."}, {"numero": 25, "texto": "Now there stood by the cross of Jesus his mother, and his mother''s sister, Mary the wife of Cleophas, and Mary Magdalene."}, {"numero": 26, "texto": "When Jesus therefore saw his mother, and the disciple standing by, whom he loved, he saith unto his mother, Woman, behold thy son!"}, {"numero": 27, "texto": "Then saith he to the disciple, Behold thy mother! And from that hour that disciple took her unto his own home."}, {"numero": 28, "texto": "After this, Jesus knowing that all things were now accomplished, that the scripture might be fulfilled, saith, I thirst."}, {"numero": 29, "texto": "Now there was set a vessel full of vinegar: and they filled a spunge with vinegar, and put it upon hyssop, and put it to his mouth."}, {"numero": 30, "texto": "When Jesus therefore had received the vinegar, he said, It is finished: and he bowed his head, and gave up the ghost."}, {"numero": 31, "texto": "The Jews therefore, because it was the preparation, that the bodies should not remain upon the cross on the sabbath day, (for that sabbath day was an high day,) besought Pilate that their legs might be broken, and that they might be taken away."}, {"numero": 32, "texto": "Then came the soldiers, and brake the legs of the first, and of the other which was crucified with him."}, {"numero": 33, "texto": "But when they came to Jesus, and saw that he was dead already, they brake not his legs:"}, {"numero": 34, "texto": "But one of the soldiers with a spear pierced his side, and forthwith came there out blood and water."}, {"numero": 35, "texto": "And he that saw it bare record, and his record is true: and he knoweth that he saith true, that ye might believe."}, {"numero": 36, "texto": "For these things were done, that the scripture should be fulfilled, A bone of him shall not be broken."}, {"numero": 37, "texto": "And again another scripture saith, They shall look on him whom they pierced."}, {"numero": 38, "texto": "And after this Joseph of Arimathaea, being a disciple of Jesus, but secretly for fear of the Jews, besought Pilate that he might take away the body of Jesus: and Pilate gave him leave. He came therefore, and took the body of Jesus."}, {"numero": 39, "texto": "And there came also Nicodemus, which at the first came to Jesus by night, and brought a mixture of myrrh and aloes, about an hundred pound weight."}, {"numero": 40, "texto": "Then took they the body of Jesus, and wound it in linen clothes with the spices, as the manner of the Jews is to bury."}, {"numero": 41, "texto": "Now in the place where he was crucified there was a garden; and in the garden a new sepulchre, wherein was never man yet laid."}, {"numero": 42, "texto": "There laid they Jesus therefore because of the Jews'' preparation day; for the sepulchre was nigh at hand."}]'::jsonb, 'King James Version'),
  ('Jo', 19, 'fr', '[{"numero": 1, "texto": "Alors Pilate prit Jésus, et le fit battre de verges."}, {"numero": 2, "texto": "Les soldats tressèrent une couronne d''''épines qu''''ils posèrent sur sa tête, et ils le revêtirent d''''un manteau de pourpre; puis, s''''approchant de lui,"}, {"numero": 3, "texto": "ils disaient: Salut, roi des Juifs! Et ils lui donnaient des soufflets."}, {"numero": 4, "texto": "Pilate sortit de nouveau, et dit aux Juifs: Voici, je vous l''''amène dehors, afin que vous sachiez que je ne trouve en lui aucun crime."}, {"numero": 5, "texto": "Jésus sortit donc, portant la couronne d''''épines et le manteau de pourpre. Et Pilate leur dit: Voici l''''homme."}, {"numero": 6, "texto": "Lorsque les principaux sacrificateurs et les huissiers le virent, ils s''''écrièrent: Crucifie! crucifie! Pilate leur dit: Prenez-le vous-mêmes, et crucifiez-le; car moi, je ne trouve point de crime en lui."}, {"numero": 7, "texto": "Les Juifs lui répondirent: Nous avons une loi; et, selon notre loi, il doit mourir, parce qu''''il s''''est fait Fils de Dieu."}, {"numero": 8, "texto": "Quand Pilate entendit cette parole, sa frayeur augmenta."}, {"numero": 9, "texto": "Il rentra dans le prétoire, et il dit à Jésus: D''''où es-tu? Mais Jésus ne lui donna point de réponse."}, {"numero": 10, "texto": "Pilate lui dit: Est-ce à moi que tu ne parles pas? Ne sais-tu pas que j''''ai le pouvoir de te crucifier, et que j''''ai le pouvoir de te relâcher?"}, {"numero": 11, "texto": "Jésus répondit: Tu n''''aurais sur moi aucun pouvoir, s''''il ne t''''avait été donné d''''en haut. C''''est pourquoi celui qui me livre à toi commet un plus grand péché."}, {"numero": 12, "texto": "Dès ce moment, Pilate cherchait à le relâcher. Mais les Juifs criaient: Si tu le relâches, tu n''''es pas ami de César. Quiconque se fait roi se déclare contre César."}, {"numero": 13, "texto": "Pilate, ayant entendu ces paroles, amena Jésus dehors; et il s''''assit sur le tribunal, au lieu appelé le Pavé, et en hébreu Gabbatha."}, {"numero": 14, "texto": "C''''était la préparation de la Pâque, et environ la sixième heure. Pilate dit aux Juifs: Voici votre roi."}, {"numero": 15, "texto": "Mais ils s''''écrièrent: Ote, ôte, crucifie-le! Pilate leur dit: Crucifierai-je votre roi? Les principaux sacrificateurs répondirent: Nous n''''avons de roi que César."}, {"numero": 16, "texto": "Alors il le leur livra pour être crucifié. Ils prirent donc Jésus, et l''''emmenèrent."}, {"numero": 17, "texto": "Jésus, portant sa croix, arriva au lieu du crâne, qui se nomme en hébreu Golgotha."}, {"numero": 18, "texto": "C''''est là qu''''il fut crucifié, et deux autres avec lui, un de chaque côté, et Jésus au milieu."}, {"numero": 19, "texto": "Pilate fit une inscription, qu''''il plaça sur la croix, et qui était ainsi conçue: Jésus de Nazareth, roi des Juifs."}, {"numero": 20, "texto": "Beaucoup de Juifs lurent cette inscription, parce que le lieu où Jésus fut crucifié était près de la ville: elle était en hébreu, en grec et en latin."}, {"numero": 21, "texto": "Les principaux sacrificateurs des Juifs dirent à Pilate: N''''écris pas: Roi des Juifs. Mais écris qu''''il a dit: Je suis roi des Juifs."}, {"numero": 22, "texto": "Pilate répondit: Ce que j''''ai écrit, je l''''ai écrit."}, {"numero": 23, "texto": "Les soldats, après avoir crucifié Jésus, prirent ses vêtements, et ils en firent quatre parts, une part pour chaque soldat. Ils prirent aussi sa tunique, qui était sans couture, d''''un seul tissu depuis le haut jusqu''''en bas."}, {"numero": 24, "texto": "Et ils dirent entre eux: Ne la déchirons pas, mais tirons au sort à qui elle sera. Cela arriva afin que s''''accomplît cette parole de l''''Ecriture: Ils se sont partagé mes vêtements, Et ils ont tiré au sort ma tunique. Voilà ce que firent les soldats."}, {"numero": 25, "texto": "Près de la croix de Jésus se tenaient sa mère et la soeur de sa mère, Marie, femme de Clopas, et Marie de Magdala."}, {"numero": 26, "texto": "Jésus, voyant sa mère, et auprès d''''elle le disciple qu''''il aimait, dit à sa mère: Femme, voilà ton fils."}, {"numero": 27, "texto": "Puis il dit au disciple: Voilà ta mère. Et, dès ce moment, le disciple la prit chez lui."}, {"numero": 28, "texto": "Après cela, Jésus, qui savait que tout était déjà consommé, dit, afin que l''''Ecriture fût accomplie: J''''ai soif."}, {"numero": 29, "texto": "Il y avait là un vase plein de vinaigre. Les soldats en remplirent une éponge, et, l''''ayant fixée à une branche d''''hysope, ils l''''approchèrent de sa bouche."}, {"numero": 30, "texto": "Quand Jésus eut pris le vinaigre, il dit: Tout est accompli. Et, baissant la tête, il rendit l''''esprit."}, {"numero": 31, "texto": "Dans la crainte que les corps ne restassent sur la croix pendant le sabbat, -car c''''était la préparation, et ce jour de sabbat était un grand jour, -les Juifs demandèrent à Pilate qu''''on rompît les jambes aux crucifiés, et qu''''on les enlevât."}, {"numero": 32, "texto": "Les soldats vinrent donc, et ils rompirent les jambes au premier, puis à l''''autre qui avait été crucifié avec lui."}, {"numero": 33, "texto": "S''''étant approchés de Jésus, et le voyant déjà mort, ils ne lui rompirent pas les jambes;"}, {"numero": 34, "texto": "mais un des soldats lui perça le côté avec une lance, et aussitôt il sortit du sang et de l''''eau."}, {"numero": 35, "texto": "Celui qui l''''a vu en a rendu témoignage, et son témoignage est vrai; et il sait qu''''il dit vrai, afin que vous croyiez aussi."}, {"numero": 36, "texto": "Ces choses sont arrivées, afin que l''''Ecriture fût accomplie: Aucun de ses os ne sera brisé."}, {"numero": 37, "texto": "Et ailleurs l''''Ecriture dit encore: Ils verront celui qu''''ils ont percé."}, {"numero": 38, "texto": "Après cela, Joseph d''''Arimathée, qui était disciple de Jésus, mais en secret par crainte des Juifs, demanda à Pilate la permission de prendre le corps de Jésus. Et Pilate le permit. Il vint donc, et prit le corps de Jésus."}, {"numero": 39, "texto": "Nicodème, qui auparavant était allé de nuit vers Jésus, vint aussi, apportant un mélange d''''environ cent livres de myrrhe et d''''aloès."}, {"numero": 40, "texto": "Ils prirent donc le corps de Jésus, et l''''enveloppèrent de bandes, avec les aromates, comme c''''est la coutume d''''ensevelir chez les Juifs."}, {"numero": 41, "texto": "Or, il y avait un jardin dans le lieu où Jésus avait été crucifié, et dans le jardin un sépulcre neuf, où personne encore n''''avait été mis."}, {"numero": 42, "texto": "Ce fut là qu''''ils déposèrent Jésus, à cause de la préparation des Juifs, parce que le sépulcre était proche."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 19, 'es', '[{"numero": 1, "texto": "ASÍ que, entonces tomó Pilato á Jesús, y le azotó."}, {"numero": 2, "texto": "Y los soldados entretejieron de espinas una corona, y pusiéronla sobre su cabeza, y le vistieron de una ropa de grana;"}, {"numero": 3, "texto": "Y decían: ¡Salve, Rey de los Judíos! y dábanle de bofetadas."}, {"numero": 4, "texto": "Entonces Pilato salió otra vez fuera, y díjoles: He aquí, os le traigo fuera, para que entendáis que ningún crimen hallo en él."}, {"numero": 5, "texto": "Y salió Jesús fuera, llevando la corona de espinas y la ropa de grana. Y díceles Pilato: He aquí el hombre."}, {"numero": 6, "texto": "Y como le vieron los príncipes de los sacerdotes, y los servidores, dieron voces diciendo: Crucifícale, crucifícale. Díceles Pilato: Tomadle vosotros, y crucificadle; porque yo no hallo en él crimen."}, {"numero": 7, "texto": "Respondiéronle los Judíos: Nosotros tenemos ley, y según nuestra ley debe morir, porque se hizo Hijo de Dios."}, {"numero": 8, "texto": "Y como Pilato oyó esta palabra, tuvo más miedo."}, {"numero": 9, "texto": "Y entró otra vez en el pretorio, y dijo á Jesús: ¿De dónde eres tú? Mas Jesús no le dió respuesta."}, {"numero": 10, "texto": "Entonces dícele Pilato: ¿A mí no me hablas? ¿no sabes que tengo potestad para crucificarte, y que tengo potestad para soltarte?"}, {"numero": 11, "texto": "Respondió Jesús: Ninguna potestad tendrías contra mí, si no te fuese dado de arriba: por tanto, el que á ti me ha entregado, mayor pecado tiene."}, {"numero": 12, "texto": "Desde entonces procuraba Pilato soltarle; mas los Judíos daban voces, diciendo: Si á éste sueltas, no eres amigo de César: cualquiera que se hace rey, á César contradice."}, {"numero": 13, "texto": "Entonces Pilato, oyendo este dicho, llevó fuera á Jesús, y se sentó en el tribunal en el lugar que se dice Lithóstrotos, y en hebreo Gabbatha."}, {"numero": 14, "texto": "Y era la víspera de la Pascua, y como la hora de sexta. Entonces dijo á los Judíos: He aquí vuestro Rey."}, {"numero": 15, "texto": "Mas ellos dieron voces: Quita, quita, crucifícale. Díceles Pilato: ¿A vuestro Rey he de crucificar? Respondieron los pontífices: No tenemos rey sino á César."}, {"numero": 16, "texto": "Así que entonces lo entregó á ellos para que fuese crucificado. Y tomaron á Jesús, y le llevaron."}, {"numero": 17, "texto": "Y llevando su cruz, salió al lugar que se dice de la Calavera, y en hebreo, Gólgotha;"}, {"numero": 18, "texto": "Donde le crucificaron, y con él otros dos, uno á cada lado, y Jesús en medio."}, {"numero": 19, "texto": "Y escribió también Pilato un título, que puso encima de la cruz. Y el escrito era: JESUS NAZARENO, REY DE LOS JUDIOS."}, {"numero": 20, "texto": "Y muchos de los Judíos leyeron este título: porque el lugar donde estaba crucificado Jesús era cerca de la ciudad: y estaba escrito en hebreo, en griego, y en latín."}, {"numero": 21, "texto": "Y decían á Pilato los pontífices de los Judíos: No escribas, Rey de los Judíos: sino, que él dijo: Rey soy de los Judíos."}, {"numero": 22, "texto": "Respondió Pilato: Lo que he escrito, he escrito."}, {"numero": 23, "texto": "Y como los soldados hubieron crucificado á Jesús, tomaron sus vestidos, é hicieron cuatro partes (para cada soldado una parte); y la túnica; mas la túnica era sin costura, toda tejida desde arriba."}, {"numero": 24, "texto": "Y dijeron entre ellos: No la partamos, sino echemos suertes sobre ella, de quién será; para que se cumpliese la Escritura, que dice: Partieron para sí mis vestidos, y sobre mi vestidura echaron suertes. Y los soldados hicieron esto."}, {"numero": 25, "texto": "Y estaban junto á la cruz de Jesús su madre, y la hermana de su madre, María mujer de Cleofas, y María Magdalena."}, {"numero": 26, "texto": "Y como vió Jesús á la madre, y al discípulo que él amaba, que estaba presente, dice á su madre: Mujer, he ahí tu hijo."}, {"numero": 27, "texto": "Después dice al discípulo: He ahí tu madre. Y desde aquella hora el discípulo la recibió consigo."}, {"numero": 28, "texto": "Después de esto, sabiendo Jesús que todas las cosas eran ya cumplidas, para que la Escritura se cumpliese, dijo: Sed tengo."}, {"numero": 29, "texto": "Y estaba allí un vaso lleno de vinagre: entonces ellos hinchieron una esponja de vinagre, y rodeada á un hisopo, se la llegaron á la boca."}, {"numero": 30, "texto": "Y como Jesús tomó el vinagre, dijo: Consumado es. Y habiendo inclinado la cabeza, dió el espíritu."}, {"numero": 31, "texto": "Entonces los Judíos, por cuanto era la víspera de la Pascua, para que los cuerpos no quedasen en la cruz en el sábado, pues era el gran día del sábado, rogaron á Pilato que se les quebrasen las piernas, y fuesen quitados."}, {"numero": 32, "texto": "Y vinieron los soldados, y quebraron las piernas al primero, y asimismo al otro que había sido crucificado con él."}, {"numero": 33, "texto": "Mas cuando vinieron á Jesús, como le vieron ya muerto, no le quebraron las piernas:"}, {"numero": 34, "texto": "Empero uno de los soldados le abrió el costado con una lanza, y luego salió sangre y agua."}, {"numero": 35, "texto": "Y el que lo vió, da testimonio, y su testimonio es verdadero: y él sabe que dice verdad, para que vosotros también creáis."}, {"numero": 36, "texto": "Porque estas cosas fueron hechas para que se cumpliese la Escritura: Hueso no quebrantaréis de él."}, {"numero": 37, "texto": "Y también otra Escritura dice: Mirarán al que traspasaron."}, {"numero": 38, "texto": "Después de estas cosas, José de Arimatea, el cual era discípulo de Jesús, mas secreto por miedo de los Judíos, rogó á Pilato que pudiera quitar el cuerpo de Jesús: y permitióselo Pilato. Entonces vino, y quitó el cuerpo de Jesús."}, {"numero": 39, "texto": "Y vino también Nicodemo, el que antes había venido á Jesús de noche, trayendo un compuesto de mirra y de áloes, como cien libras."}, {"numero": 40, "texto": "Tomaron pues el cuerpo de Jesús, y envolviéronlo en lienzos con especias, como es costumbre de los Judíos sepultar."}, {"numero": 41, "texto": "Y en aquel lugar donde había sido crucificado, había un huerto; y en el huerto un sepulcro nuevo, en el cual aun no había sido puesto ninguno."}, {"numero": 42, "texto": "Allí, pues, por causa de la víspera de la Pascua de los Judíos, porque aquel sepulcro estaba cerca, pusieron á Jesús."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 20, 'pt', '[{"numero": 1, "texto": "E no primeiro [dia] da semana Maria Madalena veio de madrugada, sendo ainda escuro, ao sepulcro; e viu a pedra já tirada do sepulcro."}, {"numero": 2, "texto": "Correu pois, e veio a Simão Pedro, e ao outro discípulo a quem Jesus amava, e disse-lhes: Tomaram o Senhor do sepulcro, e não sabemos onde o puseram."}, {"numero": 3, "texto": "Pedro saiu pois e o outro discípulo [também] ,e vieram ao sepulcro."}, {"numero": 4, "texto": "E corriam estes dois juntos: e o outro discípulo correu adiante mais depressa que Pedro, e chegou primeiro ao sepulcro."}, {"numero": 5, "texto": "E abaixando-se, viu estar os lençóis; entretanto não entrou."}, {"numero": 6, "texto": "Chegou pois Simão Pedro seguindo-o, e entrou no sepulcro, e viu estar os lençóis [ali] ."}, {"numero": 7, "texto": "E o lenço que fora [posto] sobre sua cabeça, não [o viu] estar com os lençóis, mas [estava] dobrado em um lugar à parte."}, {"numero": 8, "texto": "Então pois entrou também o outro discípulo, que primeiro chegara ao sepulcro, e viu, e creu."}, {"numero": 9, "texto": "Porque ainda não sabiam a Escritura, que era necessário que ressuscitasse dos mortos."}, {"numero": 10, "texto": "Voltaram pois os Discípulos para [a casa] deles."}, {"numero": 11, "texto": "E Maria estava fora chorando junto ao sepulcro. Estando ela pois chorando, abaixou-se para [ver] o sepulcro."}, {"numero": 12, "texto": "E viu a dois anjos [vestidos] de branco, sentados um à cabeceira, e o outro aos pés, onde estava posto o corpo de Jesus."}, {"numero": 13, "texto": "E disseram-lhe eles: Mulher, por que choras? Disse-lhes ela: Porque levaram a meu Senhor, e não sei onde o puseram."}, {"numero": 14, "texto": "E havendo dito isto, virou-se para trás, e viu Jesus em pé, e não sabia que era Jesus."}, {"numero": 15, "texto": "Disse-lhe Jesus: Mulher, por que choras? A quem buscas? Ela, pensando que era o jardineiro, disse-lhe: Senhor, se tu o levaste, dize-me onde o puseste, e eu o levarei."}, {"numero": 16, "texto": "Disse-lhe Jesus: Maria! Ela, virando-se, disse-lhe: Rabôni! (que quer dizer Mestre)."}, {"numero": 17, "texto": "Disse-lhe Jesus: Não me toques; porque ainda não subi para o meu Pai; porém vai a meus irmãos, e dize- lhes: Subo para meu Pai, e para vosso Pai; [para] meu Deus, e [para] vosso Deus."}, {"numero": 18, "texto": "Veio Maria Madalena, e anunciou aos discípulos, que vira ao Senhor, e [que] estas coisas lhe dissera."}, {"numero": 19, "texto": "Vinda pois já a tarde, o primeiro dia da semana, e fechadas as portas onde os Discípulos, por medo dos judeus, tinham se reunido, veio Jesus, e pôs-se no meio [deles] ,e disse-lhes: Tenhais paz!"}, {"numero": 20, "texto": "E dizendo isto, mostrou-lhes suas mãos, e [seu] lado. Então os discípulos se alegraram, vendo ao Senhor."}, {"numero": 21, "texto": "Disse-lhes pois Jesus outra vez: Tenhais Paz! Como o Pai me enviou, assim eu vos envio."}, {"numero": 22, "texto": "E havendo dito isto, soprou [sobre eles] ,e disse-lhes: Recebei o Espírito Santo."}, {"numero": 23, "texto": "A quem quer que perdoardes os pecados, lhes são perdoados; [e] a quem quer que vós retiverdes [os pecados] ,[lhes] são retidos."}, {"numero": 24, "texto": "E a Tomé, um dos doze, chamado o Dídimo, não estava com eles, quando Jesus veio."}, {"numero": 25, "texto": "Disseram-lhe pois os outros discípulos: Vimos ao Senhor. Porém ele lhes disse: Se em suas mãos não vir o sinal dos cravos, e não pôr meu dedo no lugar dos cravos, e não pôr minha mão em seu lado, em maneira nenhuma crerei."}, {"numero": 26, "texto": "E oito dias depois, estavam os discípulos outra vez dentro, [e] com eles Tomé; e veio Jesus, fechadas já as portas, e pôs-se no meio, e disse: Tenhais paz!"}, {"numero": 27, "texto": "Depois disse a Tomé: Põe teu dedo aqui, e vê minhas mãos; e chega tua mão, e toca-a em meu lado; e não sejas incrédulo, mas sim crente."}, {"numero": 28, "texto": "E respondeu Tomé e disse-lhe: Senhor meu, e Deus meu!"}, {"numero": 29, "texto": "Disse-lhe Jesus: Porque me viste, Tomé, creste; bem-aventurados aqueles que não virem, e crerem."}, {"numero": 30, "texto": "Jesus fez também ainda muitos outros sinais ainda em presença de seus discípulos, que neste livro não estão escritos;"}, {"numero": 31, "texto": "Porém estes estão escritos, para que creiais que Jesus é o Cristo, o Filho de Deus; e para que crendo, tenhais vida em seu nome."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 20, 'en', '[{"numero": 1, "texto": "The first day of the week cometh Mary Magdalene early, when it was yet dark, unto the sepulchre, and seeth the stone taken away from the sepulchre."}, {"numero": 2, "texto": "Then she runneth, and cometh to Simon Peter, and to the other disciple, whom Jesus loved, and saith unto them, They have taken away the Lord out of the sepulchre, and we know not where they have laid him."}, {"numero": 3, "texto": "Peter therefore went forth, and that other disciple, and came to the sepulchre."}, {"numero": 4, "texto": "So they ran both together: and the other disciple did outrun Peter, and came first to the sepulchre."}, {"numero": 5, "texto": "And he stooping down, and looking in, saw the linen clothes lying; yet went he not in."}, {"numero": 6, "texto": "Then cometh Simon Peter following him, and went into the sepulchre, and seeth the linen clothes lie,"}, {"numero": 7, "texto": "And the napkin, that was about his head, not lying with the linen clothes, but wrapped together in a place by itself."}, {"numero": 8, "texto": "Then went in also that other disciple, which came first to the sepulchre, and he saw, and believed."}, {"numero": 9, "texto": "For as yet they knew not the scripture, that he must rise again from the dead."}, {"numero": 10, "texto": "Then the disciples went away again unto their own home."}, {"numero": 11, "texto": "But Mary stood without at the sepulchre weeping: and as she wept, she stooped down, and looked into the sepulchre,"}, {"numero": 12, "texto": "And seeth two angels in white sitting, the one at the head, and the other at the feet, where the body of Jesus had lain."}, {"numero": 13, "texto": "And they say unto her, Woman, why weepest thou? She saith unto them, Because they have taken away my Lord, and I know not where they have laid him."}, {"numero": 14, "texto": "And when she had thus said, she turned herself back, and saw Jesus standing, and knew not that it was Jesus."}, {"numero": 15, "texto": "Jesus saith unto her, Woman, why weepest thou? whom seekest thou? She, supposing him to be the gardener, saith unto him, Sir, if thou have borne him hence, tell me where thou hast laid him, and I will take him away."}, {"numero": 16, "texto": "Jesus saith unto her, Mary. She turned herself, and saith unto him, Rabboni; which is to say, Master."}, {"numero": 17, "texto": "Jesus saith unto her, Touch me not; for I am not yet ascended to my Father: but go to my brethren, and say unto them, I ascend unto my Father, and your Father; and to my God, and your God."}, {"numero": 18, "texto": "Mary Magdalene came and told the disciples that she had seen the Lord, and that he had spoken these things unto her."}, {"numero": 19, "texto": "Then the same day at evening, being the first day of the week, when the doors were shut where the disciples were assembled for fear of the Jews, came Jesus and stood in the midst, and saith unto them, Peace be unto you."}, {"numero": 20, "texto": "And when he had so said, he shewed unto them his hands and his side. Then were the disciples glad, when they saw the Lord."}, {"numero": 21, "texto": "Then said Jesus to them again, Peace be unto you: as my Father hath sent me, even so send I you."}, {"numero": 22, "texto": "And when he had said this, he breathed on them, and saith unto them, Receive ye the Holy Ghost:"}, {"numero": 23, "texto": "Whose soever sins ye remit, they are remitted unto them; and whose soever sins ye retain, they are retained."}, {"numero": 24, "texto": "But Thomas, one of the twelve, called Didymus, was not with them when Jesus came."}, {"numero": 25, "texto": "The other disciples therefore said unto him, We have seen the Lord. But he said unto them, Except I shall see in his hands the print of the nails, and put my finger into the print of the nails, and thrust my hand into his side, I will not believe."}, {"numero": 26, "texto": "And after eight days again his disciples were within, and Thomas with them: then came Jesus, the doors being shut, and stood in the midst, and said, Peace be unto you."}, {"numero": 27, "texto": "Then saith he to Thomas, Reach hither thy finger, and behold my hands; and reach hither thy hand, and thrust it into my side: and be not faithless, but believing."}, {"numero": 28, "texto": "And Thomas answered and said unto him, My Lord and my God."}, {"numero": 29, "texto": "Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed."}, {"numero": 30, "texto": "And many other signs truly did Jesus in the presence of his disciples, which are not written in this book:"}, {"numero": 31, "texto": "But these are written, that ye might believe that Jesus is the Christ, the Son of God; and that believing ye might have life through his name."}]'::jsonb, 'King James Version'),
  ('Jo', 20, 'fr', '[{"numero": 1, "texto": "Le premier jour de la semaine, Marie de Magdala se rendit au sépulcre dès le matin, comme il faisait encore obscur; et elle vit que la pierre était ôtée du sépulcre."}, {"numero": 2, "texto": "Elle courut vers Simon Pierre et vers l''''autre disciple que Jésus aimait, et leur dit: Ils ont enlevé du sépulcre le Seigneur, et nous ne savons où ils l''''ont mis."}, {"numero": 3, "texto": "Pierre et l''''autre disciple sortirent, et allèrent au sépulcre."}, {"numero": 4, "texto": "Ils couraient tous deux ensemble. Mais l''''autre disciple courut plus vite que Pierre, et arriva le premier au sépulcre;"}, {"numero": 5, "texto": "s''''étant baissé, il vit les bandes qui étaient à terre, cependant il n''''entra pas."}, {"numero": 6, "texto": "Simon Pierre, qui le suivait, arriva et entra dans le sépulcre; il vit les bandes qui étaient à terre,"}, {"numero": 7, "texto": "et le linge qu''''on avait mis sur la tête de Jésus, non pas avec les bandes, mais plié dans un lieu à part."}, {"numero": 8, "texto": "Alors l''''autre disciple, qui était arrivé le premier au sépulcre, entra aussi; et il vit, et il crut."}, {"numero": 9, "texto": "Car ils ne comprenaient pas encore que, selon l''''Ecriture, Jésus devait ressusciter des morts."}, {"numero": 10, "texto": "Et les disciples s''''en retournèrent chez eux."}, {"numero": 11, "texto": "Cependant Marie se tenait dehors près du sépulcre, et pleurait. Comme elle pleurait, elle se baissa pour regarder dans le sépulcre;"}, {"numero": 12, "texto": "et elle vit deux anges vêtus de blanc, assis à la place où avait été couché le corps de Jésus, l''''un à la tête, l''''autre aux pieds."}, {"numero": 13, "texto": "Ils lui dirent: Femme, pourquoi pleures-tu? Elle leur répondit: Parce qu''''ils ont enlevé mon Seigneur, et je ne sais où ils l''''ont mis."}, {"numero": 14, "texto": "En disant cela, elle se retourna, et elle vit Jésus debout; mais elle ne savait pas que c''''était Jésus."}, {"numero": 15, "texto": "Jésus lui dit: Femme, pourquoi pleures-tu? Qui cherches-tu? Elle, pensant que c''''était le jardinier, lui dit: Seigneur, si c''''est toi qui l''''as emporté, dis-moi où tu l''''as mis, et je le prendrai."}, {"numero": 16, "texto": "Jésus lui dit: Marie! Elle se retourna, et lui dit en hébreu: Rabbouni! c''''est-à-dire, Maître!"}, {"numero": 17, "texto": "Jésus lui dit: Ne me touche pas; car je ne suis pas encore monté vers mon Père. Mais va trouver mes frères, et dis-leur que je monte vers mon Père et votre Père, vers mon Dieu et votre Dieu."}, {"numero": 18, "texto": "Marie de Magdala alla annoncer aux disciples qu''''elle avait vu le Seigneur, et qu''''il lui avait dit ces choses."}, {"numero": 19, "texto": "Le soir de ce jour, qui était le premier de la semaine, les portes du lieu où se trouvaient les disciples étant fermées, à cause de la crainte qu''''ils avaient des Juifs, Jésus vint, se présenta au milieu d''''eux, et leur dit: La paix soit avec vous!"}, {"numero": 20, "texto": "Et quand il eut dit cela, il leur montra ses mains et son côté. Les disciples furent dans la joie en voyant le Seigneur."}, {"numero": 21, "texto": "Jésus leur dit de nouveau: La paix soit avec vous! Comme le Père m''''a envoyé, moi aussi je vous envoie."}, {"numero": 22, "texto": "Après ces paroles, il souffla sur eux, et leur dit: Recevez le Saint-Esprit."}, {"numero": 23, "texto": "Ceux à qui vous pardonnerez les péchés, ils leur seront pardonnés; et ceux à qui vous les retiendrez, ils leur seront retenus."}, {"numero": 24, "texto": "Thomas, appelé Didyme, l''''un des douze, n''''était pas avec eux lorsque Jésus vint."}, {"numero": 25, "texto": "Les autres disciples lui dirent donc: Nous avons vu le Seigneur. Mais il leur dit: Si je ne vois dans ses mains la marque des clous, et si je ne mets mon doigt dans la marque des clous, et si je ne mets ma main dans son côté, je ne croirai point."}, {"numero": 26, "texto": "Huit jours après, les disciples de Jésus étaient de nouveau dans la maison, et Thomas se trouvait avec eux. Jésus vint, les portes étant fermées, se présenta au milieu d''''eux, et dit: La paix soit avec vous!"}, {"numero": 27, "texto": "Puis il dit à Thomas: Avance ici ton doigt, et regarde mes mains; avance aussi ta main, et mets-la dans mon côté; et ne sois pas incrédule, mais crois."}, {"numero": 28, "texto": "Thomas lui répondit: Mon Seigneur et mon Dieu!"}, {"numero": 29, "texto": "Jésus lui dit: Parce que tu m''''as vu, tu as cru. Heureux ceux qui n''''ont pas vu, et qui ont cru!"}, {"numero": 30, "texto": "Jésus a fait encore, en présence de ses disciples, beaucoup d''''autres miracles, qui ne sont pas écrits dans ce livre."}, {"numero": 31, "texto": "Mais ces choses ont été écrites afin que vous croyiez que Jésus est le Christ, le Fils de Dieu, et qu''''en croyant vous ayez la vie en son nom."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 20, 'es', '[{"numero": 1, "texto": "Y EL primer día de la semana, María Magdalena vino de mañana, siendo aún obscuro, al sepulcro; y vió la piedra quitada del sepulcro."}, {"numero": 2, "texto": "Entonces corrió, y vino á Simón Pedro, y al otro discípulo, al cual amaba Jesús, y les dice: Han llevado al Señor del sepulcro, y no sabemos dónde le han puesto."}, {"numero": 3, "texto": "Y salió Pedro, y el otro discípulo, y vinieron al sepulcro."}, {"numero": 4, "texto": "Y corrían los dos juntos; mas el otro discípulo corrió más presto que Pedro, y llegó primero al sepulcro."}, {"numero": 5, "texto": "Y bajándose á mirar, vió los lienzos echados; mas no entró."}, {"numero": 6, "texto": "Llegó luego Simón Pedro siguiéndole, y entró en el sepulcro, y vió los lienzos echados,"}, {"numero": 7, "texto": "Y el sudario, que había estado sobre su cabeza, no puesto con los lienzos, sino envuelto en un lugar aparte."}, {"numero": 8, "texto": "Y entonces entró también el otro discípulo, que había venido primero al sepulcro, y vió, y creyó."}, {"numero": 9, "texto": "Porque aun no sabían la Escritura, que era necesario que él resucitase de los muertos."}, {"numero": 10, "texto": "Y volvieron los discípulos á los suyos."}, {"numero": 11, "texto": "Empero María estaba fuera llorando junto al sepulcro: y estando llorando, bajóse á mirar el sepulcro;"}, {"numero": 12, "texto": "Y vió dos ángeles en ropas blancas que estaban sentados, el uno á la cabecera, y el otro á los pies, donde el cuerpo de Jesús había sido puesto."}, {"numero": 13, "texto": "Y dijéronle: Mujer, ¿por qué lloras? Díceles: Porque se han llevado á mi Señor, y no sé dónde le han puesto."}, {"numero": 14, "texto": "Y como hubo dicho esto, volvióse atrás, y vió á Jesús que estaba allí; mas no sabía que era Jesús."}, {"numero": 15, "texto": "Dícele Jesús: Mujer, ¿por qué lloras? ¿á quién buscas? Ella, pensando que era el hortelano, dícele: Señor, si tú lo has llevado, dime dónde lo has puesto, y yo lo llevaré."}, {"numero": 16, "texto": "Dícele Jesús: ¡María! Volviéndose ella, dícele: ¡Rabboni! que quiere decir, Maestro."}, {"numero": 17, "texto": "Dícele Jesús: No me toques: porque aun no he subido á mi Padre: mas ve á mis hermanos, y diles: Subo á mi Padre y á vuestro Padre, á mi Dios y á vuestro Dios."}, {"numero": 18, "texto": "Fué María Magdalena dando las nuevas á los discípulos de que había visto al Señor, y que él le había dicho estas cosas."}, {"numero": 19, "texto": "Y como fué tarde aquel día, el primero de la semana, y estando las puertas cerradas donde los discípulos estaban juntos por miedo de los Judíos, vino Jesús, y púsose en medio, y díjoles: Paz á vosotros."}, {"numero": 20, "texto": "Y como hubo dicho esto, mostróles las manos y el costado. Y los discípulos se gozaron viendo al Señor."}, {"numero": 21, "texto": "Entonces les dijo Jesús otra vez: Paz á vosotros; como me envió el Padre, así también yo os envío."}, {"numero": 22, "texto": "Y como hubo dicho esto, sopló, y díjoles: Tomad el Espíritu Santo:"}, {"numero": 23, "texto": "A los que remitiereis los pecados, les son remitidos: á quienes los retuviereis, serán retenidos."}, {"numero": 24, "texto": "Empero Tomás, uno de los doce, que se dice el Dídimo, no estaba con ellos cuando Jesús vino."}, {"numero": 25, "texto": "Dijéronle pues los otros discípulos: Al Señor hemos visto. Y él les dijo: Si no viere en sus manos la señal de los clavos, y metiere mi dedo en el lugar de los clavos, y metiere mi mano en su costado, no creeré."}, {"numero": 26, "texto": "Y ocho días después, estaban otra vez sus discípulos dentro, y con ellos Tomás. Vino Jesús, las puertas cerradas, y púsose en medio, y dijo: Paz á vosotros."}, {"numero": 27, "texto": "Luego dice á Tomás: Mete tu dedo aquí, y ve mis manos: y alarga acá tu mano, y métela en mi costado: y no seas incrédulo, sino fiel."}, {"numero": 28, "texto": "Entonces Tomás respondió, y díjole: ¡Señor mío, y Dios mío!"}, {"numero": 29, "texto": "Dícele Jesús: Porque me has visto, Tomás, creiste: bienaventurados los que no vieron y creyeron."}, {"numero": 30, "texto": "Y también hizo Jesús muchas otras señales en presencia de sus discípulos, que no están escritas en este libro."}, {"numero": 31, "texto": "Estas empero son escritas, para que creáis que Jesús es el Cristo, el Hijo de Dios; y para que creyendo, tengáis vida en su nombre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jo', 21, 'pt', '[{"numero": 1, "texto": "Depois disto Jesus se manifestou outra vez aos discípulos, junto ao mar de Tibérias; e manifestou [-se] assim:"}, {"numero": 2, "texto": "Estavam juntos Simão Pedro, e Tomé (chamado o Dídimo), e Natanael (o de Caná de Galileia), e os [filhos] de Zebedeu, e outros dois de seus discípulos."}, {"numero": 3, "texto": "Disse-lhes Simão Pedro: Vou pescar. Dizem-lhe eles: Também nós vamos contigo. Foram, e subiram logo no barco; e aquela noite nada pescaram."}, {"numero": 4, "texto": "E fazendo-se já manhã, Jesus se pôs na praia; porém os discípulos não sabiam que era Jesus."}, {"numero": 5, "texto": "Então Jesus lhes disse: Filhinhos, tendes [algo] para comer? Responderam-lhe: Não."}, {"numero": 6, "texto": "E ele lhes disse: Lançai a rede do lado direito do barco, e achareis. Lançaram-na pois, e já não a podiam tirar pela multidão dos peixes."}, {"numero": 7, "texto": "Disse pois aquele discípulo, a quem Jesus amava, a Pedro: É o Senhor! Ouvindo pois Simão Pedro que era o Senhor, vestiu-se com a roupa, (porque estava nu), e lançou-se ao mar."}, {"numero": 8, "texto": "E os outros discípulos vieram com o barquinho (porque não estavam longe da terra, mas sim a cerca de duzentos côvados) trazendo a rede de peixes."}, {"numero": 9, "texto": "Quando pois desceram à terra, viram já as brasas postas, e um peixe posto nelas, e mais pão."}, {"numero": 10, "texto": "Disse-lhes Jesus: Trazei dos peixes que pescastes agora."}, {"numero": 11, "texto": "Simão Pedro subiu, e puxou a rede para a terra, cheia de cento e cinquenta e três grandes peixes; e sendo tantos, a rede não se rompeu."}, {"numero": 12, "texto": "Disse-lhes Jesus: Vinde, jantai. E nenhum dos discípulos ousava lhe perguntar: Tu quem és? sabendo que era o Senhor."}, {"numero": 13, "texto": "Então Jesus veio, e tomou o pão, e deu-o a eles; e da mesma maneira o peixe."}, {"numero": 14, "texto": "E esta era já a terceira vez que Jesus se manifestou a seus discípulos, depois de haver ressuscitado dos mortos."}, {"numero": 15, "texto": "Havendo eles pois já jantado, disse Jesus a Simão Pedro: Simão [filho] de Jonas, tu me amas mais do que estes [outros] ? Disse-lhes ele: Sim, Senhor, tu sabes que te amo. Disse-lhe: Alimenta meus cordeiros."}, {"numero": 16, "texto": "Voltou a lhe a dizer a segunda vez: Simão, [filho] de Jonas, tu me amas? Disse-lhe: Sim, Senhor, tu sabes que te amo. Disse-lhe: Apascenta minhas ovelhas."}, {"numero": 17, "texto": "Disse-lhe a terceira vez: Simão, [filho] de Jonas, tu me amas? Entristeceu-se Pedro de que já pela terceira vez lhe dissesse: Tu me amas? E disse-lhe: Senhor, tu sabes todas as coisas, tu sabes que eu te amo. Disse-lhe Jesus: Alimenta minhas ovelhas."}, {"numero": 18, "texto": "Em verdade, em verdade te digo, que quando eras mais jovem, tu mesmo te vestias, e andava por onde querias; mas quando fores já velho, estenderás tuas mãos, e outro te vestirá, e te levará para onde tu não queres."}, {"numero": 19, "texto": "E disse isto, fazendo entender que [Pedro] glorificaria a Deus com [sua] morte. E tendo dito isto, [Jesus] lhe disse: Segue-me."}, {"numero": 20, "texto": "E virando-se Pedro, viu que [o] seguia aquele discípulo a quem Jesus amava, o que também na ceia se recostara a seu peito, e dissera: Senhor, quem é o que te trairá?"}, {"numero": 21, "texto": "Vendo Pedro a este, disse a Jesus: Senhor, e este, que [lhe acontecerá] ?"}, {"numero": 22, "texto": "Disse-lhe Jesus: Se eu quero que ele fique até que eu venha, que te importa? Segue-me tu."}, {"numero": 23, "texto": "Saiu, pois, esta conversa entre os irmãos, que aquele discípulo não morreria. Contudo Jesus não lhe disse que não morreria, mas sim: Se eu quero que ele fique até que eu venha, que te importa?"}, {"numero": 24, "texto": "Este é o discípulo que testemunha destas coisas, e estas coisas escreveu; e sabemos que seu testemunho é verdadeiro."}, {"numero": 25, "texto": "Ainda há, porém, muitas outras coisas que Jesus fez, que se sobre cada uma delas se escrevessem, penso que nem mesmo o mundo poderia caber os livros escritos. Amém."}]'::jsonb, 'Almeida Livre'),
  ('Jo', 21, 'en', '[{"numero": 1, "texto": "After these things Jesus shewed himself again to the disciples at the sea of Tiberias; and on this wise shewed he himself."}, {"numero": 2, "texto": "There were together Simon Peter, and Thomas called Didymus, and Nathanael of Cana in Galilee, and the sons of Zebedee, and two other of his disciples."}, {"numero": 3, "texto": "Simon Peter saith unto them, I go a fishing. They say unto him, We also go with thee. They went forth, and entered into a ship immediately; and that night they caught nothing."}, {"numero": 4, "texto": "But when the morning was now come, Jesus stood on the shore: but the disciples knew not that it was Jesus."}, {"numero": 5, "texto": "Then Jesus saith unto them, Children, have ye any meat? They answered him, No."}, {"numero": 6, "texto": "And he said unto them, Cast the net on the right side of the ship, and ye shall find. They cast therefore, and now they were not able to draw it for the multitude of fishes."}, {"numero": 7, "texto": "Therefore that disciple whom Jesus loved saith unto Peter, It is the Lord. Now when Simon Peter heard that it was the Lord, he girt his fisher''s coat unto him, (for he was naked,) and did cast himself into the sea."}, {"numero": 8, "texto": "And the other disciples came in a little ship; (for they were not far from land, but as it were two hundred cubits,) dragging the net with fishes."}, {"numero": 9, "texto": "As soon then as they were come to land, they saw a fire of coals there, and fish laid thereon, and bread."}, {"numero": 10, "texto": "Jesus saith unto them, Bring of the fish which ye have now caught."}, {"numero": 11, "texto": "Simon Peter went up, and drew the net to land full of great fishes, an hundred and fifty and three: and for all there were so many, yet was not the net broken."}, {"numero": 12, "texto": "Jesus saith unto them, Come and dine. And none of the disciples durst ask him, Who art thou? knowing that it was the Lord."}, {"numero": 13, "texto": "Jesus then cometh, and taketh bread, and giveth them, and fish likewise."}, {"numero": 14, "texto": "This is now the third time that Jesus shewed himself to his disciples, after that he was risen from the dead."}, {"numero": 15, "texto": "So when they had dined, Jesus saith to Simon Peter, Simon, son of Jonas, lovest thou me more than these? He saith unto him, Yea, Lord; thou knowest that I love thee. He saith unto him, Feed my lambs."}, {"numero": 16, "texto": "He saith to him again the second time, Simon, son of Jonas, lovest thou me? He saith unto him, Yea, Lord; thou knowest that I love thee. He saith unto him, Feed my sheep."}, {"numero": 17, "texto": "He saith unto him the third time, Simon, son of Jonas, lovest thou me? Peter was grieved because he said unto him the third time, Lovest thou me? And he said unto him, Lord, thou knowest all things; thou knowest that I love thee. Jesus saith unto him, Feed my sheep."}, {"numero": 18, "texto": "Verily, verily, I say unto thee, When thou wast young, thou girdest thyself, and walkedst whither thou wouldest: but when thou shalt be old, thou shalt stretch forth thy hands, and another shall gird thee, and carry thee whither thou wouldest not."}, {"numero": 19, "texto": "This spake he, signifying by what death he should glorify God. And when he had spoken this, he saith unto him, Follow me."}, {"numero": 20, "texto": "Then Peter, turning about, seeth the disciple whom Jesus loved following; which also leaned on his breast at supper, and said, Lord, which is he that betrayeth thee?"}, {"numero": 21, "texto": "Peter seeing him saith to Jesus, Lord, and what shall this man do?"}, {"numero": 22, "texto": "Jesus saith unto him, If I will that he tarry till I come, what is that to thee? follow thou me."}, {"numero": 23, "texto": "Then went this saying abroad among the brethren, that that disciple should not die: yet Jesus said not unto him, He shall not die; but, If I will that he tarry till I come, what is that to thee?"}, {"numero": 24, "texto": "This is the disciple which testifieth of these things, and wrote these things: and we know that his testimony is true."}, {"numero": 25, "texto": "And there are also many other things which Jesus did, the which, if they should be written every one, I suppose that even the world itself could not contain the books that should be written. Amen."}]'::jsonb, 'King James Version'),
  ('Jo', 21, 'fr', '[{"numero": 1, "texto": "Après cela, Jésus se montra encore aux disciples, sur les bords de la mer de Tibériade. Et voici de quelle manière il se montra."}, {"numero": 2, "texto": "Simon Pierre, Thomas, appelé Didyme, Nathanaël, de Cana en Galilée, les fils de Zébédée, et deux autres disciples de Jésus, étaient ensemble."}, {"numero": 3, "texto": "Simon Pierre leur dit: Je vais pêcher. Ils lui dirent: Nous allons aussi avec toi. Ils sortirent et montèrent dans une barque, et cette nuit-là ils ne prirent rien."}, {"numero": 4, "texto": "Le matin étant venu, Jésus se trouva sur le rivage; mais les disciples ne savaient pas que c''''était Jésus."}, {"numero": 5, "texto": "Jésus leur dit: Enfants, n''''avez-vous rien à manger? Ils lui répondirent: Non."}, {"numero": 6, "texto": "Il leur dit: Jetez le filet du côté droit de la barque, et vous trouverez. Ils le jetèrent donc, et ils ne pouvaient plus le retirer, à cause de la grande quantité de poissons."}, {"numero": 7, "texto": "Alors le disciple que Jésus aimait dit à Pierre: C''''est le Seigneur! Et Simon Pierre, dès qu''''il eut entendu que c''''était le Seigneur, mit son vêtement et sa ceinture, car il était nu, et se jeta dans la mer."}, {"numero": 8, "texto": "Les autres disciples vinrent avec la barque, tirant le filet plein de poissons, car ils n''''étaient éloignés de terre que d''''environ deux cents coudées."}, {"numero": 9, "texto": "Lorsqu''''ils furent descendus à terre, ils virent là des charbons allumés, du poisson dessus, et du pain."}, {"numero": 10, "texto": "Jésus leur dit: Apportez des poissons que vous venez de prendre."}, {"numero": 11, "texto": "Simon Pierre monta dans la barque, et tira à terre le filet plein de cent cinquante-trois grands poissons; et quoiqu''''il y en eût tant, le filet ne se rompit point."}, {"numero": 12, "texto": "Jésus leur dit: Venez, mangez. Et aucun des disciples n''''osait lui demander: Qui es-tu? sachant que c''''était le Seigneur."}, {"numero": 13, "texto": "Jésus s''''approcha, prit le pain, et leur en donna; il fit de même du poisson."}, {"numero": 14, "texto": "C''''était déjà la troisième fois que Jésus se montrait à ses disciples depuis qu''''il était ressuscité des morts."}, {"numero": 15, "texto": "Après qu''''ils eurent mangé, Jésus dit à Simon Pierre: Simon, fils de Jonas, m''''aimes-tu plus que ne m''''aiment ceux-ci? Il lui répondit: Oui, Seigneur, tu sais que je t''''aime. Jésus lui dit: Pais mes agneaux."}, {"numero": 16, "texto": "Il lui dit une seconde fois: Simon, fils de Jonas, m''''aimes-tu? Pierre lui répondit: Oui, Seigneur, tu sais que je t''''aime. Jésus lui dit: Pais mes brebis."}, {"numero": 17, "texto": "Il lui dit pour la troisième fois: Simon, fils de Jonas, m''''aimes-tu? Pierre fut attristé de ce qu''''il lui avait dit pour la troisième fois: M''''aimes-tu? Et il lui répondit: Seigneur, tu sais toutes choses, tu sais que je t''''aime. Jésus lui dit: Pais mes brebis."}, {"numero": 18, "texto": "En vérité, en vérité, je te le dis, quand tu étais plus jeune, tu te ceignais toi-même, et tu allais où tu voulais; mais quand tu seras vieux, tu étendras tes mains, et un autre te ceindra, et te mènera où tu ne voudras pas."}, {"numero": 19, "texto": "Il dit cela pour indiquer par quelle mort Pierre glorifierait Dieu. Et ayant ainsi parlé, il lui dit: Suis-moi."}, {"numero": 20, "texto": "Pierre, s''''étant retourné, vit venir après eux le disciple que Jésus aimait, celui qui, pendant le souper, s''''était penché sur la poitrine de Jésus, et avait dit: Seigneur, qui est celui qui te livre?"}, {"numero": 21, "texto": "En le voyant, Pierre dit à Jésus: Et celui-ci, Seigneur, que lui arrivera-t-il?"}, {"numero": 22, "texto": "Jésus lui dit: Si je veux qu''''il demeure jusqu''''à ce que je vienne, que t''''importe? Toi, suis-moi."}, {"numero": 23, "texto": "Là-dessus, le bruit courut parmi les frères que ce disciple ne mourrait point. Cependant Jésus n''''avait pas dit à Pierre qu''''il ne mourrait point; mais: Si je veux qu''''il demeure jusqu''''à ce que je vienne, que t''''importe?"}, {"numero": 24, "texto": "C''''est ce disciple qui rend témoignage de ces choses, et qui les a écrites. Et nous savons que son témoignage est vrai."}, {"numero": 25, "texto": "Jésus a fait encore beaucoup d''''autres choses; si on les écrivait en détail, je ne pense pas que le monde même pût contenir les livres qu''''on écrirait."}]'::jsonb, 'Louis Segond 1910'),
  ('Jo', 21, 'es', '[{"numero": 1, "texto": "DESPUÉS se manifestó Jesús otra vez á sus discípulos en la mar de Tiberias; y manifestóse de esta manera."}, {"numero": 2, "texto": "Estaban juntos Simón Pedro, y Tomás, llamado el Dídimo, y Natanael, el que era de Caná de Galilea, y los hijos de Zebedeo, y otros dos de sus discípulos."}, {"numero": 3, "texto": "Díceles Simón: A pescar voy. Dícenle: Vamos nosotros también contigo. Fueron, y subieron en una barca; y aquella noche no cogieron nada."}, {"numero": 4, "texto": "Y venida la mañana, Jesús se puso á la ribera: mas los discípulos no entendieron que era Jesús."}, {"numero": 5, "texto": "Y díjoles: Mozos, ¿tenéis algo de comer? Respondiéronle: No."}, {"numero": 6, "texto": "Y él les dice: Echad la red á la mano derecha del barco, y hallaréis. Entonces la echaron, y no la podían en ninguna manera sacar, por la multitud de los peces."}, {"numero": 7, "texto": "Entonces aquel discípulo, al cual amaba Jesús, dijo á Pedro: El Señor es. Y Simón Pedro, como oyó que era el Señor, ciñóse la ropa, porque estaba desnudo, y echóse á la mar."}, {"numero": 8, "texto": "Y los otros discípulos vinieron con el barco (porque no estaban lejos de tierra sino como doscientos codos), trayendo la red de peces."}, {"numero": 9, "texto": "Y como descendieron á tierra, vieron ascuas puestas, y un pez encima de ellas, y pan."}, {"numero": 10, "texto": "Díceles Jesús: Traed de los peces que cogisteis ahora."}, {"numero": 11, "texto": "Subió Simón Pedro, y trajo la red á tierra, llena de grandes peces, ciento cincuenta y tres: y siendo tantos, la red no se rompió."}, {"numero": 12, "texto": "Díceles Jesús: Venid, comed. Y ninguno de los discípulos osaba preguntarle: ¿Tú, quién eres? sabiendo que era el Señor."}, {"numero": 13, "texto": "Viene pues Jesús, y toma el pan, y les da; y asimismo del pez."}, {"numero": 14, "texto": "Esta era ya la tercera vez que Jesús se manifestó á sus discípulos, habiendo resucitado de los muertos."}, {"numero": 15, "texto": "Y cuando hubieron comido, Jesús dijo á Simón Pedro: Simón, hijo de Jonás, ¿me amas más que éstos? Dícele: Sí, Señor: tú sabes que te amo. Dícele: Apacienta mis corderos."}, {"numero": 16, "texto": "Vuélvele á decir la segunda vez: Simón, hijo de Jonás, ¿me amas? Respóndele: Sí, Señor: tú sabes que te amo. Dícele: Apacienta mis ovejas."}, {"numero": 17, "texto": "Dícele la tercera vez: Simón, hijo de Jonás, ¿me amas? Entristecióse Pedro de que le dijese la tercera vez: ¿Me amas? y dícele: Señor, tú sabes todas las cosas; tú sabes que te amo. Dícele Jesús: Apacienta mis ovejas."}, {"numero": 18, "texto": "De cierto, de cierto te digo: Cuando eras más mozo, te ceñías, é ibas donde querías; mas cuando ya fueres viejo, extenderás tus manos, y te ceñirá otro, y te llevará á donde no quieras."}, {"numero": 19, "texto": "Y esto dijo, dando á entender con qué muerte había de glorificar á Dios. Y dicho esto, dícele: Sígueme."}, {"numero": 20, "texto": "Volviéndose Pedro, ve á aquel discípulo al cual amaba Jesús, que seguía, el que también se había recostado á su pecho en la cena, y le había dicho: Señor, ¿quién es el que te ha de entregar?"}, {"numero": 21, "texto": "Así que Pedro vió á éste, dice á Jesús: Señor, ¿y éste, qué?"}, {"numero": 22, "texto": "Dícele Jesús: Si quiero que él quede hasta que yo venga, ¿qué á tí? Sígueme tú."}, {"numero": 23, "texto": "Salió entonces este dicho entre los hermanos, que aquel discípulo no había de morir. Mas Jesús no le dijo, No morirá; sino: Si quiero que él quede hasta que yo venga ¿qué á ti?"}, {"numero": 24, "texto": "Este es aquel discípulo que da testimonio de estas cosas, y escribió estas cosas: y sabemos que su testimonio es verdadero."}, {"numero": 25, "texto": "Y hay también otras muchas cosas que hizo Jesús, que si se escribiesen cada una por sí, ni aun en el mundo pienso que cabrían los libros que se habrían de escribir. Amén."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jr', 9, 'pt', '[{"numero": 1, "texto": "Ah, se minha cabeça se tornasse em águas, e meus olhos em um manancial de águas! Então eu choraria dia e noite pelos mortos da filha de meu povo."}, {"numero": 2, "texto": "Ah, se houvesse para mim no deserto uma hospedaria para caminhantes! Então eu deixaria o meu povo, e me afastaria deles; pois todos eles são adúlteros, são um bando de traiçoeiros."}, {"numero": 3, "texto": "Eles estendem suas línguas, como [se] lhes fossem arcos, para atirarem mentira; e se fortaleceram na terra, mas não por meio da verdade; porque se avançam de mal em mal, e não me conhecem, diz o SENHOR."}, {"numero": 4, "texto": "Guardai-vos cada um de seu amigo, nem em irmão algum tende confiança: porque todo irmão só faz enganar, e todo amigo anda com falsidades."}, {"numero": 5, "texto": "E cada um engana a seu amigo, e não falam a verdade; ensinaram sua língua a falar mentira, e agem perversamente até se cansarem."}, {"numero": 6, "texto": "Tua habitação é em meio ao engano; por meio do engano se negam a me conhecer,diz o SENHOR."}, {"numero": 7, "texto": "Portanto assim diz o SENHOR dos exércitos: Eis que que eu os fundirei, e os provarei; pois de que [outra maneira] agiria eu com a filha de meu povo?"}, {"numero": 8, "texto": "A língua deles é uma flecha mortífera, que fala engano; com sua boca fala paz com seu próximo, mas em seu interior lhe arma ciladas."}, {"numero": 9, "texto": "Por acaso eu não os puniria por estas coisas? Diz o SENHOR. Por acaso minha alma não se vingaria de tal nação?"}, {"numero": 10, "texto": "Sobre os montes levantarei choro e pranto, e lamentação as moradas do deserto; porque foram desoladas até não haver quem [por ali] passe, nem [ali] se ouve bramido de gado; desde as aves do céu e até os animais da terra fugiram, e foram embora."}, {"numero": 11, "texto": "E tornarei Jerusalém em amontoados [de pedras] ,para morada de chacais; e tornarei as cidades de Judá em ruínas, de modo que não haja morador."}, {"numero": 12, "texto": "Quem é homem sábio, que entenda isto? E a quem falou a boca do SENHOR, para que possa anunciá-lo? Por que razão a terra pereceu, queimada como deserto, de modo que não há quem [nela] passe?"}, {"numero": 13, "texto": "E disse o SENHOR: Foi porque abandonaram minha lei, que dei diante deles, nem deram ouvidos a minha voz, nem caminharam conforme a ela;"}, {"numero": 14, "texto": "Ao invés disso, eles seguiram atrás da teimosia de seu coração, e atrás dos Baalins, que seus pais lhes ensinaram."}, {"numero": 15, "texto": "Por isso assim diz o SENHOR dos exércitos, Deus de Israel: Eis que a este povo eu lhes darei de comer absinto, e lhes darei de beber água de fel."}, {"numero": 16, "texto": "E os espalharei entre nações que nem eles, nem seus pais conheceram; e mandarei espada atrás deles, até que eu os acabe."}, {"numero": 17, "texto": "Assim diz o SENHOR dos exércitos: Considerai, e chamai carpideiras, que venham; e enviai as mais hábeis, que venham:"}, {"numero": 18, "texto": "E se apressem, e levantem pranto sobre nós, e desfaçam-se nossos olhos em lágrimas, e nossas pálpebras se destilem em águas."}, {"numero": 19, "texto": "Porque uma voz de pranto foi ouvida de Sião: Como fomos destruídos! Nós nos tornamos muito envergonhados, por termos deixado a terra, por nossas moradas terem sido arruinadas."}, {"numero": 20, "texto": "Ouvi pois, vós mulheres, a palavra do SENHOR, e vossos ouvidos recebam a palavra de sua boca; e ensinai pranto a vossas filhas, e cada uma lamentação a sua companheira."}, {"numero": 21, "texto": "Porque a morte subiu a nossas janelas, [e] entrou em nossos palácios; para arrancar os meninos das ruas, os rapazes das praças."}, {"numero": 22, "texto": "Fala: Assim disse o SENHOR: Os cadáveres dos homens cairão como esterco sobre a face do campo, e como espigas de cereal atrás do ceifeiro, que não há quem as recolha."}, {"numero": 23, "texto": "Assim diz o SENHOR: Não se orgulhe o sábio em sua sabedoria, nem o valente se orgulhe em sua valentia, nem o rico se orgulhe em suas riquezas."}, {"numero": 24, "texto": "Mas aquele que se orgulhar, orgulhe-se nisto: em me entender e me conhecer, que eu sou o SENHOR, que faço bondade, juízo, e justiça na terra; porque destas coisas eu me agrado,diz o SENHOR."}, {"numero": 25, "texto": "Eis que vêm dias, diz o SENHOR, em que castigarei todo circunciso e todo incircunciso:"}, {"numero": 26, "texto": "A Egito, a Judá, a Edom, aos filhos de Amom e de Moabe, e a todos os dos cantos mais distantes, que moram no deserto; pois todas as nações são incircuncisas; mas toda a casa de Israel é incircuncisa no coração."}]'::jsonb, 'Almeida Livre'),
  ('Jr', 9, 'en', '[{"numero": 1, "texto": "Oh that my head were waters, and mine eyes a fountain of tears, that I might weep day and night for the slain of the daughter of my people!"}, {"numero": 2, "texto": "Oh that I had in the wilderness a lodging place of wayfaring men; that I might leave my people, and go from them! for they be all adulterers, an assembly of treacherous men."}, {"numero": 3, "texto": "And they bend their tongues like their bow for lies: but they are not valiant for the truth upon the earth; for they proceed from evil to evil, and they know not me, saith the Lord."}, {"numero": 4, "texto": "Take ye heed every one of his neighbour, and trust ye not in any brother: for every brother will utterly supplant, and every neighbour will walk with slanders."}, {"numero": 5, "texto": "And they will deceive every one his neighbour, and will not speak the truth: they have taught their tongue to speak lies, and weary themselves to commit iniquity."}, {"numero": 6, "texto": "Thine habitation is in the midst of deceit; through deceit they refuse to know me, saith the Lord."}, {"numero": 7, "texto": "Therefore thus saith the Lord of hosts, Behold, I will melt them, and try them; for how shall I do for the daughter of my people?"}, {"numero": 8, "texto": "Their tongue is as an arrow shot out; it speaketh deceit: one speaketh peaceably to his neighbour with his mouth, but in heart he layeth his wait."}, {"numero": 9, "texto": "Shall I not visit them for these things? saith the Lord: shall not my soul be avenged on such a nation as this?"}, {"numero": 10, "texto": "For the mountains will I take up a weeping and wailing, and for the habitations of the wilderness a lamentation, because they are burned up, so that none can pass through them; neither can men hear the voice of the cattle; both the fowl of the heavens and the beast are fled; they are gone."}, {"numero": 11, "texto": "And I will make Jerusalem heaps, and a den of dragons; and I will make the cities of Judah desolate, without an inhabitant."}, {"numero": 12, "texto": "Who is the wise man, that may understand this? and who is he to whom the mouth of the Lord hath spoken, that he may declare it, for what the land perisheth and is burned up like a wilderness, that none passeth through?"}, {"numero": 13, "texto": "And the Lord saith, Because they have forsaken my law which I set before them, and have not obeyed my voice, neither walked therein;"}, {"numero": 14, "texto": "But have walked after the imagination of their own heart, and after Baalim, which their fathers taught them:"}, {"numero": 15, "texto": "Therefore thus saith the Lord of hosts, the God of Israel; Behold, I will feed them, even this people, with wormwood, and give them water of gall to drink."}, {"numero": 16, "texto": "I will scatter them also among the heathen, whom neither they nor their fathers have known: and I will send a sword after them, till I have consumed them."}, {"numero": 17, "texto": "Thus saith the Lord of hosts, Consider ye, and call for the mourning women, that they may come; and send for cunning women, that they may come:"}, {"numero": 18, "texto": "And let them make haste, and take up a wailing for us, that our eyes may run down with tears, and our eyelids gush out with waters."}, {"numero": 19, "texto": "For a voice of wailing is heard out of Zion, How are we spoiled! we are greatly confounded, because we have forsaken the land, because our dwellings have cast us out."}, {"numero": 20, "texto": "Yet hear the word of the Lord, O ye women, and let your ear receive the word of his mouth, and teach your daughters wailing, and every one her neighbour lamentation."}, {"numero": 21, "texto": "For death is come up into our windows, and is entered into our palaces, to cut off the children from without, and the young men from the streets."}, {"numero": 22, "texto": "Speak, Thus saith the Lord, Even the carcases of men shall fall as dung upon the open field, and as the handful after the harvestman, and none shall gather them."}, {"numero": 23, "texto": "Thus saith the Lord, Let not the wise man glory in his wisdom, neither let the mighty man glory in his might, let not the rich man glory in his riches:"}, {"numero": 24, "texto": "But let him that glorieth glory in this, that he understandeth and knoweth me, that I am the Lord which exercise lovingkindness, judgment, and righteousness, in the earth: for in these things I delight, saith the Lord."}, {"numero": 25, "texto": "Behold, the days come, saith the Lord, that I will punish all them which are circumcised with the uncircumcised;"}, {"numero": 26, "texto": "Egypt, and Judah, and Edom, and the children of Ammon, and Moab, and all that are in the utmost corners, that dwell in the wilderness: for all these nations are uncircumcised, and all the house of Israel are uncircumcised in the heart."}]'::jsonb, 'King James Version'),
  ('Jr', 9, 'fr', '[{"numero": 1, "texto": "Oh! si ma tête était remplie d''''eau, Si mes yeux étaient une source de larmes, Je pleurerais jour et nuit Les morts de la fille de mon peuple!"}, {"numero": 2, "texto": "Oh! si j''''avais au désert une cabane de voyageurs, J''''abandonnerais mon peuple, je m''''en éloignerais! Car ce sont tous des adultères, C''''est une troupe de perfides."}, {"numero": 3, "texto": "Ils ont la langue tendue comme un arc et lancent le mensonge; Ce n''''est pas par la vérité qu''''ils sont puissants dans le pays; Car ils vont de méchanceté en méchanceté, Et ils ne me connaissent pas, dit l''''Eternel."}, {"numero": 4, "texto": "Que chacun se tienne en garde contre son ami, Et qu''''on ne se fie à aucun de ses frères; Car tout frère cherche à tromper, Et tout ami répand des calomnies."}, {"numero": 5, "texto": "Ils se jouent les uns des autres, Et ne disent point la vérité; Ils exercent leur langue à mentir, Ils s''''étudient à faire le mal."}, {"numero": 6, "texto": "Ta demeure est au sein de la fausseté; C''''est par fausseté qu''''ils refusent de me connaître, Dit l''''Eternel."}, {"numero": 7, "texto": "C''''est pourquoi ainsi parle l''''Eternel des armées: Voici je les sonderai, je les éprouverai. Car comment agir à l''''égard de la fille de mon peuple?"}, {"numero": 8, "texto": "Leur langue est un trait meurtrier, Ils ne disent que des mensonges; De la bouche ils parlent de paix à leur prochain, Et au fond du coeur ils lui dressent des pièges."}, {"numero": 9, "texto": "Ne les châtierais-je pas pour ces choses-là, dit l''''Eternel, Ne me vengerais-je pas d''''une pareille nation?"}, {"numero": 10, "texto": "Sur les montagnes je veux pleurer et gémir, Sur les plaines du désert je prononce une complainte; Car elles sont brûlées, personne n''''y passe, On n''''y entend plus la voix des troupeaux; Les oiseaux du ciel et les bêtes ont pris la fuite, ont disparu. -"}, {"numero": 11, "texto": "Je ferai de Jérusalem un monceau de ruines, un repaire de chacals, Et je réduirai les villes de Juda en un désert sans habitants. -"}, {"numero": 12, "texto": "Où est l''''homme sage qui comprenne ces choses? Qu''''il le dise, celui à qui la bouche de l''''Eternel a parlé! Pourquoi le pays est-il détruit, Brûlé comme un désert où personne ne passe?"}, {"numero": 13, "texto": "L''''Eternel dit: C''''est parce qu''''ils ont abandonné ma loi, Que j''''avais mise devant eux; Parce qu''''ils n''''ont point écouté ma voix, Et qu''''ils ne l''''ont point suivie;"}, {"numero": 14, "texto": "Parce qu''''ils ont suivi les penchants de leur coeur, Et qu''''ils sont allés après les Baals, Comme leurs pères le leur ont appris."}, {"numero": 15, "texto": "C''''est pourquoi ainsi parle l''''Eternel des armées, le Dieu d''''Israël: Voici, je vais nourrir ce peuple d''''absinthe, Et je lui ferai boire des eaux empoisonnées."}, {"numero": 16, "texto": "Je les disperserai parmi des nations Que n''''ont connues ni eux ni leurs pères, Et j''''enverrai derrière eux l''''épée, Jusqu''''à ce que je les aie exterminés."}, {"numero": 17, "texto": "Ainsi parle l''''Eternel des armées: Cherchez, appelez les pleureuses, et qu''''elles viennent! Envoyez vers les femmes habiles, et qu''''elles viennent!"}, {"numero": 18, "texto": "Qu''''elles se hâtent de dire sur nous une complainte! Et que les larmes tombent de nos yeux, Que l''''eau coule de nos paupières!"}, {"numero": 19, "texto": "Car des cris lamentables se font entendre de Sion: Eh quoi! nous sommes détruits! Nous sommes couverts de honte! Il nous faut abandonner le pays! On a renversé nos demeures! -"}, {"numero": 20, "texto": "Femmes, écoutez la parole de l''''Eternel, Et que votre oreille saisisse ce que dit sa bouche! Apprenez à vos filles des chants lugubres, Enseignez-vous des complaintes les unes aux autres!"}, {"numero": 21, "texto": "Car la mort est montée par nos fenêtres, Elle a pénétré dans nos palais; Elle extermine les enfants dans la rue, Les jeunes gens sur les places."}, {"numero": 22, "texto": "Dis: Ainsi parle l''''Eternel: Les cadavres des hommes tomberont Comme du fumier sur les champs, Comme tombe derrière le moissonneur une gerbe Que personne ne ramasse."}, {"numero": 23, "texto": "Ainsi parle l''''Eternel: Que le sage ne se glorifie pas de sa sagesse, Que le fort ne se glorifie pas de sa force, Que le riche ne se glorifie pas de sa richesse."}, {"numero": 24, "texto": "Mais que celui qui veut se glorifier se glorifie D''''avoir de l''''intelligence et de me connaître, De savoir que je suis l''''Eternel, Qui exerce la bonté, le droit et la justice sur la terre; Car c''''est à cela que je prends plaisir, dit l''''Eternel."}, {"numero": 25, "texto": "Voici, les jours viennent, dit l''''Eternel, Où je châtierai tous les circoncis qui ne le sont pas de coeur,"}, {"numero": 26, "texto": "L''''Egypte, Juda, Edom, les enfants d''''Ammon, Moab, Tous ceux qui se rasent les coins de la barbe, Ceux qui habitent dans le désert; Car toutes les nations sont incirconcises, Et toute la maison d''''Israël a le coeur incirconcis."}]'::jsonb, 'Louis Segond 1910'),
  ('Jr', 9, 'es', '[{"numero": 1, "texto": "¡OH si mi cabeza se tornase aguas, y mis ojos fuentes de aguas, para que llore día y noche los muertos de la hija de mi pueblo!"}, {"numero": 2, "texto": "¡Oh quién me diese en el desierto un mesón de caminantes, para que dejase mi pueblo, y de ellos me apartase! Porque todos ellos son adúlteros, congregación de prevaricadores."}, {"numero": 3, "texto": "E hicieron que su lengua, como su arco, tirase mentira; y no se fortalecieron por verdad en la tierra: porque de mal en mal procedieron, y me han desconocido, dice Jehová."}, {"numero": 4, "texto": "Guárdese cada uno de su compañero, ni en ningún hermano tenga confianza: porque todo hermano engaña con falacia, y todo compañero anda con falsedades."}, {"numero": 5, "texto": "Y cada uno engaña á su compañero, y no hablan verdad: enseñaron su lengua á hablar mentira, se ocupan de hacer perversamente."}, {"numero": 6, "texto": "Tu morada es en medio de engaño; de muy engañadores no quisieron conocerme, dice Jehová."}, {"numero": 7, "texto": "Por tanto, así ha dicho Jehová de los ejércitos: He aquí que yo los fundiré, y los ensayaré; porque ¿cómo he de hacer por la hija de mi pueblo?"}, {"numero": 8, "texto": "Saeta afilada es la lengua de ellos; engaño habla; con su boca habla paz con su amigo, y dentro de sí pone sus asechanzas."}, {"numero": 9, "texto": "¿No los tengo de visitar sobre estas cosas? dice Jehová. ¿De tal gente no se vengará mi alma?"}, {"numero": 10, "texto": "Sobre los montes levantaré lloro y lamentación, y llanto sobre las moradas del desierto; porque desolados fueron hasta no quedar quien pase, ni oyeron bramido de ganado: desde las aves del cielo y hasta las bestias de la tierra se trasportaron, y se fueron."}, {"numero": 11, "texto": "Y pondré á Jerusalem en montones, por morada de culebras; y pondré las ciudades de Judá en asolamiento, que no quede morador."}, {"numero": 12, "texto": "¿Quién es varón sabio que entienda esto? ¿y á quién habló la boca de Jehová, para que pueda declararlo? ¿Por qué causa la tierra ha perecido, ha sido asolada como desierto, que no hay quien pase?"}, {"numero": 13, "texto": "Y dijo Jehová: Porque dejaron mi ley, la cual dí delante de ellos, y no obedecieron á mi voz, ni caminaron conforme á ella;"}, {"numero": 14, "texto": "Antes se fueron tras la imaginación de su corazón, y en pos de los Baales que les enseñaron sus padres:"}, {"numero": 15, "texto": "Por tanto, así ha dicho Jehová de los ejércitos, Dios de Israel: He aquí que á este pueblo yo les daré á comer ajenjos, y les daré á beber aguas de hiel."}, {"numero": 16, "texto": "Y los esparciré entre gentes que no conocieron ellos ni sus padres; y enviaré espada en pos de ellos, hasta que yo los acabe."}, {"numero": 17, "texto": "Así dice Jehová de los ejércitos: Considerad, y llamad plañideras que vengan; y enviad por las sabias que vengan:"}, {"numero": 18, "texto": "Y dense prisa, y levanten llanto sobre nosotros, y córranse nuestros ojos en lágrimas, y nuestros párpados en aguas se destilen."}, {"numero": 19, "texto": "Porque voz de endecha fué oída de Sión: ¡Cómo hemos sido destruídos! en gran manera hemos sido confundidos. ¿Por qué dejamos la tierra? ¿por qué nos han echado de sí nuestras moradas?"}, {"numero": 20, "texto": "Oid pues, oh mujeres, palabra de Jehová, y vuestro oído reciba la palabra de su boca; y enseñad endechas á vuestras hijas, y cada una á su amiga, lamentación."}, {"numero": 21, "texto": "Porque la muerte ha subido por nuestras ventanas, ha entrado en nuestros palacios; para talar los niños de las calles, los mancebos de las plazas."}, {"numero": 22, "texto": "Habla: Así ha dicho Jehová: Los cuerpos de los hombres muertos caerán como estiércol sobre la haz del campo, y como manojo tras el segador, que no hay quien lo recoja."}, {"numero": 23, "texto": "Así dijo Jehová: No se alabe el sabio en su sabiduría, ni en su valentía se alabe el valiente, ni el rico se alabe en sus riquezas."}, {"numero": 24, "texto": "Mas alábese en esto el que se hubiere de alabar: en entenderme y conocerme, que yo soy Jehová, que hago misericordia, juicio, y justicia en la tierra: porque estas cosas quiero, dice Jehová."}, {"numero": 25, "texto": "He aquí que vienen días, dice Jehová, y visitaré sobre todo circuncidado, y sobre todo incircunciso:"}, {"numero": 26, "texto": "A Egipto, y á Judá, y á Edom, y á los hijos de Ammón y de Moab, y á todos los arrinconados en el postrer rincón, que moran en el desierto; porque todas las gentes tienen prepucio, y toda la casa de Israel tiene prepucio en el corazón."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jr', 10, 'pt', '[{"numero": 1, "texto": "Ouvi a palavra que o SENHOR fala sobre vós, ó casa de Israel."}, {"numero": 2, "texto": "Assim diz o SENHOR: Não aprendais o caminho das nações, nem vos espanteis dos sinais do céu; ainda que as nações as temam."}, {"numero": 3, "texto": "Porque as ordenanças dos povos são inúteis; pois cortam madeira do bosque, obra de mãos de artífice, com machado."}, {"numero": 4, "texto": "Com prata e ouro a enfeitam; com pregos e martelo a firmam, para que não se abale."}, {"numero": 5, "texto": "São como espantalhos numa plantação, não podem falar; têm que ser levados, pois não podem andar. Não tenhais temor deles; pois nem podem fazer o mal, nem neles há [capacidade de fazer] o bem."}, {"numero": 6, "texto": "Pois ninguém há semelhante a ti, SENHOR! Grande és tu, e grande é teu nome em poder!"}, {"numero": 7, "texto": "Quem não temeria a ti, ó Rei das nações? Porque a ti pertence [o temor] ; porque entre todos os sábios das nações, e em todos seus reinos, não há semelhante a ti."}, {"numero": 8, "texto": "E juntamente se tornaram irracionais e tolos. Ensino inútil é o [ídolo] de madeira."}, {"numero": 9, "texto": "Trazem prata estendida de Társis, e ouro de Ufaz; [para] trabalho do artífice, e das mãos do fundidor; eles os vestem de azul celeste e de púrpura; todos eles são obra de [trabalhadores] habilidosos."}, {"numero": 10, "texto": "Mas o SENHOR Deus é a verdade; ele é Deus vivo e o Rei eterno; a terra treme pela sua ira, e as nações não podem suportar sua fúria."}, {"numero": 11, "texto": "Assim lhes direis: Os deuses que não fizeram os céus nem a terra perecerão da terra e de debaixo deste céu."}, {"numero": 12, "texto": "[Mas o SENHOR] é aquele que fez a terra com seu poder, que preparou o mundo com sua sabedoria, e estendeu os céus com seu entendimento."}, {"numero": 13, "texto": "Quando ele pronuncia sua voz, [logo] há ruído de águas no céu, e faz subir vapores dos confins da terra; faz os relâmpagos com a chuva, e faz sair o vento de seus tesouros."}, {"numero": 14, "texto": "Todo homem se tornou irracional e sem conhecimento; envergonha-se todo fundidor de imagem de escultura, pois sua imagem fundida é uma mentira, e nelas não há espírito."}, {"numero": 15, "texto": "Elas são inúteis, obras de engano; no tempo de sua punição, virão a perecer."}, {"numero": 16, "texto": "A Porção de Jacó não é como eles; porque ele é o Formador de tudo, e Israel é a tribo de sua herança; EU-SOU dos exércitos é o seu nome."}, {"numero": 17, "texto": "Recolhe tuas mercadorias da terra; tu que habitas em cerco,"}, {"numero": 18, "texto": "Porque assim diz o SENHOR: Eis que desta vez lançarei como que por uma funda aos moradores da terra; e eu os oprimirei, de modo que sejam achados [em opressão] ."}, {"numero": 19, "texto": "Ai de mim, por causa do meu quebrantamento! Minha ferida [me] causa grande dor. E eu havia dito: Isto de fato é uma enfermidade, e terei que suportá-la."}, {"numero": 20, "texto": "Minha tenda está destruída, e todas as minhas cordas arrebentadas; meus filhos saíram [de perto] de mim, e nenhum deles há; ninguém há que estenda minha tenda, nem que levante minhas cortinas;"}, {"numero": 21, "texto": "Porque os pastores se tornaram irracionais, e não buscaram ao SENHOR; por isso não agiram prudentemente, e todo o seu rebanho se dispersou."}, {"numero": 22, "texto": "Eis que vem uma voz de aviso, e um grande tremor da terra do norte; para tornar em desolação as cidades de Judá, em morada de chacais."}, {"numero": 23, "texto": "Eu sei, SENHOR, que não pertence ao homem o seu caminho, nem ao homem que anda a direção de seus passos."}, {"numero": 24, "texto": "Corrige-me, SENHOR, porém com moderação; não em tua ira, para que não me destruas."}, {"numero": 25, "texto": "Derrama tua ira sobre as nações que não te conhecem, e sobre os povos que não invocam o teu nome; pois devoraram a Jacó; eles o devoraram, consumiram e assolaram sua morada."}]'::jsonb, 'Almeida Livre'),
  ('Jr', 10, 'en', '[{"numero": 1, "texto": "Hear ye the word which the Lord speaketh unto you, O house of Israel:"}, {"numero": 2, "texto": "Thus saith the Lord, Learn not the way of the heathen, and be not dismayed at the signs of heaven; for the heathen are dismayed at them."}, {"numero": 3, "texto": "For the customs of the people are vain: for one cutteth a tree out of the forest, the work of the hands of the workman, with the axe."}, {"numero": 4, "texto": "They deck it with silver and with gold; they fasten it with nails and with hammers, that it move not."}, {"numero": 5, "texto": "They are upright as the palm tree, but speak not: they must needs be borne, because they cannot go. Be not afraid of them; for they cannot do evil, neither also is it in them to do good."}, {"numero": 6, "texto": "Forasmuch as there is none like unto thee, O Lord; thou art great, and thy name is great in might."}, {"numero": 7, "texto": "Who would not fear thee, O King of nations? for to thee doth it appertain: forasmuch as among all the wise men of the nations, and in all their kingdoms, there is none like unto thee."}, {"numero": 8, "texto": "But they are altogether brutish and foolish: the stock is a doctrine of vanities."}, {"numero": 9, "texto": "Silver spread into plates is brought from Tarshish, and gold from Uphaz, the work of the workman, and of the hands of the founder: blue and purple is their clothing: they are all the work of cunning men."}, {"numero": 10, "texto": "But the Lord is the true God, he is the living God, and an everlasting king: at his wrath the earth shall tremble, and the nations shall not be able to abide his indignation."}, {"numero": 11, "texto": "Thus shall ye say unto them, The gods that have not made the heavens and the earth, even they shall perish from the earth, and from under these heavens."}, {"numero": 12, "texto": "He hath made the earth by his power, he hath established the world by his wisdom, and hath stretched out the heavens by his discretion."}, {"numero": 13, "texto": "When he uttereth his voice, there is a multitude of waters in the heavens, and he causeth the vapours to ascend from the ends of the earth; he maketh lightnings with rain, and bringeth forth the wind out of his treasures."}, {"numero": 14, "texto": "Every man is brutish in his knowledge: every founder is confounded by the graven image: for his molten image is falsehood, and there is no breath in them."}, {"numero": 15, "texto": "They are vanity, and the work of errors: in the time of their visitation they shall perish."}, {"numero": 16, "texto": "The portion of Jacob is not like them: for he is the former of all things; and Israel is the rod of his inheritance: The Lord of hosts is his name."}, {"numero": 17, "texto": "Gather up thy wares out of the land, O inhabitant of the fortress."}, {"numero": 18, "texto": "For thus saith the Lord, Behold, I will sling out the inhabitants of the land at this once, and will distress them, that they may find it so."}, {"numero": 19, "texto": "Woe is me for my hurt! my wound is grievous; but I said, Truly this is a grief, and I must bear it."}, {"numero": 20, "texto": "My tabernacle is spoiled, and all my cords are broken: my children are gone forth of me, and they are not: there is none to stretch forth my tent any more, and to set up my curtains."}, {"numero": 21, "texto": "For the pastors are become brutish, and have not sought the Lord: therefore they shall not prosper, and all their flocks shall be scattered."}, {"numero": 22, "texto": "Behold, the noise of the bruit is come, and a great commotion out of the north country, to make the cities of Judah desolate, and a den of dragons."}, {"numero": 23, "texto": "O Lord, I know that the way of man is not in himself: it is not in man that walketh to direct his steps."}, {"numero": 24, "texto": "O Lord, correct me, but with judgment; not in thine anger, lest thou bring me to nothing."}, {"numero": 25, "texto": "Pour out thy fury upon the heathen that know thee not, and upon the families that call not on thy name: for they have eaten up Jacob, and devoured him, and consumed him, and have made his habitation desolate."}]'::jsonb, 'King James Version'),
  ('Jr', 10, 'fr', '[{"numero": 1, "texto": "Ecoutez la parole que l''''Eternel vous adresse, Maison d''''Israël!"}, {"numero": 2, "texto": "Ainsi parle l''''Eternel: N''''imitez pas la voie des nations, Et ne craignez pas les signes du ciel, Parce que les nations les craignent."}, {"numero": 3, "texto": "Car les coutumes des peuples ne sont que vanité. On coupe le bois dans la forêt; La main de l''''ouvrier le travaille avec la hache;"}, {"numero": 4, "texto": "On l''''embellit avec de l''''argent et de l''''or, On le fixe avec des clous et des marteaux, Pour qu''''il ne branle pas."}, {"numero": 5, "texto": "Ces dieux sont comme une colonne massive, et ils ne parlent point; On les porte, parce qu''''ils ne peuvent marcher. Ne les craignez pas, car ils ne sauraient faire aucun mal, Et ils sont incapables de faire du bien."}, {"numero": 6, "texto": "Nul n''''est semblable à toi, ô Eternel! Tu es grand, et ton nom est grand par ta puissance."}, {"numero": 7, "texto": "Qui ne te craindrait, roi des nations? C''''est à toi que la crainte est due; Car, parmi tous les sages des nations et dans tous leurs royaumes, Nul n''''est semblable à toi."}, {"numero": 8, "texto": "Tous ensemble, ils sont stupides et insensés; Leur science n''''est que vanité, c''''est du bois!"}, {"numero": 9, "texto": "On apporte de Tarsis des lames d''''argent, et d''''Uphaz de l''''or, L''''ouvrier et la main de l''''orfèvre les mettent en oeuvre; Les vêtements de ces dieux sont d''''étoffes teintes en bleu et en pourpre, Tous sont l''''ouvrage d''''habiles artisans."}, {"numero": 10, "texto": "Mais l''''Eternel est Dieu en vérité, Il est un Dieu vivant et un roi éternel; La terre tremble devant sa colère, Et les nations ne supportent pas sa fureur."}, {"numero": 11, "texto": "Vous leur parlerez ainsi: Les dieux qui n''''ont point fait les cieux et la terre Disparaîtront de la terre et de dessous les cieux."}, {"numero": 12, "texto": "Il a créé la terre par sa puissance, Il a fondé le monde par sa sagesse, Il a étendu les cieux par son intelligence."}, {"numero": 13, "texto": "A sa voix, les eaux mugissent dans les cieux; Il fait monter les nuages des extrémités de la terre, Il produit les éclairs et la pluie, Il tire le vent de ses trésors."}, {"numero": 14, "texto": "Tout homme devient stupide par sa science, Tout orfèvre est honteux de son image taillée; Car ses idoles ne sont que mensonge, Il n''''y a point en elles de souffle,"}, {"numero": 15, "texto": "Elles sont une chose de néant, une oeuvre de tromperie; Elles périront, quand viendra le châtiment."}, {"numero": 16, "texto": "Celui qui est la part de Jacob n''''est pas comme elles; Car c''''est lui qui a tout formé, Et Israël est la tribu de son héritage. L''''Eternel des armées est son nom."}, {"numero": 17, "texto": "Emporte du pays ce qui t''''appartient, Toi qui es assise dans la détresse!"}, {"numero": 18, "texto": "Car ainsi parle l''''Eternel: Voici, cette fois je vais lancer au loin les habitants du pays; Je vais les serrer de près, afin qu''''on les atteigne. -"}, {"numero": 19, "texto": "Malheur à moi! je suis brisée! Ma plaie est douloureuse! Mais je dis: C''''est une calamité qui m''''arrive, Je la supporterai!"}, {"numero": 20, "texto": "Ma tente est détruite, Tous mes cordages sont rompus; Mes fils m''''ont quittée, ils ne sont plus; Je n''''ai personne qui dresse de nouveau ma tente, Qui relève mes pavillons. -"}, {"numero": 21, "texto": "Les bergers ont été stupides, Ils n''''ont pas cherché l''''Eternel; C''''est pour cela qu''''ils n''''ont point prospéré, Et que tous leurs troupeaux se dispersent."}, {"numero": 22, "texto": "Voici, une rumeur se fait entendre; C''''est un grand tumulte qui vient du septentrion, Pour réduire les villes de Juda en un désert, En un repaire de chacals. -"}, {"numero": 23, "texto": "Je le sais, ô Eternel! La voie de l''''homme n''''est pas en son pouvoir; Ce n''''est pas à l''''homme, quand il marche, A diriger ses pas."}, {"numero": 24, "texto": "Châtie-moi, ô Eternel! mais avec équité, Et non dans ta colère, de peur que tu ne m''''anéantisses."}, {"numero": 25, "texto": "Répands ta fureur sur les nations qui ne te connaissent pas, Et sur les peuples qui n''''invoquent pas ton nom! Car ils dévorent Jacob, ils le dévorent, ils le consument, Ils ravagent sa demeure."}]'::jsonb, 'Louis Segond 1910'),
  ('Jr', 10, 'es', '[{"numero": 1, "texto": "OID la palabra que Jehová ha hablado sobre vosotros, oh casa de Israel."}, {"numero": 2, "texto": "Así dijo Jehová: No aprendáis el camino de las gentes, ni de las señales del cielo tengáis temor, aunque las gentes las teman."}, {"numero": 3, "texto": "Porque las ordenanzas de los pueblos son vanidad: porque leño del monte cortaron, obra de manos de artífice con azuela."}, {"numero": 4, "texto": "Con plata y oro lo engalanan; con clavos y martillo lo afirman, para que no se salga."}, {"numero": 5, "texto": "Como palma lo igualan, y no hablan; son llevados, porque no pueden andar. No tengáis temor de ellos; porque ni pueden hacer mal, ni para hacer bien tienen poder."}, {"numero": 6, "texto": "No hay semejante á ti, oh Jehová; grande tú, y grande tu nombre en fortaleza."}, {"numero": 7, "texto": "¿Quién no te temerá, oh Rey de las gentes? porque á ti compete ello; porque entre todos los sabios de las gentes, y en todos sus reinos, no hay semejante á ti."}, {"numero": 8, "texto": "Y todos se infatuarán, y entontecerán. Enseñanza de vanidades es el mismo leño."}, {"numero": 9, "texto": "Traerán plata extendida de Tarsis, y oro de Uphaz; obrará el artífice, y las manos del fundidor; vestiránlos de cárdeno y de púrpura: obra de peritos es todo."}, {"numero": 10, "texto": "Mas Jehová Dios es la verdad; él es Dios vivo y Rey eterno: á su ira tiembla la tierra, y las gentes no pueden sufrir su saña."}, {"numero": 11, "texto": "Les diréis así: Los dioses que no hicieron los cielos ni la tierra, perezcan de la tierra y de debajo de estos cielos."}, {"numero": 12, "texto": "El que hizo la tierra con su potencia, el que puso en orden el mundo con su saber, y extendió los cielos con su prudencia;"}, {"numero": 13, "texto": "A su voz se da muchedumbre de aguas en el cielo, y hace subir las nubes de lo postrero de la tierra; hace los relámpagos con la lluvia, y saca el viento de sus depósitos."}, {"numero": 14, "texto": "Todo hombre se embrutece y le falta ciencia; avergüéncese de su vaciadizo todo fundidor: porque mentira es su obra de fundición, y no hay espíritu en ellos;"}, {"numero": 15, "texto": "Vanidad son, obra de escarnios: en el tiempo de su visitación perecerán."}, {"numero": 16, "texto": "No es como ellos la suerte de Jacob: porque él es el Hacedor de todo, é Israel es la vara de su herencia: Jehová de los ejércitos es su nombre."}, {"numero": 17, "texto": "Recoge de las tierras tus mercaderías, la que moras en lugar fuerte."}, {"numero": 18, "texto": "Porque así ha dicho Jehová: He aquí que esta vez arrojaré con honda los moradores de la tierra, y he de afligirlos, para que lo hallen."}, {"numero": 19, "texto": "¡Ay de mí, por mi quebrantamiento! mi llaga es muy dolorosa. Yo empero dije: Ciertamente enfermedad mía es esta, y debo sufrirla."}, {"numero": 20, "texto": "Mi tienda es destruída, y todas mis cuerdas están rotas: mis hijos fueron sacados de mí, y perecieron: no hay ya más quien extienda mi tienda, ni quien levante mis cortinas."}, {"numero": 21, "texto": "Porque los pastores se infatuaron, y no buscaron á Jehová: por tanto no prosperaron, y todo su ganado se esparció."}, {"numero": 22, "texto": "He aquí que voz de fama viene, y alboroto grande de la tierra del aquilón, para tornar en soledad todas las ciudades de Judá, en morada de culebras."}, {"numero": 23, "texto": "Conozco, oh Jehová, que el hombre no es señor de su camino, ni del hombre que camina es ordenar sus pasos."}, {"numero": 24, "texto": "Castígame, oh Jehová, mas con juicio; no con tu furor, porque no me aniquiles."}, {"numero": 25, "texto": "Derrama tu enojo sobre las gentes que no te conocen, y sobre las naciones que no invocan tu nombre: porque se comieron á Jacob, y lo devoraron, y le han consumido, y asolado su morada."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jr', 26, 'pt', '[{"numero": 1, "texto": "No princípio do reinado de Jeoaquim, filho de Josias, rei de Judá, veio esta palavra do SENHOR,dizendo:"}, {"numero": 2, "texto": "Assim diz o SENHOR: Põe-te no pátio da casa do SENHOR, e fala a todas as cidades de Judá, que vêm para adorar [na] casa do SENHOR, todas as palavras que te mandei que lhes falasses; não diminuas uma só palavra."}, {"numero": 3, "texto": "Pode ser que ouçam, e se convertam cada um de seu mal caminho; então eu me arrependeria do mal que pretendo lhes fazer pela maldade de suas ações."}, {"numero": 4, "texto": "Dize-lhes, pois: Assim diz o SENHOR: Se não me ouvirdes para andardes em minha Lei, a qual dei diante de vós,"}, {"numero": 5, "texto": "Para dar atenção às palavras de meus servos, os profetas, que eu vos envio, insistentemente os enviando, mas não os ouvistes;"}, {"numero": 6, "texto": "Então farei desta casa como a Siló, e tornarei esta cidade em maldição a todas as nações da terra."}, {"numero": 7, "texto": "E os sacerdotes, os profetas, e todo o povo, ouviram a Jeremias falar estas palavras na casa do SENHOR."}, {"numero": 8, "texto": "E sucedeu que, acabando Jeremias de falar tudo o que o SENHOR tinha lhe mandado falar a todo o povo, os sacerdotes e os profetas e todo o povo lhe pegaram, dizendo: Certamente morrerás;"}, {"numero": 9, "texto": "Pois profetizaste em nome do SENHOR, dizendo: Esta casa será como Siló, e esta cidade será assolada até não restar morador.E juntou-se todo o povo contra Jeremias na casa do SENHOR."}, {"numero": 10, "texto": "E os príncipes de Judá, ao ouvirem estas coisas, subiram da casa do rei à casa do SENHOR; e sentaram-se à entrada da porta nova do SENHOR."}, {"numero": 11, "texto": "Então os sacerdotes e os profetas falaram aos príncipes e a todo o povo, dizendo: Pena de morte [deve ter] este homem, pois profetizou contra esta cidade, como ouvistes com vossos [próprios] ouvidos."}, {"numero": 12, "texto": "E Jeremias falou a todos os príncipes e a todo o povo, dizendo: O SENHOR me enviou para profetizar contra esta casa e contra esta cidade todas as palavras que ouvistes."}, {"numero": 13, "texto": "Agora, portanto, melhorai vossos caminhos e vossas ações, e ouvi à voz do SENHOR vosso Deus; então o SENHOR mudará de ideia quanto ao mal que falou contra vós."}, {"numero": 14, "texto": "Eu, porém, eis que estou em vossas mãos: fazei de mim como parecer melhor e mais correto aos vossos olhos."}, {"numero": 15, "texto": "Mas sabei certamente que, se vós me matardes, então trareis sangue inocente sobre vós, e sobre esta cidade, e sobre seus moradores; porque em verdade o SENHOR me enviou a vós para falar aos vossos ouvidos todas estas palavras."}, {"numero": 16, "texto": "Então os príncipes e todo o povo disseram aos sacerdotes e profetas: Este homem não é merecedor de pena de morte, porque em nome do SENHOR nosso Deus ele nos falou."}, {"numero": 17, "texto": "E se levantaram alguns dos anciãos da terra, e falaram a todo o ajuntamento do povo, dizendo:"}, {"numero": 18, "texto": "Miqueias, o morastita, profetizou nos dias de Ezequias rei de Judá, e falou a todo o povo de Judá, dizendo: Assim diz o SENHOR dos exércitos: Sião será arada como campo, e Jerusalém se tornará em amontoados [de pedras] , e o monte do templo em lugares altos de mato."}, {"numero": 19, "texto": "Por acaso foi ele morto por Ezequias rei de Judá e todo Judá? Por acaso [Ezequias] não temeu ao SENHOR, e orou na presença do SENHOR, e o SENHOR mudou de ideia quanto ao mal que tinha falado contra eles? E nós, faremos pois tão grande mal contra nossas [próprias] almas?"}, {"numero": 20, "texto": "Houve também um homem que profetizava em nome do SENHOR: Urias, filho de Semaías de Quiriate-Jearim, o qual profetizou contra esta cidade e contra esta terra, conforme todas as palavras de Jeremias;"}, {"numero": 21, "texto": "E quando ouviu suas palavras o rei Jeoaquim, e todos seus grandes, e todos seus príncipes, então o rei procurou matá-lo; e Urias, ao ouvir [isso] , teve medo, fugiu, e foi ao Egito;"}, {"numero": 22, "texto": "Porém o rei Jeoaquim enviou [alguns] homens a Egito: Elnatã filho de Acbor, e [outros] homens com ele, ao Egito;"}, {"numero": 23, "texto": "Os quais tiraram a Urias do Egito, e o trouxeram ao rei Jeoaquim, que o feriu à espada, e lançou seu cadáver nas sepulturas do povo comum."}, {"numero": 24, "texto": "Porém a mão de Aicã, filho de Safã, foi com Jeremias, para que não o entregassem nas mãos do povo para o matarem."}]'::jsonb, 'Almeida Livre'),
  ('Jr', 26, 'en', '[{"numero": 1, "texto": "In the beginning of the reign of Jehoiakim the son of Josiah king of Judah came this word from the Lord, saying,"}, {"numero": 2, "texto": "Thus saith the Lord; Stand in the court of the Lord''s house, and speak unto all the cities of Judah, which come to worship in the Lord''s house, all the words that I command thee to speak unto them; diminish not a word:"}, {"numero": 3, "texto": "If so be they will hearken, and turn every man from his evil way, that I may repent me of the evil, which I purpose to do unto them because of the evil of their doings."}, {"numero": 4, "texto": "And thou shalt say unto them, Thus saith the Lord; If ye will not hearken to me, to walk in my law, which I have set before you,"}, {"numero": 5, "texto": "To hearken to the words of my servants the prophets, whom I sent unto you, both rising up early, and sending them, but ye have not hearkened;"}, {"numero": 6, "texto": "Then will I make this house like Shiloh, and will make this city a curse to all the nations of the earth."}, {"numero": 7, "texto": "So the priests and the prophets and all the people heard Jeremiah speaking these words in the house of the Lord."}, {"numero": 8, "texto": "Now it came to pass, when Jeremiah had made an end of speaking all that the Lord had commanded him to speak unto all the people, that the priests and the prophets and all the people took him, saying, Thou shalt surely die."}, {"numero": 9, "texto": "Why hast thou prophesied in the name of the Lord, saying, This house shall be like Shiloh, and this city shall be desolate without an inhabitant? And all the people were gathered against Jeremiah in the house of the Lord."}, {"numero": 10, "texto": "When the princes of Judah heard these things, then they came up from the king''s house unto the house of the Lord, and sat down in the entry of the new gate of the Lord''s house."}, {"numero": 11, "texto": "Then spake the priests and the prophets unto the princes and to all the people, saying, This man is worthy to die; for he hath prophesied against this city, as ye have heard with your ears."}, {"numero": 12, "texto": "Then spake Jeremiah unto all the princes and to all the people, saying, The Lord sent me to prophesy against this house and against this city all the words that ye have heard."}, {"numero": 13, "texto": "Therefore now amend your ways and your doings, and obey the voice of the Lord your God; and the Lord will repent him of the evil that he hath pronounced against you."}, {"numero": 14, "texto": "As for me, behold, I am in your hand: do with me as seemeth good and meet unto you."}, {"numero": 15, "texto": "But know ye for certain, that if ye put me to death, ye shall surely bring innocent blood upon yourselves, and upon this city, and upon the inhabitants thereof: for of a truth the Lord hath sent me unto you to speak all these words in your ears."}, {"numero": 16, "texto": "Then said the princes and all the people unto the priests and to the prophets; This man is not worthy to die: for he hath spoken to us in the name of the Lord our God."}, {"numero": 17, "texto": "Then rose up certain of the elders of the land, and spake to all the assembly of the people, saying,"}, {"numero": 18, "texto": "Micah the Morasthite prophesied in the days of Hezekiah king of Judah, and spake to all the people of Judah, saying, Thus saith the Lord of hosts; Zion shall be plowed like a field, and Jerusalem shall become heaps, and the mountain of the house as the high places of a forest."}, {"numero": 19, "texto": "Did Hezekiah king of Judah and all Judah put him at all to death? did he not fear the Lord, and besought the Lord, and the Lord repented him of the evil which he had pronounced against them? Thus might we procure great evil against our souls."}, {"numero": 20, "texto": "And there was also a man that prophesied in the name of the Lord, Urijah the son of Shemaiah of Kirjathjearim, who prophesied against this city and against this land according to all the words of Jeremiah."}, {"numero": 21, "texto": "And when Jehoiakim the king, with all his mighty men, and all the princes, heard his words, the king sought to put him to death: but when Urijah heard it, he was afraid, and fled, and went into Egypt;"}, {"numero": 22, "texto": "And Jehoiakim the king sent men into Egypt, namely, Elnathan the son of Achbor, and certain men with him into Egypt."}, {"numero": 23, "texto": "And they fetched forth Urijah out of Egypt, and brought him unto Jehoiakim the king; who slew him with the sword, and cast his dead body into the graves of the common people."}, {"numero": 24, "texto": "Nevertheless the hand of Ahikam the son of Shaphan was with Jeremiah, that they should not give him into the hand of the people to put him to death."}]'::jsonb, 'King James Version'),
  ('Jr', 26, 'fr', '[{"numero": 1, "texto": "Au commencement du règne de Jojakim, fils de Josias, roi de Juda, cette parole fut prononcée de la part de l''''Eternel, en ces mots:"}, {"numero": 2, "texto": "Ainsi parle l''''Eternel: Tiens-toi dans le parvis de la maison de l''''Eternel, et dis à ceux qui de toutes les villes de Juda viennent se prosterner dans la maison de l''''Eternel toutes les paroles que je t''''ordonne de leur dire; n''''en retranche pas un mot."}, {"numero": 3, "texto": "Peut-être écouteront-ils, et reviendront-ils chacun de leur mauvaise voie; alors je me repentirai du mal que j''''avais pensé leur faire à cause de la méchanceté de leurs actions."}, {"numero": 4, "texto": "Tu leur diras: Ainsi parle l''''Eternel: Si vous ne m''''écoutez pas quand je vous ordonne de suivre ma loi que j''''ai mise devant vous,"}, {"numero": 5, "texto": "d''''écouter les paroles de mes serviteurs, les prophètes, que je vous envoie, que je vous ai envoyés dès le matin, et que vous n''''avez pas écoutés,"}, {"numero": 6, "texto": "alors je traiterai cette maison comme Silo, et je ferai de cette ville un objet de malédiction pour toutes les nations de la terre."}, {"numero": 7, "texto": "Les sacrificateurs, les prophètes, et tout le peuple, entendirent Jérémie prononcer ces paroles dans la maison de l''''Eternel."}, {"numero": 8, "texto": "Et comme Jérémie achevait de dire tout ce que l''''Eternel lui avait ordonné de dire à tout le peuple, les sacrificateurs, les prophètes, et tout le peuple, se saisirent de lui, en disant: Tu mourras!"}, {"numero": 9, "texto": "Pourquoi prophétises-tu au nom de l''''Eternel, en disant: Cette maison sera comme Silo, et cette ville sera dévastée, privée d''''habitants? Tout le peuple s''''attroupa autour de Jérémie dans la maison de l''''Eternel."}, {"numero": 10, "texto": "Lorsque les chefs de Juda eurent appris ces choses, ils montèrent de la maison du roi à la maison de l''''Eternel, et s''''assirent à l''''entrée de la porte neuve de la maison de l''''Eternel."}, {"numero": 11, "texto": "Alors les sacrificateurs et les prophètes parlèrent ainsi aux chefs et à tout le peuple: Cet homme mérite la mort; car il a prophétisé contre cette ville, comme vous l''''avez entendu de vos oreilles."}, {"numero": 12, "texto": "Jérémie dit à tous les chefs et à tout le peuple: L''''Eternel m''''a envoyé pour prophétiser contre cette maison et contre cette ville, toutes les choses que vous avez entendues."}, {"numero": 13, "texto": "Maintenant réformez vos voies et vos oeuvres, écoutez la voix de l''''Eternel, votre Dieu, et l''''Eternel se repentira du mal qu''''il a prononcé contre vous."}, {"numero": 14, "texto": "Pour moi, me voici entre vos mains; traitez-moi comme il vous semblera bon et juste."}, {"numero": 15, "texto": "Seulement sachez que, si vous me faites mourir, vous vous chargez du sang innocent, vous, cette ville et ses habitants; car l''''Eternel m''''a véritablement envoyé vers vous pour prononcer à vos oreilles toutes ces paroles."}, {"numero": 16, "texto": "Les chefs et tout le peuple dirent aux sacrificateurs et aux prophètes: Cet homme ne mérite point la mort; car c''''est au nom de l''''Eternel, notre Dieu, qu''''il nous a parlé."}, {"numero": 17, "texto": "Et quelques-uns des anciens du pays se levèrent, et dirent à toute l''''assemblée du peuple:"}, {"numero": 18, "texto": "Michée, de Moréscheth, prophétisait du temps d''''Ezéchias, roi de Juda, et il disait à tout le peuple de Juda: Ainsi parle l''''Eternel des armées: Sion sera labourée comme un champ, Jérusalem deviendra un monceau de pierres, Et la montagne de la maison une haute forêt."}, {"numero": 19, "texto": "Ezéchias, roi de Juda, et tout Juda l''''ont-ils fait mourir? Ezéchias ne craignit-il pas l''''Eternel? N''''implora-t-il pas l''''Eternel? Alors l''''Eternel se repentit du mal qu''''il avait prononcé contre eux. Et nous, nous chargerions notre âme d''''un si grand crime!"}, {"numero": 20, "texto": "Il y eut aussi un homme qui prophétisait au nom de l''''Eternel, Urie, fils de Schemaeja, de Kirjath-Jearim. Il prophétisa contre cette ville et contre ce pays entièrement les mêmes choses que Jérémie."}, {"numero": 21, "texto": "Le roi Jojakim, tous ses vaillants hommes, et tous ses chefs, entendirent ses paroles, et le roi chercha à le faire mourir. Urie, qui en fut informé, eut peur, prit la fuite, et alla en Egypte."}, {"numero": 22, "texto": "Le roi Jojakim envoya des gens en Egypte, Elnathan, fils d''''Acbor, et des gens avec lui en Egypte."}, {"numero": 23, "texto": "Ils firent sortir d''''Egypte Urie et l''''amenèrent au roi Jojakim, qui le fit mourir par l''''épée et jeta son cadavre sur les sépulcres des enfants du peuple."}, {"numero": 24, "texto": "Cependant la main d''''Achikam, fils de Schaphan, fut avec Jérémie, et empêcha qu''''il ne fût livré au peuple pour être mis à mort."}]'::jsonb, 'Louis Segond 1910'),
  ('Jr', 26, 'es', '[{"numero": 1, "texto": "EN el principio del reinado de Joacim hijo de Josías, rey de Judá, fué esta palabra de Jehová, diciendo:"}, {"numero": 2, "texto": "Así ha dicho Jehová: Ponte en el atrio de la casa de Jehová, y habla á todas las ciudades de Judá, que vienen para adorar en la casa de Jehová, todas las palabras que yo te mandé les hablases; no retengas palabra."}, {"numero": 3, "texto": "Quizá oirán, y se tornarán cada uno de su mal camino; y arrepentiréme yo del mal que pienso hacerles por la maldad de sus obras."}, {"numero": 4, "texto": "Les dirás pues: Así ha dicho Jehová: Si no me oyereis para andar en mi ley, la cual dí delante de vosotros,"}, {"numero": 5, "texto": "Para atender á las palabras de mis siervos los profetas que yo os envío, madrugando en enviarlos, á los cuales no habéis oído;"}, {"numero": 6, "texto": "Yo pondré esta casa como Silo, y daré esta ciudad en maldición á todas las gentes de la tierra."}, {"numero": 7, "texto": "Y los sacerdotes, los profetas, y todo el pueblo, oyeron á Jeremías hablar estas palabras en la casa de Jehová."}, {"numero": 8, "texto": "Y fué que, acabando de hablar Jeremías todo lo que Jehová le había mandado que hablase á todo el pueblo, los sacerdotes y los profetas y todo el pueblo le echaron mano, diciendo: De cierto morirás."}, {"numero": 9, "texto": "¿Por qué has profetizado en nombre de Jehová, diciendo: Esta casa será como Silo, y esta ciudad será asolada hasta no quedar morador? Y juntóse todo el pueblo contra Jeremías en la casa de Jehová."}, {"numero": 10, "texto": "Y los príncipes de Judá oyeron estas cosas, y subieron de casa del rey á la casa de Jehová; y sentáronse en la entrada de la puerta nueva de Jehová."}, {"numero": 11, "texto": "Entonces hablaron los sacerdotes y los profetas á los príncipes y á todo el pueblo, diciendo: En pena de muerte ha incurrido este hombre; porque profetizó contra esta ciudad, como vosotros habéis oído con vuestros oídos."}, {"numero": 12, "texto": "Y habló Jeremías á todos los príncipes y á todo el pueblo, diciendo: Jehová me envió á que profetizase contra esta casa y contra esta ciudad, todas las palabras que habéis oído."}, {"numero": 13, "texto": "Y ahora, mejorad vuestros caminos y vuestras obras, y oid la voz de Jehová vuestro Dios, y arrepentiráse Jehová del mal que ha hablado contra vosotros."}, {"numero": 14, "texto": "En lo que á mí toca, he aquí estoy en vuestras manos: haced de mí como mejor y más recto os pareciere."}, {"numero": 15, "texto": "Mas sabed de cierto que, si me matareis, sangre inocente echaréis sobre vosotros, y sobre esta ciudad, y sobre sus moradores: porque en verdad Jehová me envió á vosotros para que dijese todas estas palabras en vuestros oídos."}, {"numero": 16, "texto": "Y dijeron los príncipes y todo el pueblo á los sacerdotes y profetas. No ha incurrido este hombre en pena de muerte, porque en nombre de Jehová nuestro Dios nos ha hablado."}, {"numero": 17, "texto": "Entonces se levantaron ciertos de los ancianos de la tierra, y hablaron á toda la junta del pueblo, diciendo:"}, {"numero": 18, "texto": "Miqueas de Morasti profetizó en tiempo de Ezechîas rey de Judá, diciendo: Así ha dicho Jehová de los ejércitos: Sión será arada como campo, y Jerusalem vendrá á ser montones, y el monte del templo en cumbres de bosque."}, {"numero": 19, "texto": "¿Matáronlo luego Ezechîas rey de Judá y todo Judá? ¿no temió á Jehová, y oró en presencia de Jehová, y Jehová se arrepintió del mal que había hablado contra ellos? ¿Haremos pues nosotros tan grande mal contra nuestras almas?"}, {"numero": 20, "texto": "Hubo también un hombre que profetizaba en nombre de Jehová, Urías, hijo de Semaías de Chîriath-jearim, el cual profetizó contra esta ciudad y contra esta tierra, conforme á todas las palabras de Jeremías:"}, {"numero": 21, "texto": "Y oyó sus palabras el rey Joacim, y todos sus grandes, y todos sus príncipes, y el rey procuró de matarle; lo cual entendiendo Urías, tuvo temor, y huyó, y metióse en Egipto:"}, {"numero": 22, "texto": "Y el rey Joacim envió hombres á Egipto, á Elnathán hijo de Acbor, y otros hombres con él, á Egipto;"}, {"numero": 23, "texto": "Los cuales sacaron á Urías de Egipto, y lo trajeron al rey Joacim, é hiriólo á cuchillo, y echó su cuerpo en los sepulcros del vulgo."}, {"numero": 24, "texto": "La mano empero de Ahicam hijo de Saphán era con Jeremías, porque no lo entregasen en las manos del pueblo para matarlo."}]'::jsonb, 'Reina-Valera 1909')
